            if parsed.path == "/download/ai-director-capture-extension.zip":
                try:
                    package_path = build_extension_package(root)
                except Exception as exc:  # noqa: BLE001 - show packaging errors in browser.
                    self.write_html(render_error_page("页面助手打包失败", str(exc)))
                    return
                self.write_file(package_path, "application/zip", "AI_Ecommerce_Director_Capture_Extension.zip")
                return
            if parsed.path == "/download/amazon-10001-template-upload-candidate.csv":
                packet = build_amazon_10001_downloaded_template_watcher_result(root)
                candidate_path = Path(str(packet.get("upload_candidate_path") or ""))
                try:
                    if not packet.get("upload_candidate_created") or not candidate_path.exists():
                        raise FileNotFoundError("Amazon 10001 upload candidate is not generated yet. Download the Seller Central template and scan again.")
                    if root.resolve() not in candidate_path.resolve().parents:
                        raise ValueError("Candidate file is outside the local workspace.")
                except Exception as exc:  # noqa: BLE001 - render user-facing file readiness error.
                    self.write_html(render_error_page("Amazon候选上传文件还没准备好", str(exc)))
                    return
                self.write_file(
                    candidate_path,
                    "text/csv; charset=utf-8",
                    "amazon_10001_template_upload_candidate.csv",
                )
                return
            if parsed.path == "/download/amazon-10001-execution-draft":
                query = parse_qs(parsed.query)
                filename = Path(query.get("file", [""])[0]).name
                try:
                    if not filename:
                        raise FileNotFoundError("Missing execution draft filename.")
                    matches = sorted(
                        (root / "outputs").glob(f"amazon_10001_execution_drafts_*/{filename}"),
                        key=lambda path: path.stat().st_mtime,
                        reverse=True,
                    )
                    if not matches:
                        raise FileNotFoundError(f"Execution draft not found: {filename}")
                    draft_path = matches[0]
                    if root.resolve() not in draft_path.resolve().parents:
                        raise ValueError("Execution draft is outside the local workspace.")
                except Exception as exc:  # noqa: BLE001 - render user-facing file readiness error.
                    self.write_html(render_error_page("Amazon执行草稿还没准备好", str(exc)))
                    return
                self.write_file(
                    draft_path,
                    "text/csv; charset=utf-8",
                    filename,
                )
                return
            if parsed.path == "/record":
                query = parse_qs(parsed.query)
                record_id = query.get("id", [""])[0]
                self.write_html(render_record_edit_page(root, record_id))
