def render_manual_capture_recent_row(record: IntakeRecord) -> str:
    fields = record.fields
    name = (
        fields.get("product_name")
        or fields.get("product_theme")
        or fields.get("creator_handle")
        or fields.get("store_id")
        or fields.get("risk_term")
        or fields.get("review_theme")
        or fields.get("page_title")
        or record.record_id[:8]
    )
    platform = fields.get("marketplace") or fields.get("source_platform") or ""
    url = fields.get("url") or fields.get("page_url") or fields.get("video_url") or fields.get("profile_url") or ""
    link = f"<a href='{html.escape(str(url))}' target='_blank'>打开</a>" if url else ""
    return (
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}</td>"
        f"<td>{html.escape(display_record_type(record.record_type))}</td>"
        f"<td>{html.escape(str(name))}</td>"
        f"<td>{html.escape(str(platform))}</td>"
        f"<td>{link}</td>"
        "</tr>"
    )


