def approval_title_text(action: dict[str, Any]) -> str:
    if approval_action_is_ads_preflight(action):
        return "生成广告前置缺口清单"
    title = str(action.get("title") or action.get("action_type") or "").strip()
    if title.startswith("Apply listing or product changes for "):
        return "根据问题修改商品页：" + title.replace("Apply listing or product changes for ", "", 1)
    if title.startswith("Publish only after compliance review for "):
        return "合规确认后再考虑上架：" + title.replace("Publish only after compliance review for ", "", 1)
    if title.startswith("Publish or update listing for "):
        return "上架/更新商品：" + title.replace("Publish or update listing for ", "", 1)
    if title.startswith("Prepare Amazon listing preflight for "):
        return "Amazon 上架预检：" + title.replace("Prepare Amazon listing preflight for ", "", 1)
    if title.startswith("Set a test discount"):
        return "设置测试折扣"
    if title.startswith("Upload produced creative asset after review for "):
        return "复核后再上传素材：" + title.replace("Upload produced creative asset after review for ", "", 1)
    if title.startswith("Check IP/reuse boundary for original creative "):
        return "检查素材/IP边界：" + title.replace("Check IP/reuse boundary for original creative ", "", 1)
    if title.startswith("Prepare AI image/video prompt for original creative "):
        return "准备图像/视频提示词：" + title.replace("Prepare AI image/video prompt for original creative ", "", 1)
    if title.startswith("Collect read-only platform data for "):
        return "读取公开/授权平台数据：" + title.replace("Collect read-only platform data for ", "", 1)
    if title.startswith("Route collected data to the best AI analysis module for "):
        return "分发采集数据到分析模块：" + title.replace("Route collected data to the best AI analysis module for ", "", 1)
    if title.startswith("Save collection outputs into the matching intelligence libraries for "):
        return "保存采集结果到情报库：" + title.replace("Save collection outputs into the matching intelligence libraries for ", "", 1)
    return title


def approval_reason_text(action: dict[str, Any]) -> str:
    reason = str(action.get("reason") or "").strip()
    if not reason:
        return "AI已经准备好动作草稿，但需要负责人确认后才进入执行。"
    lowered = reason.lower()
    if "store protection active" in lowered:
        return "店铺保护已开启：AI 只能分析、读取证据和准备草稿，不会改广告、商品页、价格、库存、优惠、直播链接、优惠券、上传或账号设置；负责人确认边界后才处理。"
    if "allowed autonomous action" in lowered:
        return "这是后台 AI 可自动完成的只读、分析、报告或草稿动作，不涉及真实店铺修改。"
    if "sensitive store/platform action" in lowered:
        return "这是涉及真实店铺或平台后台的动作。AI只准备草稿、证据和风险，不会自动执行，必须负责人同意后再处理。"
    if "sensitive store action" in lowered:
        return "这是涉及真实店铺的动作。AI不会自动操作，需要负责人确认。"
    if "will not execute it without user confirmation" in lowered:
        return "AI已经准备好动作草稿，但没有负责人确认不会执行。"
    return reason


def approval_risk_score(action: dict[str, Any]) -> int:
    action_type = str(action.get("action_type") or "").strip().lower()
    text = " ".join(
        [
            action_type,
            str(action.get("title") or ""),
            str(action.get("reason") or ""),
        ]
    ).lower()
    if action_type in {"after_sales_review_draft", "launch_ad", "ads_test_plan_draft", "delist_product", "b2b_quote_pi_owner_review"}:
        return 95
    if action_type in {"publish_listing", "update_listing", "set_discount", "publish_video_via_aip", "upload_asset"}:
        return 90
    if action_type in {"store_connection_setup", "pricing_promotion_draft", "listing_draft"}:
        return 82
    if any(keyword in text for keyword in ["refund", "退款", "退货", "advert", "投流", "广告", "publish", "发布", "upload", "上传"]):
        return 88
    if any(keyword in text for keyword in ["authorization", "授权", "listing", "price", "改价", "discount", "折扣"]):
        return 78
    return safe_int(action.get("priority") or 0)


def approval_risk_label(score: int) -> str:
    if score >= 90:
        return "高风险先确认"
    if score >= 75:
        return "中风险复核"
    return "低风险草稿"


