def approval_rollback_text(action: dict[str, Any]) -> str:
    action_type = str(action.get("action_type") or "").strip()
    if approval_action_is_ads_preflight(action):
        return "只保留广告前置缺口清单；未补齐授权数据前不生成预算、不启动投放、不自动放量。"
    rollback_items = action.get("activity_rollback_conditions")
    if isinstance(rollback_items, list):
        filtered_items: list[str] = []
        for item in rollback_items:
            text_item = str(item or "").strip()
            if not text_item:
                continue
            if approval_should_hide_ads_execution_details(action) and approval_text_is_ads_execution_detail(text_item):
                continue
            filtered_items.append(text_item)
        text = "；".join(approval_unique(filtered_items)[:3])
        if text:
            return text
    labels = {
        "after_sales_review_draft": "未确认不触发退款、退货或客服回复；拒绝后只保留草稿和学习记录。",
        "ads_test_plan_draft": "先按小预算和止损线执行；效果异常或未确认时暂停投放，不自动放量。",
        "launch_ad": "未确认不创建广告；确认后仍保留暂停广告、降预算和停用素材的回滚入口。",
        "publish_listing": "未确认不发布；确认后如出错，按旧标题/价格/库存口径恢复或下架。",
        "update_listing": "未确认不改字段；确认后如指标异常，恢复到修改前的商品页文案和价格。",
        "set_discount": "未确认不改价；确认后如利润或转化异常，按原价和原活动状态恢复。",
        "publish_video_via_aip": "未确认不上传公开视频；确认后如素材/音乐/挂车异常，删除或转私密并停用挂车。",
        "upload_asset": "未确认不上传；确认后如发现 IP 或用途风险，删除素材并停用后续复用。",
        "store_connection_setup": "未确认不扩大读取范围；确认后可停用连接并保留历史对账记录。",
        "b2b_quote_pi_owner_review": "未确认不发送报价、不收款、不建订单、不发货；确认后仍由负责人手动外发并回写证据。",
    }
    return labels.get(action_type, "未确认不执行真实外部动作；确认后若证据不成立，停止动作并保留复盘记录。")


def extract_activity_execution_plan(source: dict[str, Any]) -> dict[str, Any]:
    plan = source.get("activity_execution_plan")
    if not isinstance(plan, dict):
        payload = source.get("payload")
        if isinstance(payload, dict):
            plan = payload.get("activity_execution_plan")
    return plan if isinstance(plan, dict) else {}


def render_activity_execution_plan_summary(source: dict[str, Any], *, compact: bool = False) -> str:
    plan = extract_activity_execution_plan(source)
    if not plan:
        return ""
    ads_preflight_only = approval_action_is_ads_preflight(source)
    hide_ads_execution_details = approval_should_hide_ads_execution_details(source)
    status = str(plan.get("plan_status") or source.get("activity_plan_status") or "").strip()
    route_key = str(plan.get("route_key") or source.get("cloud_route_key") or source.get("route_key") or "").strip()
    route_label = customer_route_key_label(route_key) if route_key else "路径待确认"
    activity_type = str(plan.get("activity_type") or source.get("activity_type") or "").strip()
    store_name = approval_customer_visible_store_name(
        plan.get("store_name") or source.get("store_name") or source.get("store") or ""
    )
    store_ownership = approval_store_ownership_summary(source)
    executor = str(plan.get("recommended_executor") or "").strip()
    missing = activity_plan_string_list(plan.get("missing_prerequisites") or source.get("activity_plan_missing_prerequisites"))
    checks = activity_plan_string_list(plan.get("required_checks"))
    if hide_ads_execution_details:
        checks = [
            item
            for item in checks
            if item not in {"ads_account", "ads_budget", "break_even_roas", "business_center_if_ads", "ads_account_if_ads"}
            and "ads" not in item
            and "roas" not in item
            and "budget" not in item
        ]
    stacking_rules = activity_plan_string_list(plan.get("stacking_rules"))
    source_review = plan.get("source_review") if isinstance(plan.get("source_review"), dict) else {}
    source_checked = str(source_review.get("checked_at") or source_review.get("last_checked_at") or "").strip()
    source_urls = activity_plan_string_list(source_review.get("official_sources"))[:2]
    submit_allowed = bool(plan.get("external_submit_allowed"))
    can_queue = bool(plan.get("can_queue_cloud_task"))
    can_prepare = bool(plan.get("can_prepare_draft"))
    missing_text = "、".join(activity_plan_missing_label(item) for item in missing[:5]) if missing else "暂未缺关键前置条件"
    check_labels = [activity_plan_check_label(item) for item in checks[:6]]
    if not compact and stacking_rules:
        check_labels.extend(activity_plan_check_label(item) for item in stacking_rules[:3])
    if ads_preflight_only:
        check_labels = [
            "广告账号",
            "广告归属主体",
            "店铺授权数据",
            "预算边界",
            "报表缺口",
        ]
    detail_rows = [
        f"<span class='activity-plan-pill'>状态：{html.escape(activity_plan_status_label(status))}</span>",
        f"<span class='activity-plan-pill'>路径：{html.escape(route_label)}</span>",
    ]
    if activity_type:
        detail_rows.append(f"<span class='activity-plan-pill'>类型：{html.escape(activity_plan_type_label(activity_type))}</span>")
    if store_name and not compact:
        detail_rows.append(f"<span class='activity-plan-pill'>店铺：{html.escape(store_name)}</span>")
    if store_ownership:
        detail_rows.append(f"<span class='activity-plan-pill'>归属：{html.escape(store_ownership)}</span>")
    if executor and not compact:
        detail_rows.append(
            f"<span class='activity-plan-pill'>后台处理：{html.escape(activity_plan_backend_handling_label(executor, can_queue, submit_allowed))}</span>"
        )
    if ads_preflight_only:
        readiness_rows = [
            "<span class='activity-plan-pill'>草稿：缺口清单</span>",
            "<span class='activity-plan-pill'>后台任务：确认后回写缺口包</span>",
            "<span class='activity-plan-pill'>真实提交：禁止自动提交</span>",
        ]
    else:
        readiness_rows = [
            f"<span class='activity-plan-pill'>草稿：{html.escape('可准备' if can_prepare else '不可准备')}</span>",
            f"<span class='activity-plan-pill'>后台任务：{html.escape('确认后生成任务包' if can_queue else '先保留草稿')}</span>",
            f"<span class='activity-plan-pill'>真实提交：{html.escape('禁止自动提交' if not submit_allowed else '仍需二次确认')}</span>",
        ]
    checks_html = ""
    if check_labels and not compact:
        checks_html = (
            "<small><b>确认前检查：</b>"
            + html.escape("、".join(dict.fromkeys(label for label in check_labels if label)))
            + "</small>"
        )
    source_html = ""
    if not compact and (source_checked or source_urls):
        source_note = "官方规则已归档，后台 AI 定期复核。"
        if source_checked:
            source_note += f" 最近复核：{source_checked}。"
        source_html = f"<small><b>规则来源：</b>{html.escape(source_note)}</small>"
    if ads_preflight_only:
        playbook_html = render_ads_preflight_gap_plan_summary(compact=compact)
        economics_html = ""
        ads_html = ""
        closure_html = ""
    else:
        playbook_html = render_activity_rule_playbook_summary(plan, compact=compact)
        economics_html = render_activity_stack_guardrail_summary(
            plan,
            compact=compact,
            include_ads_metrics=not hide_ads_execution_details,
        )
        ads_html = "" if hide_ads_execution_details else render_ad_budget_plan_summary(plan, compact=compact)
        closure_html = render_activity_rule_to_task_closure_summary(plan, compact=compact)
    evidence_html = render_activity_rule_evidence_pack_summary(
        plan,
        compact=compact,
        hide_ads_execution_details=hide_ads_execution_details,
    )
    preflight_html = render_operator_activity_preflight_pack_summary(
        plan,
        compact=compact,
        hide_ads_execution_details=hide_ads_execution_details,
    )
    plan_title = "广告前置缺口计划" if ads_preflight_only else ("活动计划" if hide_ads_execution_details else "活动/广告计划")
    return (
        "<div class='activity-plan'>"
        f"<strong>{html.escape(plan_title)}</strong>"
        f"<div class='activity-plan-row'>{''.join(detail_rows)}</div>"
        f"<div class='activity-plan-row'>{''.join(readiness_rows)}</div>"
        f"<small><b>缺口：</b>{html.escape(missing_text)}</small>"
        f"{playbook_html}"
        f"{economics_html}"
        f"{ads_html}"
        f"{preflight_html}"
        f"{closure_html}"
        f"{evidence_html}"
        f"{checks_html}"
        f"{source_html}"
        "</div>"
    )


def render_ads_preflight_gap_plan_summary(*, compact: bool = False) -> str:
    if compact:
        return (
            "<small><b>广告前置缺口：</b>"
            "只核对广告账号、归属主体、授权数据、预算边界和报表缺口；未补齐前不生成可投放预算。"
            "</small>"
        )
    rows = [
        "广告账号与 Business Center 归属是否匹配当前店铺",
        "店铺授权、广告授权、报表数据是否可读",
        "预算边界只作为风险上限记录，不输出可投放方案",
        "未补齐前不创建广告、不启动投放、不自动放量",
    ]
    return (
        "<small><b>广告前置缺口：</b>"
        + html.escape("；".join(rows))
        + "</small>"
    )


def render_operator_activity_preflight_pack_summary(
    plan: dict[str, Any],
    *,
    compact: bool = False,
    hide_ads_execution_details: bool = False,
) -> str:
    preflight = plan.get("operator_preflight_pack") if isinstance(plan.get("operator_preflight_pack"), dict) else {}
    if not preflight:
        return ""
    checkpoints = preflight.get("checkpoints")
    if not isinstance(checkpoints, list):
        checkpoints = []
    rows: list[str] = []
    for checkpoint in checkpoints:
        if not isinstance(checkpoint, dict):
            continue
        label = str(checkpoint.get("label") or "").strip()
        if not label:
            continue
        if hide_ads_execution_details and approval_text_is_ads_execution_detail(label):
            continue
        status = operator_preflight_status_label(str(checkpoint.get("status") or ""))
        next_action = compact_operator_preflight_next_action(str(checkpoint.get("next_action") or ""), compact=compact)
        rows.append(f"<span><b>{html.escape(label)}：</b>{html.escape(status)}{html.escape('；' + next_action if next_action else '')}</span>")
        if compact and len(rows) >= 5:
            break
    if not rows:
        return ""
    boundary = str(preflight.get("customer_boundary") or "").strip()
    boundary_html = ""
    if boundary and not compact:
        boundary_html = f"<span><b>客户边界：</b>{html.escape(boundary)}</span>"
    return "<div class='operator-preflight'><strong>后台 AI 预检</strong>" + "".join(rows) + boundary_html + "</div>"


def compact_operator_preflight_next_action(text: str, *, compact: bool = False) -> str:
    clean = re.sub(r"\s+", " ", str(text or "")).strip()
    if not clean:
        return ""
    limit = 58 if compact else 120
    if len(clean) <= limit:
        return clean
    return clean[: limit - 1].rstrip("，。； ") + "…"


def operator_preflight_status_label(status: str) -> str:
    labels = {
        "ready": "已完成",
        "blocked": "待补",
        "needs_inputs": "待补数据",
        "needs_review": "待复核",
        "not_needed": "本次不涉及",
        "required": "必须确认",
        "ready_after_confirmation": "确认后可准备",
        "draft_only": "先保留草稿",
        "ready_for_confirmed_ads_draft": "可准备广告草稿",
        "needs_ads_identity": "待补广告身份",
        "needs_unit_economics": "待补售价/成本",
        "stop_before_ads": "不建议启动投放",
        "ads_budget_warning": "预算需降档",
        "needs_budget_review": "待复核预算",
    }
    clean = str(status or "").strip()
    return labels.get(clean, "待复核" if clean else "待确认")


def render_activity_rule_evidence_pack_summary(
    plan: dict[str, Any],
    *,
    compact: bool = False,
    hide_ads_execution_details: bool = False,
) -> str:
    evidence = plan.get("activity_rule_evidence_pack") if isinstance(plan.get("activity_rule_evidence_pack"), dict) else {}
    if not evidence:
        return ""
    checked_at = str(evidence.get("checked_at") or "").strip()
    sources = activity_plan_string_list(evidence.get("official_sources"))
    surfaces = activity_plan_string_list(evidence.get("authorization_surfaces"))
    blocked = activity_plan_string_list(evidence.get("blocked_external_actions"))
    domains = activity_plan_string_list(evidence.get("requested_domains"))
    if hide_ads_execution_details:
        surfaces = [
            item
            for item in surfaces
            if not approval_text_is_ads_execution_detail(activity_plan_check_label(item))
            and "ads" not in item
            and "advertising" not in item
            and "business_center" not in item
        ]
        blocked = [
            item
            for item in blocked
            if not approval_text_is_ads_execution_detail(activity_plan_check_label(item))
            and "ads" not in item
            and "advertising" not in item
            and "budget" not in item
        ]
        domains = [
            item
            for item in domains
            if item not in {"ads", "advertising"}
            and "ads" not in item
            and "advertising" not in item
            and not approval_text_is_ads_execution_detail(activity_plan_check_label(item))
        ]
    scope = str(evidence.get("rule_scope") or "").strip()
    source_text = "官方规则已核对，负责人可复核来源" if sources else "官方规则来源待补"
    surface_text = "、".join(activity_plan_check_label(item) for item in surfaces[:4]) or (
        "店铺后台待确认" if hide_ads_execution_details else "店铺后台/广告后台待确认"
    )
    blocked_text = "、".join(activity_plan_check_label(item) for item in blocked[:4]) or "外部提交需负责人确认"
    domain_text = "、".join(activity_plan_check_label(item) for item in domains[:4]) or (
        "活动能力待确认" if hide_ads_execution_details else "活动/广告能力待确认"
    )
    rows = [
        f"<span><b>规则证据：</b>{html.escape(source_text)}</span>",
        f"<span><b>授权面：</b>{html.escape(surface_text)}</span>",
        f"<span><b>禁止自动动作：</b>{html.escape(blocked_text)}</span>",
    ]
    if not compact:
        if checked_at:
            rows.append(f"<span><b>最近核对：</b>{html.escape(checked_at)}</span>")
        rows.append(f"<span><b>能力域：</b>{html.escape(domain_text)}</span>")
        if scope:
            rows.append(f"<span><b>规则范围：</b>{html.escape(activity_plan_check_label(scope))}</span>")
    return "<div class='activity-rule-evidence'>" + "".join(rows) + "</div>"


def render_activity_rule_to_task_closure_summary(plan: dict[str, Any], *, compact: bool = False) -> str:
    closure = plan.get("rule_to_task_closure") if isinstance(plan.get("rule_to_task_closure"), dict) else {}
    if not closure and plan:
        closure = {
            "stack_checks": activity_plan_string_list(
                plan.get("stacking_rules")
                or (plan.get("activity_rule_playbook") if isinstance(plan.get("activity_rule_playbook"), dict) else {}).get("stackability_checks")
                or plan.get("required_checks")
            ),
            "margin_guardrail_status": (
                plan.get("activity_stack_guardrail") if isinstance(plan.get("activity_stack_guardrail"), dict) else {}
            ).get("calculation_status")
            or ("needs_price_cost_inputs" if "unit_economics" in activity_plan_string_list(plan.get("missing_prerequisites")) else ""),
            "real_submission_gates": activity_plan_string_list(
                (plan.get("activity_rule_playbook") if isinstance(plan.get("activity_rule_playbook"), dict) else {}).get("real_submission_gates")
                or plan.get("required_checks")
                or ["owner_confirmation_required"]
            ),
            "capability_domains": activity_plan_string_list(plan.get("required_checks"))[:4],
            "task_package_readiness": (
                "backend_task_package_after_confirmation"
                if bool(plan.get("can_queue_cloud_task"))
                else "draft_only_until_prerequisites_ready"
            ),
        }
    if not closure:
        return ""
    stack_checks = activity_plan_string_list(closure.get("stack_checks"))
    gates = activity_plan_string_list(closure.get("real_submission_gates"))
    domains = activity_plan_string_list(closure.get("capability_domains"))
    margin_status = str(closure.get("margin_guardrail_status") or "").strip()
    task_readiness = str(closure.get("task_package_readiness") or "").strip()
    stack_text = "、".join(activity_plan_check_label(item) for item in stack_checks[:3]) or "叠加校验待复核"
    gate_text = "、".join(activity_plan_check_label(item) for item in gates[:3]) or "负责人确认"
    domain_text = "、".join(activity_plan_check_label(item) for item in domains[:4]) or "能力域待确认"
    readiness_label = "确认后生成后台任务包" if task_readiness == "backend_task_package_after_confirmation" else "先保留后台草稿"
    rows = [
        f"<span><b>规则到任务：</b>{html.escape(stack_text)}</span>",
        f"<span><b>毛利护栏：</b>{html.escape(activity_plan_check_label(margin_status) if margin_status else '待计算')}</span>",
        f"<span><b>提交门槛：</b>{html.escape(gate_text)}</span>",
    ]
    if not compact:
        rows.append(f"<span><b>能力域：</b>{html.escape(domain_text)}</span>")
    rows.append(f"<span><b>后台任务：</b>{html.escape(readiness_label)}</span>")
    return "<div class='rule-to-task-closure'>" + "".join(rows) + "</div>"


def render_activity_rule_playbook_summary(plan: dict[str, Any], *, compact: bool = False) -> str:
    playbook = plan.get("activity_rule_playbook") if isinstance(plan.get("activity_rule_playbook"), dict) else {}
    if not playbook:
        return ""
    window = str(playbook.get("campaign_window") or plan.get("site_campaign_window") or "").strip()
    focus = activity_plan_string_list(playbook.get("site_activity_focus") or plan.get("site_activity_focus"))
    slots = activity_plan_string_list(playbook.get("calendar_slots"))
    checks = activity_plan_string_list(playbook.get("stackability_checks") or plan.get("stacking_rules"))
    gates = activity_plan_string_list(playbook.get("real_submission_gates") or plan.get("real_submission_requires"))
    focus_text = "、".join(activity_plan_check_label(item) for item in focus[:4]) or "活动类型待确认"
    slot_text = "、".join(activity_plan_check_label(item) for item in slots[:3]) or "活动窗口待确认"
    check_text = "、".join(activity_plan_check_label(item) for item in checks[:4]) or "叠加规则待复核"
    result = (
        f"<small><b>站点节奏：</b>{html.escape(activity_plan_check_label(window) if window else '按站点活动日历')}；"
        f"重点 {html.escape(focus_text)}；窗口 {html.escape(slot_text)}</small>"
    )
    if not compact:
        gate_text = "、".join(activity_plan_check_label(item) for item in gates[:4]) or "负责人确认"
        result += (
            f"<small><b>叠加限制：</b>{html.escape(check_text)}</small>"
            f"<small><b>提交门槛：</b>{html.escape(gate_text)}；真实提交仍禁止自动执行。</small>"
        )
    return result


def render_ad_budget_plan_summary(plan: dict[str, Any], *, compact: bool = False) -> str:
    ad_plan = plan.get("ad_budget_plan") if isinstance(plan.get("ad_budget_plan"), dict) else {}
    if not ad_plan or not ad_plan.get("applies"):
        return ""
    status = str(ad_plan.get("planning_status") or "").strip()
    if status == "needs_ads_identity":
        missing = "、".join(activity_plan_missing_label(item) for item in activity_plan_string_list(ad_plan.get("missing_prerequisites"))) or "广告账号"
        return f"<small><b>广告预算计划：</b>缺 {html.escape(missing)}，只能保留广告草稿。</small>"
    if status == "needs_unit_economics":
        missing = "、".join(activity_economics_missing_label(item) for item in activity_plan_string_list(ad_plan.get("missing_prerequisites"))) or "售价/成本"
        return f"<small><b>广告预算计划：</b>缺 {html.escape(missing)}，暂不能计算冷启动预算。</small>"
    if status == "stop_before_ads":
        return "<small><b>广告预算计划：</b>毛利不过线，禁止启动或提高预算，只保留复核草稿。</small>"
    cold_budget = ad_plan.get("cold_start_daily_budget")
    cap = ad_plan.get("budget_cap_per_day")
    break_even = ad_plan.get("break_even_roas")
    creative_count = ad_plan.get("creative_count")
    test_days = ad_plan.get("test_days")
    parts = [
        f"状态：{ad_budget_status_label(status)}",
        f"冷启动 {money(cold_budget)}/天",
        f"素材 {html.escape(str(creative_count or '-'))} 条",
        f"测试 {html.escape(str(test_days or '-'))} 天",
    ]
    if break_even is not None:
        parts.append(f"保本 ROAS {ratio(break_even)}")
    if cap is not None and not compact:
        parts.append(f"日预算上限 {money(cap)}")
    details = ""
    if not compact:
        creative_html = render_ad_creative_scorecard_summary(ad_plan, compact=compact)
        pause_rules = "、".join(ad_budget_rule_label(item) for item in activity_plan_string_list(ad_plan.get("pause_rules"))[:3])
        scale_rules = "、".join(ad_budget_rule_label(item) for item in activity_plan_string_list(ad_plan.get("scale_rules"))[:3])
        warnings = "、".join(ad_budget_warning_label(item) for item in activity_plan_string_list(ad_plan.get("warnings"))[:3])
        details = (
            f"{creative_html}"
            f"<small><b>暂停规则：</b>{html.escape(pause_rules or '低于保本线或库存/退款异常即暂停')}</small>"
            f"<small><b>放量规则：</b>{html.escape(scale_rules or '过保本 ROAS 且负责人确认后再放量')}</small>"
        )
        if warnings:
            details += f"<small><b>预算风险：</b>{html.escape(warnings)}</small>"
    return f"<small><b>广告预算计划：</b>{html.escape('；'.join(parts))}；预算变化仍需负责人确认。</small>{details}"


def render_ad_creative_scorecard_summary(ad_plan: dict[str, Any], *, compact: bool = False) -> str:
    scorecard = ad_plan.get("creative_scorecard") if isinstance(ad_plan.get("creative_scorecard"), dict) else {}
    if not scorecard:
        return ""
    status = str(scorecard.get("creative_status") or "").strip()
    score = scorecard.get("score")
    creative_count = scorecard.get("creative_count")
    minimum = scorecard.get("minimum_creative_count") or 3
    missing = activity_plan_string_list(scorecard.get("missing_assets"))
    tests = activity_plan_string_list(scorecard.get("test_plan"))
    replacements = activity_plan_string_list(scorecard.get("replacement_rules"))
    parts = [
        f"状态：{ad_creative_status_label(status)}",
        f"评分 {html.escape(str(score if score is not None else '-'))}/100",
        f"素材 {html.escape(str(creative_count if creative_count is not None else '-'))}/{html.escape(str(minimum))}",
    ]
    if missing:
        parts.append("缺 " + "、".join(ad_creative_missing_label(item) for item in missing[:4]))
    summary = f"<small><b>素材冷启动：</b>{html.escape('；'.join(parts))}</small>"
    if compact:
        return summary
    test_text = "、".join(ad_creative_test_label(item) for item in tests[:4]) or "先补产品证明、钩子和优惠角度"
    replacement_text = "、".join(ad_creative_rule_label(item) for item in replacements[:3]) or "弱素材先替换再加预算"
    return (
        summary
        +
        f"<small><b>测试角度：</b>{html.escape(test_text)}</small>"
        f"<small><b>替换规则：</b>{html.escape(replacement_text)}</small>"
    )


