    labels = {
        "pause_if_spend_reaches_no_order_cap_without_order": "无订单花费到上限即暂停",
        "pause_if_roas_below_break_even_after_test_window": "测试期后 ROAS 低于保本线即暂停",
        "pause_if_refund_or_stock_sla_risk_appears": "退款/库存/SLA 异常即暂停",
        "scale_only_if_margin_inventory_and_owner_confirmation_pass": "毛利/库存/负责人确认后放量",
        "do_not_raise_budget_more_than_30_percent_per_day": "单日加预算不超过 30%",
        "refresh_creative_before_budget_increase": "加预算前先换弱素材",
        "scale_only_after_positive_roas_signal": "有正向 ROAS 信号才放量",
        "hold_until_roas_is_clear": "ROAS 不清晰先观察",
    }
    return labels.get(clean, clean.replace("_", " ") if clean else "待确认")


