def activity_plan_backend_handling_label(executor: str, can_queue: bool, submit_allowed: bool) -> str:
    clean = str(executor or "").strip()
    if clean in {"cloud_store_executor", "cloud_ads_executor", "isolated_cloud_plugin"}:
        return "确认后准备后台待执行包，真实提交前停住"
    if clean in {"ads_draft_planner", "api_mapping_planner", "activity_draft_planner"}:
        return "后台先准备草稿和缺口清单"
    if clean in {"seller_center", "ads_manager", "open_api"}:
        return "负责人按官方后台执行，系统只记录证据"
    if can_queue:
        return "确认后准备后台任务包，真实提交前停住"
    if submit_allowed:
        return "仍需二次确认后才能提交"
    return "后台先保留草稿，不自动提交"


