def approval_activity_bundle_summary(action: dict[str, Any]) -> str:
    bundle_label = str(action.get("activity_bundle_label") or "").strip()
    bundle_id = str(action.get("activity_bundle_id") or "").strip()
    if not bundle_label and not bundle_id:
        return ""
    return bundle_label or "活动和广告联动运营包"


ADS_CONFIRMATION_CONTROLS = {
    "ads_identity_gate",
    "budget_cap",
    "roas_stop_loss",
    "creative_gate",
    "rollback_ads",
}


def approval_action_is_ads_execution(action: dict[str, Any]) -> bool:
    return str(action.get("action_type") or "").strip() in {"ads_test_plan_draft", "launch_ad"}


def approval_should_hide_ads_execution_details(action: dict[str, Any]) -> bool:
    return not approval_action_is_ads_execution(action)


def approval_text_is_ads_execution_detail(text: str) -> bool:
    clean = str(text or "").strip()
    if not clean:
        return False
    markers = [
        "广告账号",
        "广告归属主体",
        "日预算",
        "预算上限",
        "ROAS",
        "素材数量",
        "止损规则",
        "暂停广告",
        "降预算",
        "停素材",
        "广告后台",
        "开启广告",
        "广告启动",
        "改预算",
        "预算调整",
        "启动投放",
        "自动放量",
    ]
    return any(marker in clean for marker in markers)


def approval_sanitize_non_ads_activity_label(label: str) -> str:
    clean = str(label or "").strip()
    if not clean:
        return ""
    clean = clean.replace(
        "确认平台、国家站点、店铺模式和真实店铺归属",
        "确认平台、国家站点、店铺模式、店铺归属、店铺路线、活动边界和广告边界",
    )
    clean = clean.replace("、利润为负或保本 ROAS 不成立", "或利润为负")
    clean = clean.replace("或保本 ROAS 不成立", "")
    clean = clean.replace("保本 ROAS 不成立时", "毛利不成立时")
    return clean


def approval_activity_checklist_summary(action: dict[str, Any]) -> str:
    if approval_action_is_ads_preflight(action):
        return "；".join(
            [
                "确认平台、国家站点、店铺模式、店铺归属、店铺路线、活动边界和广告边界",
                "确认广告账号、广告归属主体、授权数据、预算边界和报表缺口",
                "确认只生成补资料清单，不生成可投放预算",
                "确认缺口未补齐前不创建广告、不启动投放、不自动放量",
            ]
        )
    checklist = action.get("activity_owner_confirmation_checklist")
    items: list[str] = []
    controls = action.get("activity_confirmation_controls")
    if isinstance(controls, list):
        for control in controls:
            if isinstance(control, dict):
                control_id = str(control.get("control") or "").strip()
                if approval_should_hide_ads_execution_details(action) and control_id in ADS_CONFIRMATION_CONTROLS:
                    continue
                label = str(control.get("label") or "").strip()
                if label:
                    items.append(approval_sanitize_non_ads_activity_label(label) if approval_should_hide_ads_execution_details(action) else label)
    if isinstance(checklist, list):
        for item in checklist:
            text = str(item or "").strip()
            if not text:
                continue
            if approval_should_hide_ads_execution_details(action) and approval_text_is_ads_execution_detail(text):
                continue
            items.append(approval_sanitize_non_ads_activity_label(text) if approval_should_hide_ads_execution_details(action) else text)
    items = approval_unique(items)
    return "；".join(items[:6])


def approval_evidence_gap_summary(action: dict[str, Any]) -> str:
    if str(action.get("status") or "") != "execution_needs_evidence":
        return "确认前看证据；执行后必须回写截图、编号、ERP状态和回滚状态"
    checks = [
        ("execution_draft_id", "后台草稿/活动编号"),
        ("before_screenshot_ref", "执行前截图"),
        ("after_screenshot_ref", "执行后截图"),
        ("cloud_execution_log_summary", "执行日志摘要"),
        ("erp_writeback_status", "ERP回写状态"),
        ("owner_confirmation_status", "负责人确认状态"),
        ("rollback_status", "回滚状态"),
    ]
    missing = [label for key, label in checks if not str(action.get(key) or "").strip()]
    if str(action.get("erp_writeback_status") or "") in {"未回写", "回写失败", "已阻断", "鏈洖鍐?", "鍥炲啓澶辫触"}:
        missing.append("ERP成功回写")
    if str(action.get("owner_confirmation_status") or "") in {"负责人未确认", "需要复核", "负责人拒绝", "璐熻矗浜烘湭纭", "闇€瑕佸鏍?", "璐熻矗浜烘嫆缁?"}:
        missing.append("负责人最终确认")
    if str(action.get("rollback_status") or "") in {"未记录回滚状态", "需要回滚", "鏈褰曞洖婊氱姸鎬?", "闇€瑕佸洖婊?"}:
        missing.append("可接受的回滚状态")
    missing = approval_unique(missing)
    if not missing and action.get("execution_evidence_complete"):
        return "证据已完整，可闭环"
    return "待补：" + "、".join(missing[:5]) if missing else "待复核：证据字段未闭环"


def approval_blocked_external_actions_summary(action: dict[str, Any]) -> str:
    blocked = action.get("activity_blocked_external_actions")
    if not isinstance(blocked, list):
        return ""
    raw_items: list[str] = []
    for item in blocked:
        text = str(item or "").strip()
        if not text:
            continue
        if approval_should_hide_ads_execution_details(action) and approval_text_is_ads_execution_detail(text):
            continue
        raw_items.append(text)
    items = approval_unique(raw_items)
    return "；".join(
        item if item.startswith("不会") else f"不会{item}"
        for item in items[:6]
    )


def render_result_writeback_summary(action: dict[str, Any], is_approved: bool) -> str:
    stage = "等待负责人执行后回写" if is_approved else "确认前不用填写"
    requirements = [
        "官方后台草稿/活动编号",
        "执行前截图",
        "执行后截图或草稿页截图",
        "ERP回写状态",
        "负责人确认状态",
        "回滚状态",
    ]
    action_type = str(action.get("action_type") or "")
    if action_type in {"pricing_promotion_draft", "set_discount"}:
        requirements.extend(["活动价/优惠券结果", "毛利或库存异常"])
    elif action_type in {"ads_test_plan_draft", "launch_ad"}:
        if approval_action_is_ads_preflight(action):
            requirements.extend(["广告账号/归属主体缺口", "授权数据/报表缺口"])
        else:
            requirements.extend(["广告账号/预算结果", "ROAS或止损状态"])
    elif action_type == "store_connection_setup":
        requirements.extend(["授权范围", "店铺连接状态"])
    elif action_type == "after_sales_review_draft":
        requirements.extend(["订单/售后处理编号", "客户影响结果"])
    elif action_type in {"publish_listing", "update_listing", "listing_draft"}:
        requirements.extend(["商品页草稿或Listing编号", "价格/库存变化"])
    requirement_text = "；".join(approval_unique(requirements)[:8])
    minimal_fill = (
        "只填能证明执行结果的截图、编号和状态；广告花费、ROAS没有就留空"
        if approval_action_is_ads_execution(action)
        else "只填能证明执行结果的截图、编号和状态；金额、订单没有就留空"
    )
    rows = [
        ("当前阶段", stage),
        ("必须回写", requirement_text),
        ("ERP状态", "执行后选择 ERP未回写/草稿已保存/可回写/已回写/失败/阻断"),
        ("回滚", approval_rollback_text(action)),
        ("少填原则", minimal_fill),
    ]
    row_html = "".join(
        f"<span><b>{html.escape(label)}：</b>{html.escape(value)}</span>"
        for label, value in rows
        if str(value or "").strip()
    )
    return f"<div class='result-writeback-summary'><strong>负责人只看结果摘要</strong>{row_html}</div>"


def render_execution_writeback_workbench(action: dict[str, Any], is_approved: bool) -> str:
    if not is_approved:
        return ""
    action_type = str(action.get("action_type") or "")
    if action_type in {"pricing_promotion_draft", "set_discount"}:
        focus = "活动/优惠/改价"
