def safe_result_note(value: Any, fallback: str = "后台已记录，详细证据保留在内部记录。") -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    internal_markers = ("outputs/", "\\", "cloud_exec_", "cloud_profile_", "callback", "executor", "route", "token", "cookie")
    if any(marker.lower() in text.lower() for marker in internal_markers):
        return fallback
    if all(ord(char) < 128 for char in text):
        return fallback
    return text


def customer_safe_execution_draft_reference(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return "未填"
    internal_markers = (
        "round",
        "callback",
        "cloud",
        "hidden",
        "internal",
        "executor",
        "token",
        "cookie",
    )
    lowered = text.lower()
    if any(marker in lowered for marker in internal_markers):
        return "后台已记录（不向客户展示内部编号）"
    if re.search(r"\b[A-Z]{1,8}-R\d{2,}[-_A-Z0-9]*\b", text):
        return "后台已记录（不向客户展示内部编号）"
    if all(ord(char) < 128 for char in text):
        return "后台已记录（不向客户展示内部编号）"
    return customer_safe_machine_text(text, empty="未填")


def render_cloud_task_customer_summary(payload: dict[str, Any], result_record: IntakeRecord | None, missing: list[Any]) -> str:
    requirements = payload.get("activity_execution_requirements") if isinstance(payload.get("activity_execution_requirements"), dict) else {}
    scope = payload.get("execution_scope") if isinstance(payload.get("execution_scope"), dict) else {}
    ownership = approval_store_ownership_summary({"payload": payload})
    draft_outputs = activity_plan_string_list(requirements.get("required_draft_outputs"))
    materials = activity_plan_string_list(requirements.get("required_materials"))
    preflight = activity_plan_string_list(requirements.get("required_preflight_checks"))
    result_fields = activity_plan_string_list(requirements.get("required_result_fields"))
    package_type = str(scope.get("task_package_type") or "").strip()
    prepared = cloud_task_prepared_summary(draft_outputs, materials, package_type)
    missing_text = cloud_task_missing_summary(missing, preflight)
    preflight_summary = cloud_task_preflight_checkpoint_summary(payload)
    rollback = "回滚方案已列入回写" if any("rollback" in str(item) for item in [*draft_outputs, *result_fields]) else "回滚状态必须记录"
    if result_record:
        result_fields_payload = result_record.fields
        evidence_status = "证据回写完整" if result_fields_payload.get("execution_evidence_complete") else "执行证据待补"
    else:
        evidence_status = "等待执行后回写证据"
    chips = [
        ("AI已准备", prepared),
        ("店铺归属", ownership),
        ("缺少", missing_text),
        ("预检", preflight_summary),
        ("确认边界", "后台只准备证据和草稿；真实提交前停住，不自动发布、改价、发券或投广告"),
        ("回滚", rollback),
        ("结果", evidence_status),
    ]
    chip_html = "".join(
        f"<span><b>{html.escape(label)}：</b>{html.escape(value)}</span>"
        for label, value in chips
        if value
    )
    return f"<div class='cloud-task-customer-summary'><strong>客户只看后台接管</strong>{chip_html}</div>"


def cloud_task_preflight_checkpoint_summary(payload: dict[str, Any]) -> str:
    plan = payload.get("activity_execution_plan") if isinstance(payload.get("activity_execution_plan"), dict) else {}
    preflight = plan.get("operator_preflight_pack") if isinstance(plan.get("operator_preflight_pack"), dict) else {}
    checkpoints = preflight.get("checkpoints") if isinstance(preflight.get("checkpoints"), list) else []
    complete: list[str] = []
    review: list[str] = []
    confirm: list[str] = []
    execution: list[str] = []
    for checkpoint in checkpoints:
        if not isinstance(checkpoint, dict):
            continue
        label = str(checkpoint.get("label") or "").strip()
        if not label:
            continue
        status = str(checkpoint.get("status") or "").strip()
        if status in {"ready", "not_needed"}:
            complete.append(label)
        elif status == "required":
            confirm.append(label)
        elif status in {"ready_after_confirmation", "draft_only", "ready_for_confirmed_ads_draft"}:
            execution.append(f"{label}：{operator_preflight_status_label(status)}")
        else:
            review.append(f"{label}：{operator_preflight_status_label(status)}")
    parts: list[str] = []
    if complete:
        parts.append("已完成 " + "、".join(complete[:3]))
    if review:
        parts.append("待补/复核 " + "、".join(review[:3]))
    if confirm:
        parts.append("必须确认 " + "、".join(confirm[:2]))
    if execution:
        parts.append("执行包 " + "、".join(execution[:2]))
    return "；".join(parts)


def render_cloud_task_execution_watchboard(
    payload: dict[str, Any],
    evidence: list[Any],
    result_record: IntakeRecord | None,
) -> str:
    steps = activity_plan_string_list(payload.get("allowed_steps"))
    blocked = activity_plan_string_list(payload.get("blocked_boundaries"))
    contract = payload.get("evidence_contract") if isinstance(payload.get("evidence_contract"), dict) else {}
    identity = payload.get("execution_identity") if isinstance(payload.get("execution_identity"), dict) else {}
    identity_text = (
        "一店一后台执行身份；任务包不携带密码、登录凭证或密钥"
        if identity.get("one_store_one_identity") is True
        else "执行身份待负责人确认"
    )
    ownership = approval_store_ownership_summary({"payload": payload})
    allowed_text = "、".join(cloud_allowed_step_label(item) for item in steps[:5]) or "只准备草稿和证据"
    blocked_text = "、".join(cloud_blocked_boundary_label(item) for item in blocked[:5]) or "真实外部提交前停住"
    required_fields = activity_plan_string_list(contract.get("required_result_fields")) or evidence
    writeback_text = "、".join(evidence_requirement_label(item) for item in required_fields[:6]) or "截图、日志、ERP 回写和回滚状态"
    evidence_status = "已回写结果" if result_record else "等待执行后回写"
    rows = [
        ("店铺归属", ownership),
        ("执行身份", identity_text),
        ("允许步骤", allowed_text),
        ("禁止边界", blocked_text),
        ("必须回写", writeback_text),
        ("回写状态", evidence_status),
    ]
    row_html = "".join(
        f"<span><b>{html.escape(label)}：</b>{html.escape(value)}</span>"
        for label, value in rows
        if value
    )
    return f"<div class='cloud-execution-watchboard'><strong>后台执行看板</strong>{row_html}</div>"


def cloud_task_prepared_summary(drafts: list[str], materials: list[str], package_type: str) -> str:
    text = " ".join([*drafts, *materials, package_type]).lower()
    parts: list[str] = []
    if any(signal in text for signal in ["discount", "coupon", "voucher", "deal", "promotion", "free_shipping", "shipping"]):
        parts.append("活动/优惠草稿")
    if any(signal in text for signal in ["ads", "ad_", "sponsored", "budget", "campaign", "roas", "acos"]):
        parts.append("广告预算和停损草稿")
    if any(signal in text for signal in ["creator", "affiliate", "commission"]):
        parts.append("达人/联盟方案")
    if any(signal in text for signal in ["listing", "catalog", "asset", "feed"]):
        parts.append("商品/素材草稿")
    if any(signal in text for signal in ["rollback"]):
        parts.append("回滚方案")
    if not parts and (drafts or materials):
        parts.append("后台执行草稿")
    return "、".join(dict.fromkeys(parts)) if parts else "后台任务包已生成"


def cloud_task_missing_summary(missing: list[Any], preflight: list[str]) -> str:
    missing_values = [str(item or "").strip() for item in missing if str(item or "").strip()]
    if missing_values:
        return "、".join(activity_plan_missing_label(item) for item in missing_values[:4])
    text = " ".join(preflight).lower()
    if "ads_account" in text or "business_center" in text:
        return "需核对广告账号和归属主体"
    if "authorization" in text or "scope" in text or "permission" in text or "token" in text:
        return "需核对店铺/插件权限"
    if "margin" in text or "price" in text or "shipping" in text or "sla" in text:
        return "需核对毛利、库存和配送"
    return "暂未缺关键前置"


def render_cloud_execution_task_row(record: IntakeRecord, result_by_action: dict[str, IntakeRecord] | None = None) -> str:
    fields = record.fields
    payload = fields.get("payload") if isinstance(fields.get("payload"), dict) else {}
    evidence = payload.get("required_evidence") if isinstance(payload.get("required_evidence"), list) else []
    execution_identity = payload.get("execution_identity") if isinstance(payload.get("execution_identity"), dict) else {}
    route_payload = payload.get("route") if isinstance(payload.get("route"), dict) else {}
    scope = payload.get("execution_scope") if isinstance(payload.get("execution_scope"), dict) else {}
    identity = fields.get("execution_identity_ref") or execution_identity.get("identity_ref") or ""
    route = fields.get("route_key") or route_payload.get("route_key") or ""
    route_label = customer_route_key_label(route) if route else ""
    action = payload.get("action") if isinstance(payload.get("action"), dict) else {}
    title = customer_safe_action_title(action.get("title") or action.get("action_type") or fields.get("task_type") or "")
    package_label = str(fields.get("task_package_label") or scope.get("task_package_label") or "后台待执行包")
    readiness_label = str(fields.get("execution_readiness_label") or scope.get("execution_readiness_label") or "等待处理")
    raw_status = str(fields.get("status") or "waiting_owner_manual_execution")
    source_action_id = str(fields.get("source_action_id") or "")
    result_record = result_by_action.get(source_action_id) if result_by_action else None
    writeback_html = render_cloud_task_writeback_summary(result_record) if result_record else ""
    missing = fields.get("missing_prerequisites") or scope.get("missing_prerequisites") or []
    if not isinstance(missing, list):
        missing = [str(missing)]
    status_detail = cloud_task_status_label(raw_status)
    if missing:
        status_detail += " / 缺 " + "、".join(evidence_requirement_label(item) for item in missing[:4])
    decision_feedback = fields.get("decision_feedback") if isinstance(fields.get("decision_feedback"), dict) else {}
    task_next_step = str(fields.get("customer_next_step") or decision_feedback.get("next_step") or "").strip()
    task_feedback_html = f"<div class='muted'>{html.escape(task_next_step)}</div>" if task_next_step else ""
    task_context = dict(fields)
    task_context["payload"] = payload
    activity_plan_html = render_activity_execution_plan_summary(task_context, compact=True)
    evidence_text = "、".join(label for label in (evidence_requirement_label(item) for item in evidence[:5]) if label)
    identity_text = "执行身份已准备" if identity else "执行身份待生成"
    ownership = approval_store_ownership_summary(task_context)
    customer_summary_html = render_cloud_task_customer_summary(payload, result_record, missing)
    watchboard_html = render_cloud_task_execution_watchboard(payload, evidence, result_record)
    return (
        "<tr>"
        f"<td>{html.escape(package_label)}<div>{html.escape(title)}</div><div class='muted'>任务编号和后台日志已收进内部记录。</div></td>"
        f"<td>{html.escape(str(route_label or '路径待确认'))}<div class='muted'>{html.escape(ownership or '店铺归属待确认')}</div><div class='muted'>{html.escape(identity_text)}</div></td>"
        f"<td>{html.escape(readiness_label)}<div class='muted'>{html.escape(status_detail)}</div>{task_feedback_html}{activity_plan_html}{writeback_html}</td>"
        f"<td>{customer_summary_html}{watchboard_html}<details class='review-details'><summary>负责人复核证据</summary>{html.escape(evidence_text or '等待后台回写证据')}{render_execution_evidence_summary(result_record) if result_record else ''}</details></td>"
        "</tr>"
    )


def render_cloud_task_writeback_summary(record: IntakeRecord | None) -> str:
    if not record:
        return ""
    fields = record.fields
    complete = "完整" if fields.get("execution_evidence_complete") else "待补"
    parts = [
        f"草稿 {customer_safe_execution_draft_reference(fields.get('execution_draft_id'))}",
        f"ERP {customer_safe_erp_writeback_status(fields.get('erp_writeback_status'))}",
        f"负责人 {customer_safe_owner_confirmation_status(fields.get('owner_confirmation_status'))}",
        f"回滚 {customer_safe_rollback_status(fields.get('rollback_status'))}",
        f"证据 {complete}",
        "系统未自动提交平台",
    ]
    return f"<div class='muted'>{html.escape(' / '.join(str(item) for item in parts))}</div>"


def customer_safe_erp_writeback_status(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return "ERP未回写"
    if "已回写" in text or "writeback_success" in text:
        return "ERP已记录回写"
    if "草稿" in text or "draft_saved" in text:
        return "草稿已保存，待ERP回写"
    if "可回写" in text or "writeback_ready" in text:
        return "可回写，等待负责人处理"
    if "失败" in text or "writeback_failed" in text:
        return "ERP回写失败，需复核"
    if "阻断" in text or "blocked" in text:
        return "已阻断外部提交"
    if "未回写" in text or "not_started" in text:
        return "ERP未回写"
    if re.fullmatch(r"[a-z0-9_\-]+", text.lower()):
        return "ERP状态已记录，需内部复核"
    return text


def customer_safe_owner_confirmation_status(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return "负责人未确认"
    if "已确认" in text or text == "confirmed":
        return "负责人已登记确认（系统未自动提交平台）"
    if "未确认" in text or "not_confirmed" in text:
        return "负责人未确认"
    if "复核" in text or "needs_recheck" in text:
        return "需要负责人复核"
    if "拒绝" in text or "rejected" in text:
        return "负责人拒绝"
    if "not_required_image_slot_evidence_only" in text:
        return "本次仅记录图片位证据，无需负责人外部提交"
    if "not_required" in text:
        return "本次无需负责人外部提交"
    if re.fullmatch(r"[a-z0-9_\-]+", text.lower()):
        return "负责人状态已记录，需内部复核"
    return text


def customer_safe_rollback_status(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return "未记录回滚状态"
    if "阻断外部提交" in text or "rollback_blocked" in text:
        return "已阻断外部提交（未自动提交平台）"
    if "不需要回滚" in text or "not_needed" in text:
        return "不需要回滚"
    if "准备回滚" in text or "rollback_ready" in text:
        return "已准备回滚"
    if "完成回滚" in text or "rollback_completed" in text:
        return "已完成回滚"
    if "需要回滚" in text or "needs_rollback" in text:
        return "需要回滚"
    if "未记录" in text:
        return "未记录回滚状态"
    if re.fullmatch(r"[a-z0-9_\-]+", text.lower()):
        return "回滚状态已记录，需内部复核"
    return text


def render_execution_evidence_summary(record: IntakeRecord | None) -> str:
    if not record:
        return ""
    fields = record.fields
    lines = [
        f"草稿/活动编号：{customer_safe_execution_draft_reference(fields.get('execution_draft_id'))}",
        f"执行前证据：{'已上传' if fields.get('before_screenshot_ref') else '未填'}",
        f"执行后证据：{'已上传' if fields.get('after_screenshot_ref') else '未填'}",
        f"ERP：{customer_safe_erp_writeback_status(fields.get('erp_writeback_status'))}",
        f"负责人：{customer_safe_owner_confirmation_status(fields.get('owner_confirmation_status'))}",
        f"回滚：{customer_safe_rollback_status(fields.get('rollback_status'))}",
        "边界：系统未自动提交平台，真实动作由负责人手动处理并回写证据",
    ]
    log_summary = str(fields.get("cloud_execution_log_summary") or "").strip()
    if log_summary:
        lines.append(f"执行记录：{safe_result_note(log_summary)}")
    note = str(fields.get("erp_writeback_note") or "").strip()
    if note:
        lines.append(f"回写说明：{safe_result_note(note, 'ERP 回写说明已保留在内部记录。')}")
    rollback_note = str(fields.get("rollback_note") or "").strip()
    if rollback_note:
        lines.append(f"回滚说明：{safe_result_note(rollback_note, '回滚说明已保留在内部记录。')}")
    owner_review_summary = amazon_10001_owner_review_evidence_summary(fields)
    if owner_review_summary:
        lines.append(owner_review_summary)
    repair_followup_summary = amazon_10001_repair_followup_evidence_summary(fields)
    if repair_followup_summary:
        lines.append(repair_followup_summary)
    return "<div class='muted'>" + html.escape("；".join(lines)) + "</div>"


def amazon_10001_owner_review_evidence_summary(fields: dict[str, Any]) -> str:
    evidence = [
        ("Listing", "amazon_10001_listing_review_ref"),
        ("广告关键词", "amazon_10001_ads_keywords_ref"),
        ("优惠利润", "amazon_10001_promotion_profit_ref"),
        ("结算回款", "amazon_10001_settlement_cashflow_ref"),
        ("成本输入", "amazon_10001_cost_input_values_ref"),
        ("外部提交阻断", "amazon_10001_external_submit_blocked_ref"),
    ]
    present = [label for label, key in evidence if str(fields.get(key) or "").strip()]
    if not present:
        return ""
    missing = [label for label, key in evidence if not str(fields.get(key) or "").strip()]
    text = "Amazon 10001复核证据：" + "、".join(present)
    if missing:
        text += "；待补：" + "、".join(missing)
    return text


def amazon_10001_repair_followup_evidence_summary(fields: dict[str, Any]) -> str:
    is_repair_task = str(fields.get("task_package_type") or "") == "amazon_10001_repair_followup"
    has_repair_specific_evidence = bool(
        str(fields.get("amazon_10001_repair_module_ref") or "").strip()
        or str(fields.get("amazon_10001_repair_blocker_summary_ref") or "").strip()
    )
    if not (is_repair_task or has_repair_specific_evidence):
        return ""
    evidence = [
        ("修复模块", "amazon_10001_repair_module_ref"),
        ("阻塞摘要", "amazon_10001_repair_blocker_summary_ref"),
        ("外部提交阻断", "amazon_10001_external_submit_blocked_ref"),
        ("页面匹配", "amazon_10001_repair_page_match_status"),
        ("下一步", "amazon_10001_repair_next_safe_step"),
    ]
    present = [label for label, key in evidence if str(fields.get(key) or "").strip()]
    if not present:
        return ""
    missing = [label for label, key in evidence if not str(fields.get(key) or "").strip()]
    text = "Amazon 10001字段修复证据：" + "、".join(present)
    if missing:
        text += "；待补：" + "、".join(missing)
    return text


def render_execution_customer_result_summary(record: IntakeRecord, outcome_label: str) -> str:
    fields = record.fields
    evidence_status = "证据回写完整" if fields.get("execution_evidence_complete") else "执行证据待补"
    erp_status = customer_safe_erp_writeback_status(fields.get("erp_writeback_status"))
    owner_status = customer_safe_owner_confirmation_status(fields.get("owner_confirmation_status"))
    rollback_status = customer_safe_rollback_status(fields.get("rollback_status"))
    has_business_data = any(
        str(fields.get(key) or "").strip()
        for key in ("after_revenue", "after_orders", "after_ad_spend", "after_refund_amount", "after_return_count", "after_roas")
    )
    business_result = (
        f"销售额 {money(fields.get('after_revenue'))} / 订单 {html.escape(str(fields.get('after_orders') or 0))} / ROAS {ratio(fields.get('after_roas'))}"
        if has_business_data
        else "暂无销售、订单或ROAS数据，等待 24-72 小时复盘"
    )
    rows = [
        ("结果", outcome_label),
        ("证据", evidence_status),
        ("ERP", erp_status),
        ("负责人", owner_status),
        ("回滚", rollback_status),
        ("执行边界", "系统未自动提交平台；负责人手动执行后回写证据"),
        ("业务数据", business_result),
    ]
    row_html = "".join(
        f"<span><b>{html.escape(label)}：</b>{html.escape(value)}</span>"
        for label, value in rows
        if str(value or "").strip()
    )
    return f"<div class='cloud-task-customer-summary'><strong>客户只看执行结果</strong>{row_html}</div>"


def render_execution_result_row(record: IntakeRecord) -> str:
    fields = record.fields
    metrics = (
        f"销售额 {money(fields.get('after_revenue'))}<br>"
        f"订单 {html.escape(str(fields.get('after_orders') or 0))}<br>"
        f"ROAS {ratio(fields.get('after_roas'))}<br>"
        f"退款 {money(fields.get('after_refund_amount'))}"
    )
    outcome = str(fields.get("outcome") or "unknown")
    outcome_label = {"unknown": "等待 24-72 小时数据", "success": "表现可复盘", "failed": "执行未达预期"}.get(outcome, outcome)
    return (
        "<tr>"
        f"<td>{html.escape(customer_safe_execution_result_title(fields))}<div class='muted'>内部动作编号已收进后台记录。</div></td>"
        f"<td>{html.escape(outcome_label)}</td>"
        f"<td>{metrics}</td>"
        f"<td>{render_execution_customer_result_summary(record, outcome_label)}{html.escape(str(fields.get('learning_summary') or ''))}<div class='muted'>{html.escape(str(fields.get('next_rule') or ''))}</div>{render_execution_evidence_summary(record)}</td>"
        "</tr>"
    )


def render_execution_memory_row(record: IntakeRecord) -> str:
    fields = record.fields
    valid_when = fields.get("valid_when") if isinstance(fields.get("valid_when"), list) else []
    guardrails = fields.get("what_not_to_do") if isinstance(fields.get("what_not_to_do"), list) else []
    return (
        "<tr>"
        f"<td>{html.escape(str(fields.get('strategy_stage') or ''))}</td>"
        f"<td>{html.escape(str(fields.get('recommendation') or fields.get('rule_summary') or ''))}</td>"
        f"<td>{html.escape(', '.join(str(item) for item in valid_when))}</td>"
        f"<td>{html.escape(', '.join(str(item) for item in guardrails))}</td>"
        "</tr>"
    )


def render_approval_table(col1: str, col2: str, col3: str, col4: str, rows: str, empty: str) -> str:
    if not rows:
        return empty
    return f"<table><thead><tr><th>{col1}</th><th>{col2}</th><th>{col3}</th><th>{col4}</th></tr></thead><tbody>{rows}</tbody></table>"


def render_workflow_page(root: Path) -> str:
    status_payload = build_workflow_status(root)
    rows = "".join(render_workflow_stage_row(stage) for stage in status_payload["stages"])
    blockers = status_payload.get("blocking_items", [])
    blocker_html = render_workflow_blockers(blockers)
    summary = status_payload["summary"]
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>工作流自检</title>
  <style>{simple_page_css()}
    main {{ max-width: 1220px; }}
    .status-ready {{ color: #047857; font-weight: 700; }}
    .status-partial {{ color: #b45309; font-weight: 700; }}
    .status-needs_config, .status-empty, .status-blocked {{ color: #b91c1c; font-weight: 700; }}
    .summary-grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; margin-top: 16px; }}
    .metric-card {{ border: 1px solid #e8edf2; border-radius: 8px; padding: 14px; background: #fff; }}
    .metric-card span {{ display: block; color: #7b8490; font-size: 12px; margin-bottom: 7px; }}
    .metric-card strong {{ font-size: 22px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e8edf2; }}
    th, td {{ padding: 10px; border-bottom: 1px solid #e8edf2; text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: #111318; }}
    details summary {{ cursor: pointer; color: #087986; }}
    .warning {{ background: #fff7ed; border: 1px solid #fed7aa; border-radius: 8px; padding: 12px; color: #9a3412; }}
  </style>
</head>
<body>
  <header>
    <h1>工作流自检</h1>
    <div class="muted">这个页面用来检查智能体到底哪里能跑、哪里只是模板、哪里需要你配置或人工验证。</div>
    <div class="actions">
      <a class="button secondary" href="/dashboard">返回控制台</a>
      <a class="button secondary" href="/chat">店铺AI顾问</a>
      <a class="button secondary" href="/api-sources">平台连接</a>
      <a class="button secondary" href="/platform-autopilot">平台巡检</a>
      <a class="button secondary" href="/dashboard">今日工作台</a>
      <a class="button secondary" href="/multi-ai">多AI大脑</a>
    </div>
  </header>
  <main>
    <section class="summary-grid">
      <div class="metric-card"><span>整体状态</span><strong>{html.escape(str(status_payload["overall_status"]))}</strong></div>
      <div class="metric-card"><span>可用环节</span><strong>{html.escape(str(summary["ready"]))}</strong></div>
      <div class="metric-card"><span>部分可用</span><strong>{html.escape(str(summary["partial"]))}</strong></div>
      <div class="metric-card"><span>需要配置/空数据</span><strong>{html.escape(str(summary["needs_config"]))}</strong></div>
      <div class="metric-card"><span>经验资料</span><strong>{html.escape(str(summary["records"]))}</strong></div>
    </section>

    <section class="panel">
      <h2>现在卡在哪里</h2>
      {blocker_html}
    </section>

    <section class="panel">
      <h2>运行监督</h2>
      <p class="muted">点击后会跑一次安全自动流程：只读平台数据、公开页面、POD快照、报告、动作队列。不会自动登录、过滑块、上架、改价、报活动或联系达人。</p>
      <div class="actions">
        <button id="run">让智能体自己跑一遍安全流程</button>
        <button id="refresh" class="secondary">刷新自检</button>
      </div>
      <div id="status"></div>
    </section>

    <section class="panel">
      <h2>工作流环节</h2>
      <table>
        <thead><tr><th>环节</th><th>状态</th><th>说明</th><th>下一步</th><th>入口</th><th>细节</th></tr></thead>
        <tbody id="stageRows">{rows}</tbody>
      </table>
    </section>

    <section class="panel">
      <h2>安全边界</h2>
      <ul>
        <li>可以自动：读取已配置数据源、保存采集数据、生成报告、拆解视频脚本、生成Listing/达人/内容草稿、生成动作队列。</li>
        <li>必须人工确认：登录、滑块/验证码、上架或改Listing、改价、改库存、折扣、活动报名、联系达人、上传素材、购买IP、修改店铺设置、付款、发货、申诉、授权。</li>
      </ul>
    </section>
  </main>
  <script>
    function escapeHtml(value) {{
      return String(value).replace(/[&<>"']/g, (char) => ({{
        "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;"
      }}[char]));
    }}
    function renderStage(stage) {{
      const url = stage.url ? `<a href="${{escapeHtml(stage.url)}}">打开</a>` : "";
      const details = `<details><summary>查看</summary><pre>${{escapeHtml(JSON.stringify(stage.details, null, 2))}}</pre></details>`;
      return `<tr>
        <td>${{escapeHtml(stage.name)}}<div class="muted">${{escapeHtml(stage.id)}}</div></td>
        <td class="status-${{escapeHtml(stage.status)}}">${{escapeHtml(stage.status)}}</td>
        <td>${{escapeHtml(stage.summary)}}</td>
        <td>${{escapeHtml(stage.next_action)}}</td>
        <td>${{url}}</td>
        <td>${{details}}</td>
      </tr>`;
    }}
    async function refreshWorkflow() {{
      const response = await fetch("/api/workflow/status");
      const payload = await response.json();
      document.getElementById("stageRows").innerHTML = payload.stages.map(renderStage).join("");
      return payload;
    }}
    document.getElementById("run").addEventListener("click", async () => {{
      const status = document.getElementById("status");
      status.textContent = "正在生成今日结论、报告和待确认动作...";
      const response = await fetch("/api/workflow/run", {{
        method: "POST",
        headers: {{ "Content-Type": "application/json" }},
        body: JSON.stringify({{}})
      }});
      const payload = await response.json();
      if (!payload.ok) {{
        status.textContent = "运行失败：" + payload.error;
        return;
      }}
      const workflow = payload.workflow;
      status.textContent = "已完成。动作队列：" + payload.run.action_queue_path + "；整体状态：" + workflow.overall_status;
      document.getElementById("stageRows").innerHTML = workflow.stages.map(renderStage).join("");
    }});
    document.getElementById("refresh").addEventListener("click", async () => {{
      const payload = await refreshWorkflow();
      document.getElementById("status").textContent = "已刷新。整体状态：" + payload.overall_status;
    }});
  </script>
</body>
</html>"""


def render_workflow_stage_row(stage: dict[str, Any]) -> str:
    url = str(stage.get("url") or "")
    url_html = f"<a href='{html.escape(url)}'>打开</a>" if url else ""
    details = html.escape(json.dumps(stage.get("details", {}), ensure_ascii=False, indent=2))
    status = str(stage.get("status") or "")
    return (
        "<tr>"
        f"<td>{html.escape(str(stage.get('name') or ''))}<div class='muted'>{html.escape(str(stage.get('id') or ''))}</div></td>"
        f"<td class='status-{html.escape(status)}'>{html.escape(status)}</td>"
        f"<td>{html.escape(str(stage.get('summary') or ''))}</td>"
        f"<td>{html.escape(str(stage.get('next_action') or ''))}</td>"
        f"<td>{url_html}</td>"
        f"<td><details><summary>查看</summary><pre>{details}</pre></details></td>"
        "</tr>"
    )


def render_workflow_blockers(blockers: list[dict[str, Any]]) -> str:
    if not blockers:
        return "<div class='empty'>没有发现阻塞项。可以继续跑报告、采集和动作队列。</div>"
    items = "".join(
        "<li>"
        f"<strong>{html.escape(str(item.get('name') or item.get('stage_id') or ''))}</strong>"
        f"：{html.escape(str(item.get('status') or ''))}。"
        f"{html.escape(str(item.get('next_action') or ''))}"
        "</li>"
        for item in blockers
    )
    return f"<div class='warning'><ul>{items}</ul></div>"


