def safe_approval_decision_response(result: dict[str, Any]) -> dict[str, Any]:
    action = result.get("action") if isinstance(result.get("action"), dict) else {}
    feedback = result.get("decision_feedback") if isinstance(result.get("decision_feedback"), dict) else {}
    response: dict[str, Any] = {
        "decision_feedback": feedback,
        "summary": result.get("summary") if isinstance(result.get("summary"), dict) else {},
    }
    action_id = str(action.get("action_id") or "").strip()
    if action_id:
        response["action"] = {
            "action_id": action_id,
            "status": action_state(action),
            "title": approval_title_text(action),
            "type_label": approval_action_type_label_for_action(action),
            "route_label": approval_route_display_label(action),
            "requires_confirmation": bool(action.get("requires_confirmation", True)),
            "external_submit_allowed": False,
        }
    if result.get("batch_count") is not None:
        response["batch_count"] = result.get("batch_count")
    if isinstance(result.get("actions"), list):
        response["actions"] = [
            {
                "action_id": str(item.get("action_id") or ""),
                "status": action_state(item),
                "title": approval_title_text(item),
                "route_label": approval_route_display_label(item),
            }
            for item in result["actions"][:50]
            if isinstance(item, dict)
        ]
    return response


