def is_admin_page_path(path: str) -> bool:
    return path in ADMIN_ONLY_PAGE_PATHS


def route_path(url: str) -> str:
    raw = str(url or "")
    try:
        parsed = urlparse(raw)
        return parsed.path or raw.split("?", 1)[0].split("#", 1)[0]
    except Exception:
        return raw.split("?", 1)[0].split("#", 1)[0]


def is_seller_safe_url(url: str) -> bool:
    path = route_path(url)
    if not path.startswith("/"):
        return True
    if is_admin_page_path(path):
        return False
    return not any(path == prefix or path.startswith(prefix + "/") for prefix in ADMIN_ONLY_PATHS)


