def render_skill_agents_page(root: Path) -> str:
    css = simple_page_css()
    agents = skill_agents.list_skill_agents(root)
    cards = ""
    for agent in agents:
        sid = agent["id"]
        head = (
            f"<h3 style='margin:0 0 4px;'>{html.escape(str(agent['name']))}</h3>"
            f"<div class='muted'>{html.escape(str(agent['agent_module']))} · {html.escape(str(agent['key_thresholds']))[:140]}</div>"
        )
        if agent["executable"] and sid in _SKILL_AGENT_FIELDS:
            inputs = "".join(
                (
                    f"<label class='f'>{html.escape(label)} "
                    + (
                        f"<input type='checkbox' data-field='{html.escape(field)}'>"
                        if ftype == "checkbox"
                        else f"<input data-field='{html.escape(field)}'>"
                    )
                    + "</label>"
                )
                for field, label, ftype in _SKILL_AGENT_FIELDS[sid]
            )
            body = (
                f"<div class='skill' data-skill='{html.escape(sid)}'>"
                f"<div class='fields'>{inputs}</div>"
                "<div class='bar'><button onclick='runSkill(this)'>运行</button></div>"
                "<pre class='result muted'>填入数据后点运行。</pre></div>"
            )
        elif sid == "tk-product-selection":
            body = "<div class='muted'>用 <a href='/product-scout'>六维选品打分</a> 运行（已是独立页面）。</div>"
        else:
            body = "<div class='muted'>方法论能力：按标准给运营判断，会在对应模块的分析里生效。</div>"
        cards += f"<section class='panel'>{head}{body}</section>"
    script = (
        "async function runSkill(btn){ const box=btn.closest('.skill'); const skill_id=box.dataset.skill; const payload={};\n"
        " box.querySelectorAll('[data-field]').forEach(i=>{ if(i.type==='checkbox'){ if(i.checked) payload[i.dataset.field]=true; } else if(i.value.trim()){ payload[i.dataset.field]=i.value.trim(); } });\n"
        " const out=box.querySelector('.result'); out.textContent='运行中...';\n"
        " try{ const r=await fetch('/api/skill-agent/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({skill_id,payload})}); const d=await r.json();\n"
        "  out.textContent = d.ok ? JSON.stringify(d.result, null, 2) : ('失败：'+(d.error||r.status)); out.classList.toggle('muted', false);\n"
        " }catch(e){ out.textContent='失败：'+e.message; } }\n"
    )
    return f"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><title>运营能力（TK体系2.0）</title><style>{css}
    main {{ max-width: 1000px; margin: 0 auto; padding: 22px 24px 50px; }}
    .panel {{ background:#fff; border:1px solid var(--line); border-radius:10px; padding:16px; margin-top:12px; }}
    .fields {{ display:flex; flex-wrap:wrap; gap:10px; margin-top:10px; }}
    .f {{ font-size:13px; font-weight:700; display:flex; flex-direction:column; gap:4px; }}
    .f input {{ width:150px; padding:7px 8px; }}
    .f input[type=checkbox] {{ width:auto; }}
    .bar {{ margin-top:10px; }}
    button {{ border:0; border-radius:8px; padding:9px 16px; font-weight:800; cursor:pointer; background:var(--primary); color:#fff; }}
    pre.result {{ margin-top:10px; background:var(--soft); border:1px solid var(--line); border-radius:8px; padding:10px; white-space:pre-wrap; }}
  </style></head>
<body>
  <header>
    <h1>运营能力 · TK体系2.0</h1>
    <div class="muted">把课程标准变成可运行的运营判断：输入数据 → 按 TK体系2.0 阈值给判定。<a href="/admin-console">返回管理员后台</a></div>
  </header>
  <main>{cards}</main>
  <script>{script}</script>
</body></html>"""


_WEB_AUDIT_PRESETS: list[tuple[str, str]] = []


def render_web_audit_page(root: Path) -> str:
    css = simple_page_css()
    presets = "".join(
        f"<button class='mini' onclick=\"setPath(this)\" data-path='{html.escape(path)}'>{html.escape(label)}</button>"
        for label, path in _WEB_AUDIT_PRESETS
    )
    script = (
        "function setPath(b){ document.getElementById('path').value=b.dataset.path; }\n"
        "async function audit(){ const path=document.getElementById('path').value.trim(); const out=document.getElementById('out'); out.innerHTML='体检中...';\n"
        " try{ const r=await fetch('/api/web-audit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path})}); const d=await r.json();\n"
        "  if(!d.ok){ out.textContent='失败：'+(d.error||r.status); return; } const rep=d.report;\n"
        "  let h='<div class=\"score\">综合 '+rep.score+'/100（'+rep.passed+'/'+rep.total+' 项通过）</div>';\n"
        "  if(rep.note) h+='<div class=\"muted\">'+rep.note+'</div>';\n"
        "  const sf=rep.site_files||{}; h+='<div class=\"muted\">站点文件：sitemap.xml '+(sf['sitemap.xml']?'✅':'⚠️缺')+' · robots.txt '+(sf['robots.txt']?'✅':'⚠️缺')+' · llms.txt(GEO) '+(sf['llms.txt']?'✅':'⚠️缺')+'</div>';\n"
        "  ['SEO','AEO','GEO'].forEach(area=>{ const items=(rep.checks||[]).filter(c=>c.area===area); if(!items.length) return; h+='<h3>'+area+'</h3><table>'; items.forEach(c=>{ h+='<tr><td>'+(c.ok?'✅':'⚠️')+'</td><td>'+c.item+'</td><td class=\"muted\">'+(c.detail||'')+'</td><td class=\"muted\">'+(c.ok?'':c.fix)+'</td></tr>'; }); h+='</table>'; });\n"
        "  out.innerHTML=h;\n"
        " }catch(e){ out.textContent='失败：'+e.message; } }\n"
    )
    return f"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><title>网站 SEO/AEO/GEO 体检</title><style>{css}
    main {{ max-width: 1000px; margin: 0 auto; padding: 22px 24px 50px; }}
    .panel {{ background:#fff; border:1px solid var(--line); border-radius:10px; padding:16px; margin-top:12px; }}
    input {{ width:100%; max-width:560px; padding:8px 10px; }}
    .mini {{ font-size:12px; font-weight:800; border:1px solid var(--line); border-radius:6px; padding:6px 10px; background:#fff; color:var(--ink); cursor:pointer; margin-right:6px; }}
    button.primary {{ border:0; border-radius:8px; padding:9px 16px; font-weight:800; cursor:pointer; background:var(--primary); color:#fff; }}
    table {{ width:100%; border-collapse:collapse; margin-top:6px; }}
    td {{ border-bottom:1px solid var(--line); padding:7px; font-size:13px; vertical-align:top; }}
    .score {{ font-size:20px; font-weight:800; margin:8px 0; }}
    h3 {{ margin:14px 0 4px; }}
  </style></head>
<body>
  <header>
    <h1>网站 SEO / AEO / GEO 体检</h1>
    <div class="muted">对你自有站点做只读体检，给逐项通过/未过 + 修复建议。SEO=传统搜索；AEO=答案引擎；GEO=AI生成引擎。<a href="/admin-console">返回后台</a></div>
  </header>
  <main>
    <section class="panel">
      <div style="margin-bottom:8px;">{presets}</div>
      <label>站点目录（本机路径，含 index.html）</label>
      <input id="path" placeholder="例如 C:\\path\\to\\site">
      <div style="margin-top:10px;"><button class="primary" onclick="audit()">体检</button></div>
    </section>
    <section class="panel"><div id="out" class="muted">选一个站或填路径，点体检。</div></section>
  </main>
  <script>{script}</script>
</body></html>"""


_SKILL_PLATFORM_GROUPS = [
    ("TikTok 体系2.0", "tk-"),
    ("Amazon", "amazon-"),
    ("独立站 DTC", "dtc-"),
    ("外贸 B2B", "b2b-"),
]


def render_skill_console_page(root: Path) -> str:
    css = simple_page_css()
    agents = skill_agents.list_skill_agents(root)
    total_count = len(agents)
    executable_count = len([agent for agent in agents if agent.get("executable")])
    connector_count = len([agent for agent in agents if agent.get("kind") == "connector"])
    methodology_count = max(0, total_count - executable_count)
    summary_cards = "".join(
        f"<div class='cap-card'><span>{html.escape(label)}</span><strong>{value}</strong><small>{html.escape(desc)}</small></div>"
        for label, value, desc in [
            ("能力总数", total_count, "平台、选品、内容、风控、POD 和外部工具"),
            ("本地可运行", executable_count, "可直接用本地记录或表单跑出判断"),
            ("外部连接器", connector_count, "需要 key、账号或授权后才可接真数据"),
            ("方法论能力", methodology_count, "作为报告、员工和流程的判断标准"),
        ]
    )
    groups = ""
    for group_name, prefix in _SKILL_PLATFORM_GROUPS:
        members = [a for a in agents if str(a["id"]).startswith(prefix)]
        if not members:
            continue
        rows = ""
        for agent in members:
            sid = agent["id"]
            batchable = sid in skill_agents.BATCH_SUPPORTED
            kind = str(agent.get("kind") or "operation")
            if kind == "connector":
                kind_label = "外部连接器"
                state = "待配置" if not agent.get("enabled", True) else "可检查"
            elif agent["executable"]:
                kind_label = "本地能力"
                state = "可运行"
            else:
                kind_label = "方法论"
                state = "进入报告标准"
            actions = "<a class='mini' href='/skill-agents'>单项运行</a>"
            if batchable:
                actions += f" <button class='mini' onclick=\"runBatch('{html.escape(sid)}', this)\">批量跑本地数据</button>"
            rows += (
                f"<tr><td>{html.escape(str(agent['name']))}<div class='muted'>后台编号：{html.escape(sid)}</div></td>"
                f"<td><span class='pill'>{html.escape(kind_label)}</span><div class='muted'>{html.escape(state)}</div></td>"
                f"<td class='muted'>{html.escape(str(agent['agent_module']))}<br>{html.escape(str(agent['key_thresholds']))[:120]}</td>"
                f"<td>{actions}</td></tr>"
                f"<tr class='report' data-for='{html.escape(sid)}'><td colspan='4'></td></tr>"
            )
        groups += (
            f"<section class='panel'><h2>{html.escape(group_name)}（{len(members)}）</h2>"
            f"<table><thead><tr><th>能力</th><th>类型</th><th>用途 / 判断标准</th><th>操作</th></tr></thead><tbody>{rows}</tbody></table></section>"
        )
    safety_html = """
    <section class="panel safety-panel">
      <h2>使用边界</h2>
      <div class="rule-grid">
        <div><strong>卖家端不显示</strong><span>Skill、原始证据、密钥、采集配置、内部训练库。</span></div>
        <div><strong>模型先过滤</strong><span>给外部模型前先走数据网关，去掉路径、凭证、买家信息和底价。</span></div>
        <div><strong>真实动作不自动执行</strong><span>发布、改价、投流、退款、发货、授权和联系达人只进待确认队列。</span></div>
      </div>
    </section>
    """
    script = (
        "async function runBatch(skill_id, btn){ const cell=document.querySelector(\".report[data-for='\"+skill_id+\"'] td\"); cell.textContent='批量运行中...';\n"
        " try{ const r=await fetch('/api/skill-agent/batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({skill_id})}); const d=await r.json();\n"
        "  if(!d.ok){ cell.textContent='失败：'+(d.error||r.status); return; }\n"
        "  if(!d.count){ cell.textContent='本地暂无可用数据。先采集/投喂带数据的记录。'; return; }\n"
        "  function sum(x){ if(x.verdict) return x.verdict; if('qualified' in x) return x.qualified?'合格':'不合格'; if('pass' in x) return x.pass?'通过':'不通过'; if('diagnosis' in x) return x.diagnosis; return '-'; }\n"
        "  let html='<div class=\"muted\" style=\"margin:6px 0;\">共 '+d.count+' 条</div><table class=\"rep\"><thead><tr><th>对象</th><th>结果</th><th>详情</th></tr></thead><tbody>';\n"
        "  d.rows.forEach(row=>{ const res=row.result||{}; const extra=res.issues?res.issues.join('；'):(res.next_action||res.recommendation||res.fix||(res.failed_checks?('缺:'+res.failed_checks.join('、')):'')); html+='<tr><td>'+(row.label||'')+'</td><td><b>'+sum(res)+'</b></td><td class=\"muted\">'+(extra||'')+'</td></tr>'; });\n"
        "  html+='</tbody></table>'; cell.innerHTML=html;\n"
        " }catch(e){ cell.textContent='失败：'+e.message; } }\n"
    )
    return f"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><title>运营能力总控台</title><style>{css}
    main {{ max-width: 1180px; margin: 0 auto; padding: 22px 24px 50px; }}
    .panel {{ background:#fff; border:1px solid var(--line); border-radius:10px; padding:16px; margin-top:12px; }}
    .cap-grid {{ display:grid; grid-template-columns:repeat(4, minmax(0, 1fr)); gap:10px; margin-top:12px; }}
    .cap-card {{ border:1px solid var(--line); border-radius:8px; background:#fff; padding:12px; min-height:96px; }}
    .cap-card span {{ display:block; color:var(--muted); font-size:12px; font-weight:800; }}
    .cap-card strong {{ display:block; font-size:26px; margin-top:6px; }}
    .cap-card small {{ display:block; color:var(--muted); line-height:1.45; margin-top:5px; }}
    .rule-grid {{ display:grid; grid-template-columns:repeat(3, minmax(0, 1fr)); gap:10px; }}
    .rule-grid div {{ border:1px solid var(--line); border-radius:8px; padding:12px; background:var(--soft); }}
    .rule-grid strong, .rule-grid span {{ display:block; }}
    .rule-grid span {{ color:var(--muted); font-size:13px; margin-top:5px; line-height:1.5; }}
    .pill {{ display:inline-block; border:1px solid var(--line); border-radius:999px; padding:3px 8px; font-size:12px; font-weight:800; background:var(--soft); }}
    table {{ width:100%; border-collapse:collapse; }}
    th, td {{ border-bottom:1px solid var(--line); padding:9px; text-align:left; font-size:13px; vertical-align:top; }}
    .mini {{ font-size:12px; font-weight:800; border:1px solid var(--line); border-radius:6px; padding:5px 9px; background:#fff; color:var(--ink); text-decoration:none; cursor:pointer; }}
    table.rep th, table.rep td {{ padding:6px 8px; }}
    @media (max-width: 860px) {{ .cap-grid, .rule-grid {{ grid-template-columns:1fr; }} }}
  </style></head>
<body>
  <header>
    <h1>运营能力库</h1>
    <div class="muted">后台能力入口：把外部 Skill、课程方法、平台连接器和自建运营员工统一整理。卖家端只看结果，不看这里的内部能力和原始证据。<a href="/admin-console">返回后台</a></div>
  </header>
  <main>
    <section class="panel">
      <h2>能力总览</h2>
      <div class="cap-grid">{summary_cards}</div>
    </section>
    {safety_html}
    {groups}
  </main>
  <script>{script}</script>
</body></html>"""


