def load_collection_strategy_config(root: Path) -> dict[str, Any]:
    path = root / "config" / "collection_strategy.json"
    if not path.exists():
        return {}
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def collection_strategy_platforms(strategy: dict[str, Any]) -> list[str]:
    platforms: list[str] = []
    for target in strategy.get("targets") or []:
        if not isinstance(target, dict):
            continue
        for platform in target.get("platforms") or []:
            name = str(platform).strip()
            if name and name not in platforms and name.lower() != "all":
                platforms.append(name)
    preferred = [
        "TikTok Shop",
        "TikTok",
        "FastMoss",
        "Kalodata",
        "Amazon",
        "Walmart",
        "Etsy",
        "eBay",
        "SHEIN",
        "Shopify",
        "Shopee",
        "Lazada",
        "Mercado Libre",
        "Temu",
        "Google Trends",
        "Google Patents",
    ]
    for name in preferred:
        if name not in platforms:
            platforms.append(name)
    return platforms


def collection_strategy_markets(strategy: dict[str, Any]) -> list[str]:
    coverage = strategy.get("coverage") if isinstance(strategy.get("coverage"), dict) else {}
    markets = coverage.get("markets") if isinstance(coverage.get("markets"), list) else []
    if markets:
        return [str(item) for item in markets]
    return ["US", "CA", "MX", "UK", "DE", "FR", "IT", "ES", "JP", "KR", "AU", "SG", "MY", "TH", "VN", "PH", "ID", "Latin America", "MENA"]


def collection_strategy_categories(strategy: dict[str, Any]) -> list[str]:
    coverage = strategy.get("coverage") if isinstance(strategy.get("coverage"), dict) else {}
    categories = coverage.get("category_roots") if isinstance(coverage.get("category_roots"), list) else []
    if categories:
        return [str(item) for item in categories]
    return [
        "Beauty & Personal Care",
        "Fashion",
        "Health",
        "Home",
        "Electronics",
        "Pet",
        "Sports & Outdoor",
        "Toys",
        "Jewelry",
        "POD / Gifts",
    ]


def admin_collection_platform_rows(records: list[IntakeRecord], platforms: list[str]) -> str:
    rows: list[str] = []
    for platform in platforms:
        related = [
            record
            for record in records
            if platform.lower() in " ".join(
                str(record.fields.get(key) or "")
                for key in ["platform", "marketplace", "source_platform", "source_id", "url", "page_url"]
            ).lower()
        ]
        jobs = [record for record in related if record.record_type == "collection_job"]
        real_records = [record for record in related if record.record_type != "collection_job" and not is_verification_record(record)]
        gates = [record for record in related if is_verification_record(record)]
        if platform in {"TikTok", "TikTok Shop", "FastMoss", "Kalodata"}:
            focus = "P0：商品榜、买家入口、短视频、达人、评论、脚本"
        elif platform == "Amazon":
            focus = "P1：BSR、新品榜、评论、价格、主图、Listing"
        else:
            focus = "P2：榜单、价格、竞品、评论和跨平台验证"
        rows.append(
            "<tr>"
            f"<td><strong>{html.escape(platform)}</strong></td>"
            f"<td>{html.escape(focus)}</td>"
            f"<td>{len(real_records)}</td>"
            f"<td>{len(jobs)}</td>"
            f"<td>{len(gates)}</td>"
            "</tr>"
        )
    return "".join(rows)


def render_admin_collection_scheduler_page(root: Path) -> str:
    records = sorted(read_records(root), key=lambda item: item.created_at, reverse=True)
    strategy = load_collection_strategy_config(root)
    autonomous = load_autonomous_config(root)
    platforms = collection_strategy_platforms(strategy)
    markets = collection_strategy_markets(strategy)
    categories = collection_strategy_categories(strategy)
    collection_jobs = [record for record in records if record.record_type == "collection_job"]
    real_records = [record for record in records if record.record_type != "collection_job" and not is_verification_record(record)]
    gates = [record for record in records if is_verification_record(record)]
    tk_video_records = [
        record
        for record in records
        if record.record_type in {"viral_content_signal", "video_breakdown", "video_script", "creator_spike_event"}
        or str(record.fields.get("platform") or record.fields.get("source_platform") or "").lower() in {"tiktok", "tiktok shop", "fastmoss", "kalodata"}
    ]
    platform_rows = admin_collection_platform_rows(records, platforms)
    market_tags = "".join(f"<span class='tag'>{html.escape(item)}</span>" for item in markets)
    category_tags = "".join(f"<span class='tag'>{html.escape(item)}</span>" for item in categories)
    run_state = "已开启" if autonomous.get("enabled") and autonomous.get("daily_collect") else "未开启"
    run_mode = str(autonomous.get("mode") or "safe_24h_collection")
    schedule_rows = "".join(
        "<tr>"
        f"<td>{html.escape(freq)}</td>"
        f"<td>{html.escape(scope)}</td>"
        f"<td>{html.escape(output)}</td>"
        f"<td>{html.escape(rule)}</td>"
        "</tr>"
        for freq, scope, output, rule in [
            ("实时 / 15分钟", "自有店铺订单、退款、广告、库存、客服异常", "经营大屏、投流复盘、待确认动作", "只读；真实动作进确认队列"),
            ("每小时", "TikTok Shop 买家入口、FastMoss、Kalodata、达人和短视频信号", "TK视频脚本、达人名单、爆款内容报告", "TK优先；验证页保持打开等待人工"),
            ("每4小时", "Amazon BSR / New Release / Movers、价格、评论、主图", "选品补充、Listing差评痛点、主图参考", "Amazon不替代TK视频证据"),
            ("每日", "全部平台一级到多级类目、榜单变化、新品、长尾词", "类目机会、蓝海词、监控商品报告", "大盘和精准商品分开"),
            ("每周", "国家/市场扩展、渠道适配、POD/侵权/TRO/政策更新", "战略记忆、风控词库、扩张计划", "灰产知识隔离为风控兵法，不进入普通策略"),
            ("每日夜间", "多AI复盘、去重、评分、报告生成", "老板短报、员工补训计划、问题清单", "前台只显示结论，证据折叠"),
        ]
    )
    recent_gate_rows = "".join(
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}</td>"
        f"<td>{html.escape(str(record.fields.get('source_platform') or record.fields.get('platform') or '-'))}</td>"
        f"<td>{html.escape(short_text(record.fields.get('task_title') or record.fields.get('keyword') or record.fields.get('url') or '', 120))}</td>"
        f"<td>{html.escape(collection_job_status(record))}</td>"
        "</tr>"
        for record in gates[:12]
    ) or "<tr><td colspan='4'>暂无登录/验证卡点。</td></tr>"
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>24小时采集调度中心</title>
  <style>{simple_page_css()}
    main {{ max-width: 1380px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 12px; }}
    .metric-card {{ background:#fff; border:1px solid #e8edf2; border-radius:8px; padding:14px; }}
    .metric-card span {{ display:block; color:#667085; font-size:12px; margin-bottom:7px; }}
    .metric-card strong {{ font-size:24px; }}
    .tag-row {{ display:flex; flex-wrap:wrap; gap:8px; margin-top:10px; }}
    .tag {{ display:inline-flex; border:1px solid #99f6e4; background:#ecfeff; color:#0f766e; border-radius:999px; padding:4px 9px; font-weight:800; font-size:12px; }}
    table {{ width:100%; border-collapse:collapse; background:#fff; border:1px solid #e8edf2; }}
    th, td {{ padding:10px; border-bottom:1px solid #e8edf2; text-align:left; vertical-align:top; font-size:13px; }}
    th {{ background:#f9fbfc; color:#111318; }}
    .split {{ display:grid; grid-template-columns:1fr 1fr; gap:14px; }}
    @media (max-width: 980px) {{ .split {{ grid-template-columns:1fr; }} }}
    .notice {{ background:#ecfeff; border:1px solid #99f6e4; border-radius:8px; padding:12px; color:#0f766e; line-height:1.6; }}
  </style>
</head>
<body>
  <header>
    <h1>24小时采集调度中心</h1>
    <div class="muted">管理员专用：全平台、全部市场、全部国家、全部类目都在这里排队采集和质检。客户/卖家端只看 AI 报告、店铺建议、视频脚本、投流方案和待确认动作。</div>
    <div class="actions">
      <a class="button secondary" href="/admin-console">管理员后台</a>
      <a class="button secondary" href="/automation-settings">自动化设置</a>
      <a class="button secondary" href="/admin-capture-data">完整资料后台</a>
      <button onclick="runAutoMode()">立即跑一轮</button>
      <span id="runStatus" class="muted"></span>
    </div>
  </header>
  <main>
    <section class="panel">
      <h2>总控状态</h2>
      <div class="grid">
        <div class="metric-card"><span>24小时模式</span><strong>{html.escape(run_state)}</strong><small>{html.escape(run_mode)}</small></div>
        <div class="metric-card"><span>平台覆盖</span><strong>{len(platforms)}</strong><small>TK / Amazon / Walmart / Etsy / SHEIN 等</small></div>
        <div class="metric-card"><span>市场覆盖</span><strong>{len(markets)}</strong><small>国家 / 区域队列</small></div>
        <div class="metric-card"><span>类目覆盖</span><strong>{len(categories)}</strong><small>一级到多级类目递进</small></div>
        <div class="metric-card"><span>待整理任务</span><strong>{len(collection_jobs)}</strong><small>后台队列</small></div>
        <div class="metric-card"><span>验证/登录卡点</span><strong>{len(gates)}</strong><small>需要人工过验证后继续</small></div>
        <div class="metric-card"><span>已整理证据</span><strong>{len(real_records)}</strong><small>去重后进入分析</small></div>
        <div class="metric-card"><span>TK / 视频证据</span><strong>{len(tk_video_records)}</strong><small>视频脚本和达人重点</small></div>
      </div>
    </section>

    <section class="panel">
      <h2>覆盖范围</h2>
      <div class="notice">采集不是把所有原始表塞给用户看，而是后台持续入湖、去重、评分，再输出短报告。TikTok Shop / FastMoss / Kalodata / 买家侧视频优先；Amazon 做榜单、评论、价格和 Listing 补充。</div>
      <h3>国家 / 市场</h3>
      <div class="tag-row">{market_tags}</div>
      <h3>类目根节点</h3>
      <div class="tag-row">{category_tags}</div>
    </section>

    <section class="panel">
      <h2>平台调度</h2>
      <table>
        <thead><tr><th>平台</th><th>整理重点</th><th>已整理</th><th>待补资料</th><th>卡点</th></tr></thead>
        <tbody>{platform_rows}</tbody>
      </table>
    </section>

    <section class="panel">
      <h2>24小时频率策略</h2>
      <table>
        <thead><tr><th>频率</th><th>看什么</th><th>输出给谁</th><th>安全规则</th></tr></thead>
        <tbody>{schedule_rows}</tbody>
      </table>
    </section>

    <section class="split">
      <div class="panel">
        <h2>最近登录 / 验证卡点</h2>
        <table>
          <thead><tr><th>时间</th><th>平台</th><th>任务</th><th>状态</th></tr></thead>
          <tbody>{recent_gate_rows}</tbody>
        </table>
      </div>
      <div class="panel">
        <h2>前台输出规则</h2>
        <ul>
          <li>卖家端只看：今日结论、监控商品报告、TK视频脚本、达人/投流建议、待确认动作。</li>
          <li>详细资料、复核依据、系统配置和权限设置只给负责人查看。</li>
          <li>没有 API 时，用已登录浏览器、选品平台、插件和人工过验证后的页面采集；不绕过滑块、验证码或授权。</li>
          <li>真实店铺发布、改价、退款、发货、广告、活动报名、授权应用只进入确认队列。</li>
        </ul>
      </div>
    </section>
  </main>
  <script>
    async function runAutoMode() {{
      const status = document.getElementById('runStatus');
      status.textContent = '正在运行...';
      try {{
        const res = await fetch('/api/auto-mode/run', {{ method: 'POST', headers: {{'Content-Type': 'application/json'}}, body: JSON.stringify({{ seed_collection_jobs: true }}) }});
        const data = await res.json();
        status.textContent = res.ok && data.ok ? '已完成一轮，正在刷新。' : ('运行失败：' + (data.error || res.status));
        if (res.ok && data.ok) setTimeout(() => location.reload(), 900);
      }} catch (err) {{
        status.textContent = '运行失败：' + err.message;
      }}
    }}
  </script>
</body>
</html>"""


def render_product_lifecycle_page(root: Path) -> str:
    plans = build_product_lifecycle_plans(root, date.today().isoformat())
    report, path = latest_lifecycle_report(root)
    rows = "".join(render_lifecycle_plan_row(item) for item in plans) or (
        "<tr><td colspan='10'>暂无生命周期数据。后台 AI 暂未读到监控商品、同行链接、榜单、视频、评论和店铺销量。</td></tr>"
    )
    stage_counts: dict[str, int] = {}
    for item in plans:
        stage = str(item.get("lifecycle_stage") or "A")
        stage_counts[stage] = stage_counts.get(stage, 0) + 1
    cards = "".join(
        "<div class='metric-card'>"
        f"<span>{html.escape(label)}</span>"
        f"<strong>{html.escape(str(stage_counts.get(stage, 0)))}</strong>"
        "</div>"
        for stage, label in [
            ("A", "A 测品/验证"),
            ("B", "B 增长/放量"),
            ("C", "C 成熟/收割"),
            ("D", "D 衰退/风险"),
        ]
    )
    report_preview = html.escape(report[:3600])
    path_text = str(path) if path else "还没有生成报告"
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>产品生命周期与备货计划</title>
  <style>{simple_page_css()}
    main {{ max-width: 1420px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }}
    .metric-card span {{ display: block; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 26px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--line); }}
    th, td {{ padding: 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: var(--ink); }}
    .stage {{ display: inline-block; border-radius: 999px; padding: 4px 9px; font-weight: 900; color: #fff; }}
    .stage-A {{ background: #2f80ed; }}
    .stage-B {{ background: #08a88a; }}
    .stage-C {{ background: #9b6a00; }}
    .stage-D {{ background: #c2410c; }}
    .mini {{ color: var(--muted); font-size: 12px; margin-top: 5px; line-height: 1.5; }}
    .list {{ margin: 0; padding-left: 16px; }}
    .list li {{ margin: 0 0 4px; }}
    .two-col {{ display: grid; grid-template-columns: 1.35fr 0.65fr; gap: 14px; align-items: start; }}
    @media (max-width: 980px) {{ .two-col {{ grid-template-columns: 1fr; }} }}
  </style>
</head>
<body>
  <header>
    <h1>产品生命周期与备货计划</h1>
    <div class="muted">按同行数据、榜单排名、视频热度、店铺销量、退货/差评和库存判断 ABCD 状态，并生成测品备货、补货和拉长生命周期方案。</div>
    <div class="actions">
      <button onclick="runLifecycle()">重新分析</button>
      <a class="button secondary" href="/chat?intent=product_data">商品证据状态</a>
      <a class="button secondary" href="/selection">选品报告</a>
      <a class="button secondary" href="/realtime-big-screen">经营大屏</a>
      <a class="button secondary" href="/dashboard">控制台</a>
    </div>
    <div class="muted" id="runStatus">最新报告：{html.escape(path_text)}</div>
  </header>
  <main>
    <section class="grid">{cards}</section>
    <div class="two-col">
      <section class="panel">
        <h2>商品生命周期表</h2>
        <table>
          <thead><tr><th>商品</th><th>状态</th><th>机会分</th><th>证据</th><th>测品/备货</th><th>补货</th><th>拉长生命周期</th><th>下一步</th><th>风险</th><th>复盘触发</th></tr></thead>
          <tbody>{rows}</tbody>
        </table>
      </section>
      <section class="panel">
        <h2>ABCD 口径</h2>
        <ul>
          <li><strong>A 测品/验证期：</strong>小批量，先验证素材、达人、Listing、价格。</li>
          <li><strong>B 增长/放量期：</strong>防断货，扩大达人/视频/广告测试，快速做变体。</li>
          <li><strong>C 成熟/收割期：</strong>稳定利润，做二代、套装、礼品版、季节版拉长生命周期。</li>
          <li><strong>D 衰退/风险期：</strong>停止大货，清库存，改版重测或淘汰。</li>
        </ul>
        <h2>最新报告</h2>
        <pre>{report_preview}</pre>
      </section>
    </div>
  </main>
  <script>
    async function runLifecycle() {{
      const status = document.getElementById('runStatus');
      status.textContent = '正在重新分析生命周期和备货计划...';
      const response = await fetch('/api/product-lifecycle/run', {{
        method: 'POST',
        headers: {{'Content-Type': 'application/json'}},
        body: JSON.stringify({{date: new Date().toISOString().slice(0, 10)}})
      }});
      const data = await response.json();
      if (!data.ok) {{
        status.textContent = '分析失败：' + (data.error || 'unknown');
        return;
      }}
      status.textContent = '分析完成，正在刷新页面...';
      location.reload();
    }}
  </script>
</body>
</html>"""


def render_lifecycle_plan_row(item: dict[str, Any]) -> str:
    stage = str(item.get("lifecycle_stage") or "A")
    stock = item.get("stock_plan") if isinstance(item.get("stock_plan"), dict) else {}
    extension = item.get("lifecycle_extension_plan") if isinstance(item.get("lifecycle_extension_plan"), list) else []
    actions = item.get("next_actions") if isinstance(item.get("next_actions"), list) else []
    risks = item.get("risks") if isinstance(item.get("risks"), list) else []
    evidence = [
        f"rank {item.get('best_rank')}" if item.get("best_rank") else "",
        f"{item.get('rank_direction')} {item.get('rank_delta')}" if item.get("rank_delta") else "",
        f"近7天 {item.get('recent_units_7d', 0)} 件",
        f"退货率 {float(item.get('return_rate') or 0) * 100:.1f}%",
        f"置信度 {item.get('confidence')}",
    ]
    return (
        "<tr>"
        f"<td><strong>{html.escape(str(item.get('product_name') or ''))}</strong><div class='mini'>信号 {html.escape(str(item.get('signal_count') or 0))} 条 · 库存 {html.escape(str(item.get('inventory_qty') if item.get('inventory_qty') is not None else '未知'))}</div></td>"
        f"<td><span class='stage stage-{html.escape(stage)}'>{html.escape(str(item.get('stage_label') or stage))}</span></td>"
        f"<td>{html.escape(str(item.get('opportunity_score') or 0))}<div class='mini'>增长 {html.escape(str(item.get('growth_score') or 0))} / 需求 {html.escape(str(item.get('demand_score') or 0))} / 风险 {html.escape(str(item.get('risk_score') or 0))}</div></td>"
        f"<td>{html.escape(' | '.join(part for part in evidence if part))}</td>"
        f"<td>{html.escape(str(stock.get('test_stock_qty', 0)))} 件<div class='mini'>{html.escape(str(stock.get('mode') or ''))}</div></td>"
        f"<td>{html.escape(str(stock.get('replenishment_qty', 0)))} 件<div class='mini'>安全库存 {html.escape(str(stock.get('recommended_available_stock', 0)))} 件 · 交期 {html.escape(str(stock.get('lead_time_days', 0)))} 天</div></td>"
        f"<td>{render_short_list(extension)}</td>"
        f"<td>{render_short_list(actions)}</td>"
        f"<td>{render_short_list(risks) if risks else '<span class=\"mini\">暂无明显风险</span>'}</td>"
        f"<td>{html.escape(str(item.get('review_trigger') or ''))}</td>"
        "</tr>"
    )


def render_short_list(items: list[Any], limit: int = 3) -> str:
    clean = [str(item) for item in items if str(item).strip()][:limit]
    if not clean:
        return "<span class='mini'>暂无</span>"
    return "<ul class='list'>" + "".join(f"<li>{html.escape(item)}</li>" for item in clean) + "</ul>"


def render_launch_control_page(root: Path) -> str:
    plans = build_launch_control_plans(root, date.today().isoformat())
    report, path = latest_launch_control_report(root)
    rows = "".join(render_launch_control_row(item) for item in plans) or (
        "<tr><td colspan='10'>暂无起盘控盘数据。后台 AI 暂未读到监控商品、同行视频、达人、销量、库存、广告和直播/折扣记录。</td></tr>"
    )
    stage_counts: dict[str, int] = {}
    pressure_count = 0
    for item in plans:
        stage = str(item.get("launch_stage") or "")
        stage_counts[stage] = stage_counts.get(stage, 0) + 1
        pressure = item.get("plate_pressure") if isinstance(item.get("plate_pressure"), dict) else {}
        if pressure.get("warnings"):
            pressure_count += 1
    cards = "".join(
        "<div class='metric-card'>"
        f"<span>{html.escape(label)}</span>"
        f"<strong>{html.escape(str(stage_counts.get(stage, 0)))}</strong>"
        "</div>"
        for stage, label in [
            ("seed_launch", "起盘蓄水"),
            ("micro_test_control", "小盘测试"),
            ("scale_control", "起量控盘"),
            ("harvest_stabilize", "收割稳盘"),
            ("cooldown_reset", "降温/重开"),
        ]
    )
    report_preview = html.escape(report[:3200])
    path_text = str(path) if path else "还没有生成报告"
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>起盘控盘策略</title>
  <style>{simple_page_css()}
    main {{ max-width: 1460px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }}
    .metric-card span {{ display: block; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 25px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--line); }}
    th, td {{ padding: 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: var(--ink); }}
    .badge {{ display: inline-block; border-radius: 999px; padding: 4px 9px; background: #0f766e; color: #fff; font-weight: 900; }}
    .pressure {{ color: #b45309; font-weight: 800; }}
    .mini {{ color: var(--muted); font-size: 12px; margin-top: 5px; line-height: 1.5; }}
    .list {{ margin: 0; padding-left: 16px; }}
    .list li {{ margin: 0 0 4px; }}
    .two-col {{ display: grid; grid-template-columns: 1.35fr 0.65fr; gap: 14px; align-items: start; }}
    @media (max-width: 980px) {{ .two-col {{ grid-template-columns: 1fr; }} }}
  </style>
</head>
<body>
  <header>
    <h1>起盘控盘策略</h1>
    <div class="muted">学习并输出：怎么起盘、怎么控盘子、什么时候种草、测品、收割、控预算、控折扣、控直播挂车、控库存和止损。</div>
    <div class="actions">
      <button onclick="runLaunchControl()">重新分析</button>
      <a class="button secondary" href="/product-lifecycle">生命周期/备货</a>
      <a class="button secondary" href="/chat?intent=tk_content">问TK内容打法</a>
      <a class="button secondary" href="/realtime-big-screen">经营大屏</a>
      <a class="button secondary" href="/chat?intent=approval">让AI整理确认草稿</a>
      <a class="button secondary" href="/dashboard">控制台</a>
    </div>
    <div class="muted" id="runStatus">最新报告：{html.escape(path_text)} · 有盘面压力商品：{html.escape(str(pressure_count))}</div>
  </header>
  <main>
    <section class="grid">{cards}</section>
    <div class="two-col">
      <section class="panel">
        <h2>商品起盘控盘表</h2>
        <table>
          <thead><tr><th>商品</th><th>阶段</th><th>平台机制</th><th>盘面压力</th><th>起盘动作</th><th>控盘规则</th><th>预算</th><th>直播间</th><th>止损</th><th>继续学习</th></tr></thead>
          <tbody>{rows}</tbody>
        </table>
      </section>
      <section class="panel">
        <h2>核心口径</h2>
        <ul>
          <li><strong>起盘：</strong>用内容、达人、Listing、价格、库存和评论信号，把品从冷启动拉到可测、可卖、可放量。</li>
          <li><strong>TK：</strong>赛马机制，平台配量。先造多匹马，再让素材、达人、账号和商品卡跑小流量筛赢家。</li>
          <li><strong>Amazon：</strong>买量机制，买关键词/搜索/PPC，但必须靠Listing、价格、评价和库存承接。</li>
          <li><strong>控盘：</strong>用预算、折扣、库存、直播挂车、达人节奏、退款和素材衰减控制风险。</li>
          <li><strong>收割：</strong>只有素材、达人、库存、ROAS、退货率同时健康，才进入放量。</li>
          <li><strong>止损：</strong>ROAS、退款、库存、差评、侵权、履约任一异常，先降速而不是硬冲。</li>
        </ul>
        <h2>最新报告</h2>
        <pre>{report_preview}</pre>
      </section>
    </div>
  </main>
  <script>
    async function runLaunchControl() {{
      const status = document.getElementById('runStatus');
      status.textContent = '正在重新分析起盘控盘策略...';
      const response = await fetch('/api/launch-control/run', {{
        method: 'POST',
        headers: {{'Content-Type': 'application/json'}},
        body: JSON.stringify({{date: new Date().toISOString().slice(0, 10)}})
      }});
      const data = await response.json();
      if (!data.ok) {{
        status.textContent = '分析失败：' + (data.error || 'unknown');
        return;
      }}
      status.textContent = '分析完成，正在刷新页面...';
      location.reload();
    }}
  </script>
</body>
</html>"""


def render_launch_control_row(item: dict[str, Any]) -> str:
    pressure = item.get("plate_pressure") if isinstance(item.get("plate_pressure"), dict) else {}
    budget = item.get("budget_control") if isinstance(item.get("budget_control"), dict) else {}
    pressure_text = "; ".join(str(value) for value in pressure.get("warnings", []) if str(value).strip()) or "暂无明显压力"
    roas = item.get("roas")
    roas_text = f"{float(roas):.2f}" if roas is not None else "缺失"
    return (
        "<tr>"
        f"<td><strong>{html.escape(str(item.get('product_name') or ''))}</strong><div class='mini'>{html.escape(str(item.get('lifecycle_label') or ''))} · 近7天 {html.escape(str(item.get('recent_units_7d') or 0))} 件 · ROAS {html.escape(roas_text)}</div></td>"
        f"<td><span class='badge'>{html.escape(str(item.get('launch_label') or item.get('launch_stage') or ''))}</span><div class='mini'>优先级 {html.escape(str(item.get('control_priority') or 0))}</div></td>"
        f"<td>{render_platform_mechanism_block(item.get('platform_mechanisms') if isinstance(item.get('platform_mechanisms'), list) else [], item.get('platform_playbook') if isinstance(item.get('platform_playbook'), list) else [])}</td>"
        f"<td><span class='pressure'>{html.escape(pressure_text)}</span></td>"
        f"<td>{render_short_list(item.get('launch_plan') if isinstance(item.get('launch_plan'), list) else [])}</td>"
        f"<td>{render_short_list(item.get('plate_control_plan') if isinstance(item.get('plate_control_plan'), list) else [])}</td>"
        f"<td><strong>{html.escape(str(budget.get('mode') or ''))}</strong><div class='mini'>{html.escape(str(budget.get('rule') or ''))}<br>允许放量：{html.escape('是' if budget.get('scale_allowed') else '否')}</div></td>"
        f"<td>{render_short_list(item.get('live_room_control') if isinstance(item.get('live_room_control'), list) else [])}</td>"
        f"<td>{render_short_list(item.get('stop_loss_rules') if isinstance(item.get('stop_loss_rules'), list) else [])}</td>"
        f"<td>{render_short_list(item.get('learning_tasks') if isinstance(item.get('learning_tasks'), list) else [])}</td>"
        "</tr>"
    )


def render_platform_mechanism_block(mechanisms: list[Any], playbook: list[Any]) -> str:
    badges = []
    for item in mechanisms:
        if not isinstance(item, dict):
            continue
        label = str(item.get("label") or item.get("traffic_model") or "")
        core = str(item.get("core_logic") or "")
        if label:
            badges.append(f"<strong>{html.escape(label)}</strong><div class='mini'>{html.escape(core)}</div>")
    playbook_html = render_short_list(playbook, limit=2)
    return "".join(badges) + playbook_html if badges else playbook_html


def render_budget_planning_page(root: Path) -> str:
    payload = build_budget_planning_payload(root, date.today().isoformat())
    plans = payload.get("plans", [])
    summary = payload.get("summary", {})
    report, path = latest_budget_planning_report(root)
    rows = "".join(render_budget_plan_row(item) for item in plans) or (
        "<tr><td colspan='9'>暂无预算计划。后台 AI 暂未读到产品预算、同行、榜单、视频和店铺数据。</td></tr>"
    )
    cards = "".join(
        "<div class='metric-card'>"
        f"<span>{html.escape(label)}</span>"
        f"<strong>{html.escape(value)}</strong>"
        "</div>"
        for label, value in [
            ("计划数", str(summary.get("plan_count", 0))),
            ("总预算", money(summary.get("total_budget"))),
            ("预计销售额", money(summary.get("expected_revenue"))),
            ("预算后预计利润", money(summary.get("expected_profit_after_budget"))),
            ("平均预计ROAS", ratio(summary.get("average_expected_roas"))),
            ("可阶梯加预算", str(summary.get("increase_candidates", 0))),
            ("仅测试/暂停", str(summary.get("hold_or_test_candidates", 0))),
        ]
    )
    report_preview = html.escape(report[:3000])
    path_text = str(path) if path else "还没有生成报告"
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>产品总预算计划</title>
  <style>{simple_page_css()}
    main {{ max-width: 1500px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }}
    .metric-card span {{ display: block; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 24px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--line); }}
    th, td {{ padding: 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: var(--ink); }}
    input, textarea, select {{ width: 100%; box-sizing: border-box; border: 1px solid var(--line); border-radius: 8px; padding: 9px; font: inherit; }}
    textarea {{ min-height: 68px; }}
    .form-grid {{ display: grid; grid-template-columns: 1.2fr 0.7fr 0.6fr 1fr 0.8fr 0.6fr 0.6fr; gap: 10px; align-items: end; }}
    .mini {{ color: var(--muted); font-size: 12px; margin-top: 5px; line-height: 1.45; }}
    .badge {{ display: inline-block; border-radius: 999px; padding: 4px 9px; background: #111827; color: #fff; font-weight: 900; }}
    .decision-increase_ladder {{ color: #047857; font-weight: 900; }}
    .decision-cut_or_hold, .decision-test_budget_only, .decision-hold {{ color: #b45309; font-weight: 900; }}
    .list {{ margin: 0; padding-left: 16px; }}
    .list li {{ margin: 0 0 4px; }}
    .two-col {{ display: grid; grid-template-columns: 1.4fr 0.6fr; gap: 14px; align-items: start; }}
    .allocation {{ border: 1px solid var(--line); border-radius: 8px; padding: 8px; margin-bottom: 6px; background: #fbfcfd; }}
    @media (max-width: 1100px) {{ .two-col, .form-grid {{ grid-template-columns: 1fr; }} }}
  </style>
</head>
<body>
  <header>
    <h1>产品总预算计划</h1>
    <div class="muted">按市场大盘、同行强度、自己店铺销售/退货/广告、产品生命周期和起盘阶段，估算预算分配、ROI、回本周期和每日调整建议。</div>
    <div class="actions">
      <button onclick="runBudgetPlanning()">重新分析</button>
      <a class="button secondary" href="/launch-control">起盘控盘</a>
      <a class="button secondary" href="/product-lifecycle">生命周期/备货</a>
      <a class="button secondary" href="/realtime-big-screen">经营大屏</a>
      <a class="button secondary" href="/chat?intent=approval">让AI整理确认草稿</a>
      <a class="button secondary" href="/dashboard">控制台</a>
    </div>
    <div class="muted" id="runStatus">最新报告：{html.escape(path_text)}。真实投流、改价、折扣、上架、报名活动都只生成待确认动作。</div>
  </header>
  <main>
    <section class="grid">{cards}</section>

    <section class="panel">
      <h2>新增预算方案</h2>
      <div class="form-grid">
        <label>产品<input id="productName" placeholder="Amino Acid Cleanser / 水洗T恤 / 褪黑素"></label>
        <label>总预算USD<input id="totalBudget" type="number" min="1" step="100" value="20000"></label>
        <label>店铺数<input id="storeCount" type="number" min="1" step="1" value="3"></label>
        <label>平台<input id="channels" value="TikTok Shop, Amazon" placeholder="TikTok Shop, Amazon, Etsy"></label>
        <label>国家<input id="countries" value="US" placeholder="US, UK, JP"></label>
        <label>周期天数<input id="durationDays" type="number" min="7" step="1" value="30"></label>
        <label>毛利率<input id="targetMargin" type="number" min="0.05" max="0.9" step="0.01" value="0.45"></label>
      </div>
      <div class="actions" style="margin-top:12px;">
        <button onclick="addBudgetPlan()">保存方案并分析</button>
        <span class="muted" id="addStatus">示例：只做 TK 三家店，填 TikTok Shop、预算 20000、店铺数 3。</span>
      </div>
    </section>

    <div class="two-col">
      <section class="panel">
        <h2>产品预算表</h2>
        <table>
          <thead><tr><th>产品</th><th>预算模型</th><th>市场/同行</th><th>自己店铺</th><th>预估回报</th><th>预算分配</th><th>调整建议</th><th>下一步</th><th>记忆/条件</th></tr></thead>
          <tbody>{rows}</tbody>
        </table>
      </section>
      <section class="panel">
        <h2>预算口径</h2>
        <ul>
          <li><strong>TK：</strong>按赛马/配量思路，预算优先给素材池、达人池、渠道号、商品卡承接和小额加热。</li>
          <li><strong>Amazon：</strong>按买量/买词思路，预算优先给Listing承接、关键词PPC、优惠券、库存和评价痛点修复。</li>
          <li><strong>多平台店群：</strong>先分平台预算，再按店铺数拆分；老店和有广告的店只给建议，不自动动手。</li>
          <li><strong>回本周期：</strong>用预算、预计销售额和毛利率估算，不等于真实利润；缺成本/库存时会保守标风险。</li>
        </ul>
        <h2>最新报告</h2>
        <pre>{report_preview}</pre>
      </section>
    </div>
  </main>
  <script>
    async function runBudgetPlanning() {{
      const status = document.getElementById('runStatus');
      status.textContent = '正在重新计算预算、ROI和回本周期...';
      const response = await fetch('/api/budget-planning/run', {{
        method: 'POST',
        headers: {{'Content-Type': 'application/json'}},
        body: JSON.stringify({{date: new Date().toISOString().slice(0, 10)}})
      }});
      const data = await response.json();
      if (!data.ok) {{
        status.textContent = '分析失败：' + (data.error || 'unknown');
        return;
      }}
      status.textContent = '分析完成，正在刷新页面...';
      location.reload();
    }}
    async function addBudgetPlan() {{
      const status = document.getElementById('addStatus');
      status.textContent = '正在保存预算方案...';
      const payload = {{
        product_name: document.getElementById('productName').value,
        total_budget: document.getElementById('totalBudget').value,
        store_count: document.getElementById('storeCount').value,
        channels: document.getElementById('channels').value,
        countries: document.getElementById('countries').value,
        duration_days: document.getElementById('durationDays').value,
        target_margin: document.getElementById('targetMargin').value
      }};
      const response = await fetch('/api/budget-planning/add', {{
        method: 'POST',
        headers: {{'Content-Type': 'application/json'}},
        body: JSON.stringify(payload)
      }});
      const data = await response.json();
      if (!data.ok) {{
        status.textContent = '保存失败：' + (data.error || 'unknown');
        return;
      }}
      status.textContent = '已保存，正在生成预算报告...';
      await runBudgetPlanning();
    }}
  </script>
</body>
</html>"""


def render_budget_plan_row(item: dict[str, Any]) -> str:
    own = item.get("own_performance") if isinstance(item.get("own_performance"), dict) else {}
    market = item.get("market_size") if isinstance(item.get("market_size"), dict) else {}
    competitors = item.get("competitor_intensity") if isinstance(item.get("competitor_intensity"), dict) else {}
    adjustment = item.get("budget_adjustment") if isinstance(item.get("budget_adjustment"), dict) else {}
    decision = str(adjustment.get("decision") or "")
    channels = ", ".join(str(channel) for channel in item.get("channels", []) if str(channel).strip())
    countries = ", ".join(str(country) for country in item.get("countries", []) if str(country).strip())
    return (
        "<tr>"
        f"<td><strong>{html.escape(str(item.get('product_name') or ''))}</strong><div class='mini'>{html.escape(str(item.get('lifecycle_label') or ''))} · {html.escape(str(item.get('launch_label') or ''))} · 优先级 {html.escape(str(item.get('priority_score') or 0))}</div></td>"
        f"<td><span class='badge'>{html.escape(str(item.get('budget_mode') or ''))}</span><div class='mini'>{html.escape(channels)}<br>{html.escape(countries)} · {html.escape(str(item.get('store_count') or 1))} 家店 · 单店 {html.escape(money(item.get('per_store_budget')))}</div></td>"
        f"<td>大盘 {html.escape(str(market.get('score', 0)))} / {html.escape(str(market.get('market_level', '')))}<div class='mini'>同行 {html.escape(str(competitors.get('score', 0)))} / {html.escape(str(competitors.get('level', '')))} · 最好排名 {html.escape(str(market.get('best_rank') or '-'))} · 可见GMV {html.escape(money(market.get('visible_gmv')))}</div></td>"
        f"<td>{html.escape(money(own.get('revenue')))}<div class='mini'>订单 {html.escape(str(own.get('orders', 0)))} · 广告 {html.escape(money(own.get('ad_spend')))} · ROAS {html.escape(ratio(own.get('roas')))} · 退货/退款 {html.escape(percent(own.get('return_rate')))}</div></td>"
        f"<td><strong>{html.escape(money(item.get('expected_revenue')))}</strong><div class='mini'>预算 {html.escape(money(item.get('total_budget')))} · 预计ROAS {html.escape(ratio(item.get('expected_roas')))} · 预算后利润 {html.escape(money(item.get('expected_profit_after_budget')))}<br>{html.escape(str(item.get('payback_label') or ''))}</div></td>"
        f"<td>{render_budget_allocation_block(item.get('recommended_allocation') if isinstance(item.get('recommended_allocation'), list) else [])}</td>"
        f"<td><span class='decision-{html.escape(decision)}'>{html.escape(decision or '-')}</span><div class='mini'>建议预算 {html.escape(money(adjustment.get('suggested_budget')))}<br>{html.escape(str(adjustment.get('reason') or ''))}</div>{render_short_list(item.get('risks') if isinstance(item.get('risks'), list) else [], limit=2)}</td>"
        f"<td>{render_short_list(item.get('next_actions') if isinstance(item.get('next_actions'), list) else [], limit=4)}</td>"
        f"<td>{render_budget_memory_block(item.get('strategy_memory') if isinstance(item.get('strategy_memory'), dict) else {})}</td>"
        "</tr>"
    )


def render_budget_allocation_block(items: list[Any], limit: int = 5) -> str:
    rows = []
    for item in items[:limit]:
        if not isinstance(item, dict):
            continue
        rows.append(
            "<div class='allocation'>"
            f"<strong>{html.escape(str(item.get('channel') or ''))} · {html.escape(str(item.get('purpose') or ''))}</strong>"
            f"<div class='mini'>{html.escape(money(item.get('amount')))} · 单店 {html.escape(money(item.get('per_store_amount')))}<br>{html.escape(str(item.get('guardrail') or ''))}</div>"
            "</div>"
        )
    return "".join(rows) or "<span class='mini'>暂无分配</span>"


def render_budget_memory_block(memory: dict[str, Any]) -> str:
    observed = memory.get("observed") if isinstance(memory.get("observed"), list) else []
    valid = memory.get("valid_conditions") if isinstance(memory.get("valid_conditions"), list) else []
    cannot = memory.get("cannot_do") if isinstance(memory.get("cannot_do"), list) else []
    lines = [*observed[:2], *valid[:1], *cannot[:1]]
    return render_short_list(lines, limit=4)


def render_operation_closure_page(root: Path) -> str:
    payload = build_operation_closure_payload(root, date.today().isoformat())
    steps = payload.get("steps", [])
    summary = payload.get("summary", {})
    report, path = latest_operation_closure_report(root)
    cards = "".join(
        "<div class='metric-card'>"
        f"<span>{html.escape(label)}</span>"
        f"<strong>{html.escape(str(value))}</strong>"
        "</div>"
        for label, value in [
            ("环节数", summary.get("step_count", 0)),
            ("Ready", summary.get("ready", 0)),
            ("Partial", summary.get("partial", 0)),
            ("Missing", summary.get("missing", 0)),
            ("整体状态", summary.get("overall_status", "")),
        ]
    )
    gap_cards = render_operation_gap_cards(summary.get("top_missing", []) if isinstance(summary.get("top_missing"), list) else [])
    rows = "".join(render_operation_step_row(item) for item in steps) or (
        "<tr><td colspan='8'>暂无闭环细节数据。</td></tr>"
    )
    report_preview = html.escape(report[:2600])
    path_text = str(path) if path else "还没有生成报告"
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>全流程闭环细节</title>
  <style>{simple_page_css()}
    main {{ max-width: 1520px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }}
    .metric-card span {{ display: block; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 24px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid var(--line); }}
    th, td {{ padding: 10px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; font-size: 12.5px; }}
    th {{ background: #f9fbfc; color: var(--ink); }}
    .status {{ display:inline-block; border-radius:999px; padding:4px 9px; color:#fff; font-weight:900; }}
    .status-ready {{ background:#047857; }}
    .status-partial {{ background:#b45309; }}
    .status-missing {{ background:#991b1b; }}
    .mini {{ color: var(--muted); font-size: 12px; margin-top: 5px; line-height: 1.45; }}
    .list {{ margin: 0; padding-left: 16px; }}
    .list li {{ margin: 0 0 4px; }}
    .two-col {{ display: grid; grid-template-columns: 1.35fr 0.65fr; gap: 14px; align-items: start; }}
    .gap-grid {{ display:grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap:10px; }}
    .gap {{ border:1px solid var(--line); border-radius:8px; padding:10px; background:#fffdf7; }}
    @media (max-width: 1100px) {{ .two-col {{ grid-template-columns: 1fr; }} }}
  </style>
</head>
<body>
  <header>
    <h1>全流程闭环细节</h1>
    <div class="muted">把一人公司 AI 运营拆成 21 个环节：每个环节该采集什么、AI 判断什么、输出什么、哪些动作必须确认、当前缺什么。</div>
    <div class="actions">
      <button onclick="runClosure()">重新检查细节</button>
      <a class="button secondary" href="/launch-control">起盘控盘</a>
      <a class="button secondary" href="/budget-planning">预算计划</a>
      <a class="button secondary" href="/product-lifecycle">生命周期/备货</a>
      <a class="button secondary" href="/chat?intent=approval">让AI整理确认草稿</a>
      <a class="button secondary" href="/dashboard">控制台</a>
    </div>
    <div class="muted" id="runStatus">最新报告：{html.escape(path_text)}</div>
  </header>
  <main>
    <section class="grid">{cards}</section>
    <section class="panel">
      <h2>优先补齐的缺口</h2>
      {gap_cards}
    </section>
    <div class="two-col">
      <section class="panel">
        <h2>21个环节细节表</h2>
        <table>
          <thead><tr><th>环节</th><th>状态</th><th>必需数据</th><th>AI判断</th><th>输出物</th><th>审批边界</th><th>当前缺口</th><th>入口</th></tr></thead>
          <tbody>{rows}</tbody>
        </table>
      </section>
      <section class="panel">
        <h2>闭环原则</h2>
        <ul>
          <li><strong>先数据：</strong>没有同品、评论、视频、店铺销售、成本库存，就只允许测试建议。</li>
          <li><strong>再判断：</strong>AI 必须说明为什么能做、什么时候能做、什么情况下不能做。</li>
          <li><strong>再草稿：</strong>Listing、视频脚本、达人、预算、折扣、活动都先生成草稿。</li>
          <li><strong>再确认：</strong>真实发布、改价、投流、退款、发货、授权、联系达人进入确认中心。</li>
          <li><strong>最后记忆：</strong>每次结果都回写策略记忆，形成“什么品、什么场景、什么打法有效”。</li>
        </ul>
        <h2>最新报告</h2>
        <pre>{report_preview}</pre>
      </section>
    </div>
  </main>
  <script>
    async function runClosure() {{
      const status = document.getElementById('runStatus');
      status.textContent = '正在检查全流程缺口...';
      const response = await fetch('/api/operation-closure/run', {{
        method: 'POST',
        headers: {{'Content-Type': 'application/json'}},
        body: JSON.stringify({{date: new Date().toISOString().slice(0, 10)}})
      }});
      const data = await response.json();
      if (!data.ok) {{
        status.textContent = '检查失败：' + (data.error || 'unknown');
        return;
      }}
      status.textContent = '检查完成，正在刷新页面...';
      location.reload();
    }}
  </script>
</body>
</html>"""


def render_operation_gap_cards(gaps: list[Any]) -> str:
    if not gaps:
        return "<div class='empty'>当前没有明显缺口。继续跑每日监控和复盘即可。</div>"
    return "<div class='gap-grid'>" + "".join(render_operation_gap_card(item) for item in gaps[:12]) + "</div>"


def render_operation_gap_card(item: Any) -> str:
    if not isinstance(item, dict):
        return ""
    return (
        "<div class='gap'>"
        f"<strong>{html.escape(str(item.get('name') or ''))}</strong>"
        f"<div class='mini'>{html.escape(str(item.get('next_action') or ''))}</div>"
        "</div>"
    )


def render_operation_step_row(item: dict[str, Any]) -> str:
    status = str(item.get("status") or "missing")
    page = str(item.get("page") or "")
    page_link = f"<a href='{html.escape(page)}'>打开</a>" if page else ""
    required = [f"{signal.get('label')}:{signal.get('count')}" for signal in item.get("evidence", []) if isinstance(signal, dict)]
    if not required:
        required = [str(signal) for signal in item.get("required_signals", [])]
    return (
        "<tr>"
        f"<td><strong>{html.escape(str(item.get('phase') or ''))}</strong><div class='mini'>{html.escape(str(item.get('name') or ''))} · {html.escape(str(item.get('automation_level') or ''))}</div></td>"
        f"<td><span class='status status-{html.escape(status)}'>{html.escape(status)}</span><div class='mini'>必需 {html.escape(str(item.get('ready_required', 0)))}/{html.escape(str(item.get('required_count', 0)))}</div></td>"
        f"<td>{render_short_list(item.get('must_capture_fields') if isinstance(item.get('must_capture_fields'), list) else [], limit=5)}<div class='mini'>证据：{html.escape(', '.join(required[:4]))}</div></td>"
        f"<td>{render_short_list(item.get('ai_decisions') if isinstance(item.get('ai_decisions'), list) else [], limit=4)}</td>"
        f"<td>{render_short_list(item.get('outputs') if isinstance(item.get('outputs'), list) else [], limit=4)}</td>"
        f"<td>{render_short_list(item.get('approval_gates') if isinstance(item.get('approval_gates'), list) else [], limit=3)}</td>"
        f"<td>{render_short_list(item.get('missing_details') if isinstance(item.get('missing_details'), list) else [], limit=4)}<div class='mini'>{html.escape(str(item.get('next_action') or ''))}</div></td>"
        f"<td>{page_link}</td>"
        "</tr>"
    )


def build_video_publishing_payload(root: Path) -> dict[str, Any]:
    accounts = sorted(read_records(root, "social_account_profile"), key=lambda item: item.created_at, reverse=True)
    plans = sorted(read_records(root, "video_publish_plan"), key=lambda item: item.created_at, reverse=True)
    stores: dict[str, dict[str, Any]] = {}
    for record in accounts:
        fields = record.fields
        store_id = str(fields.get("store_id") or fields.get("target_store_id") or "unassigned")
        entry = stores.setdefault(
            store_id,
            {
                "store_id": store_id,
                "official_accounts": 0,
                "channel_accounts": 0,
                "bound_accounts": 0,
                "total_accounts": 0,
                "missing_channel_accounts": 4,
                "ready": False,
            },
        )
        role = str(fields.get("account_role") or "").lower()
        entry["total_accounts"] += 1
        if "official" in role or "官方" in role:
            entry["official_accounts"] += 1
        if "channel" in role or "渠道" in role:
            entry["channel_accounts"] += 1
        if not record.score.get("requires_aip_binding"):
            entry["bound_accounts"] += 1
    for entry in stores.values():
        entry["missing_channel_accounts"] = max(0, 4 - int(entry.get("channel_accounts") or 0))
        entry["ready"] = bool(
            int(entry.get("official_accounts") or 0) >= 1
            and int(entry.get("channel_accounts") or 0) >= 4
            and int(entry.get("bound_accounts") or 0) >= 1
        )
    blocked_plans = [record for record in plans if record.score.get("blocks_auto_publish")]
    ready_plans = [record for record in plans if record.score.get("publish_ready")]
    return {
        "stores": sorted(stores.values(), key=lambda item: str(item.get("store_id") or "")),
        "accounts": [record.to_dict() for record in accounts],
        "plans": [record.to_dict() for record in plans],
        "summary": {
            "account_count": len(accounts),
            "publish_plan_count": len(plans),
            "ready_plan_count": len(ready_plans),
            "blocked_plan_count": len(blocked_plans),
        },
    }


def video_status_label(value: Any) -> str:
    text = str(value or "").strip()
    normalized = text.lower()
    mapping = {
        "official": "官方号",
        "channel": "渠道号",
        "not_bound": "未绑定",
        "bound": "已绑定",
        "manual_gate": "需人工登录/验证",
        "unknown": "待确认",
        "tiktok_library_safe": "TikTok 商用曲库可用",
        "licensed": "已授权",
        "unauthorized": "未授权，不可用",
        "royalty_free": "免版权/可商用",
        "commercial": "商用授权",
        "safe": "安全",
        "true": "是",
        "false": "否",
    }
    return mapping.get(normalized, text or "未填写")


def video_action_label(score: dict[str, Any]) -> tuple[str, str]:
    if score.get("publish_ready"):
        return "素材包已齐，可进入发布确认", "badge"
    if score.get("blocks_auto_publish"):
        return "先补资料/音乐复核", "badge bad"
    return "草稿，继续补齐", "badge warn"


def video_account_bind_label(fields: dict[str, Any], score: dict[str, Any]) -> tuple[str, str]:
    if score.get("requires_aip_binding"):
        return "需绑定 AIP 或人工确认权限", "badge warn"
    if str(fields.get("can_publish_video") or "").lower() in {"true", "yes", "1"}:
        return "可发视频，但发布仍需确认", "badge"
    return "已绑定/可用性待复核", "badge"


def build_store_data_import_payload(root: Path, session_info: dict[str, Any] | None = None) -> dict[str, Any]:
    dashboard = summarize_store_metrics(
        root,
        start=None,
        end=None,
        platform="all",
        store="all",
        country="all",
        grain="day",
        **session_metric_scope_filters(session_info),
    )
    recent_records = [
        record
        for record in sorted(read_records(root, "store_metric_snapshot"), key=lambda item: item.created_at, reverse=True)
        if store_record_matches_session_scope(record, session_info)
    ][:30]
    return {
        "dashboard": dashboard,
        "recent_records": [record.to_dict() for record in recent_records],
    }


def build_feedback_center_payload(root: Path) -> dict[str, Any]:
    records = sorted(read_records(root, "feedback_ticket"), key=lambda item: item.created_at, reverse=True)
    summary: dict[str, int] = {}
    for record in records:
        category = str(record.score.get("feedback_category") or record.fields.get("feedback_type") or "feedback")
        summary[category] = summary.get(category, 0) + 1
    return {
        "summary": {
            "total": len(records),
            "by_category": summary,
            "with_visual_evidence": sum(1 for record in records if record.score.get("has_visual_evidence")),
            "requires_fix": sum(1 for record in records if record.score.get("requires_fix_draft")),
        },
        "records": [record.to_dict() for record in records[:80]],
    }


def render_feedback_center_page(root: Path) -> str:
    payload = build_feedback_center_payload(root)
    summary = payload["summary"]
    rows = "".join(render_feedback_ticket_row(item) for item in payload["records"]) or (
        "<tr><td colspan='8'>暂无反馈。别人觉得哪里不好、数据不准、页面看不懂或想新增功能，都可以在这里提交。</td></tr>"
    )
    by_category = summary.get("by_category", {})
    category_cards = "".join(
        f"<div class='metric-card'><span>{html.escape(str(key))}</span><strong>{html.escape(str(value))}</strong></div>"
        for key, value in by_category.items()
    ) or "<div class='metric-card'><span>反馈分类</span><strong>0</strong></div>"
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>投诉建议中心</title>
  <style>{simple_page_css()}
    main {{ max-width: 1320px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; }}
    .two-col {{ display: grid; grid-template-columns: 0.8fr 1.2fr; gap: 14px; align-items: start; }}
    label {{ display: block; font-size: 12px; color: #7b8490; margin: 8px 0 4px; font-weight: 800; }}
    input, select, textarea {{ width: 100%; box-sizing: border-box; border: 1px solid #d7dee5; border-radius: 6px; padding: 9px 10px; font: inherit; background: #fff; }}
    textarea {{ min-height: 96px; resize: vertical; }}
    .form-grid {{ display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 8px 12px; }}
    .full {{ grid-column: 1 / -1; }}
    .canvas-wrap {{ border: 1px dashed #cfd8df; border-radius: 8px; background: #f8fbfb; padding: 10px; }}
    canvas {{ max-width: 100%; width: 100%; min-height: 280px; background: #fff; border: 1px solid #e8edf2; border-radius: 6px; cursor: crosshair; }}
    .hint {{ background: #f6fbfb; border: 1px solid #d7eeee; border-radius: 8px; padding: 12px; line-height: 1.55; }}
    .thumb {{ max-width: 96px; max-height: 72px; border: 1px solid #e8edf2; border-radius: 6px; object-fit: cover; background: #fff; }}
    table {{ width: 100%; border-collapse: collapse; }}
    th, td {{ padding: 10px; border-bottom: 1px solid #e8edf2; text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ color: #7b8490; font-size: 12px; }}
    @media (max-width: 980px) {{ .two-col, .form-grid {{ grid-template-columns: 1fr; }} .full {{ grid-column: auto; }} }}
  </style>
</head>
<body>
  <header>
    <h1>投诉建议中心</h1>
    <div class="muted">给测试用户、大卖家和内部运营提交问题。支持截图/视频截图上传、鼠标画圈标注，AI自动归类为 bug、数据偏差、界面体验、功能建议或运营策略问题。</div>
    <div class="actions">
      <a class="button secondary" href="/dashboard">返回控制台</a>
      <a class="button secondary" href="/chat?intent=approval">查看AI待办草稿</a>
      <a class="button secondary" href="/workflow">工作流自检</a>
      <a class="button secondary" href="/report">今日报告</a>
    </div>
  </header>
  <main>
    <section class="grid">
      <div class="metric-card"><span>总反馈</span><strong>{html.escape(str(summary.get("total", 0)))}</strong></div>
      <div class="metric-card"><span>带截图/标注</span><strong>{html.escape(str(summary.get("with_visual_evidence", 0)))}</strong></div>
      <div class="metric-card"><span>需修复草稿</span><strong>{html.escape(str(summary.get("requires_fix", 0)))}</strong></div>
      {category_cards}
    </section>

    <div class="two-col">
      <section class="panel">
        <h2>提交反馈</h2>
        <div class="form-grid" id="feedbackForm">
          <div><label>反馈类型</label><select name="feedback_type"><option value="bug">bug/不能用</option><option value="data_accuracy">数据不准</option><option value="ux_ui">界面体验</option><option value="feature_request">功能建议</option><option value="operation_strategy">运营策略</option><option value="other">其他</option></select></div>
          <div><label>严重程度</label><select name="severity"><option value="medium">medium</option><option value="high">high</option><option value="critical">critical</option><option value="low">low</option></select></div>
          <div><label>模块/页面</label><input name="module_area" placeholder="经营大屏 / 视频发布 / 店铺数据"></div>
          <div><label>提交人</label><input name="feedback_source" placeholder="姓名/品牌/店铺/测试用户"></div>
          <div class="full"><label>问题页面链接</label><input name="page_url" placeholder="http://127.0.0.1:8765/..."></div>
          <div class="full"><label>问题描述</label><textarea name="feedback_text" placeholder="哪里不行、哪里看不懂、数据哪里不对、想新增什么"></textarea></div>
          <div class="full"><label>实际情况</label><textarea name="actual_behavior" placeholder="现在看到的情况"></textarea></div>
          <div class="full"><label>期望结果/建议</label><textarea name="expected_behavior" placeholder="希望改成什么样"></textarea></div>
          <div class="full"><label>标注说明</label><textarea name="annotation_notes" placeholder="比如：红圈这里按钮太多；箭头这里数据不准；这里需要加图片"></textarea></div>
        </div>
        <div class="actions"><button onclick="submitFeedback()">提交给AI分析</button></div>
        <div id="feedbackStatus" class="muted"></div>
      </section>

      <section class="panel">
        <h2>上传截图并画圈</h2>
        <div class="hint">可以上传页面截图或视频截图，然后用鼠标直接画圈/划线。提交后会保存原图和标注图，AI会优先处理带证据的反馈。</div>
        <label>截图/视频截图</label>
        <input id="feedbackImage" type="file" accept="image/png,image/jpeg,image/webp">
        <div class="actions">
          <button class="secondary" onclick="clearAnnotation()">清除标注</button>
        </div>
        <div class="canvas-wrap"><canvas id="annotationCanvas" width="900" height="520"></canvas></div>
      </section>
    </div>

    <section class="panel">
      <h2>最近反馈</h2>
      <table><thead><tr><th>时间</th><th>分类</th><th>模块</th><th>问题</th><th>严重程度</th><th>证据</th><th>AI优先级</th><th>状态</th></tr></thead><tbody>{rows}</tbody></table>
    </section>
  </main>
  <script>
    let imageDataUrl = "";
    let baseImage = null;
    let drawing = false;
    const canvas = document.getElementById('annotationCanvas');
    const ctx = canvas.getContext('2d');
    drawEmpty();
    document.getElementById('feedbackImage').addEventListener('change', async (event) => {{
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      imageDataUrl = await readFile(file);
      baseImage = new Image();
      baseImage.onload = () => drawBaseImage();
      baseImage.src = imageDataUrl;
    }});
    canvas.addEventListener('mousedown', (event) => {{ drawing = true; drawPoint(event, true); }});
    canvas.addEventListener('mousemove', (event) => {{ if (drawing) drawPoint(event, false); }});
    window.addEventListener('mouseup', () => drawing = false);
    function readFile(file) {{
      return new Promise((resolve, reject) => {{
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ""));
        reader.onerror = reject;
        reader.readAsDataURL(file);
      }});
    }}
    function drawEmpty() {{
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#7b8490';
      ctx.font = '22px Arial';
      ctx.fillText('上传截图后可用鼠标画圈标注', 30, 70);
    }}
    function drawBaseImage() {{
      ctx.fillStyle = '#fff';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      const scale = Math.min(canvas.width / baseImage.width, canvas.height / baseImage.height);
      const w = baseImage.width * scale;
      const h = baseImage.height * scale;
      const x = (canvas.width - w) / 2;
      const y = (canvas.height - h) / 2;
      ctx.drawImage(baseImage, x, y, w, h);
    }}
    function drawPoint(event, start) {{
      const rect = canvas.getBoundingClientRect();
      const x = (event.clientX - rect.left) * (canvas.width / rect.width);
      const y = (event.clientY - rect.top) * (canvas.height / rect.height);
      ctx.strokeStyle = '#ff2d55';
      ctx.lineWidth = 5;
      ctx.lineCap = 'round';
      if (start) {{
        ctx.beginPath();
        ctx.moveTo(x, y);
      }} else {{
        ctx.lineTo(x, y);
        ctx.stroke();
      }}
    }}
    function clearAnnotation() {{
      if (baseImage) drawBaseImage(); else drawEmpty();
    }}
    async function submitFeedback() {{
      const box = document.getElementById('feedbackForm');
      const fields = {{}};
      box.querySelectorAll('input, select, textarea').forEach((item) => fields[item.name] = item.value);
      const annotated = imageDataUrl ? canvas.toDataURL('image/png') : "";
      const res = await fetch('/api/feedback-center/add', {{
        method: 'POST',
        headers: {{ 'Content-Type': 'application/json' }},
        body: JSON.stringify({{ fields, image_data_url: imageDataUrl, annotated_image_data_url: annotated }})
      }});
      const data = await res.json();
      const status = document.getElementById('feedbackStatus');
      if (!data.ok) {{ status.textContent = data.error || '提交失败'; return; }}
      status.textContent = '已提交，AI分类：' + (data.record.score.feedback_category || 'feedback') + '，优先级：' + data.record.score.priority;
      setTimeout(() => location.reload(), 700);
    }}
  </script>
</body>
</html>"""


def render_feedback_ticket_row(item: dict[str, Any]) -> str:
    fields = item.get("fields", {}) if isinstance(item.get("fields"), dict) else {}
    score = item.get("score", {}) if isinstance(item.get("score"), dict) else {}
    image_path = str(fields.get("annotated_image_path") or fields.get("screenshot_path") or "")
    evidence = render_reference_image(image_path) if image_path else ""
    return (
        "<tr>"
        f"<td>{html.escape(str(item.get('created_at') or '')[:19])}</td>"
        f"<td>{html.escape(str(score.get('feedback_category') or fields.get('feedback_type') or 'feedback'))}</td>"
        f"<td>{html.escape(str(fields.get('module_area') or ''))}</td>"
        f"<td>{html.escape(str(fields.get('feedback_text') or fields.get('suggestion') or '')[:220])}</td>"
        f"<td>{html.escape(str(fields.get('severity') or ''))}</td>"
        f"<td>{evidence}</td>"
        f"<td>{html.escape(str(score.get('priority', '')))}</td>"
        f"<td>{html.escape(str(fields.get('feedback_status') or 'new'))}</td>"
        "</tr>"
    )


