def build_big_screen_ai_report(
    root: Path,
    *,
    platform: str,
    store: str,
    country: str,
    product: str,
    session_info: dict[str, Any] | None = None,
) -> dict[str, Any]:
    records = [
        record
        for record in read_records(root, "store_metric_snapshot")
        if record.review_status != "pending" and is_real_store_metric_record(record)
        and store_record_matches_session_scope(record, session_info)
    ]
    grouped: dict[str, list[IntakeRecord]] = {}
    for record in records:
        if not big_screen_record_matches(record, platform=platform, store=store, country=country, product=product):
            continue
        grouped.setdefault(record.record_type, []).append(record)

    counts = {key: len(value) for key, value in grouped.items()}
    total = sum(counts.values())
    sales_count = counts.get("store_metric_snapshot", 0)
    sales_records = grouped.get("store_metric_snapshot", [])
    refund_records = [
        record
        for record in sales_records
        if number_like(record.fields.get("refund_amount")) > 0
        or number_like(record.fields.get("refund_count")) > 0
        or number_like(record.fields.get("return_count")) > 0
    ]
    ad_records = [record for record in sales_records if number_like(record.fields.get("ad_spend")) > 0]

    cards = [
        {
            "label": "总判断",
            "title": f"已读取 {total} 条自己店铺数据" if total else "后台 AI 等待店铺经营数据",
            "body": build_big_screen_main_judgement(total, sales_count, len(refund_records), len(ad_records)),
        },
        {
            "label": "销售快照",
            "title": f"{sales_count} 条销售/订单/财务快照",
            "body": summarize_top_record(sales_records, "后台 AI 等待授权范围内的订单、销售、广告、退款退货或结算数据，读取后自动生成经营快照。"),
        },
        {
            "label": "退款退货",
            "title": f"{len(refund_records)} 条退款/退货记录" if refund_records else "退款退货待读取",
            "body": summarize_top_record(refund_records, "后台 AI 还没有读到退款退货数据，暂时不能判断是否异常。"),
        },
        {
            "label": "投流线索",
            "title": f"{len(ad_records)} 条含广告花费/ROAS",
            "body": summarize_top_record(ad_records, "后台 AI 读取广告花费后，会按店铺、平台和时间段复盘 ROAS。"),
        },
    ]
    source_map = [
        ("自己店铺销售快照", "store_metric_snapshot", "分析国家、平台、店铺、商品、退款、广告和时间段走势"),
    ]
    source_rows = [
        {
            "name": label,
            "count": counts.get(record_type, 0),
            "priority": top_priority(grouped.get(record_type, [])),
            "action": action,
        }
        for label, record_type, action in source_map
        if counts.get(record_type, 0) or total == 0
    ]
    return {"cards": cards, "sourceRows": source_rows, "rankingRows": []}


def big_screen_record_matches(record: IntakeRecord, *, platform: str, store: str, country: str, product: str) -> bool:
    fields = record.fields
    text = " ".join(str(value) for value in fields.values()).lower()
    if product and product.lower() not in text:
        return False
    if platform and platform != "all":
        platform_text = str(fields.get("marketplace") or fields.get("source_platform") or fields.get("platform") or "").lower()
        if platform.lower() not in platform_text:
            return False
    if store and store != "all":
        store_text = str(fields.get("store_id") or fields.get("store_name") or fields.get("target_store") or "").lower()
        if store.lower() not in store_text:
            return False
    if country and country != "all":
        country_text = str(fields.get("country") or fields.get("country_code") or fields.get("market") or fields.get("region") or "").lower()
        if normalize_country_key(country) not in {normalize_country_key(country_text), country_text} and country.lower() not in text:
            return False
    return True


def build_big_screen_main_judgement(total: int, sales_count: int, refund_count: int, ad_count: int) -> str:
    if total == 0:
        return "当前筛选下后台 AI 暂未读到店铺经营数据；负责人确认授权范围或报表来源后会自动整理销售、订单、广告、退款退货和结算。"
    signals = []
    if sales_count:
        signals.append("已有自己店铺销售数据，可以按国家、平台、店铺、商品和时间段复盘")
    if refund_count:
        signals.append("存在退款/退货信号，需要联动客服、Listing和产品质量")
    if ad_count:
        signals.append("存在广告花费数据，可以继续做ROAS和投流节奏分析")
    return "；".join(signals) if signals else "已有自己店铺数据，后台 AI 会继续补齐销售、订单、广告、退款退货和结算字段。"


def summarize_top_record(records: list[IntakeRecord], fallback: str) -> str:
    if not records:
        return fallback
    top = max(records, key=lambda item: float(item.score.get("priority", 0) or 0))
    return f"优先看：{record_display_name(top)}。AI建议：{'; '.join(top.director_notes[:1]) or '进入拆解和复盘。'}"


def top_priority(records: list[IntakeRecord]) -> str:
    if not records:
        return "-"
    return str(max(int(float(record.score.get("priority", 0) or 0)) for record in records))


def number_like(value: Any) -> float:
    if value in {"", None}:
        return 0.0
    if isinstance(value, (int, float)):
        return float(value)
    clean = re.sub(r"[^0-9.\-]", "", str(value))
    if not clean or clean in {"-", ".", "-."}:
        return 0.0
    try:
        return float(clean)
    except ValueError:
        return 0.0


