def render_big_screen_options(
    items: list[str],
    selected: str,
    all_label: str,
    labels: dict[str, str] | None = None,
) -> str:
    seen: list[str] = []
    for item in items:
        if item not in seen:
            seen.append(item)
    return "".join(
        f"<option value='{html.escape(item)}' {'selected' if item == selected else ''}>{html.escape(all_label if item == 'all' else (labels or {}).get(item, item))}</option>"
        for item in seen
    )


def big_screen_scope_label(
    selected: str,
    *,
    all_label: str,
    options: list[str],
    missing_label: str,
    country: bool = False,
) -> str:
    if selected in {"", "all"}:
        return all_label
    clean_selected = str(selected or "").strip()
    selected_key = normalize_country_key(clean_selected) if country else clean_selected.lower()
    for item in options:
        if item == "all":
            continue
        item_key = normalize_country_key(item) if country else item.strip().lower()
        if item_key and item_key == selected_key:
            return item
    return missing_label


def ensure_selected_option(items: list[str], selected: str) -> list[str]:
    result = list(items)
    if selected and selected != "all" and selected not in result:
        result.append(selected)
    return result


def split_scope_values(value: Any) -> list[str]:
    if isinstance(value, list):
        raw_items = value
    else:
        raw_items = re.split(r"[,;|/\n]+", str(value or ""))
    return [str(item).strip() for item in raw_items if str(item).strip()]


