def big_screen_customer_visible_store_label(
    store_name_value: Any,
    *,
    platform: str = "",
    country: str = "",
    store_model: str = "",
    fallback: str = "当前店铺",
) -> str:
    raw_name = str(store_name_value or "").strip()
    platform_label = customer_safe_machine_text(platform, empty="平台待确认")
    country_label = str(country or "").strip().upper()
    model_value = normalize_channel_store_model_for_route(store_model)
    model_label = customer_safe_machine_text(model_value, empty="店铺模式待确认")
    if looks_like_demo_store_value(raw_name) and not store_name_looks_internal_audit_record(raw_name):
        return "历史/测试店铺（不作为真实店铺拉单、投放或外部执行）"
    if store_name_looks_internal_audit_record(raw_name):
        parts = [platform_label]
        if country_label:
            parts.append(country_label)
        if model_label and model_label != "店铺模式待确认":
            parts.append(model_label)
        elif country_label:
            parts.append("店铺")
        return " / ".join(part for part in parts if part).strip() or fallback
    return customer_visible_store_reference_name(
        raw_name,
        route_label=" / ".join(part for part in [platform_label, country_label, model_label] if part and part != "店铺模式待确认"),
        fallback=fallback,
    )


def record_scope_entries(root: Path) -> list[dict[str, str]]:
    entries: list[dict[str, str]] = []
    seen: set[tuple[str, str, str]] = set()

    def add_entry(
        platform: str,
        store: str,
        country_value: str,
        record_type: str,
        *,
        display_store: str = "",
        store_model: str = "",
    ) -> None:
        clean_platform = str(platform or "").strip()
        clean_store = str(store or "").strip()
        clean_country = str(country_value or "").strip()
        if not clean_platform or clean_platform == "Unknown" or not clean_store or clean_store == "Unassigned Store":
            return
        if not normalize_country_key(clean_country):
            return
        key = (
            clean_platform.lower(),
            clean_store.lower(),
            normalize_country_key(clean_country),
        )
        if key in seen:
            return
        seen.add(key)
        entries.append(
            {
                "platform": clean_platform,
                "store": clean_store,
                "display_store": str(display_store or clean_store).strip(),
                "country": clean_country,
                "store_model": str(store_model or "").strip(),
                "record_type": record_type,
            }
        )

    if account_center.profile_exists(root):
        profile = account_center.load_profile(root)
        for store in profile.get("stores") or []:
            if not isinstance(store, dict):
                continue
            if store_is_historical_test_record(store):
                continue
            add_entry(
                str(store.get("platform_label") or store.get("platform_id") or ""),
                str(store.get("store_name") or store.get("store_external_id") or ""),
                str(store.get("country_code") or ""),
                "account_store_binding",
                display_store=customer_visible_store_name_for_store(store, fallback="当前店铺"),
                store_model=str(store.get("shop_type") or store.get("store_model") or ""),
            )

    for record in read_records(root, "store_profile"):
        if is_fake_store_profile_record(record):
            continue
        fields = record.fields
        platform = str(fields.get("marketplace") or fields.get("platform") or fields.get("source_platform") or "").strip()
        store = str(fields.get("store_name") or fields.get("shop_name") or fields.get("store_id") or fields.get("seller_name") or "").strip()
        country_values: list[str] = []
        for raw in [
            fields.get("country"),
            fields.get("country_code"),
            fields.get("shop_region"),
            fields.get("market"),
            fields.get("markets"),
        ]:
            country_values.extend(split_scope_values(raw))
        if not country_values:
            country_values = [""]
        for country_value in country_values:
            add_entry(
                platform,
                store,
                country_value,
                "store_profile",
                display_store=big_screen_customer_visible_store_label(
                    store,
                    platform=platform,
                    country=country_value,
                    store_model=str(fields.get("shop_type") or fields.get("store_model") or ""),
                ),
                store_model=str(fields.get("shop_type") or fields.get("store_model") or ""),
            )

    for record in read_records(root, "store_metric_snapshot"):
        if not is_real_store_metric_record(record):
            continue
        fields = record.fields
        platform = platform_name(record)
        store = store_name(record)
        country_values = []
        for raw in [
            fields.get("country"),
            fields.get("country_code"),
            fields.get("region"),
            fields.get("market"),
            fields.get("markets"),
            fields.get("buyer_country"),
            fields.get("ship_to_country"),
        ]:
            country_values.extend(split_scope_values(raw))
        country_values = [item for item in country_values if normalize_country_key(item)]
        if not country_values:
            continue
        for country_value in country_values:
            add_entry(
                platform,
                store,
                country_value,
                "store_metric_snapshot",
                display_store=big_screen_customer_visible_store_label(
                    store,
                    platform=platform,
                    country=country_value,
                    store_model=str(fields.get("shop_type") or fields.get("store_model") or ""),
                ),
                store_model=str(fields.get("shop_type") or fields.get("store_model") or ""),
            )
    return entries


def scope_entry_matches(entry: dict[str, str], *, country: str = "all", platform: str = "all", store: str = "all") -> bool:
    if country not in {"", "all"} and normalize_country_key(entry.get("country", "")) != normalize_country_key(country):
        return False
    if platform not in {"", "all"} and entry.get("platform", "").strip().lower() != platform.strip().lower():
        return False
    if store not in {"", "all"} and entry.get("store", "").strip().lower() != store.strip().lower():
        return False
    return True


def unique_scope_values(entries: list[dict[str, str]], key: str) -> list[str]:
    values = sorted({str(entry.get(key) or "").strip() for entry in entries if str(entry.get(key) or "").strip()})
    if key == "store":
        values = [item for item in values if item != "Unassigned Store"]
    return values


def store_scope_display_labels(entries: list[dict[str, str]]) -> dict[str, str]:
    labels: dict[str, str] = {}
    for entry in entries:
        store = str(entry.get("store") or "").strip()
        if not store:
            continue
        label = str(entry.get("display_store") or "").strip()
        if not label or label == store:
            label = big_screen_customer_visible_store_label(
                store,
                platform=str(entry.get("platform") or ""),
                country=str(entry.get("country") or ""),
                store_model=str(entry.get("store_model") or ""),
            )
        labels.setdefault(store, label)
    return labels


def build_store_scope_catalog(
    root: Path,
    *,
    country: str = "all",
    platform: str = "all",
    store: str = "all",
    session_info: dict[str, Any] | None = None,
) -> dict[str, Any]:
    entries = record_scope_entries(root)
    if session_scope_is_restricted(session_info):
        entries = [
            entry
            for entry in entries
            if store_identity_matches_session_scope(
                str(entry.get("platform") or ""),
                str(entry.get("store") or ""),
                str(entry.get("country") or ""),
                session_info,
            )
        ]
    country_scoped = [entry for entry in entries if scope_entry_matches(entry, country=country)]
    platform_scoped = [entry for entry in country_scoped if scope_entry_matches(entry, platform=platform)]
    store_scoped = [entry for entry in platform_scoped if scope_entry_matches(entry, store=store)]
    countries = unique_scope_values(entries, "country")
    platforms = unique_scope_values(country_scoped or entries, "platform")
    stores = unique_scope_values(platform_scoped or country_scoped or entries, "store")
    quick_countries = unique_scope_values(entries, "country")[:12]
    quick_platforms = unique_scope_values(country_scoped or entries, "platform")[:10]
    quick_stores = unique_scope_values(platform_scoped or country_scoped or entries, "store")[:10]
    store_labels = store_scope_display_labels(platform_scoped or country_scoped or entries)
    return {
        "entries": entries,
        "active_entries": store_scoped if store_scoped else platform_scoped if platform_scoped else country_scoped,
        "countries": countries,
        "platforms": platforms,
        "stores": stores,
        "quick_countries": quick_countries,
        "quick_platforms": quick_platforms,
        "quick_stores": quick_stores,
        "store_labels": store_labels,
    }


