def summary_field_has_value(summary: dict[str, Any], field: str) -> bool:
    value = summary.get(field)
    if value in (None, "", [], {}):
        return False
    if isinstance(value, (int, float)):
        return value != 0
    return True


def manifest_detected_fields_from_summary(summary: dict[str, Any], fields: list[str]) -> list[str]:
    labels = {
        "orders": "订单量",
        "units": "件数",
        "revenue": "销售额",
        "net_revenue": "净销售额",
        "ad_spend": "广告花费",
        "roas": "ROAS",
        "cpa": "CPA",
        "refund_amount": "退款金额",
        "refund_count": "退款数",
        "return_count": "退货数",
        "settlement_amount": "结算金额",
    }
    return [labels.get(field, field) for field in fields if summary_field_has_value(summary, field)]


def manifest_record_count(root: Path, record_types: list[str], session_info: dict[str, Any] | None) -> int:
    if not record_types:
        return 0
    return count_records_for_session_scope(root, record_types, session_info)


def manifest_action_count(root: Path, keywords: list[str], session_info: dict[str, Any] | None) -> int:
    if not keywords:
        return 0
    lowered = [keyword.lower() for keyword in keywords]
    total = 0
    for action in pending_actions_for_session_scope(root, session_info):
        text = " ".join(
            str(action.get(key) or "")
            for key in ("action_type", "title", "reason", "approval_category", "route_key")
        ).lower()
        if any(keyword in text for keyword in lowered):
            total += 1
    return total


def build_store_data_manifest(
    root: Path | None,
    session_info: dict[str, Any] | None,
    summary: dict[str, Any] | None = None,
) -> dict[str, Any]:
    summary = summary or {}
    if root is None or not session_info:
        domains = [
            {
                "id": spec["id"],
                "label": spec["label"],
                "status": "missing",
                "status_label": "待读取",
                "evidence_count": 0,
                "detected_fields": [],
                "required_fields": list(spec.get("required_fields") or []),
                "next_step": spec.get("next_step") or "等待后台 AI 读取授权范围内的数据。",
            }
            for spec in STORE_DATA_MANIFEST_SPECS
        ]
        return {
            "domains": domains,
            "ready_count": 0,
            "missing_count": len(domains),
            "critical_gaps": [domain["label"] for domain in domains],
            "can_use_for_autopilot": False,
            "lines": store_data_manifest_lines(domains),
        }
    domains: list[dict[str, Any]] = []
    for spec in STORE_DATA_MANIFEST_SPECS:
        record_count = manifest_record_count(root, list(spec.get("record_types") or []), session_info)
        detected_fields = manifest_detected_fields_from_summary(summary, list(spec.get("summary_fields") or []))
        action_count = manifest_action_count(root, list(spec.get("action_keywords") or []), session_info)
        evidence_count = record_count + (1 if detected_fields else 0) + action_count
        status = "ready" if evidence_count else "missing"
        if spec["id"] == "campaign_signup_status" and action_count:
            status_label = "有待确认草稿"
        else:
            status_label = "可分析" if status == "ready" else "待读取"
        evidence_bits: list[str] = []
        if record_count:
            evidence_bits.append(f"{record_count} 条记录")
        if detected_fields:
            evidence_bits.append("已识别 " + "、".join(detected_fields[:5]))
        if action_count:
            evidence_bits.append(f"{action_count} 条待确认动作")
        domains.append(
            {
                "id": spec["id"],
                "label": spec["label"],
                "status": status,
                "status_label": status_label,
                "evidence_count": evidence_count,
                "record_count": record_count,
                "action_count": action_count,
                "detected_fields": detected_fields,
                "required_fields": list(spec.get("required_fields") or []),
                "evidence_text": "；".join(evidence_bits) if evidence_bits else "后台 AI 还没有读到可用证据",
                "next_step": spec.get("next_step") or "等待后台 AI 读取授权范围内的数据。",
            }
        )
    ready_count = sum(1 for domain in domains if domain["status"] == "ready")
    missing = [domain for domain in domains if domain["status"] != "ready"]
    return {
        "domains": domains,
        "ready_count": ready_count,
        "missing_count": len(missing),
        "critical_gaps": [domain["label"] for domain in missing],
        "can_use_for_autopilot": ready_count >= 5 and not any(
            domain["id"] in {"orders_sales", "settlement_finance"} for domain in missing
        ),
        "lines": store_data_manifest_lines(domains),
    }


def store_data_manifest_lines(domains: list[dict[str, Any]]) -> list[str]:
    lines: list[str] = []
    for domain in domains:
        required = "、".join([str(item) for item in (domain.get("required_fields") or [])[:4]])
        detected = "、".join([str(item) for item in (domain.get("detected_fields") or [])[:4]]) or str(
            domain.get("evidence_text") or "未读到"
        )
        lines.append(
            f"{domain.get('label')}：{domain.get('status_label')}；已看到 {detected}；后台要核对 {required}；下一步 {domain.get('next_step')}"
        )
    return lines


def first_scope_value(value: Any) -> str:
    values = scope_values(value)
    return values[0] if len(values) == 1 else ""


def session_metric_scope_filters(session_info: dict[str, Any] | None) -> dict[str, list[str]]:
    if not session_scope_is_restricted(session_info):
        return {}
    assert session_info is not None
    filters: dict[str, list[str]] = {}
    platform_values = scope_values(session_info.get("platform_scope"))
    store_values = scope_values(session_info.get("store_scope"))
    if platform_values:
        filters["allowed_platforms"] = platform_values
    if store_values:
        filters["allowed_stores"] = store_values
    return filters


def session_scope_context_values(session_info: dict[str, Any] | None) -> dict[str, Any]:
    if not session_scope_is_restricted(session_info):
        return {
            "restricted": False,
            "store": "",
            "platform": "",
            "country": "",
            "store_values": [],
            "platform_values": [],
            "country_values": [],
            "store_label": "",
            "platform_label": "",
            "country_label": "",
        }
    assert session_info is not None
    store_values = scope_values(session_info.get("store_scope"))
    platform_values = scope_values(session_info.get("platform_scope"))
    country_values = scope_values(session_info.get("country_scope"))
    return {
        "restricted": True,
        "store": store_values[0] if len(store_values) == 1 else "",
        "platform": platform_values[0] if len(platform_values) == 1 else "",
        "country": country_values[0] if len(country_values) == 1 else "",
        "store_values": store_values,
        "platform_values": platform_values,
        "country_values": country_values,
        "store_label": "、".join(store_values) if store_values else "全部店铺",
        "platform_label": "、".join(platform_values) if platform_values else "全部平台",
        "country_label": "、".join(country_values) if country_values else "全部站点",
    }


def session_with_query_scope(
    session_info: dict[str, Any] | None,
    *,
    store: str = "",
    platform: str = "",
    country: str = "",
) -> dict[str, Any] | None:
    if not session_info:
        return session_info
    clean_store = str(store or "").strip()
    clean_platform = str(platform or "").strip()
    clean_country = str(country or "").strip().upper()
    if not any([clean_store, clean_platform, clean_country]):
        return session_info
    scoped = dict(session_info)
    if session_scope_is_restricted(session_info):
        current = session_scope_context_values(session_info)
        allowed_stores = [str(item) for item in current.get("store_values", [])]
        allowed_platforms = [str(item) for item in current.get("platform_values", [])]
        if clean_store and (not allowed_stores or scope_value_matches(clean_store, allowed_stores)):
            scoped["store_scope"] = clean_store
        elif clean_store and allowed_stores:
            scoped["store_scope"] = ",".join(allowed_stores)
        if clean_platform and (not allowed_platforms or scope_value_matches(clean_platform, allowed_platforms)):
            scoped["platform_scope"] = clean_platform
        elif clean_platform and allowed_platforms:
            scoped["platform_scope"] = ",".join(allowed_platforms)
    else:
        if clean_store:
            scoped["store_scope"] = clean_store
        if clean_platform:
            scoped["platform_scope"] = clean_platform
    if clean_country:
        scoped["country_scope"] = clean_country
    scoped["_query_scope_active"] = True
    return scoped


def render_session_scope_context_inputs(session_info: dict[str, Any] | None) -> str:
    values = session_scope_context_values(session_info)
    if not values["restricted"]:
        return ""
    return (
        f'<input type="hidden" id="storeId" value="{html.escape(str(values["store"]))}">'
        f'<input type="hidden" id="platform" value="{html.escape(str(values["platform"]))}">'
        f'<input type="hidden" id="country" value="{html.escape(str(values["country"]))}">'
        '<div class="muted scope-context" data-ai-scope="session">'
        "当前账号范围："
        f'{html.escape(str(values["platform_label"]))} / {html.escape(str(values["store_label"]))}'
        "</div>"
    )


def seller_chat_context_from_payload(
    root: Path | None,
    payload: dict[str, Any],
    session_info: dict[str, Any] | None,
) -> dict[str, Any]:
    session_info_for_scope = session_with_query_scope(
        session_info,
        store=str(payload.get("store_id") or payload.get("store") or payload.get("shop_id") or ""),
        platform=str(payload.get("platform") or ""),
        country=str(payload.get("country") or ""),
    )
    page_context = payload.get("page_context") if isinstance(payload.get("page_context"), dict) else {}
    page_context = dict(page_context)
    if not session_info_for_scope or session_scope_is_restricted(session_info_for_scope):
        page_context = sanitize_frontend_page_context_for_session_scope(page_context)
    context: dict[str, Any] = {
        "store_id": payload.get("store_id") or "",
        "platform": payload.get("platform") or "",
        "country": payload.get("country") or "",
        "product_id": payload.get("product_id") or "",
        "page_title": payload.get("page_title") or "",
        "page_url": payload.get("page_url") or "",
        "page_context": page_context,
        "model_provider": payload.get("model_provider") or payload.get("provider") or "",
        "action_package": payload.get("action_package") or "",
        "authenticated": bool(session_info_for_scope),
    }
    if not session_info_for_scope:
        context["store_id"] = safe_anonymous_visible_context_value(context.get("store_id"))
        context["platform"] = safe_anonymous_visible_context_value(context.get("platform"))
        context["country"] = safe_anonymous_visible_context_value(context.get("country"), limit=16)
        context["page_url"] = sanitize_anonymous_page_url(str(context.get("page_url") or ""))
        if isinstance(context.get("page_context"), dict):
            context["page_context"]["url"] = context["page_url"]
            append_context_values(
                context["page_context"],
                "report_evidence_gaps",
                report_evidence_context_lines_for_chat(root, str(context.get("page_url") or "")),
            )
            if "intent=approval" in str(context.get("page_url") or "").lower():
                append_context_values(
                    context["page_context"],
                    "approval_queue",
                    approval_queue_context_lines_for_chat(root, None),
                )
        return context
    merge_backend_store_context_into_page_context(root, page_context, session_info_for_scope)
    append_context_values(
        page_context,
        "report_evidence_gaps",
        report_evidence_context_lines_for_chat(root, str(context.get("page_url") or "")),
    )
    if not session_scope_is_restricted(session_info_for_scope):
        return context
    values = session_scope_context_values(session_info_for_scope)
    platform_values = [str(item) for item in values["platform_values"]]
    store_values = [str(item) for item in values["store_values"]]
    country_values = [str(item) for item in values.get("country_values", [])]
    context["allowed_platforms"] = platform_values
    context["allowed_stores"] = store_values
    context["allowed_countries"] = country_values
    if len(platform_values) == 1:
        context["platform"] = platform_values[0]
    elif platform_values and not scope_value_matches(str(context.get("platform") or ""), platform_values):
        context["platform"] = ""
    if len(store_values) == 1:
        context["store_id"] = store_values[0]
    elif store_values and not scope_value_matches(str(context.get("store_id") or ""), store_values):
        context["store_id"] = ""
    if len(country_values) == 1:
        context["country"] = country_values[0]
    elif country_values and not scope_value_matches(str(context.get("country") or ""), country_values):
        context["country"] = ""
    context["page_url"] = sanitize_session_scoped_page_url(str(context.get("page_url") or ""), context)
    if isinstance(context.get("page_context"), dict):
        context["page_context"]["url"] = context["page_url"]
        append_context_values(
            context["page_context"],
            "report_evidence_gaps",
            report_evidence_context_lines_for_chat(root, str(context.get("page_url") or "")),
        )
    return context


def safe_anonymous_visible_context_value(value: Any, *, limit: int = 90) -> str:
    clean = re.sub(r"\s+", " ", str(value or "")).strip()
    if not clean:
        return ""
    blocked = re.compile(
        r"cloud_exec_|route[_\s-]?key|[a-z][a-z0-9_]*:[A-Z]{2,6}:[a-z][a-z0-9_]*|"
        r"secret|token|cookie|password|api\s*key|密钥|密码|令牌",
        re.I,
    )
    if blocked.search(clean):
        return ""
    return clean[:limit]


def sanitize_anonymous_page_url(page_url: str) -> str:
    return clean_page_context_url(page_url, limit=220)


def sanitize_frontend_page_context_for_session_scope(page_context: dict[str, Any]) -> dict[str, Any]:
    sanitized: dict[str, Any] = {}
    title = str(page_context.get("title") or "").strip()
    if title:
        sanitized["title"] = title[:120]
    headings = page_context.get("headings")
    if isinstance(headings, list):
        safe_headings = [str(item).strip()[:120] for item in headings if str(item).strip()]
        if safe_headings:
            sanitized["headings"] = safe_headings[:8]
    elif isinstance(headings, str) and headings.strip():
        sanitized["headings"] = [headings.strip()[:120]]
    return sanitized


def merge_backend_store_context_into_page_context(
    root: Path | None,
    page_context: dict[str, Any],
    session_info: dict[str, Any] | None,
) -> None:
    if root is None:
        return
    snapshot = store_erp_snapshot_for_chat(root, session_info)
    append_context_values(page_context, "route_rows", snapshot.get("route_lines") or [])
    append_context_values(page_context, "activity_rules", snapshot.get("activity_lines") or [])
    append_context_values(page_context, "activity_boundaries", snapshot.get("activity_boundary_lines") or [])
    append_context_values(page_context, "developer_capabilities", snapshot.get("developer_capability_lines") or [])
    append_context_values(page_context, "store_connection_rows", snapshot.get("connection_lines") or [])
    append_context_values(page_context, "store_data_manifest", snapshot.get("manifest_lines") or [])
    append_context_values(page_context, "execution_results", snapshot.get("execution_result_lines") or [])
    append_context_values(page_context, "approval_queue", approval_queue_context_lines_for_chat(root, session_info))
    gaps = [str(item) for item in (snapshot.get("gaps") or []) if str(item).strip()]
    if gaps and "erp_gaps" not in page_context:
        page_context["erp_gaps"] = ["、".join(gaps[:8])]


def report_evidence_context_lines_for_chat(root: Path | None, page_url: str) -> list[str]:
    if root is None:
        return []
    parsed = urlparse(page_url or "")
    if parsed.path != "/report-file":
        return []
    query = parse_qs(parsed.query)
    report_ref = query.get("id", [""])[0]
    filename = query.get("name", [""])[0] or Path(query.get("path", [""])[0]).name
    try:
        if report_ref:
            path = safe_output_report_path_by_reference(root, report_ref)
        elif filename:
            path = safe_output_report_path(root, filename)
        else:
            _content, path = load_dashboard_report_preview(root)
        content = path.read_text(encoding="utf-8", errors="replace")
    except Exception:
        return []

    score, missing, present = grade_operating_intelligence_report(sanitize_public_report_content(content))
    score, missing, present = align_report_summary_with_real_store_data(
        root,
        score=score,
        missing=missing,
        present=present,
    )
    lines = [
        f"报表证据完整度：{score}/100",
        "报表已有证据：" + ("、".join(present[:5]) if present else "证据不足"),
        "报表待读取证据：" + ("、".join(missing[:5]) if missing else "暂无明显缺口"),
    ]
    return lines


def approval_queue_context_lines_for_chat(
    root: Path | None,
    session_info: dict[str, Any] | None,
    limit: int = 5,
) -> list[str]:
    if root is None:
        return []
    if not session_info:
        return [
            "待确认动作：负责人登录后才显示具体店铺草稿、执行结果和草稿编号；未登录只说明确认规则。"
        ]
    actions = pending_actions_for_session_scope(root, session_info)
    if not actions:
        return ["待确认动作：当前授权范围内暂无真实动作等待负责人确认。"]
    decision_actions = [
        action
        for action in actions
        if str(action.get("status") or "pending_confirmation") == "pending_confirmation"
    ]
    approved_actions = [
        action
        for action in actions
        if str(action.get("status") or "") == "approved_pending_manual_execution"
    ]
    evidence_actions = [
        action
        for action in actions
        if str(action.get("status") or "") == "execution_needs_evidence"
    ]
    grouped: dict[tuple[str, str, str], list[dict[str, Any]]] = {}
    for action in decision_actions + approved_actions + evidence_actions:
        title = customer_safe_action_title(approval_title_text(action))
        status = str(action.get("status") or "pending_confirmation")
        action_type = str(action.get("action_type") or "")
        grouped.setdefault((status, action_type, title), []).append(action)
    grouped_actions = sorted(
        grouped.values(),
        key=lambda group: (
            -approval_risk_score(group[0]),
            -safe_int(group[0].get("priority") or 0),
            customer_safe_action_title(approval_title_text(group[0])),
        ),
    )
    lines = [
        (
            f"待确认动作汇总：{len(decision_actions)} 条等待负责人确认，"
            f"{len(approved_actions)} 条已确认待负责人手动执行，"
            f"{len(evidence_actions)} 条待补执行证据，已按风险合并为 {len(grouped_actions)} 组。"
        )
    ]
    for group in grouped_actions[:limit]:
        action = group[0]
        title = customer_safe_action_title(approval_title_text(action))
        status_label, _stage_class = approval_status_label(str(action.get("status") or "pending_confirmation"))
        risk_label = approval_risk_label(approval_risk_score(action))
        source_label = approval_source_category_label(action)
        route = "；".join(approval_route_group_labels(group)) or approval_route_summary(action)
        activity_boundary = approval_activity_boundary_summary(action)
        ads_boundary = approval_ads_boundary_summary(action)
        confirm = approval_confirmation_summary(action)
        rollback = approval_rollback_text(action)
        evidence_hint = approval_evidence_gap_summary(action)
        reason = approval_reason_text(action)
        if len(reason) > 90:
            reason = reason[:87].rstrip() + "..."
        group_suffix = f"；同类 {len(group)} 条" if len(group) > 1 else ""
        lines.append(
            "待确认动作："
            f"{title}{group_suffix}；状态={status_label}；风险={risk_label}；"
            f"来源={source_label}；店铺路线={route}；活动边界={activity_boundary}；广告边界={ads_boundary}；"
            f"原因={reason}；负责人确认={confirm}；回滚={rollback}；证据={evidence_hint}"
        )
    if len(grouped_actions) > limit:
        lines.append(f"待确认动作：还有 {len(grouped_actions) - limit} 组未展开，继续问 AI 可按风险查看证据和回滚条件。")
    return lines


def append_context_values(page_context: dict[str, Any], key: str, values: Any) -> None:
    if not isinstance(values, list):
        return
    existing = page_context.get(key)
    rows: list[str] = []
    if isinstance(existing, list):
        rows.extend(str(item) for item in existing if str(item).strip())
    elif isinstance(existing, str) and existing.strip():
        rows.append(existing.strip())
    for value in values:
        text = str(value or "").strip()
        if text and text not in rows:
            rows.append(text)
    if rows:
        page_context[key] = rows[:10]


def sanitize_session_scoped_page_url(page_url: str, context: dict[str, Any]) -> str:
    if not (context.get("allowed_stores") or context.get("allowed_platforms") or context.get("allowed_countries")):
        return page_url
    parsed = urlparse(clean_page_context_url(page_url, limit=220))
    query = parse_qs(parsed.query, keep_blank_values=True)
    store_id = str(context.get("store_id") or "").strip()
    platform = str(context.get("platform") or "").strip()
    country = str(context.get("country") or "").strip()
    if platform:
        query["platform"] = [platform]
    if country:
        query["country"] = [country]
    if store_id:
        for key in ("store_id", "shop_id", "shop", "store"):
            query.pop(key, None)
        query["store"] = [store_id]
    sanitized_query = urlencode(query, doseq=True)
    path = parsed.path or page_url.split("?", 1)[0] or ""
    fragment = f"#{parsed.fragment}" if parsed.fragment else ""
    return path + (f"?{sanitized_query}" if sanitized_query else "") + fragment


def coerce_session_scope_query_value(
    value: str,
    allowed_values: list[str],
    single_value: str,
    *,
    all_value: str = "all",
) -> str:
    clean = str(value or "").strip() or all_value
    if not allowed_values:
        return clean
    if clean.lower() == all_value:
        return single_value or all_value
    if scope_value_matches(clean, allowed_values):
        return clean
    return single_value or all_value


def imported_store_metric_identity_rows(root: Path) -> list[dict[str, str]]:
    rows: list[dict[str, str]] = []
    seen: set[tuple[str, str, str]] = set()
    for record in read_records(root, "store_metric_snapshot"):
        if not is_real_store_metric_record(record):
            continue
        fields = record.fields
        platform = str(fields.get("marketplace") or fields.get("platform") or fields.get("source_platform") or "").strip()
        name = str(fields.get("store_id") or fields.get("store_name") or fields.get("shop_id") or fields.get("shop_name") or "").strip()
        country = str(fields.get("country_code") or fields.get("country") or fields.get("market") or fields.get("shop_region") or "").strip().upper()
        key = store_identity_key(platform, name, country)
        if not platform or not name or key in seen:
            continue
        seen.add(key)
        rows.append({"platform": platform, "name": name, "country": country})
    return rows


def count_connected_store_identities(
    profile_stores: list[dict[str, Any]],
    store_profiles: list[IntakeRecord],
    imported_metric_stores: list[dict[str, str]] | None = None,
) -> int:
    identities: set[tuple[str, str, str]] = set()
    for store in profile_stores:
        if store_is_historical_test_record(store):
            continue
        platform = str(store.get("platform_label") or store.get("platform_id") or "").strip()
        name = str(store.get("store_name") or "").strip()
        country = str(store.get("country_code") or "").strip()
        if platform and name:
            identities.add(store_identity_key(platform, name, country))
    for record in store_profiles:
        fields = record.fields
        platform = str(fields.get("marketplace") or fields.get("platform") or fields.get("source_platform") or "").strip()
        name = str(fields.get("store_name") or fields.get("store_id") or "").strip()
        country = str(fields.get("country_code") or fields.get("shop_region") or fields.get("market") or "").strip()
        if re.search(r"\b(demo|sample|test|bundle)\b", name, flags=re.IGNORECASE):
            continue
        if platform and name:
            identities.add(store_identity_key(platform, name, country))
    for item in imported_metric_stores or []:
        platform = str(item.get("platform") or "").strip()
        name = str(item.get("name") or "").strip()
        country = str(item.get("country") or "").strip()
        if platform and name:
            identities.add(store_identity_key(platform, name, country))
    return len(identities)


def customer_visible_store_connection_count(connection_lines: list[str], fallback: int = 0) -> int:
    real_lines = [line for line in connection_lines if "历史/测试" not in str(line)]
    if real_lines:
        return len(real_lines)
    if connection_lines:
        return 0
    return fallback


def store_connection_next_step(method: str, *, key_present: bool = False, imported_profile: bool = False) -> str:
    if key_present:
        return "验证系统连接是否能同步订单、广告、售后和结算；未覆盖的数据由负责人确认一次报表范围，后台 AI 自动归类。"
    if imported_profile:
        return "店铺档案已接入；后台 AI 等待授权数据后自动读取订单、广告、售后、财务、库存和商品状态。"
    if method == "official_authorization":
        return "负责人完成官方授权后，后台 AI 自动校验订单、广告、退款和结算是否同步。"
    if method == "browser_visible_capture":
        return "负责人打开已登录页面后，后台 AI 读取可见订单、广告、售后和商品列表，不绕过验证。"
    if method == "report_import":
        return "负责人确认报表来源后，后台 AI 自动归类订单、广告、售后、财务、库存和商品状态。"
    return "已登记店铺范围；后台 AI 等待授权数据或负责人确认来源的报表后自动整理经营数据。"


def store_connection_sync_status(method: str, *, key_present: bool = False, imported_profile: bool = False, imported_metrics: bool = False) -> str:
    if key_present:
        return "系统连接已就绪，等待最近一次同步校验"
    if imported_metrics:
        return "已读到经营报表，等待负责人确认连接档案"
    if imported_profile:
        return "店铺档案已接入，等待授权数据"
    if method == "official_authorization":
        return "等待官方授权回调和权限范围校验"
    if method == "browser_visible_capture":
        return "等待负责人打开已登录页面后只读采集"
    if method == "report_import":
        return "等待负责人确认报表来源后后台归类"
    return "等待负责人确认店铺范围"


def store_connection_failure_reason(method: str, *, key_present: bool = False, imported_profile: bool = False, imported_metrics: bool = False) -> str:
    if key_present:
        return "暂未发现失败；后台 AI 仍需校验订单、广告、退款、结算是否完整"
    if imported_metrics:
        return "缺店铺授权档案，商品状态、库存和广告结算可能不完整"
    if imported_profile:
        return "缺授权数据，暂不能做放量、止损、利润和售后责任判断"
    if method == "official_authorization":
        return "未完成官方授权或授权范围未确认"
    if method == "browser_visible_capture":
        return "受登录、验证码和页面可见范围限制，不绕过平台验证"
    if method == "report_import":
        return "缺系统同步，报表口径需负责人确认后才能用于判断"
    return "缺平台、站点、店铺名或读取方式"


def store_connection_unbind_risk(method: str) -> str:
    if method == "official_authorization":
        return "解除授权会停止订单、广告、退款和结算同步；必须负责人确认"
    if method == "browser_visible_capture":
        return "退出登录或验证码会中断读取；后台 AI 只记录缺口"
    if method == "report_import":
        return "删除报表来源会让历史对账断层；先保留记录再停用"
    return "删除连接只移除本地读取范围，不会替你操作平台店铺"


def normalize_store_authorization_scopes(value: Any) -> list[str]:
    if isinstance(value, list):
        return [str(item).strip() for item in value if str(item).strip()]
    text = str(value or "")
    return [item.strip() for item in text.replace("\n", ",").replace("，", ",").split(",") if item.strip()]


def masked_business_identifier(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    compact = "".join(ch for ch in text if ch.isalnum())
    if len(compact) <= 4:
        return "已登记"
    return f"已登记，尾号 {compact[-4:]}"


def store_connection_ads_status(store: dict[str, Any]) -> str:
    ads_account = str(store.get("ads_account_id") or "").strip()
    business_center = str(store.get("business_center_id") or "").strip()
    if ads_account and business_center:
        return "广告投放归属已登记；后台 AI 等待校验店铺、广告权限和负责人范围一致"
    if ads_account:
        return "广告账号已登记；等待负责人确认归属主体，ROAS 暂不用于放量判断"
    return "未登记广告账号；广告花费、ROAS 和素材放量不会进入自动判断"


def store_connection_business_center_status(store: dict[str, Any]) -> str:
    business_center = masked_business_identifier(store.get("business_center_id"))
    if business_center:
        return "广告归属主体已登记；仍需校验店铺、广告账号和子账号归属一致"
    return "待确认店铺与广告账号是否同属一个归属主体；未确认前不做投流放量判断"


def store_connection_site_limit_status(store: dict[str, Any]) -> str:
    country = str(store.get("country_code") or "").strip().upper()
    identity_text = store_identity_scope_label(store, empty="")
    if country and identity_text:
        return f"{country} / {identity_text}；后台 AI 按站点、店铺模式和子店铺限制读取"
    if country:
        return f"{country} 已登记；仍需确认本土/跨境/半托管/ACCU 和子店铺限制"
    return "站点和店铺模式未确认；后台 AI 只保留缺口，不混用其他国家店铺"


def store_identity_scope_label(store: dict[str, Any], *, empty: str = "待确认") -> str:
    shop_type = str(store.get("shop_type") or "").strip()
    store_external_id = str(store.get("store_external_id") or "").strip()
    sub_store_name = str(store.get("sub_store_name") or "").strip()
    identity_bits: list[str] = []
    if shop_type:
        identity_bits.append(customer_safe_machine_text(shop_type, empty="店铺模式待确认"))
    if store_external_id:
        identity_bits.append("平台店铺编号已登记")
    if sub_store_name:
        identity_bits.append("内部子店铺备注已登记")
    return " / ".join(identity_bits) or empty


def render_store_authorization_queue(profile_stores: list[dict[str, Any]], imported_metric_stores: list[dict[str, str]] | None = None) -> str:
    profile_stores = [store for store in profile_stores if not store_is_historical_test_record(store)]
    store_count = len(profile_stores)
    metric_count = len(imported_metric_stores or [])
    official_count = sum(1 for store in profile_stores if str(store.get("connection_method") or "") == "official_authorization")
    ready_count = sum(1 for store in profile_stores if store.get("key_present"))
    ads_count = sum(1 for store in profile_stores if str(store.get("ads_account_id") or "").strip())
    bc_count = sum(1 for store in profile_stores if str(store.get("business_center_id") or "").strip())
    scope_count = sum(1 for store in profile_stores if normalize_store_authorization_scopes(store.get("authorization_scopes")))
    shop_type_count = sum(1 for store in profile_stores if str(store.get("shop_type") or "").strip())
    shop_identity_count = sum(
        1
        for store in profile_stores
        if str(store.get("shop_type") or store.get("store_external_id") or store.get("sub_store_name") or "").strip()
    )
    sample_store = profile_stores[0] if profile_stores else {}
    if store_count:
        auth_status = f"{official_count or store_count}/{store_count} 家店铺进入授权核对；{ready_count} 家系统连接就绪"
        data_scope_status = f"{scope_count}/{store_count} 家已登记权限范围"
        ads_status = (
            store_connection_ads_status(sample_store)
            if store_count == 1
            else f"{ads_count}/{store_count} 家广告账号档案已登记；仍需校验店铺授权、广告归属和负责人范围，未完成前 ROAS 不参与放量判断"
        )
        bc_status = (
            store_connection_business_center_status(sample_store)
            if store_count == 1
            else f"{bc_count}/{store_count} 家广告归属主体档案已登记；仍需校验店铺、广告账号和子账号归属一致"
        )
        site_status = store_connection_site_limit_status(sample_store) if store_count == 1 else f"{shop_identity_count}/{store_count} 家已登记店铺范围；其余按站点限制暂停判断"
    else:
        auth_status = "等待负责人登记第一家店铺；后台 AI 之后再建立读取边界"
        data_scope_status = "等待订单、商品、库存、广告、退款、财务结算等权限范围"
        ads_status = "未登记广告账号；广告花费、ROAS 和素材放量不会进入自动判断"
        bc_status = "待确认店铺与广告账号是否同属一个归属主体"
        site_status = "站点和店铺模式未确认；不混用其他国家店铺"
    if metric_count and not store_count:
        auth_status = f"已从 {metric_count} 个报表店铺识别经营数据，等待负责人确认店铺授权档案"
    ads_tone = "ok" if ads_count and ads_count == store_count and ready_count == store_count and scope_count == store_count else "warn"
    bc_tone = "ok" if bc_count and bc_count == store_count and ready_count == store_count and scope_count == store_count else "warn"
    cards = [
        ("店铺授权", auth_status, "ok" if ready_count else "warn"),
        ("数据权限范围", data_scope_status, "ok" if scope_count else "warn"),
        ("广告授权", ads_status, ads_tone),
        ("广告归属校验", bc_status, bc_tone),
        ("站点 / 店铺范围", site_status, "ok" if shop_identity_count else "warn"),
        ("安全边界", "登录、验证码、付费、授权确认和真实外部提交仍由负责人处理", "ok"),
    ]
    card_html = "".join(
        f"<div class='auth-card {html.escape(tone)}'><span>{html.escape(label)}</span><strong>{html.escape(status)}</strong></div>"
        for label, status, tone in cards
    )
    return f"""
      <div class="auth-queue">
        <div class="auth-queue-head">
          <div><b>授权核对队列</b><span>像真实 ERP 一样把店铺授权、广告授权、归属主体、站点和权限范围分开看。</span></div>
          <a class="button secondary" href="/chat?intent=store_data&source=store-erp">让AI查店铺数据缺口</a>
        </div>
        <div class="auth-queue-grid">{card_html}</div>
      </div>
    """


