def normalize_store_model_for_route(shop_type: Any) -> str:
    return normalize_channel_store_model_for_route(shop_type)


def platform_route_id_for_store(store: dict[str, Any]) -> str:
    return channel_platform_route_id_for_store(store)


def render_platform_developer_execution_boundary(root: Path, profile_stores: list[dict[str, Any]]) -> str:
    route_sample_labels: list[str] = []
    seen_route_sample_labels: set[str] = set()
    for store in profile_stores:
        route_sample = platform_route_id_for_store(store)
        if not str(route_sample or "").strip():
            continue
        label = customer_route_key_label(route_sample)
        if label in seen_route_sample_labels:
            continue
        seen_route_sample_labels.add(label)
        route_sample_labels.append(label)
        if len(route_sample_labels) >= 3:
            break
    route_sample_html = (
        "；当前样例 " + "、".join(html.escape(sample) for sample in route_sample_labels)
        if route_sample_labels
        else "；例如 TikTok Shop 美国站 本土店"
    )
    rule_cards = "".join(
        f"""
        <div class="developer-card">
          <strong>{html.escape(rule["platform"])}</strong>
          <span>{html.escape(rule["api"])}</span>
          <span>{html.escape(rule["ads"])}</span>
          <em>{html.escape(rule["execution"])}</em>
        </div>
        """
        for rule in PLATFORM_DEVELOPER_EXECUTION_RULES
    )
    capability_table = render_platform_capability_table(root)
    activity_ops_panel = render_platform_activity_ops_panel(root, profile_stores)
    activity_table = render_platform_activity_rule_table(root, profile_stores)
    return f"""
      <div class="developer-boundary">
        <div class="developer-boundary-head">
          <div>
            <b>平台连接 / 后台任务包执行边界</b>
            <span>ERP 不假装一个授权能管全部店铺；后台 AI 按店铺、国家、模式、广告账号和执行身份拆开。</span>
          </div>
          <a class="button secondary" href="/chat?intent=store_data&source=store-erp">让AI查店铺数据缺口</a>
        </div>
        <div class="ai-rule-takeover">
          <div>
            <b>后台 AI 已研究平台规则</b>
            <span>客户只看接入状态、规则摘要、草稿和待确认动作；平台连接、活动叠加、广告账号和店铺身份由后台 AI 自动核对。</span>
          </div>
          <div class="ai-rule-takeover-grid">
            <div><strong>已拆平台规则</strong><span>按平台、国家站点、店铺模式、店铺归属和 ERP 路径判断能不能上架、拉单、回传物流和结算。</span></div>
            <div><strong>活动先变草稿</strong><span>优惠券、折扣、直播券、Bundle、广告预算和叠加规则先生成可审核草稿。</span></div>
            <div><strong>真实动作停在确认</strong><span>发布、改价、投放、退款、发货、授权和付费动作必须负责人确认后执行。</span></div>
            <div><strong>后台代办回写</strong><span>遇到一店一主体、多店关联或平台能力未开放时，后台按独立店铺准备草稿和证据，负责人确认后回写结果。</span></div>
          </div>
        </div>
        <div class="cloud-policy-list">
          <div><b>一店一路径</b><span>按平台、国家站点、店铺模式和店铺归属分开{route_sample_html}</span></div>
          <div><b>广告单独授权</b><span>店铺订单连接、广告归属主体、广告账号、GMV Max 和站外广告不混用。</span></div>
          <div><b>后台待执行包</b><span>平台连接做不到或多店混绑有风险时，后台按独立店铺准备证据和草稿；确认后执行，结果回写 ERP。</span></div>
          <div><b>客户不背流程</b><span>客户只看读取状态、AI 分析和待确认动作；登录、验证码、真实提交、付费和授权边界停给负责人。</span></div>
        </div>
        {activity_ops_panel}
        <div class="developer-matrix">{rule_cards}</div>
        <details class="technical-rule-details">
          <summary>负责人 / 技术查看：完整平台连接和活动规则表</summary>
          <div class="muted">这里保留后台 AI 的规则证据、连接能力和活动叠加表；客户默认只看上面的摘要、缺口和待确认动作。</div>
          {capability_table}
          {activity_table}
        </details>
      </div>
    """


def usable_display_text(value: Any) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    has_cjk = any("\u4e00" <= char <= "\u9fff" for char in text)
    return has_cjk and text.count("?") < max(3, len(text) // 6)


def default_capability_binding_policy(channel: str) -> str:
    channel = str(channel or "")
    if channel == "meta_ads":
        return "不是店铺授权；必须按广告归属主体、广告账号、像素/目录单独映射，再回写到店铺路径。"
    if channel in {"shopify", "woocommerce"}:
        return "每个独立站单独安装应用或配置连接凭证；不能跨店共用写入权限，广告账号另算。"
    if channel == "amazon":
        return "Amazon 店铺数据、促销后台和广告账号分开授权；按站点和卖家账号拆路径。"
    if channel == "shein":
        return "按国家站点和店铺模式拆路径；半托、本土、跨境、TeeLab 联名和官方全托管不能混用。"
    if channel in {"shopee", "lazada"}:
        return "按国家站点和店铺身份拆路径；活动后台、广告后台和店铺连接分开授权。"
    return "一店一路径；一个店铺/国家站点/店铺模式生成一个独立上架路径，不复用到其它主体。"


def default_capability_customer_boundary(channel: str) -> str:
    channel = str(channel or "")
    if channel == "meta_ads":
        return "后台 AI 可读广告表现、准备广告组/素材/预算草稿；启动、暂停、调预算必须确认。"
    if channel in {"shopify", "woocommerce"}:
        return "后台 AI 可准备优惠券、折扣、包邮和组合规则草稿；保存、启用、投放必须确认。"
    if channel == "amazon":
        return "后台 AI 可读报表并准备 Coupon、Promotion、Deal、广告草稿；提交和预算变化必须确认。"
    return "后台 AI 可读授权店铺数据并准备活动/广告草稿；真实报名、改价、发券、投放必须确认。"


