def customer_safe_machine_text(value: Any, *, empty: str = "待后台 AI 复核") -> str:
    text = str(value or "").strip()
    if not text:
        return empty
    if text.startswith(("http://", "https://")):
        return "官方资料已记录，后台 AI 会定期复核。"
    translated = humanize_activity_token_for_display(text)
    if translated != text:
        return translated
    snake_like = "_" in text or text.isupper()
    if snake_like and not usable_display_text(text):
        return "后台已记录规则，等待负责人复核。"
    return text


