def sanitize_seller_chat_reply_payload(payload: dict[str, Any]) -> dict[str, Any]:
    safe = dict(payload)
    reply = str(safe.get("reply") or "")
    if reply:
        reply = customer_safe_activity_context_line(reply)
        reply = re.sub(r"\broute\s+key\b", "店铺路径", reply, flags=re.I)
        reply = re.sub(r"\broute\b", "店铺路径", reply, flags=re.I)
        reply = (
            reply.replace("Business 权限", "广告归属主体与店铺权限")
            .replace("Business Center", "广告归属主体")
            .replace("开发者权限", "后台权限")
            .replace("开发者/卖家后台能力", "卖家后台可用入口")
            .replace("开发者", "后台")
        )
        reply = sanitize_seller_visible_reply_text(reply)
        safe["reply"] = reply
    return safe


def seller_chat_payload_requests_activity_plan(payload: dict[str, Any]) -> bool:
    page_url = str(payload.get("page_url") or "")
    page_context = payload.get("page_context") if isinstance(payload.get("page_context"), dict) else {}
    context_url = str(page_context.get("url") or "")
    message = str(payload.get("message") or "")
    return activity_plan_intent_requested(
        message,
        page_url=page_url,
        context_url=context_url,
        safe_context="\n".join(
            str(value)
            for value in (
                page_context.get("title"),
                " ".join(str(item) for item in page_context.get("headings", []) if str(item).strip())
                if isinstance(page_context.get("headings"), list)
                else page_context.get("headings"),
            )
            if str(value or "").strip()
        ),
    )


def customer_safe_machine_list(values: list[Any], *, limit: int = 6, empty: str = "待后台 AI 复核") -> str:
    parts = [customer_safe_machine_text(value) for value in values[:limit] if str(value or "").strip()]
    return " / ".join(parts) if parts else empty


def activity_site_display_text(item: dict[str, Any]) -> str:
    focus = item.get("site_activity_focus") if isinstance(item.get("site_activity_focus"), list) else []
    ads_notes = item.get("site_ads_notes") if isinstance(item.get("site_ads_notes"), list) else []
    rule_notes = item.get("site_rule_notes") if isinstance(item.get("site_rule_notes"), list) else []
    parts: list[str] = []
    if item.get("site_campaign_window"):
        parts.append(humanize_activity_token_for_display(str(item.get("site_campaign_window"))))
    if focus:
        parts.append("重点：" + " / ".join(humanize_activity_token_for_display(str(value)) for value in focus[:5]))
    if ads_notes:
        parts.append("广告：" + " / ".join(humanize_activity_token_for_display(str(value)) for value in ads_notes[:3]))
    if rule_notes:
        parts.append("边界：" + " / ".join(humanize_activity_token_for_display(str(value)) for value in rule_notes[:3]))
    return "；".join(parts) or "按平台通用规则，后续继续补站点差异。"


def compact_activity_site_display_text(item: dict[str, Any], *, max_length: int = 150) -> str:
    """Short customer-safe site notes for ERP cards and tables."""
    focus = item.get("site_activity_focus") if isinstance(item.get("site_activity_focus"), list) else []
    ads_notes = item.get("site_ads_notes") if isinstance(item.get("site_ads_notes"), list) else []
    rule_notes = item.get("site_rule_notes") if isinstance(item.get("site_rule_notes"), list) else []
    parts: list[str] = []
    if item.get("site_campaign_window"):
        parts.append(customer_safe_machine_text(item.get("site_campaign_window"), empty=""))
    if focus:
        parts.append("重点：" + customer_safe_machine_list(focus, limit=3, empty=""))
    if ads_notes:
        parts.append("广告：" + customer_safe_machine_list(ads_notes, limit=2, empty=""))
    if rule_notes:
        parts.append("边界：" + customer_safe_machine_list(rule_notes, limit=2, empty=""))
    text = "；".join(part for part in parts if part.strip())
    text = customer_safe_machine_text(text, empty="按平台通用规则，后续继续补站点差异。")
    if len(text) > max_length:
        text = text[: max_length - 3].rstrip("；/，, ") + "..."
    return text


def render_platform_capability_table(root: Path) -> str:
    rows: list[str] = []
    for item in load_platform_capabilities(root)[:12]:
        sites = item.get("sites") if isinstance(item.get("sites"), list) else []
        channel = str(item.get("channel_id") or "")
        binding_policy = " / ".join(
            value
            for value in [
                str(item.get("authorization_surface") or "").strip(),
                str(item.get("store_binding_policy") or "").strip(),
                str(item.get("cloud_plugin_policy") or "").strip(),
            ]
            if value
        ) or "按店铺路径单独授权；写入动作先进入确认。"
        if not usable_display_text(binding_policy):
            binding_policy = default_capability_binding_policy(channel)
        customer_boundary = str(item.get("customer_boundary") or "后台 AI 先读授权数据和准备草稿；真实外部动作必须确认。")
        if not usable_display_text(customer_boundary):
            customer_boundary = default_capability_customer_boundary(channel)
        source_text = customer_safe_machine_text(item.get("official_source_url"))
        detail_text = platform_capability_detail_text(item)
        ownership_text = platform_admin_store_ownership_labels(rule_list(item.get("store_models") or item.get("shop_types")), item)
        rows.append(
            "<tr>"
            f"<td data-label='平台'>{html.escape(str(item.get('label') or item.get('channel_id') or ''))}<div class='muted'>已按平台和站点拆分。</div></td>"
            f"<td data-label='站点'>{html.escape(' / '.join(str(site) for site in sites[:10]) if sites else 'GLOBAL')}</td>"
            f"<td data-label='店铺归属'>{html.escape(ownership_text)}</td>"
            f"<td data-label='上架'>{html.escape(customer_safe_machine_text(item.get('listing')))}</td>"
            f"<td data-label='拉单'>{html.escape(customer_safe_machine_text(item.get('order')))}</td>"
            f"<td data-label='物流'>{html.escape(customer_safe_machine_text(item.get('shipment')))}</td>"
            f"<td data-label='结算'>{html.escape(customer_safe_machine_text(item.get('settlement')))}</td>"
            f"<td data-label='优惠/活动'>{html.escape(customer_safe_machine_text(item.get('discount')))}<br>{html.escape(customer_safe_machine_text(item.get('promotion')))}</td>"
            f"<td data-label='广告'>{html.escape(customer_safe_machine_text(item.get('ads')))}</td>"
            f"<td data-label='细分能力'>{html.escape(detail_text)}</td>"
            f"<td data-label='绑定/后台'>{html.escape(binding_policy)}</td>"
            f"<td data-label='客户边界'>{html.escape(customer_boundary)}</td>"
            f"<td data-label='来源'>{html.escape(source_text)}</td>"
            "</tr>"
        )
    body = "".join(rows) or "<tr><td colspan='13'>还没有平台能力表；先保守按后台草稿和负责人确认处理。</td></tr>"
    return f"""
        <div class="capability-table-wrap">
          <div class="muted">平台连接能力：每个平台按站点、店铺归属和能力拆开，标记平台连接、后台待执行包和不可自动执行范围。平台规则会变化，后续按官方资料继续更新。</div>
          <table class="capability-table">
            <thead><tr><th>平台</th><th>站点</th><th>店铺归属</th><th>上架</th><th>拉单</th><th>物流</th><th>结算</th><th>优惠/活动</th><th>广告</th><th>细分能力</th><th>绑定/后台</th><th>客户边界</th><th>来源</th></tr></thead>
            <tbody>{body}</tbody>
          </table>
        </div>
    """


def platform_capability_detail_text(item: dict[str, Any]) -> str:
    details = item.get("domain_details") if isinstance(item.get("domain_details"), dict) else {}
    if not details:
        return customer_safe_capability_detail_phrase(
            customer_safe_machine_text(item.get("developer_rule_summary"), empty="按平台连接 / 后台 / 广告账号分开维护。")
        )
    domain_labels = {
        "promotion": "活动",
        "coupon": "优惠券",
        "ads": "广告",
        "listing": "商品",
        "reporting": "报表",
    }
    parts: list[str] = []
    for domain in ("promotion", "coupon", "ads", "listing", "reporting"):
        detail = details.get(domain)
        if not isinstance(detail, dict):
            continue
        objects = [customer_safe_capability_detail_phrase(value) for value in rule_list(detail.get("api_objects"))[:3]]
        gates = [customer_safe_machine_text(value) for value in rule_list(detail.get("required_authorizations"))[:2]]
        if objects:
            text = f"{domain_labels.get(domain, customer_safe_machine_text(domain))}: {' / '.join(objects)}"
            if gates:
                text += f"（{' / '.join(gates)}）"
            parts.append(text)
    return "；".join(parts[:5]) or "按平台连接 / 后台 / 广告账号分开维护。"


def customer_safe_capability_detail_phrase(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    replacements = {
        "Seller Center campaign backend": "卖家后台活动",
        "Campaign backend": "卖家后台活动",
        "Product Discount": "商品折扣",
        "Flash Deal": "限时活动",
        "Campaign price": "活动价",
        "Inventory campaign": "活动库存",
        "Flexi Combo": "组合优惠",
        "Seller Voucher": "卖家优惠券",
        "TikTok Business": "广告后台",
        "Ads Manager": "广告后台",
        "Ad Account Reports": "广告报表",
        "Seller Hub": "卖家后台",
        "shop_access_token": "店铺连接凭证",
        "seller_access_token": "卖家连接凭证",
        "authorized_shop_token": "授权店铺凭证",
        "seller_authorization_code": "卖家授权码",
        "access_token": "连接凭证",
        "Open Platform": "开放平台",
        "Open API": "开放平台连接",
        "API": "连接",
        "OAuth": "授权",
    }
    for raw, label in replacements.items():
        text = text.replace(raw, label)
    return customer_safe_machine_text(text)


def activity_ops_action_text(item: dict[str, Any]) -> tuple[str, str, str]:
    readiness = str(item.get("execution_readiness") or "")
    readiness_label = str(item.get("execution_readiness_label") or "只能草稿")
    ads_status = str(item.get("ads_account_status") or "missing")
    business_status = str(item.get("business_center_status") or "missing")
    if readiness == "needs_platform_store":
        return (
            "先补真实平台店铺",
            "只能做候选规划、平台招商和开店准备，不能自动上架、拉单或投放。",
            "warn",
        )
    if readiness == "needs_ads_account" or ads_status != "registered" or business_status != "registered":
        return (
            "先补广告账号和归属主体",
            "可以生成活动草稿、预算测算和止损线，但不会启动广告投放。",
            "warn",
        )
    if "确认后可执行" in readiness_label or readiness == "ready_after_confirmation":
        return (
            "可生成活动草稿",
            "AI 准备报名、改价、发券、预算和叠加校验，负责人确认前不提交。",
            "ok",
        )
    return (
        "先做规则复核",
        "AI 只整理活动证据、叠加风险和确认包，等负责人确认后再进入执行。",
        "warn",
    )


def activity_ops_blocked_actions_text(item: dict[str, Any]) -> str:
    readiness = str(item.get("execution_readiness") or "")
    if readiness == "needs_platform_store":
        return "禁止自动上架、拉单、报名活动、改价、发券或投放广告；先补真实平台店铺。"
    if readiness == "needs_ads_account":
        return "禁止自动启动广告、改预算、提交活动或发券；先补广告账号、归属主体和负责人确认。"
    if readiness == "ready_after_confirmation":
        return "确认后只生成后台待执行包；最终提交、改价、发券、报名活动和投放广告仍需负责人最后确认。"
    return "只做规则复核、草稿和风险清单；不自动提交活动、优惠、价格、库存或广告动作。"


def activity_ops_preflight_text(item: dict[str, Any]) -> str:
    status = str(item.get("status") or "")
    readiness = str(item.get("execution_readiness") or "")
    ads_status = str(item.get("ads_account_status") or "missing")
    business_status = str(item.get("business_center_status") or "missing")
    parts: list[str] = []
    source = str(item.get("official_source_url") or item.get("source_status") or "").strip()
    parts.append("官方规则已记录" if source else "官方规则待复核")
    if status == "needs_platform_store" or readiness == "needs_platform_store":
        parts.append("真实店铺待补")
    else:
        parts.append("店铺路径已核对")
    if ads_status == "registered" and business_status == "registered":
        parts.append("广告身份已登记")
    else:
        parts.append("广告身份待补")
    parts.append("叠加/毛利/库存进草稿")
    if readiness == "ready_after_confirmation":
        parts.append("确认后生成后台待执行包")
    else:
        parts.append("未齐前只保留草稿")
    return "；".join(parts)


def render_platform_activity_ops_panel(root: Path, profile_stores: list[dict[str, Any]]) -> str:
    cards: list[str] = []
    for item in build_platform_activity_readiness(root, profile_stores)[:6]:
        route_label = customer_route_key_label(item.get("route_key"))
        ownership_label = store_ownership_label_for_route(item)
        action_title, action_body, tone = activity_ops_action_text(item)
        preflight_text = activity_ops_preflight_text(item)
        blocked_actions = activity_ops_blocked_actions_text(item)
        readiness_label = str(item.get("execution_readiness_label") or "只能草稿")
        activity_types = customer_safe_machine_list(item.get("activity_types", [])[:4], empty="活动类型待维护")
        stack_text = customer_safe_machine_list(item.get("stacking_rules", [])[:3], empty="叠加规则待复核")
        site_text = compact_activity_site_display_text(item, max_length=140)
        guardrails = " / ".join(
            part
            for part in [
                customer_safe_machine_text(item.get("margin_guardrail") or ""),
                customer_safe_machine_text(item.get("inventory_guardrail") or ""),
            ]
            if part and part != "待后台 AI 复核"
        ) or "利润和库存待复核"
        next_step = customer_safe_machine_text(item.get("next_step"), empty="先生成活动草稿、叠加校验和负责人确认包。")
        cards.append(
            f"""
            <div class="activity-ops-card {html.escape(tone)}">
              <div class="activity-ops-card-head">
                <b>{html.escape(route_label)}</b>
                <span>{html.escape(readiness_label)} / {html.escape(ownership_label)}</span>
              </div>
              <strong>{html.escape(action_title)}</strong>
              <p>{html.escape(action_body)}</p>
              <div class="activity-ops-preflight">
                <b>后台 AI 预检包</b>
                <span>{html.escape(preflight_text)}</span>
              </div>
              <div class="activity-ops-blocked">
                <b>禁止自动执行</b>
                <span>{html.escape(blocked_actions)}</span>
              </div>
              <dl>
                <div><dt>活动</dt><dd>{html.escape(activity_types)}</dd></div>
                <div><dt>叠加</dt><dd>{html.escape(stack_text)}</dd></div>
                <div><dt>护栏</dt><dd>{html.escape(guardrails)}</dd></div>
                <div><dt>站点</dt><dd>{html.escape(site_text)}</dd></div>
              </dl>
              <em>{html.escape(next_step)}</em>
            </div>
            """
        )
    cards_html = "".join(cards) or "<div class='activity-ops-empty'>还没有活动规则；后台 AI 先只生成草稿、证据和负责人确认包。</div>"
    return f"""
      <div class="activity-ops-panel">
        <div class="activity-ops-head">
          <b>活动 / 广告下一步</b>
          <span>客户不用研究平台后台；后台 AI 先做官方规则、真实店铺、广告身份、叠加/毛利/库存和确认回写预检，只把可执行动作和缺口露出来。</span>
        </div>
        <div class="activity-ops-grid">{cards_html}</div>
      </div>
    """


def render_platform_activity_rule_table(root: Path, profile_stores: list[dict[str, Any]]) -> str:
    rows: list[str] = []
    for item in build_platform_activity_readiness(root, profile_stores)[:18]:
        status = str(item.get("status") or "")
        tone = "ok" if status == "rule_available" else "warn"
        readiness_label = str(item.get("execution_readiness_label") or "只能草稿")
        readiness_tone = "ok" if readiness_label == "确认后可执行" else "warn"
        activity_types = (
            customer_safe_machine_list(item.get("activity_types", [])[:8])
            or "平台规则待复核"
        )
        stacking_rules = (
            customer_safe_machine_list(item.get("stacking_rules", [])[:8])
            or "需要叠加规则校验"
        )
        guardrails = (
            f"{customer_safe_machine_text(item.get('margin_guardrail') or 'needs_margin_review')} / "
            f"{customer_safe_machine_text(item.get('inventory_guardrail') or 'needs_inventory_review')}"
        )
        auth_requirements = item.get("authorization_requirements") if isinstance(item.get("authorization_requirements"), list) else []
        execution_surfaces = item.get("execution_surfaces") if isinstance(item.get("execution_surfaces"), list) else []
        auth_and_cloud = customer_safe_machine_list([*auth_requirements[:4], *execution_surfaces[:3]], empty="按店铺路径授权")
        ownership_label = store_ownership_label_for_route(item)
        customer_boundary = str(item.get("customer_execution_boundary") or "后台 AI 先生成草稿和确认包，不替客户真实提交。")
        if not usable_display_text(customer_boundary):
            customer_boundary = customer_safe_machine_text(customer_boundary)
        cloud_reason = str(item.get("cloud_plugin_reason") or "需要外部后台时按店铺路径使用后台执行身份。")
        if not usable_display_text(cloud_reason):
            cloud_reason = customer_safe_machine_text(cloud_reason)
        site_difference = compact_activity_site_display_text(item, max_length=180)
        source_status = customer_safe_machine_text(item.get("source_status"))
        status_text = customer_safe_machine_text(status)
        confirmation_text = "需要负责人确认" if item.get("confirmation_required", True) else "不需要确认"
        source_text = customer_safe_machine_text(item.get("official_source_url"))
        route_label = customer_route_key_label(item.get("route_key"))
        customer_summary = activity_customer_execution_summary(item)
        closure_summary = activity_rule_to_task_summary(item)
        mechanism_text = platform_activity_mechanism_text(item)
        identity_text = activity_route_execution_identity_text(item)
        rows.append(
            "<tr>"
            f"<td data-label='路径'>{html.escape(route_label)}<div class='muted'>{html.escape(source_status)}</div></td>"
            f"<td data-label='店铺归属'>{html.escape(ownership_label)}</td>"
            f"<td data-label='状态'><span class='route-status {html.escape(tone)}'>{html.escape(status_text)}</span></td>"
            f"<td data-label='执行状态'><span class='route-status {html.escape(readiness_tone)}'>{html.escape(readiness_label)}</span></td>"
            f"<td data-label='客户摘要'>{html.escape(customer_summary)}</td>"
            f"<td data-label='规则到任务'>{html.escape(closure_summary)}</td>"
            f"<td data-label='广告/执行身份'>{html.escape(identity_text)}</td>"
            f"<td data-label='活动类型'>{html.escape(activity_types)}</td>"
            f"<td data-label='机制/叠加'>{html.escape(mechanism_text)}</td>"
            f"<td data-label='站点差异'>{html.escape(site_difference)}</td>"
            f"<td data-label='叠加规则'>{html.escape(stacking_rules)}</td>"
            f"<td data-label='执行边界'>{html.escape(customer_safe_machine_text(item.get('execution_mode') or 'draft_then_confirmation'))}</td>"
            f"<td data-label='连接/广告'>{html.escape(customer_safe_machine_text(item.get('api_boundary') or 'rules_need_review'))}<br>{html.escape(customer_safe_machine_text(item.get('ads_boundary') or 'ads_need_separate_review'))}</td>"
            f"<td data-label='利润/库存'>{html.escape(guardrails)}</td>"
            f"<td data-label='授权/后台身份'>{html.escape(auth_and_cloud)}<div class='muted'>{html.escape(cloud_reason)}</div></td>"
            f"<td data-label='客户边界'>{html.escape(customer_boundary)}</td>"
            f"<td data-label='确认'>{html.escape(confirmation_text)}</td>"
            f"<td data-label='下一步'>{html.escape(customer_safe_machine_text(item.get('next_step')))}<div class='muted'>{html.escape(source_text)}</div></td>"
            "</tr>"
        )
    body = "".join(rows) or "<tr><td colspan='18'>还没有活动规则；默认只生成草稿和负责人确认包。</td></tr>"
    return f"""
        <div class="activity-table-wrap">
          <div class="muted">活动 / 广告规则表：按平台、国家站点、店铺模式和店铺归属记录平台大促、店铺券、折扣、直播券、达人券、包邮、Bundle、广告联动和叠加校验。真实提交仍进确认队列。</div>
          <table class="activity-table">
            <thead><tr><th>路径</th><th>店铺归属</th><th>状态</th><th>执行状态</th><th>客户摘要</th><th>规则到任务</th><th>广告/执行身份</th><th>活动类型</th><th>机制/叠加</th><th>站点差异</th><th>叠加规则</th><th>执行边界</th><th>连接/广告</th><th>利润/库存</th><th>授权/后台身份</th><th>客户边界</th><th>确认</th><th>下一步</th></tr></thead>
            <tbody>{body}</tbody>
          </table>
        </div>
    """


def activity_route_execution_identity_text(item: dict[str, Any]) -> str:
    readiness = str(item.get("execution_readiness") or "")
    ads_status = str(item.get("ads_account_status") or "missing")
    business_status = str(item.get("business_center_status") or "missing")
    execution_mode = str(item.get("execution_mode") or "")
    parts: list[str] = []
    ownership_label = store_ownership_label_for_route(item)
    if ownership_label:
        parts.append(f"店铺归属：{ownership_label}")
    parts.append("广告账号已登记" if ads_status == "registered" else "缺广告账号")
    parts.append("广告归属主体已确认" if business_status == "registered" else "缺广告归属主体")
    if readiness == "needs_platform_store":
        parts.append("先补真实平台店铺")
    elif readiness == "needs_ads_account":
        parts.append("只保留活动/广告草稿")
    elif "isolated_cloud_plugin" in execution_mode:
        parts.append("确认后生成后台执行身份")
    else:
        parts.append("只生成负责人确认包")
    return "；".join(parts)


def platform_activity_mechanism_text(item: dict[str, Any]) -> str:
    mechanisms = item.get("activity_mechanisms") if isinstance(item.get("activity_mechanisms"), list) else []
    parts: list[str] = []
    for mechanism in mechanisms[:5]:
        if not isinstance(mechanism, dict):
            continue
        label = str(mechanism.get("display") or mechanism.get("activity_type") or "").strip()
        api_objects = " / ".join(
            customer_safe_capability_detail_phrase(value)
            for value in rule_list(mechanism.get("api_objects"))[:2]
        )
        stacking = " / ".join(customer_safe_machine_text(value) for value in rule_list(mechanism.get("stacking"))[:2])
        guardrails = " / ".join(customer_safe_machine_text(value) for value in rule_list(mechanism.get("guardrails"))[:2])
        text = label
        if api_objects:
            text += f": {api_objects}"
        if stacking:
            text += f"；叠加 {stacking}"
        if guardrails:
            text += f"；护栏 {guardrails}"
        if text.strip():
            parts.append(text)
    return "；".join(parts) or customer_safe_machine_text(item.get("developer_rule_summary"), empty="按活动类型继续补平台规则。")


def customer_route_source_label(item: dict[str, Any]) -> str:
    raw = str(item.get("source_label") or "").strip()
    source_type = str(item.get("source_type") or "").strip()
    route_key = str(item.get("route_key") or "").strip()
    matched_store = str(item.get("matched_store") or "").strip()
    status = str(item.get("status") or "").strip()
    if matched_store and status in {"platform_store_configured", "ready_for_api_mapping"}:
        return customer_visible_store_reference_name(matched_store, route_label=customer_route_key_label(route_key))
    if "platform_co_ops" in route_key or "teelab_owned" in route_key:
        return "TeeLab 代运营 / 联名运营候选"
    if "shopify" in route_key or "woocommerce" in route_key or "independent_site" in route_key:
        return "设计师自运营店铺候选"
    lowered = raw.lower()
    if "priority" in lowered or "product pool" in lowered or "co-ops candidate" in lowered:
        if "tiktok" in route_key:
            return "TikTok 站点候选"
        if "shein" in route_key:
            return "SHEIN 站点候选"
        return "平台站点候选"
    if "designer" in lowered and any(token in lowered for token in ["self", "operated", "store"]):
        return "设计师自运营店铺候选"
    if usable_display_text(raw):
        return raw
    if "request" in source_type:
        return "设计师站点申请"
    if "store" in source_type:
        return "后台平台店铺"
    return customer_route_key_label(route_key) or "平台路径"


def activity_rule_to_task_summary(item: dict[str, Any]) -> str:
    stacking_rules = item.get("stacking_rules") if isinstance(item.get("stacking_rules"), list) else []
    stack_text = customer_safe_machine_list(stacking_rules[:3], empty="叠加校验待复核")
    margin_text = customer_safe_machine_text(item.get("margin_guardrail") or "needs_margin_review")
    inventory_text = customer_safe_machine_text(item.get("inventory_guardrail") or "needs_inventory_review")
    readiness = str(item.get("execution_readiness_label") or item.get("execution_readiness") or "").strip()
    confirmation_text = "负责人确认后"
    if item.get("confirmation_required", True) is False:
        confirmation_text = "仍保留后台复核"
    task_text = "进入后台任务包" if "确认后可执行" in readiness or str(item.get("execution_readiness") or "") == "ready_after_confirmation" else "先保留后台草稿"
    return f"规则已连到任务：{stack_text}；护栏：{margin_text} / {inventory_text}；门槛：{confirmation_text}；后台：{task_text}。"


def activity_customer_execution_summary(item: dict[str, Any]) -> str:
    status = str(item.get("status") or "")
    readiness = str(item.get("execution_readiness_label") or item.get("execution_readiness") or "")
    next_step = customer_safe_machine_text(item.get("next_step"), empty="")
    if status == "needs_platform_store":
        return "后台缺真实平台店铺；AI 只保留候选和开店准备，不进入外部后台。"
    if "缺广告" in readiness or str(item.get("execution_readiness") or "") == "needs_ads_account":
        return "缺广告账号或归属主体；AI 先算预算和止损，不启动投放。"
    if "确认后可执行" in readiness:
        return "AI 已能准备草稿；负责人确认后走平台连接或后台待执行包，提交前停住。"
    if next_step:
        return next_step
    return "AI 先准备草稿、证据和风险；真实报名、改价、发券或投广告必须确认。"


def render_channel_route_readiness_panel(root: Path, profile_stores: list[dict[str, Any]]) -> str:
    rows: list[str] = []
    for item in build_channel_route_readiness(root, profile_stores)[:40]:
        status = str(item.get("status") or "")
        tone = "ok" if status in {"platform_store_configured", "ready_for_api_mapping"} else "warn"
        source_type = customer_safe_machine_text(item.get("source_type"))
        status_text = customer_safe_machine_text(status)
        route_label = customer_route_key_label(item.get("route_key"))
        source_label = customer_route_source_label(item)
        visibility_note = str(item.get("store_visibility_note") or "").strip()
        visibility_note_html = f"<div class='muted'>{html.escape(visibility_note)}</div>" if visibility_note else ""
        matched_store = str(item.get("matched_store") or "未匹配后台平台店铺")
        if "历史/测试" in visibility_note:
            matched_store = "历史/测试店铺（不作为真实店铺拉单、投放或外部执行）"
        else:
            matched_store = customer_visible_store_reference_name(matched_store, route_label=route_label, fallback="未匹配后台平台店铺")
        rows.append(
            "<tr>"
            f"<td data-label='来源'>{html.escape(source_label)}<div class='muted'>{html.escape(source_type)}</div>{visibility_note_html}</td>"
            f"<td data-label='路径'>{html.escape(route_label)}</td>"
            f"<td data-label='状态'><span class='route-status {html.escape(tone)}'>{html.escape(status_text)}</span></td>"
            f"<td data-label='匹配店铺'>{html.escape(matched_store)}</td>"
            f"<td data-label='下一步'>{html.escape(str(item.get('next_step') or ''))}</td>"
            "</tr>"
        )
    body = "".join(rows) or "<tr><td colspan='5'>还没有设计师站点申请或后台平台店铺；后续申请进来后，会先检查是否需要配置平台店铺。</td></tr>"
    return f"""
      <div class="route-readiness">
        <div class="route-readiness-head">
          <div><b>站点 / 平台店铺准备状态</b><span>设计师申请某站点，不等于后台已有真实平台店铺；没有匹配店铺时只进入候选和开店准备。</span></div>
        </div>
        <div class="route-table-wrap">
          <table class="route-table">
            <thead><tr><th>来源</th><th>路径</th><th>状态</th><th>匹配店铺</th><th>下一步</th></tr></thead>
            <tbody>{body}</tbody>
          </table>
        </div>
      </div>
    """


def render_store_connection_panel(
    root: Path,
    profile_stores: list[dict[str, Any]],
    store_profiles: list[IntakeRecord],
    imported_metric_stores: list[dict[str, str]] | None = None,
    *,
    can_bind_store: bool = True,
    scope_note: str = "",
    show_execution_details: bool = True,
    connected_flash_message: str = "",
) -> str:
    platform_opts = "<option value=''>请选择平台</option>" + "".join(
        f"<option value='{html.escape(str(platform['id']))}'>{html.escape(str(platform['label']))}</option>"
        for platform in account_center.BINDABLE_PLATFORMS
    )
    seen: set[tuple[str, str, str]] = set()
    rows: list[str] = []
    for store in profile_stores:
        platform = str(store.get("platform_label") or store.get("platform_id") or "").strip()
        name = str(store.get("store_name") or "").strip()
        visible_name = customer_visible_store_name_for_store(store, fallback="-")
        country = str(store.get("country_code") or "").strip().upper()
        method = str(store.get("connection_method") or "manual_report_or_authorized_connection").strip()
        key = store_identity_key(platform, name, country)
        seen.add(key)
        status = "已登记，等待授权数据" if not store.get("key_present") else "连接配置已就绪"
        next_step = store_connection_next_step(method, key_present=bool(store.get("key_present")))
        scopes = normalize_store_authorization_scopes(store.get("authorization_scopes"))
        data_scope = "、".join(scopes[:8]) if scopes else "权限范围待确认"
        sync_status = store_connection_sync_status(method, key_present=bool(store.get("key_present")))
        failure_reason = store_connection_failure_reason(method, key_present=bool(store.get("key_present")))
        unbind_risk = store_connection_unbind_risk(method)
        store_external_id = str(store.get("store_external_id") or "").strip()
        sub_store_name = str(store.get("sub_store_name") or "").strip()
        store_identity = store_identity_scope_label(store)
        route_missing = store_route_missing_prerequisites(store)
        connection_note = store_connection_visibility_note(store, route_missing=route_missing)
        if "platform_store_identity" in route_missing and method == "official_authorization":
            status = "已登记，平台店铺身份待确认"
            sync_status = "平台店铺身份待确认；暂不进入系统连接或外部执行"
            failure_reason = "缺平台店铺编号、卖家ID或真实平台店铺身份；内部备注不能替代平台身份"
            next_step = store_route_pending_next_step(store)
        rows.append(
            "<tr>"
            f"<td data-label='平台'>{html.escape(platform)}</td>"
            f"<td data-label='店铺'>{html.escape(visible_name)}<div class='tiny'>{html.escape(connection_note)}</div></td>"
            f"<td data-label='店铺范围'>{html.escape(store_identity)}</td>"
            f"<td data-label='国家'>{html.escape(country or '-')}</td>"
            f"<td data-label='接入方式'>{html.escape(connection_method_label(method))}</td>"
            f"<td data-label='数据范围'>{html.escape(data_scope)}</td>"
            f"<td data-label='状态'>{html.escape(status)}</td>"
            f"<td data-label='同步状态'>{html.escape(sync_status)}</td>"
            f"<td data-label='失败/限制'>{html.escape(failure_reason)}</td>"
            f"<td data-label='解绑/删除风险'>{html.escape(unbind_risk)}</td>"
            f"<td data-label='后台下一步'>{html.escape(next_step)}</td>"
            "</tr>"
        )
    for record in store_profiles:
        fields = record.fields
        platform = str(fields.get("marketplace") or fields.get("platform") or fields.get("source_platform") or "").strip()
        name = str(fields.get("store_name") or fields.get("store_id") or "").strip()
        country = str(fields.get("country_code") or fields.get("shop_region") or "").strip().upper()
        visible_name = customer_visible_store_reference_name(name, fallback="已登记店铺")
        key = store_identity_key(platform, name, country)
        if key in seen:
            continue
        seen.add(key)
        rows.append(
            "<tr>"
            f"<td data-label='平台'>{html.escape(platform or '-')}</td>"
            f"<td data-label='店铺'>{html.escape(visible_name or '-')}</td>"
            "<td data-label='店铺范围'>店铺档案已登记</td>"
            f"<td data-label='国家'>{html.escape(country or '-')}</td>"
            "<td data-label='接入方式'>已接入店铺档案</td>"
            "<td data-label='数据范围'>店铺档案、国家、币种、履约方式、负责人</td>"
            "<td data-label='状态'>可用于经营判断</td>"
            f"<td data-label='同步状态'>{html.escape(store_connection_sync_status('', imported_profile=True))}</td>"
            f"<td data-label='失败/限制'>{html.escape(store_connection_failure_reason('', imported_profile=True))}</td>"
            f"<td data-label='解绑/删除风险'>{html.escape(store_connection_unbind_risk(''))}</td>"
            f"<td data-label='后台下一步'>{html.escape(store_connection_next_step('', imported_profile=True))}</td>"
            "</tr>"
        )
    for item in imported_metric_stores or []:
        platform = str(item.get("platform") or "").strip()
        name = str(item.get("name") or "").strip()
        country = str(item.get("country") or "").strip().upper()
        visible_name = customer_visible_store_reference_name(name, fallback="已识别店铺")
        key = store_identity_key(platform, name, country)
        if not platform or not name or key in seen:
            continue
        seen.add(key)
        rows.append(
            "<tr>"
            f"<td data-label='平台'>{html.escape(platform)}</td>"
            f"<td data-label='店铺'>{html.escape(visible_name)}</td>"
            "<td data-label='店铺范围'>待确认</td>"
            f"<td data-label='国家'>{html.escape(country or '-')}</td>"
            "<td data-label='接入方式'>已读取经营报表</td>"
            "<td data-label='数据范围'>订单、销售、退款、广告或结算报表</td>"
            "<td data-label='状态'>已从报表识别，等待连接档案</td>"
            f"<td data-label='同步状态'>{html.escape(store_connection_sync_status('', imported_metrics=True))}</td>"
            f"<td data-label='失败/限制'>{html.escape(store_connection_failure_reason('', imported_metrics=True))}</td>"
            f"<td data-label='解绑/删除风险'>{html.escape(store_connection_unbind_risk('report_import'))}</td>"
            "<td data-label='后台下一步'>负责人确认一次授权方式后，后台 AI 继续读取商品状态、库存、广告和结算。</td>"
            "</tr>"
        )
    row_html = "".join(rows) or "<tr><td data-label='状态' colspan='11' class='muted'>还没有可读取的店铺连接。负责人登记一次店铺范围或完成授权后，后台 AI 会自动读取订单、广告、售后、财务、库存和商品状态；页面会显示同步状态、失败限制和解绑风险。</td></tr>"
    bind_controls = (
        f"""
      <div class="owner-connection-summary">
        <div><b>负责人确认入口已收起</b><span>客户默认只看接入状态、缺口和后台 AI 下一步；需要保存授权范围时再展开。</span></div>
        <a class="button secondary" href="/chat?intent=store_data&source=store-erp">让AI查店铺数据缺口</a>
      </div>
      <details class="owner-bind-details">
        <summary>负责人处理：新增 / 修改店铺连接</summary>
        <div class="muted">只给负责人使用：确认平台、国家站点、店铺名和运营模式。客户不用填写平台连接细节、广告账号或权限字段；后台 AI 会把缺口标出来，再交给负责人确认真实授权。</div>
      <div class="connect-grid">
        <label>平台
          <select id="erpPlatform">{platform_opts}</select>
        </label>
        <label>国家 / 站点
          <input id="erpCountry" placeholder="US / UK / MX">
        </label>
        <label>店铺名称
          <input id="erpStoreName" placeholder="例如 US 主店">
        </label>
          <label>内部子店铺 / 业务线备注
            <input id="erpSubStoreName" placeholder="可空；仅作内部备注，不等于平台店铺编号">
        </label>
        <label>连接方式
          <select id="erpConnectionMethod">
            <option value="official_authorization">官方授权</option>
            <option value="report_import">负责人确认报表来源</option>
            <option value="browser_visible_capture">已登录页面只读</option>
            <option value="manual_report_or_authorized_connection">登记范围，等待后台读取</option>
          </select>
        </label>
        <label>店铺类型
          <select id="erpShopType">
            <option value="">待确认店铺类型</option>
            <option value="TikTok 本土店">TikTok 本土店</option>
            <option value="TikTok 跨境店">TikTok 跨境店</option>
            <option value="TikTok 半托管跨境">TikTok 半托管跨境</option>
            <option value="TikTok 半托管本土">TikTok 半托管本土</option>
            <option value="TikTok ACCU 本土店">TikTok ACCU 本土店</option>
            <option value="SHEIN Marketplace">SHEIN Marketplace</option>
            <option value="SHEIN 本土店">SHEIN 本土店</option>
            <option value="SHEIN 跨境半托">SHEIN 跨境半托</option>
            <option value="Amazon Marketplace">Amazon Marketplace</option>
            <option value="Shopee 本土店">Shopee 本土店</option>
            <option value="Shopee 跨境店">Shopee 跨境店</option>
            <option value="Lazada 本土店">Lazada 本土店</option>
            <option value="Lazada 跨境店">Lazada 跨境店</option>
            <option value="Shopify 独立站">Shopify 独立站</option>
            <option value="WooCommerce 独立站">WooCommerce 独立站</option>
            <option value="内容商品目录">内容商品目录</option>
            <option value="POD 渠道店铺">POD 渠道店铺</option>
          </select>
        </label>
      </div>
      <details class="technical-bind-details">
        <summary>后台映射字段（负责人 / 技术查看）</summary>
        <div class="muted">这些字段只用于后台识别店铺路径、广告归属和负责人执行范围。内部子店铺 / 业务线只作备注，不等于平台店铺编号；缺字段时只显示缺口，不把多店铺授权混到同一个执行身份里。</div>
        <div class="connect-grid">
          <label>平台店铺编号
            <input id="erpStoreExternalId" placeholder="可空；后台校验用">
          </label>
          <label>广告归属主体
            <input id="erpBusinessCenter" placeholder="可空；涉及投放或活动时再确认">
          </label>
          <label>广告账号
            <input id="erpAdsAccount" placeholder="可空；涉及投放才需要">
          </label>
          <label>权限范围
            <input id="erpAuthorizationScopes" value="订单/销售, 商品页资料, 库存, 广告, 退款/售后, 财务结算" placeholder="订单、广告、退款、结算等">
          </label>
        </div>
      </details>
      <div class="erp-route-preview" id="erpRoutePreview">
        <b>后台 AI 路由预检</b>
        <span>保存前先确认这家店会进入哪条平台 / 国家 / 店铺模式路径；广告账号和活动能力仍然单独确认。</span>
        <div class="erp-route-preview-grid">
          <div><em>平台 / 站点</em><strong id="erpRoutePreviewPlatform">待选择平台和国家站点</strong></div>
          <div><em>店铺模式</em><strong id="erpRoutePreviewModel">待确认本土 / 跨境 / 半托 / 独立站</strong></div>
          <div><em>广告边界</em><strong id="erpRoutePreviewAds">广告账号和归属主体单独确认</strong></div>
          <div><em>保存后下一步</em><strong id="erpRoutePreviewNext">只建立读取边界；真实授权、投放、改价、活动报名进确认队列</strong></div>
        </div>
      </div>
      <div class="actions">
        <button type="button" onclick="erpConnectStore()">保存负责人确认范围</button>
      </div>
      </details>
"""
        if can_bind_store
        else f"""
      <div class="notice">{html.escape(scope_note or "当前账号只能查看已授权店铺范围；新增或修改店铺连接请让主账号处理。")}</div>
      <div class="actions">
        <a class="button primary" href="/account?next=/store-erp">负责人登录 / 切换主账号</a>
        <a class="button secondary" href="/chat?intent=store_data&source=store-erp">让AI查店铺数据缺口</a>
      </div>
"""
    )
    auth_queue_html = render_store_authorization_queue(profile_stores, imported_metric_stores)
    if show_execution_details:
        route_readiness_html = render_channel_route_readiness_panel(root, profile_stores)
        developer_boundary_html = render_platform_developer_execution_boundary(root, profile_stores)
    else:
        route_readiness_html = ""
        developer_boundary_html = (
            "<div class='notice'>负责人登录后，后台 AI 才会显示平台路线、活动规则到任务闭环、广告边界和后台执行方案；"
            "客户不用研究规则后台，后台 AI 会自动核对活动叠加、毛利/库存、广告账号和待确认动作。</div>"
        )
    return f"""
    <section class="panel" id="store-connections">
      <h2>店铺数据接入状态</h2>
      <div class="muted">这里显示后台 AI 能读到哪些授权店铺数据。真实授权、登录、验证码和外部提交仍由负责人确认；确认后系统自动读取和分析。</div>
      {bind_controls}
      <div id="erpConnectStatus" class="{'connect-flash' if connected_flash_message else ''}" aria-live="polite">{html.escape(connected_flash_message)}</div>
      {auth_queue_html}
      {route_readiness_html}
      {developer_boundary_html}
      <div class="connector-steps">
        <div><b>1. 平台范围</b><span>负责人确认 TikTok Shop、Amazon、Shopify、Etsy 等来源。</span></div>
        <div><b>2. 授权边界</b><span>官方授权、只读页面或报表接入都先标明权限边界。</span></div>
        <div><b>3. 自动读取</b><span>后台 AI 读取可用数据，页面只显示同步状态和缺口。</span></div>
        <div><b>4. 风险确认</b><span>真实动作继续进入确认队列，不在 ERP 页直接执行。</span></div>
      </div>
      <div class="connector-steps">
        <div><b>授权状态</b><span>客户默认只看是否已登记、是否等待授权数据。</span></div>
        <div><b>同步状态</b><span>后台 AI 标出订单、广告、退款、结算、库存和商品状态是否可读。</span></div>
        <div><b>失败/限制原因</b><span>登录、验证码、系统连接缺失、报表口径不完整都会显示为缺口。</span></div>
        <div><b>解绑/删除风险</b><span>停用连接只记录风险，不自动解除平台授权。</span></div>
      </div>
      <div class="report-checklist">
        <strong>后台 AI 等待读取</strong>
        <span>订单报表</span>
        <span>广告报表</span>
        <span>退款/售后</span>
        <span>财务结算</span>
        <span>库存</span>
        <span>商品状态</span>
      </div>
      <div class="connection-table-wrap">
        <table class="connection-table">
          <thead><tr><th>平台</th><th>店铺</th><th>店铺范围</th><th>国家</th><th>接入方式</th><th>数据范围</th><th>状态</th><th>同步状态</th><th>失败/限制</th><th>解绑/删除风险</th><th>后台下一步</th></tr></thead>
          <tbody>{row_html}</tbody>
        </table>
      </div>
    </section>
    """


def render_erp_action_draft_panel(
    profile_stores: list[dict[str, Any]],
    *,
    can_generate: bool,
) -> str:
    historical_store_count = sum(
        1 for store in profile_stores if isinstance(store, dict) and store_is_historical_test_record(store)
    )
    stores = [
        store
        for store in profile_stores
        if isinstance(store, dict) and not store_is_historical_test_record(store)
    ]
    stores = sorted(
        stores,
        key=lambda store: normalize_store_model_for_route(str(store.get("shop_type") or "")) == "store_model_pending",
    )
    primary = stores[0] if stores else {}
    platform = str(primary.get("platform_label") or primary.get("platform_id") or "当前平台").strip()
    country = str(primary.get("country_code") or "当前站点").strip().upper()
    store_name = customer_visible_store_name_for_store(primary, fallback="当前店铺") if primary else "当前店铺"
    raw_store_name = customer_safe_machine_text(primary.get("store_name"), empty=store_name) if primary else store_name
    store_name_is_internal = bool(primary) and store_name_looks_internal_audit_record(primary.get("store_name"))
    shop_type = str(primary.get("shop_type") or "店铺模式待确认").strip()
    normalized_store_model = normalize_store_model_for_route(shop_type)
    store_model_pending = normalized_store_model == "store_model_pending"
    store_model_text = (
        "店铺模式待确认"
        if store_model_pending
        else customer_safe_machine_text(shop_type, empty="店铺模式待确认")
    )
    store_ownership_text = store_ownership_label_for_route(primary) if primary else "店铺归属待确认"
    route_key = platform_route_id_for_store(primary) if primary and not store_model_pending and "待确认" not in store_model_text else ""
    connection_method = str(primary.get("connection_method") or "manual_report_or_authorized_connection").strip()
    store_connection_ready_for_ads = bool(primary.get("key_present")) or connection_method in {
        "report_import",
        "browser_visible_capture",
    }
    has_ads_account = bool(str(primary.get("ads_account_id") or "").strip())
    has_business_center = bool(str(primary.get("business_center_id") or "").strip())
    has_ads_identity = has_ads_account and has_business_center
    has_ads_budget_prerequisites = has_ads_identity and store_connection_ready_for_ads
    ads_status = "广告账号已登记" if has_ads_account else "缺广告账号"
    business_status = "广告归属主体已确认" if has_business_center else "缺广告归属主体"
    ads_identity_instruction = (
        "广告前置状态=广告账号、广告归属主体和店铺授权数据已就绪；可以生成预算上限、ROAS止损和放量条件草稿，但真实投放仍需负责人确认。"
        if has_ads_budget_prerequisites
        else (
            "广告前置状态=广告账号和广告归属主体已登记，但店铺授权数据未就绪；只能生成授权/报表/预算前置缺口清单，不要生成可投放预算、不要进入可执行投放包。"
            if has_ads_identity
            else "广告前置状态=缺广告账号或广告归属主体；只能生成广告账号缺口清单、归属主体校验项和预算前置条件，不要生成可投放预算、不要进入可执行投放包。"
        )
    )
    output_requirements = (
        "必须输出优惠叠加、毛利止损、库存/SLA门槛、广告预算上限、ROAS止损、回滚条件、执行后截图和ERP回写证据。"
        if has_ads_budget_prerequisites
        else "必须输出优惠叠加、毛利止损、库存/SLA门槛、广告预算前置条件、授权/报表缺口、负责人确认项和ERP回写字段；不要输出可投放预算上限。"
    )
    if route_key:
        route_label = customer_route_key_label(route_key)
        if store_name and store_name != "当前店铺" and not store_name_is_internal and store_name not in route_label:
            route_label = f"{route_label} - {store_name}"
