def connection_method_label(method: str) -> str:
    return {
        "official_authorization": "官方授权",
        "report_import": "负责人确认报表来源",
        "browser_visible_capture": "已登录页面只读",
        "manual_report_or_authorized_connection": "登记范围，等待后台读取",
    }.get(method, method or "登记范围，等待后台读取")


def render_store_data_manifest_panel(manifest: dict[str, Any]) -> str:
    domains = [domain for domain in (manifest.get("domains") or []) if isinstance(domain, dict)]
    ready_count = int(manifest.get("ready_count") or 0)
    missing_count = int(manifest.get("missing_count") or 0)
    autopilot_text = (
        "基础证据够用，可以进入经营复盘和待确认动作草稿。"
        if manifest.get("can_use_for_autopilot")
        else "还不能全自动判断经营动作；后台 AI 先补齐缺口，只输出草稿和风险。"
    )
    cards = []
    for domain in domains:
        tone = "ok" if domain.get("status") == "ready" else "warn"
        detected = str(domain.get("evidence_text") or "").strip()
        if not detected:
            detected_fields = [str(item) for item in (domain.get("detected_fields") or []) if str(item).strip()]
            detected = "已识别 " + "、".join(detected_fields[:4]) if detected_fields else "后台 AI 还没有读到可用证据"
        required = "、".join([str(item) for item in (domain.get("required_fields") or [])[:5]])
        detail_html = (
            f"<details class='manifest-card-details'><summary>查看后台核对字段</summary><small>{html.escape(required)}</small></details>"
            if required
            else ""
        )
        cards.append(
            f"""
        <div class="manifest-card {html.escape(tone)}">
          <span>{html.escape(str(domain.get("label") or ""))}</span>
          <strong>{html.escape(str(domain.get("status_label") or ""))}</strong>
          <p>{html.escape(detected)}</p>
          <em>{html.escape(str(domain.get("next_step") or ""))}</em>
          {detail_html}
        </div>
"""
        )
    return f"""
    <section class="panel data-manifest-panel">
      <div class="manifest-head">
        <div>
          <h2>后台 AI 真实数据清单</h2>
          <p class="muted">AI 自己检查订单、广告、退款、库存、结算、商品状态和活动报名证据；客户只看哪些能分析、哪些后台继续等待读取。</p>
        </div>
        <strong>{html.escape(str(ready_count))} 项可分析 / {html.escape(str(missing_count))} 项待读取</strong>
      </div>
      <div class="manifest-grid">{''.join(cards)}</div>
      <div class="manifest-foot">{html.escape(autopilot_text)}</div>
    </section>
"""


