        f"<td>{html.escape(money(item.get('revenue')))}</td>"
        f"<td>{html.escape(money(item.get('net_revenue')))} / {html.escape(money(item.get('settlement_amount')))}</td>"
        f"<td>{html.escape(str(item.get('orders', 0)))} / {html.escape(str(item.get('units', 0)))}</td>"
        f"<td>{html.escape(money(item.get('ad_spend')))} / {html.escape(ratio(item.get('roas')))}</td>"
        f"<td>{html.escape(money(item.get('fee_total')))}</td>"
        f"<td>{html.escape(money(item.get('refund_amount')))} / 退货 {html.escape(str(item.get('return_count', 0)))} / 退款率 {html.escape(percent(item.get('refund_rate')))}</td>"
