def render_metric_trend_row(item: dict[str, Any], max_revenue: Any) -> str:
    revenue = float(item.get("revenue", 0) or 0)
    max_value = max(float(max_revenue or 0), revenue, 1.0)
    width = min(100, max(4 if revenue else 0, int(revenue / max_value * 100)))
    return (
        "<tr>"
        f"<td>{html.escape(str(item.get('name', '')))}</td>"
        f"<td>{html.escape(money(revenue))}</td>"
        f"<td>{html.escape(str(item.get('orders', 0)))}</td>"
        f"<td><div class='bar'><i style='width:{width}%'></i></div></td>"
        "</tr>"
    )


def render_forecast_card(forecast: dict[str, Any]) -> str:
    direction = str(forecast.get("direction") or "insufficient_data")
    label_map = {
        "up": "看涨",
        "down": "看跌",
        "flat": "趋势平稳",
        "insufficient_data": "暂无预测",
    }
    confidence = str(forecast.get("confidence") or "low")
    if direction == "insufficient_data":
        return (
            "<div class='forecast'>"
            "<span class='tag'>AI预测</span>"
            "<strong>暂无预测</strong>"
            "<div>后台 AI 读到真实订单、广告、退款和结算数据后，才会生成趋势。</div>"
            f"<p class='muted'>{html.escape(str(forecast.get('reason') or ''))}</p>"
            "</div>"
        )
    return (
        "<div class='forecast'>"
        "<span class='tag'>AI预测</span>"
        f"<strong>{html.escape(label_map.get(direction, direction))}</strong>"
        f"<div>下一周期GMV：{html.escape(money(forecast.get('next_revenue')))}</div>"
        f"<div>下一周期订单：{html.escape(str(forecast.get('next_orders', 0)))}</div>"
        f"<div>置信度：{html.escape(confidence)}</div>"
        f"<p class='muted'>{html.escape(str(forecast.get('reason') or ''))}</p>"
        "</div>"
    )


def render_metric_leaders(
    summary: dict[str, Any],
    platforms: list[dict[str, Any]],
    stores: list[dict[str, Any]],
    products: list[dict[str, Any]],
) -> str:
    has_business_data = metric_bucket_has_business_value(summary) or bool(platforms or stores or products)
    if not has_business_data:
        leaders = [
            ("数据状态", "等待真实店铺数据", "后台 AI 读到订单、广告、退款、结算后生成经营排行"),
            ("店铺排行", "暂无", "有销售后显示表现最好的店铺"),
            ("商品排行", "暂无", "有销量后显示表现最好的商品"),
        ]
        return "".join(
            "<div class='leader'>"
            f"<span>{html.escape(label)}</span>"
            f"<strong>{html.escape(name)}</strong>"
            f"<small>{html.escape(detail)}</small>"
            "</div>"
            for label, name, detail in leaders
        )

    top_platform = platforms[0] if platforms else {}
    top_store = stores[0] if stores else {}
    top_product = products[0] if products else {}
    leaders = [
        (
            "最佳平台",
            str(top_platform.get("name") or "暂无"),
            f"{money(top_platform.get('revenue'))} · {top_platform.get('orders', 0)} 单",
        ),
        (
            "最佳店铺",
            str(top_store.get("name") or "暂无"),
            f"{money(top_store.get('revenue'))} · ROAS {ratio(top_store.get('roas'))}",
        ),
        (
            "最佳商品",
            str(top_product.get("name") or "暂无"),
            f"{money(top_product.get('revenue'))} · {top_product.get('units', 0)} 件",
        ),
    ]
    return "".join(
        "<div class='leader'>"
        f"<span>{html.escape(label)}</span>"
        f"<strong>{html.escape(name)}</strong>"
        f"<small>{html.escape(detail)}</small>"
        "</div>"
        for label, name, detail in leaders
    )


