def newest_dashboard_records(records: list[IntakeRecord], limit: int) -> list[IntakeRecord]:
    return sorted(records, key=lambda item: item.created_at, reverse=True)[:limit]


def newest_output_file(root: Path, pattern: str) -> Path | None:
    output_dir = root / "outputs"
    if not output_dir.exists():
        return None
    paths = sorted(output_dir.glob(pattern), key=lambda item: item.stat().st_mtime, reverse=True)
    return paths[0] if paths else None


def safe_b2b_output_asset_path(root: Path, raw_path: str) -> Path:
    rel = unquote(str(raw_path or "")).replace("\\", "/").lstrip("/")
    parts = [part for part in rel.split("/") if part]
    if not parts or any(part in {".", ".."} for part in parts):
        raise ValueError("这个 B2B 文件路径无效。")
    suffix = Path(parts[-1]).suffix.lower()
    allowed_suffixes = {".html", ".csv", ".md", ".eml", ".txt", ".png", ".jpg", ".jpeg", ".pdf"}
    if suffix not in allowed_suffixes:
        raise ValueError("这个文件类型不能从 B2B 工作台打开。")
    first = parts[0]
    allowed = False
    if len(parts) == 1 and first.startswith("b2b_10001_"):
        allowed = True
    elif len(parts) == 1 and first.startswith("first_order_sprint_10001_"):
        allowed = True
    elif len(parts) == 1 and first.startswith("amazon_10001_ready_image_upload_manifest_"):
        allowed = True
    elif first in {"b2b_10001_sales_assets", "b2b_email_drafts_2026-07-03", "b2b_email_drafts_batch2_2026-07-03"}:
        allowed = True
    elif len(parts) >= 2 and first.startswith("b2b_10001_"):
        allowed = True
    elif len(parts) >= 3 and parts[0] == "amazon_10001_assets" and parts[1] == "ready":
        allowed = True
    if not allowed:
        raise ValueError("这个文件不属于 10001 B2B 获客/跟单资料包。")
    output_dir = (root / "outputs").resolve()
    path = (output_dir / Path(*parts)).resolve()
    if output_dir not in path.parents or not path.exists() or not path.is_file():
        raise ValueError("找不到这份 B2B 获客/跟单资料。")
    return path


def b2b_output_href(path_value: str) -> str:
    raw = str(path_value or "").strip().replace("\\", "/")
    if raw.startswith("outputs/"):
        raw = raw[len("outputs/") :]
    return "/b2b-output/" + quote(raw.lstrip("/"), safe="/")


def b2b_output_href_from_path(root: Path, path_value: str) -> str:
    raw = str(path_value or "").strip()
    if not raw:
        return ""
    path = Path(raw)
    if path.is_absolute():
        try:
            raw = str(path.resolve().relative_to((root / "outputs").resolve()))
        except ValueError:
            raw = path.name
    return b2b_output_href(raw)


def b2b_output_relative_path(root: Path, path_value: str) -> str:
    raw = str(path_value or "").strip().replace("\\", "/")
    if not raw:
        return ""
    path = Path(raw)
    if path.is_absolute():
        try:
            return str(path.resolve().relative_to((root / "outputs").resolve())).replace("\\", "/")
        except ValueError:
            return path.name
    if raw.startswith("outputs/"):
        return raw[len("outputs/") :]
    return raw


def safe_amazon_output_asset_path(root: Path, raw_path: str) -> Path:
    rel = unquote(str(raw_path or "")).replace("\\", "/").lstrip("/")
    parts = [part for part in rel.split("/") if part]
    if not parts or any(part in {".", ".."} for part in parts):
        raise ValueError("这个 Amazon 文件路径无效。")
    suffix = Path(parts[-1]).suffix.lower()
    allowed_suffixes = {".html", ".csv", ".json", ".md", ".txt", ".png", ".jpg", ".jpeg", ".pdf", ".xlsx"}
    if suffix not in allowed_suffixes:
        raise ValueError("这个文件类型不能从 Amazon 工作台打开。")
    first = parts[0]
    allowed = False
    if len(parts) == 1 and first.startswith("amazon_10001_"):
        allowed = True
    elif len(parts) >= 2 and first.startswith("amazon_10001_"):
        allowed = True
    elif len(parts) == 1 and first.startswith("tk_24_round") and "amazon" in first:
        allowed = True
    if not allowed:
        raise ValueError("这个文件不属于 Amazon 10001 出单资料包。")
    output_dir = (root / "outputs").resolve()
    path = (output_dir / Path(*parts)).resolve()
    if output_dir not in path.parents or not path.exists() or not path.is_file():
        raise ValueError("找不到这份 Amazon 出单资料。")
    return path


def load_b2b_10001_pipeline_rows(root: Path) -> list[dict[str, str]]:
    path = newest_output_file(root, "b2b_10001_master_sales_pipeline_*.csv")
    if not path:
        return []
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


def load_b2b_10001_top3_send_rows(root: Path) -> list[dict[str, str]]:
    path = newest_output_file(root, "b2b_10001_top3_send_preflight_*.csv")
    if not path:
        return []
    execution_path = newest_output_file(root, "b2b_10001_top3_first_touch_execution_*.csv")
    execution_by_pipeline: dict[str, dict[str, str]] = {}
    if execution_path:
        with execution_path.open("r", encoding="utf-8-sig", newline="") as handle:
            for execution_row in csv.DictReader(handle):
                execution_pipeline_id = str(execution_row.get("pipeline_id") or "").strip()
                if execution_pipeline_id:
                    execution_by_pipeline[execution_pipeline_id] = {str(k): str(v or "") for k, v in execution_row.items()}
    rows: list[dict[str, str]] = []
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        for row in csv.DictReader(handle):
            pipeline_id = str(row.get("pipeline_id") or "").strip()
            company = str(row.get("company") or "").strip()
            email = str(row.get("email_candidate") or "").strip()
            execution_row = execution_by_pipeline.get(pipeline_id, {})
            draft_file = b2b_output_relative_path(root, str(execution_row.get("email_file") or row.get("email_draft") or ""))
            first_touch_packet = b2b_output_relative_path(root, str(execution_row.get("packet_file") or ""))
            pi_pdf = b2b_output_relative_path(root, str(row.get("pi_pdf") or ""))
            if not pipeline_id or not company:
                continue
            rows.append(
                {
                    "pipeline_id": pipeline_id,
                    "batch": "top3",
                    "company": company,
                    "market": "US",
                    "current_stage": "ready_for_owner_review",
                    "next_stage_after_send": "sent_pending_reply",
                    "send_channel": "email" if email else "manual_review",
                    "contact_path": email,
                    "subject": str(execution_row.get("subject") or f"230gsm washed cotton blank T-shirt samples for {company}"),
                    "draft_file": draft_file,
                    "first_touch_packet": first_touch_packet,
                    "first_touch_boundary": str(execution_row.get("boundary") or "internal_execution_packet_only_no_external_send"),
                    "pi_pdf": pi_pdf,
                    "reply_due_date": str((date.today() + timedelta(days=2)).isoformat()),
                    "reply_status": "not_sent",
                    "next_action": "Owner manually sends first touch, asks for ZIP/sample preference/use case, then logs evidence.",
                    "owner": "AI B2B BD",
                    "external_message_sent": str(row.get("external_message_sent") or "false"),
                }
            )
    return rows


def load_b2b_10001_manual_console_rows(root: Path) -> list[dict[str, str]]:
    path = newest_output_file(root, "b2b_10001_manual_send_console_*.csv")
    if not path:
        return []
    console_html_path = newest_output_file(root, "b2b_10001_manual_send_console_*.html") or path
    rows: list[dict[str, str]] = []
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        for source in csv.DictReader(handle):
            pipeline_id = str(source.get("pipeline_id") or "").strip()
            company = str(source.get("company") or "").strip()
            if not pipeline_id or not company:
                continue
            contact_type = str(source.get("contact_type") or "").strip()
            contact_path = str(source.get("contact_path") or source.get("email_to_use_if_owner_approved") or "").strip()
            rows.append(
                {
                    "pipeline_id": pipeline_id,
                    "batch": str(source.get("lane") or "first_order_sprint"),
                    "company": company,
                    "market": "US",
                    "current_stage": "ready_for_owner_review",
                    "next_stage_after_send": "sent_pending_reply",
                    "send_channel": "email" if contact_type == "email" else contact_type or "manual_review",
                    "contact_path": contact_path,
                    "subject": str(source.get("subject") or "230gsm washed cotton blank T-shirt samples").strip(),
                    "draft_file": b2b_output_relative_path(root, str(source.get("draft_file") or "")),
                    "first_touch_packet": b2b_output_relative_path(root, str(source.get("first_touch_packet") or "")),
                    "first_touch_boundary": "owner/manual execution only; system does not send externally",
                    "pi_pdf": "",
                    "buyer_kit_pdf": b2b_output_relative_path(root, str(source.get("buyer_kit_pdf") or "")),
                    "close_loop_html": b2b_output_relative_path(root, str(source.get("close_loop_html") or "")),
                    "manual_send_console_html": b2b_output_relative_path(root, str(console_html_path)),
                    "sent_evidence_log_template": b2b_output_relative_path(
                        root, str(newest_output_file(root, "b2b_10001_sent_evidence_log_template_*.csv") or "")
                    ),
                    "reply_intake_queue": b2b_output_relative_path(root, str(newest_output_file(root, "b2b_10001_reply_intake_queue_*.csv") or "")),
                    "quote_pi_workbench_html": b2b_output_relative_path(root, str(newest_output_file(root, "b2b_10001_quote_pi_workbench_*.html") or "")),
                    "reply_due_date": str((date.today() + timedelta(days=2)).isoformat()),
                    "reply_status": "not_sent",
                    "next_action": "Open send console, manually send only after owner review, then log evidence and route buyer reply.",
                    "owner": "AI B2B BD",
                    "external_message_sent": str(source.get("external_message_sent_by_system") or "false"),
                }
            )
    return rows


def normalize_b2b_company_key(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def load_b2b_10001_all_send_rows(root: Path) -> list[dict[str, str]]:
    manual_rows = load_b2b_10001_manual_console_rows(root)
    top3_rows = load_b2b_10001_top3_send_rows(root)
    pipeline_rows = load_b2b_10001_pipeline_rows(root)
    rows_by_company: dict[str, dict[str, str]] = {}
    company_order: list[str] = []
    protected_master_fields = {
        "pipeline_id",
        "company",
        "market",
        "current_stage",
        "next_stage_after_send",
        "external_message_sent",
    }

    for source in pipeline_rows:
        pipeline_id = str(source.get("pipeline_id") or "").strip()
        company = str(source.get("company") or "").strip()
        company_key = normalize_b2b_company_key(company) or pipeline_id.lower()
        if not pipeline_id or not company_key or company_key in rows_by_company:
            continue
        row = {str(key): str(value or "") for key, value in source.items()}
        row["candidate_scope"] = "authoritative_master_pipeline"
        rows_by_company[company_key] = row
        company_order.append(company_key)

    for source in [*top3_rows, *manual_rows]:
        pipeline_id = str(source.get("pipeline_id") or "").strip()
        company = str(source.get("company") or "").strip()
        company_key = normalize_b2b_company_key(company) or pipeline_id.lower()
        if not pipeline_id or not company_key:
            continue
        existing = rows_by_company.get(company_key)
        if existing is None:
            row = {str(key): str(value or "") for key, value in source.items()}
            row["candidate_scope"] = "execution_candidate_pending_master_review"
            rows_by_company[company_key] = row
            company_order.append(company_key)
            continue
        master_values = {key: existing.get(key, "") for key in protected_master_fields}
        for key, value in source.items():
            text_value = str(value or "").strip()
            if text_value:
                existing[str(key)] = text_value
        if existing.get("candidate_scope") == "authoritative_master_pipeline":
            existing.update(master_values)
        existing["has_execution_packet"] = "true"

    return [rows_by_company[key] for key in company_order]


