def load_b2b_10001_manual_send_log(root: Path) -> list[dict[str, str]]:
    paths = sorted((root / "outputs").glob("b2b_10001_manual_send_log_*.csv"))
    rows: list[dict[str, str]] = []
    for path in paths:
        try:
            with path.open("r", encoding="utf-8-sig", newline="") as handle:
                rows.extend(dict(row) for row in csv.DictReader(handle))
        except OSError:
            continue
    return rows


def record_b2b_10001_manual_send_aftercare(root: Path, send_row: dict[str, str]) -> dict[str, Any]:
    pipeline_id = str(send_row.get("pipeline_id") or "").strip()
    company = str(send_row.get("company") or "").strip()
    manual_sent_at = str(send_row.get("manual_sent_at") or datetime.now(timezone.utc).isoformat()).strip()
    try:
        base_date = date.fromisoformat(manual_sent_at[:10])
    except ValueError:
        base_date = date.today()
    slug = b2b_10001_queue_slug(pipeline_id, company)
    path = b2b_10001_sent_followup_tasks_path(root)
    existing_ids: set[str] = set()
    if path.exists() and path.stat().st_size:
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            existing_ids = {str(row.get("task_id") or "") for row in csv.DictReader(handle)}
    rows: list[dict[str, str]] = []
    for days, label, next_action in [
        (2, "D+2", "If no reply, send a short value nudge and ask for ZIP/postcode plus sample preferences."),
        (5, "D+5", "If no reply, send proof-oriented follow-up: blank quality, sample pack, low-friction test order."),
        (10, "D+10", "If no reply, send last-touch permission note and pause the lead unless new signal appears."),
    ]:
        task_id = f"SENTFOLLOW-10001-{base_date.strftime('%Y%m%d')}-{slug}-{label}"
        if task_id in existing_ids:
            continue
        rows.append(
            {
                "created_at": datetime.now(timezone.utc).isoformat(),
                "task_id": task_id,
                "pipeline_id": pipeline_id,
                "buyer_company": company,
                "contact_path": str(send_row.get("contact_path") or ""),
                "market": str(send_row.get("market") or ""),
                "send_channel": str(send_row.get("send_channel") or ""),
                "subject": str(send_row.get("subject") or ""),
                "manual_sent_at": manual_sent_at,
                "follow_up_day": label,
                "follow_up_date": str(base_date + timedelta(days=days)),
                "crm_stage": "sent_pending_reply",
                "follow_up_owner": "AI Campaign & B2B BD",
                "next_action": next_action,
                "send_log_note": str(send_row.get("note") or ""),
                "external_submit_performed_by_system": "false",
            }
        )
    if rows:
        fieldnames = list(rows[0].keys())
        write_header = not path.exists() or path.stat().st_size == 0
        with path.open("a", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames)
            if write_header:
                writer.writeheader()
            writer.writerows(rows)
    return {"sent_followup_tasks_path": str(path), "sent_followup_task_count": len(rows)}


def write_b2b_10001_current_send_status(root: Path, log_rows: list[dict[str, str]] | None = None) -> Path:
    pipeline_rows = load_b2b_10001_all_send_rows(root)
    log_rows = log_rows if log_rows is not None else load_b2b_10001_manual_send_log(root)
    sent_by_pipeline: dict[str, dict[str, str]] = {}
    for row in log_rows:
        pipeline_id = str(row.get("pipeline_id") or "").strip()
        if pipeline_id:
            sent_by_pipeline[pipeline_id] = row
    output_rows: list[dict[str, str]] = []
    for row in pipeline_rows:
        merged = dict(row)
        pipeline_id = str(row.get("pipeline_id") or "").strip()
        sent = sent_by_pipeline.get(pipeline_id)
        if sent:
            merged["manual_sent_at"] = str(sent.get("manual_sent_at") or "")
            merged["reply_status"] = "sent_pending_reply"
            merged["current_stage"] = "contacted"
            merged["external_message_sent"] = "owner_marked_manual_send"
            merged["send_log_source"] = str(sent.get("source") or "")
            merged["send_log_note"] = str(sent.get("note") or "")
        output_rows.append(merged)
    path = b2b_10001_current_send_status_path(root)
    if output_rows:
        fieldnames = list(output_rows[0].keys())
        extra_fields = ["send_log_source", "send_log_note"]
        for field in extra_fields:
            if field not in fieldnames:
                fieldnames.append(field)
        with path.open("w", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames, extrasaction="ignore")
            writer.writeheader()
            writer.writerows(output_rows)
    else:
        path.write_text("", encoding="utf-8")
    return path


def record_b2b_10001_manual_send(root: Path, payload: dict[str, Any], session_info: dict[str, Any] | None = None) -> dict[str, Any]:
    pipeline_id = str(payload.get("pipeline_id") or "").strip()
    if not re.fullmatch(r"PIPE-10001-(?:\d{3}|PUB-\d{3})", pipeline_id):
        raise ValueError("无效的 B2B 发送编号。")
    pipeline_rows = load_b2b_10001_all_send_rows(root)
    source_row = next((row for row in pipeline_rows if str(row.get("pipeline_id") or "").strip() == pipeline_id), None)
    if not source_row:
        raise ValueError("找不到这条 B2B 发送对象。")
    manual_sent_at = str(payload.get("manual_sent_at") or datetime.now(timezone.utc).isoformat()).strip()
    source = str(payload.get("source") or "b2b-sales-local").strip()
    note = str(payload.get("note") or "owner_marked_manual_send_after_external_manual_action").strip()
    actor = str((session_info or {}).get("display_name") or (session_info or {}).get("login_id") or "owner").strip()
    log_path = b2b_10001_manual_send_log_path(root)
    fieldnames = [
        "manual_sent_at",
        "pipeline_id",
        "company",
        "market",
        "send_channel",
        "contact_path",
        "subject",
        "source",
        "actor",
        "note",
    ]
    row = {
        "manual_sent_at": manual_sent_at,
        "pipeline_id": pipeline_id,
        "company": str(source_row.get("company") or payload.get("company") or ""),
        "market": str(source_row.get("market") or ""),
        "send_channel": str(source_row.get("send_channel") or ""),
        "contact_path": str(source_row.get("contact_path") or ""),
        "subject": str(source_row.get("subject") or ""),
        "source": source,
        "actor": actor,
        "note": note,
    }
    write_header = not log_path.exists() or log_path.stat().st_size == 0
    with log_path.open("a", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=fieldnames)
        if write_header:
            writer.writeheader()
        writer.writerow(row)
    aftercare = record_b2b_10001_manual_send_aftercare(root, row)
    status_path = write_b2b_10001_current_send_status(root)
    return {
        "pipeline_id": pipeline_id,
        "company": row["company"],
        "manual_sent_at": manual_sent_at,
        "reply_status": "sent_pending_reply",
        "log_path": str(log_path),
        "status_path": str(status_path),
        "sent_followup_tasks_path": aftercare["sent_followup_tasks_path"],
        "sent_followup_task_count": aftercare["sent_followup_task_count"],
        "external_submit_performed_by_system": False,
    }


def load_b2b_10001_quote_template_rows(root: Path) -> list[dict[str, str]]:
    path = newest_output_file(root, "b2b_10001_sample_quote_templates_*.csv")
    if not path:
        return []
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


