def select_b2b_10001_reply_rule(reply_type: str, raw_reply: str) -> dict[str, Any]:
    rules = b2b_10001_reply_rules()
    normalized_type = str(reply_type or "").strip()
    if normalized_type and normalized_type != "auto_detect":
        for rule in rules:
            if rule["reply_type"] == normalized_type:
                return rule
    haystack = str(raw_reply or "").lower()
    for rule in rules:
        for keyword in rule.get("keywords") or []:
            if keyword.lower() in haystack:
                return rule
    return next(rule for rule in rules if rule["reply_type"] == "unclear")


def safe_float(value: Any, default: float = 0.0) -> float:
    try:
        return float(str(value or "").strip() or default)
    except (TypeError, ValueError):
        return default


def b2b_10001_default_follow_up_date(now: datetime | None = None) -> str:
    base = now.date() if now else date.today()
    return (base + timedelta(days=2)).isoformat()


def b2b_10001_queue_slug(*parts: Any) -> str:
    raw = "-".join(str(part or "").strip() for part in parts if str(part or "").strip())
    slug = re.sub(r"[^A-Za-z0-9]+", "-", raw).strip("-").upper()
    return slug[:48] or uuid4().hex[:10].upper()


def b2b_10001_append_csv_row(path: Path, row: dict[str, str], fieldnames: list[str] | None = None) -> None:
    actual_fieldnames = fieldnames or list(row.keys())
    write_header = not path.exists() or path.stat().st_size == 0
    with path.open("a", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=actual_fieldnames, extrasaction="ignore")
        if write_header:
            writer.writeheader()
        writer.writerow(row)


def b2b_10001_quote_profit_summary(payload: dict[str, Any]) -> dict[str, str]:
    quantity = max(safe_float(payload.get("quantity"), 0.0), 0.0)
    quote_total = max(safe_float(payload.get("quote_total_usd") or payload.get("quote_total"), 0.0), 0.0)
    unit_cost = max(safe_float(payload.get("unit_cost_usd"), 0.0), 0.0)
    packaging_cost = max(safe_float(payload.get("packaging_cost_usd"), 0.0), 0.0)
    freight_cost = max(safe_float(payload.get("freight_cost_usd"), 0.0), 0.0)
    payment_fee_rate = max(safe_float(payload.get("payment_fee_rate"), 0.0), 0.0)
    target_margin_rate = max(safe_float(payload.get("target_margin_rate"), 0.0), 0.0)
    production_cost = unit_cost * quantity
    payment_fee = quote_total * payment_fee_rate / 100
    total_cost = production_cost + packaging_cost + freight_cost + payment_fee
    net_profit = quote_total - total_cost
    margin_rate = (net_profit / quote_total * 100) if quote_total else 0.0
    profit_status = "needs_cost_inputs"
    if quote_total and quantity and unit_cost:
        profit_status = "below_target_margin" if target_margin_rate and margin_rate < target_margin_rate else "profit_draft_review"
    return {
        "unit_cost_usd": f"{unit_cost:.2f}",
        "packaging_cost_usd": f"{packaging_cost:.2f}",
        "freight_cost_usd": f"{freight_cost:.2f}",
        "payment_fee_rate": f"{payment_fee_rate:.2f}",
        "target_margin_rate": f"{target_margin_rate:.2f}",
        "estimated_gross_revenue_usd": f"{quote_total:.2f}",
        "estimated_production_cost_usd": f"{production_cost:.2f}",
        "estimated_payment_fee_usd": f"{payment_fee:.2f}",
        "estimated_total_cost_usd": f"{total_cost:.2f}",
        "estimated_net_profit_usd": f"{net_profit:.2f}",
        "estimated_margin_rate": f"{margin_rate:.2f}",
        "profit_status": profit_status,
    }


def record_b2b_10001_quote_aftercare(root: Path, quote_row: dict[str, str]) -> dict[str, Any]:
    created_at = str(quote_row.get("created_at") or datetime.now(timezone.utc).isoformat())
    pipeline_id = str(quote_row.get("pipeline_id") or "").strip()
    buyer_company = str(quote_row.get("buyer_company") or "").strip()
    slug = b2b_10001_queue_slug(pipeline_id, buyer_company, quote_row.get("request_type"), quote_row.get("quantity"))
    follow_up_date = str(quote_row.get("follow_up_date") or b2b_10001_default_follow_up_date()).strip()
    task_id = f"FOLLOW-10001-{date.today().strftime('%Y%m%d')}-{slug}"
    confirmation_id = f"CONFIRM-10001-{date.today().strftime('%Y%m%d')}-{slug}"
    followup_row = {
        "created_at": created_at,
        "task_id": task_id,
        "pipeline_id": pipeline_id,
        "buyer_company": buyer_company,
        "buyer_email": str(quote_row.get("buyer_email") or ""),
        "market": str(quote_row.get("market") or ""),
        "city_or_postcode": str(quote_row.get("city_or_postcode") or ""),
        "crm_stage": "quote_draft_owner_review",
        "follow_up_date": follow_up_date,
        "follow_up_owner": "AI Campaign & B2B BD",
        "next_action": "owner_review_quote_then_send_or_adjust",
        "quote_total_usd": str(quote_row.get("quote_total_usd") or ""),
        "estimated_net_profit_usd": str(quote_row.get("estimated_net_profit_usd") or ""),
        "estimated_margin_rate": str(quote_row.get("estimated_margin_rate") or ""),
        "profit_status": str(quote_row.get("profit_status") or ""),
        "external_submit_performed_by_system": "false",
    }
    confirmation_row = {
        "created_at": created_at,
        "confirmation_id": confirmation_id,
        "pipeline_id": pipeline_id,
        "buyer_company": buyer_company,
        "buyer_email": str(quote_row.get("buyer_email") or ""),
        "market": str(quote_row.get("market") or ""),
        "city_or_postcode": str(quote_row.get("city_or_postcode") or ""),
        "action_type": "send_b2b_quote_pi",
        "requires_confirmation": "true",
        "blocked_until": "owner_confirms_stock_freight_payment_terms_and_send_channel",
        "follow_up_date": follow_up_date,
        "quote_total_usd": str(quote_row.get("quote_total_usd") or ""),
        "estimated_net_profit_usd": str(quote_row.get("estimated_net_profit_usd") or ""),
        "estimated_margin_rate": str(quote_row.get("estimated_margin_rate") or ""),
        "profit_status": str(quote_row.get("profit_status") or ""),
        "payload_summary": (
            f"{quote_row.get('request_type') or 'quote'}; "
            f"{quote_row.get('quantity') or 'TBD'} pcs; "
            f"{quote_row.get('preferred_colors') or 'TBD colors'}; "
            f"{quote_row.get('preferred_sizes') or 'TBD sizes'}; "
            f"{quote_row.get('market') or 'TBD market'} {quote_row.get('city_or_postcode') or ''}".strip()
        ),
        "rollback_note": "No external message, payment request, or shipment is performed by this queue record.",
        "external_submit_performed_by_system": "false",
    }
    followup_path = b2b_10001_quote_followup_tasks_path(root)
    confirmation_path = b2b_10001_quote_confirmation_queue_path(root)
    b2b_10001_append_csv_row(followup_path, followup_row)
    b2b_10001_append_csv_row(confirmation_path, confirmation_row)
    return {
        "task_id": task_id,
        "confirmation_id": confirmation_id,
        "follow_up_date": follow_up_date,
        "followup_tasks_path": str(followup_path),
        "confirmation_queue_path": str(confirmation_path),
    }


def record_b2b_10001_reply_intake(root: Path, payload: dict[str, Any], session_info: dict[str, Any] | None = None) -> dict[str, Any]:
    pipeline_id = str(payload.get("pipeline_id") or "").strip()
    if pipeline_id and not re.fullmatch(r"PIPE-10001-(?:\d{3}|PUB-\d{3})", pipeline_id):
        raise ValueError("无效的 B2B 客户编号。")
    pipeline_rows = load_b2b_10001_all_send_rows(root)
    source_row = next((row for row in pipeline_rows if str(row.get("pipeline_id") or "").strip() == pipeline_id), None)
    company = str(payload.get("company") or payload.get("buyer_company") or (source_row or {}).get("company") or "").strip()
    if not company:
        raise ValueError("请先选择或填写客户公司。")
    raw_reply = str(payload.get("raw_reply") or "").strip()
    rule = select_b2b_10001_reply_rule(str(payload.get("reply_type") or "auto_detect"), raw_reply)
    actor = str((session_info or {}).get("display_name") or (session_info or {}).get("login_id") or "owner").strip()
    now = datetime.now(timezone.utc).isoformat()
    raw_excerpt = raw_reply[:600]
    row = {
        "created_at": now,
        "pipeline_id": pipeline_id,
        "company": company,
        "contact": str(payload.get("contact") or payload.get("buyer_email") or (source_row or {}).get("contact_path") or ""),
        "market": str(payload.get("market") or (source_row or {}).get("market") or ""),
        "reply_type": str(rule["reply_type"]),
        "raw_reply_excerpt": raw_excerpt,
        "crm_stage": str(rule["crm_stage"]),
        "next_action": str(rule["next_action"]),
        "required_fields": str(rule["required_fields"]),
        "reply_draft": str(rule["reply_draft"]),
        "reply_status": "draft_owner_review",
        "actor": actor,
        "external_submit_performed_by_system": "false",
    }
    log_path = b2b_10001_reply_intake_log_path(root)
    next_path = b2b_10001_reply_next_actions_path(root)
    fieldnames = list(row.keys())
    for path in (log_path, next_path):
        write_header = not path.exists() or path.stat().st_size == 0
        with path.open("a", encoding="utf-8-sig", newline="") as handle:
            writer = csv.DictWriter(handle, fieldnames=fieldnames)
            if write_header:
                writer.writeheader()
            writer.writerow(row)
    return {
        "pipeline_id": pipeline_id,
        "company": company,
        "reply_type": row["reply_type"],
        "crm_stage": row["crm_stage"],
        "next_action": row["next_action"],
        "required_fields": row["required_fields"],
        "reply_draft": row["reply_draft"],
        "reply_status": row["reply_status"],
        "reply_log_path": str(log_path),
        "next_actions_path": str(next_path),
        "external_submit_performed_by_system": False,
    }


def record_b2b_10001_quote_draft(root: Path, payload: dict[str, Any], session_info: dict[str, Any] | None = None) -> dict[str, Any]:
    company = str(payload.get("buyer_company") or payload.get("company") or "").strip()
    email = str(payload.get("buyer_email") or payload.get("email") or "").strip()
    market = str(payload.get("market") or payload.get("country") or "").strip()
    city = str(payload.get("city_or_postcode") or payload.get("city") or "").strip()
    request_type = str(payload.get("request_type") or "").strip()
    quantity = str(payload.get("quantity") or "").strip()
    quote_total = str(payload.get("quote_total_usd") or payload.get("quote_total") or "").strip()
    if not company:
        raise ValueError("请先填写客户公司。")
    if not market:
        raise ValueError("请先填写国家/市场。")
    if not request_type:
        raise ValueError("请先选择样品/订单类型。")
    if not quantity:
        raise ValueError("请先填写数量。")
    if not quote_total:
        raise ValueError("请先生成或填写报价金额。")
    actor = str((session_info or {}).get("display_name") or (session_info or {}).get("login_id") or "owner").strip()
    now = datetime.now(timezone.utc).isoformat()
    profit = b2b_10001_quote_profit_summary(payload)
    follow_up_date = str(payload.get("follow_up_date") or b2b_10001_default_follow_up_date()).strip()
    row = {
        "created_at": now,
        "pipeline_id": str(payload.get("pipeline_id") or ""),
        "buyer_company": company,
        "buyer_contact_name": str(payload.get("buyer_contact_name") or ""),
        "buyer_email": email,
        "market": market,
        "city_or_postcode": city,
        "request_type": request_type,
        "quantity": quantity,
        "preferred_colors": str(payload.get("preferred_colors") or ""),
        "preferred_sizes": str(payload.get("preferred_sizes") or ""),
        "print_method": str(payload.get("print_method") or ""),
        "delivery_terms": str(payload.get("delivery_terms") or ""),
        "quote_total_usd": quote_total,
        "unit_cost_usd": profit["unit_cost_usd"],
        "packaging_cost_usd": profit["packaging_cost_usd"],
        "freight_cost_usd": profit["freight_cost_usd"],
        "payment_fee_rate": profit["payment_fee_rate"],
        "target_margin_rate": profit["target_margin_rate"],
        "estimated_gross_revenue_usd": profit["estimated_gross_revenue_usd"],
        "estimated_production_cost_usd": profit["estimated_production_cost_usd"],
        "estimated_payment_fee_usd": profit["estimated_payment_fee_usd"],
        "estimated_total_cost_usd": profit["estimated_total_cost_usd"],
        "estimated_net_profit_usd": profit["estimated_net_profit_usd"],
        "estimated_margin_rate": profit["estimated_margin_rate"],
        "profit_status": profit["profit_status"],
        "follow_up_date": follow_up_date,
        "follow_up_note": str(payload.get("follow_up_note") or ""),
        "quote_status": "draft_owner_review",
        "next_step": "owner_review_before_sending_or_payment",
        "actor": actor,
        "external_submit_performed_by_system": "false",
    }
    path = b2b_10001_quote_draft_log_path(root)
    fieldnames = list(row.keys())
    b2b_10001_append_csv_row(path, row, fieldnames)
    aftercare = record_b2b_10001_quote_aftercare(root, row)
    approval_queue = ensure_b2b_10001_quote_confirmation_action_queue(root)
    return {
        "quote_status": row["quote_status"],
        "quote_path": str(path),
        "buyer_company": company,
        "quote_total_usd": quote_total,
        "estimated_net_profit_usd": profit["estimated_net_profit_usd"],
        "estimated_margin_rate": profit["estimated_margin_rate"],
        "profit_status": profit["profit_status"],
        "follow_up_date": follow_up_date,
        "followup_task_id": aftercare["task_id"],
        "confirmation_id": aftercare["confirmation_id"],
        "followup_tasks_path": aftercare["followup_tasks_path"],
        "confirmation_queue_path": aftercare["confirmation_queue_path"],
        "approval_queue_path": approval_queue["queue_path"],
        "approval_queue_added": approval_queue["added"],
        "external_submit_performed_by_system": False,
    }


def load_b2b_10001_csv_rows(path: Path | None, limit: int = 8) -> list[dict[str, str]]:
    if not path or not path.exists():
        return []
    rows: list[dict[str, str]] = []
    try:
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            for row in csv.DictReader(handle):
                rows.append({str(key): str(value or "") for key, value in row.items()})
                if len(rows) >= limit:
                    break
    except (OSError, csv.Error):
        return []
    return rows


def b2b_10001_quote_confirmation_action_id(row: dict[str, str]) -> str:
    seed = "|".join(
        str(row.get(key) or "").strip()
        for key in ("confirmation_id", "pipeline_id", "buyer_company", "quote_total_usd", "payload_summary")
    )
    digest = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:12]
    return f"b2b-10001-quote-confirm-{digest}"


def b2b_10001_country_code(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return "GLOBAL"
    normalized = re.sub(r"[^A-Za-z]", "", raw).upper()
    aliases = {
        "UNITEDSTATES": "US",
        "USA": "US",
        "US": "US",
        "CANADA": "CA",
        "CA": "CA",
        "MEXICO": "MX",
        "MX": "MX",
        "UK": "GB",
        "GB": "GB",
        "UNITEDKINGDOM": "GB",
        "AUSTRALIA": "AU",
        "AU": "AU",
        "JAPAN": "JP",
        "JP": "JP",
    }
    return aliases.get(normalized, normalized[:2] if len(normalized) == 2 else "GLOBAL")


