def ensure_b2b_10001_quote_confirmation_action_queue(root: Path) -> dict[str, Any]:
    confirmation_paths = sorted((root / "outputs").glob("b2b_10001_quote_confirmation_queue_*.csv"))
    if not confirmation_paths:
        return {"added": 0, "queue_path": ""}
    queue_path = latest_action_queue_path(root) or (root / "outputs" / f"action_queue_{date.today().isoformat()}.json")
    actions = load_action_queue_file(queue_path)
    existing_ids = {str(action.get("action_id") or "") for action in actions if isinstance(action, dict)}
    added = 0
    for path in confirmation_paths:
        for row in load_b2b_10001_csv_rows(path, limit=500):
            action = b2b_10001_quote_confirmation_to_action(row)
            action_id = str(action.get("action_id") or "")
            if not action_id or action_id in existing_ids:
                continue
            actions.append(action)
            existing_ids.add(action_id)
            added += 1
    if added:
        write_action_queue_file(queue_path, actions)
    return {"added": added, "queue_path": str(queue_path)}


def b2b_10001_top3_outreach_action_id(row: dict[str, str]) -> str:
    seed = "|".join(
        str(row.get(key) or "").strip()
        for key in ("pipeline_id", "company", "quote_id", "pi_draft_file")
    )
    digest = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:12]
    return f"b2b-10001-top3-outreach-{digest}"


