def render_b2b_10001_send_action_cards(root: Path, rows: list[dict[str, str]], limit: int = 5) -> str:
    cards: list[str] = []
    for index, row in enumerate(rows[:limit], start=1):
        pipeline_id = str(row.get("pipeline_id") or f"PIPE-{index}").strip()
        company = str(row.get("company") or "").strip()
        contact_path = str(row.get("contact_path") or "").strip()
        contact_display = b2b_10001_contact_display(contact_path)
        send_channel = str(row.get("send_channel") or "").strip()
        send_channel_label = b2b_10001_send_channel_label(send_channel)
        subject = str(row.get("subject") or "").strip()
        draft_body = read_b2b_10001_draft_body(root, row.get("draft_file") or "")
        draft_url = b2b_output_href_from_path(root, row.get("draft_file") or "")
        first_touch_packet_url = b2b_output_href_from_path(root, row.get("first_touch_packet") or "")
        pi_pdf_url = b2b_output_href_from_path(root, row.get("pi_pdf") or "")
        buyer_kit_url = b2b_output_href_from_path(root, row.get("buyer_kit_pdf") or "")
        close_loop_url = b2b_output_href_from_path(root, row.get("close_loop_html") or "")
        send_console_url = b2b_output_href_from_path(root, row.get("manual_send_console_html") or "")
        quote_workbench_url = b2b_output_href_from_path(root, row.get("quote_pi_workbench_html") or "")
        evidence_url = b2b_output_href_from_path(root, row.get("sent_evidence_log_template") or "")
        reply_queue_url = b2b_output_href_from_path(root, row.get("reply_intake_queue") or "")
        contact_email = b2b_10001_contact_email(contact_path)
        is_email = "email" in send_channel.lower() and bool(contact_email)
        mailto_url = (
            "mailto:" + quote(contact_email, safe="@.") + "?" + urlencode({"subject": subject, "body": draft_body})
            if is_email
            else ""
        )
        contact_url = b2b_10001_contact_url(contact_path)
        execution_boundary = b2b_10001_execution_boundary_label(row.get("first_touch_boundary") or "")
        pipeline_js = html.escape(json.dumps(pipeline_id, ensure_ascii=False))
        company_js = html.escape(json.dumps(company, ensure_ascii=False))
        primary_actions: list[str] = []
        if mailto_url:
            primary_actions.append(f"<a class='button secondary' href='{html.escape(mailto_url)}'>打开邮件</a>")
        if contact_url:
            primary_actions.append(
                f"<a class='button secondary' href='{html.escape(contact_url)}' target='_blank'>打开联系页</a>"
            )
        if not primary_actions:
            primary_actions.append("<span class='send-chip'>先人工确认联系路径</span>")
        primary_action = "".join(primary_actions)
        draft_action = (
            f"<a class='button secondary' href='{html.escape(draft_url)}' target='_blank'>打开草稿</a>"
            if draft_url
            else ""
        )
        packet_action = f"<a class='button secondary' href='{html.escape(first_touch_packet_url)}' target='_blank'>打开执行包</a>" if first_touch_packet_url else ""
        pi_action = f"<a class='button secondary' href='{html.escape(pi_pdf_url)}' target='_blank'>打开PI</a>" if pi_pdf_url else ""
        buyer_kit_action = f"<a class='button secondary' href='{html.escape(buyer_kit_url)}' target='_blank'>买家包</a>" if buyer_kit_url else ""
        close_loop_action = f"<a class='button secondary' href='{html.escape(close_loop_url)}' target='_blank'>成交闭环</a>" if close_loop_url else ""
        send_console_action = f"<a class='button secondary' href='{html.escape(send_console_url)}' target='_blank'>发送台</a>" if send_console_url else ""
        quote_workbench_action = f"<a class='button secondary' href='{html.escape(quote_workbench_url)}' target='_blank'>报价台</a>" if quote_workbench_url else ""
        evidence_action = f"<a class='button secondary' href='{html.escape(evidence_url)}' target='_blank'>证据表</a>" if evidence_url else ""
        reply_queue_action = f"<a class='button secondary' href='{html.escape(reply_queue_url)}' target='_blank'>回复队列</a>" if reply_queue_url else ""
        cards.append(
            f"""
        <article class="send-card" data-pipeline="{html.escape(pipeline_id)}">
          <div class="send-card-head">
            <strong>{index}. {html.escape(company)}</strong>
            <span>{html.escape(send_channel_label)}</span>
          </div>
          <dl>
            <dt>收件/路径</dt><dd>{html.escape(contact_display)}</dd>
            <dt>主题</dt><dd>{html.escape(subject)}</dd>
            <dt>执行边界</dt><dd>{html.escape(execution_boundary)}</dd>
          </dl>
          <textarea id="draft-{html.escape(pipeline_id)}" readonly>{html.escape(draft_body)}</textarea>
          <div class="send-actions">
            <button type="button" onclick="copyDraft({pipeline_js})">复制正文</button>
            <button type="button" onclick="markSent({pipeline_js},{company_js}, this)">外部发送后回写证据</button>
            {packet_action}
            {draft_action}
            {pi_action}
            {buyer_kit_action}
            {close_loop_action}
            {send_console_action}
            {quote_workbench_action}
            {evidence_action}
            {reply_queue_action}
            {primary_action}
          </div>
          <div class="send-status" id="status-{html.escape(pipeline_id)}">未发送：等待负责人手动执行。</div>
        </article>
"""
        )
    if not cards:
        return "<div class='empty'>暂无可发送对象。</div>"
    return "".join(cards)


def render_b2b_10001_dashboard_panel(root: Path) -> str:
    rows = load_b2b_10001_pipeline_rows(root)
    total = len(rows)
    approved = sum(1 for row in rows if str(row.get("current_stage") or "") == "approved_to_send")
    pending_review = sum(1 for row in rows if "pending" in str(row.get("current_stage") or ""))
    research = sum(1 for row in rows if "research" in str(row.get("current_stage") or ""))
    sent = sum(1 for row in rows if str(row.get("external_message_sent") or "").lower() == "true")
    sample_page = newest_output_file(root, "b2b_10001_sample_request_page_*.html")
    command_page = newest_output_file(root, "b2b_10001_manual_send_console_*.html") or newest_output_file(root, "b2b_10001_unified_sales_command_center_*.html")
    return f"""
    <section class="panel">
      <h2>外贸 B2B 获客/跟单</h2>
      <div class="brief-grid">
        <a class="brief-card" href="/b2b-sales">
          <strong>打开获客跟单台</strong>
          <span>权威主池 {total} 个去重客户：{approved} 个已批准草稿、{pending_review} 个待复核、{research} 个研究对象；真实外联 {sent} 个。</span>
        </a>
        <a class="brief-card" href="{html.escape(b2b_output_href(command_page.name) if command_page else '/b2b-sales')}">
          <strong>销售执行页</strong>
          <span>打开联系人、邮件草稿、资料包、报价/样品话术；真实外联仍需负责人确认。</span>
        </a>
        <a class="brief-card" href="{html.escape(b2b_output_href(sample_page.name) if sample_page else '/b2b-sales')}">
          <strong>样品申请页</strong>
          <span>给客户看产品、颜色卡、尺码表和样品包选项；先收询盘再报价。</span>
        </a>
      </div>
      <div class="muted" style="margin-top:10px;">这条线不是当前“出单主线”；它负责持续找客户、建 CRM、跑样品包、批发询盘、报价、跟单和复购，Amazon 才是当前出单主线。</div>
    </section>
"""


def render_b2b_10001_sales_page(root: Path, session_info: dict[str, Any] | None = None) -> str:
    rows = load_b2b_10001_pipeline_rows(root)
    action_rows = load_b2b_10001_all_send_rows(root)
    command_page = newest_output_file(root, "b2b_10001_unified_sales_command_center_*.html")
    first_order_sprint = newest_output_file(root, "first_order_sprint_10001_*.html")
    manual_send_console = newest_output_file(root, "b2b_10001_manual_send_console_*.html")
    manual_send_console_csv = newest_output_file(root, "b2b_10001_manual_send_console_*.csv")
    sent_evidence_log_template = newest_output_file(root, "b2b_10001_sent_evidence_log_template_*.csv")
    reply_intake_queue_template = newest_output_file(root, "b2b_10001_reply_intake_queue_*.csv")
    quote_pi_workbench = newest_output_file(root, "b2b_10001_quote_pi_workbench_*.html")
    quote_pi_workbench_csv = newest_output_file(root, "b2b_10001_quote_pi_workbench_*.csv")
    sample_page = newest_output_file(root, "b2b_10001_sample_request_page_*.html")
    send_confirmation_sheet = newest_output_file(root, "b2b_10001_first5_send_confirmation_sheet_*.md")
    current_send_status = newest_output_file(root, "b2b_10001_current_send_status_*.csv")
    manual_send_log = newest_output_file(root, "b2b_10001_manual_send_log_*.csv")
    quote_draft_log = newest_output_file(root, "b2b_10001_quote_draft_log_*.csv")
    quote_followup_tasks = newest_output_file(root, "b2b_10001_quote_followup_tasks_*.csv")
    quote_confirmation_queue = newest_output_file(root, "b2b_10001_quote_confirmation_queue_*.csv")
    reply_intake_log = newest_output_file(root, "b2b_10001_reply_intake_log_*.csv")
    reply_next_actions = newest_output_file(root, "b2b_10001_reply_next_actions_*.csv")
    sent_followup_tasks = newest_output_file(root, "b2b_10001_sent_followup_tasks_*.csv")
    top3_deal_pack = newest_output_file(root, "b2b_10001_top3_deal_pack_*.html")
    top3_send_preflight = newest_output_file(root, "b2b_10001_top3_send_preflight_*.csv")
    top3_followup_cadence = newest_output_file(root, "b2b_10001_top3_followup_cadence_*.html")
    top3_followup_cadence_csv = newest_output_file(root, "b2b_10001_top3_followup_cadence_*.csv")
    top3_deal_readiness = newest_output_file(root, "b2b_10001_top3_deal_readiness_*.html")
    top3_deal_readiness_csv = newest_output_file(root, "b2b_10001_top3_deal_readiness_*.csv")
    top3_close_ready = newest_output_file(root, "b2b_10001_top3_close_ready_checklist_*.html")
    top3_close_ready_csv = newest_output_file(root, "b2b_10001_top3_close_ready_checklist_*.csv")
    top3_owner_confirmation_queue = newest_output_file(root, "b2b_10001_top3_owner_confirmation_queue_*.csv")
    top3_first_touch_execution = newest_output_file(root, "b2b_10001_top3_first_touch_execution_*.html")
    top3_first_touch_execution_csv = newest_output_file(root, "b2b_10001_top3_first_touch_execution_*.csv")
    onepager = root / "outputs" / "b2b_10001_sales_assets" / "teelab_10001_b2b_onepager_en.pdf"
    color_card = root / "outputs" / "b2b_10001_sales_assets" / "teelab_10001_b2b_color_card_en.pdf"
    size_chart = root / "outputs" / "amazon_10001_assets" / "ready" / "TL10001_size_chart_en.jpg"
    total = len(rows)
    approved = sum(1 for row in rows if str(row.get("current_stage") or "") == "approved_to_send")
    pending_review = sum(1 for row in rows if "pending" in str(row.get("current_stage") or ""))
    research = sum(1 for row in rows if "research" in str(row.get("current_stage") or ""))
    sent = sum(1 for row in rows if str(row.get("external_message_sent") or "").lower() == "true")
    email_count = sum(1 for row in rows if "email" in str(row.get("send_channel") or "").lower())
    form_count = sum(
        1
        for row in rows
        if any(token in str(row.get("send_channel") or "").lower() for token in ("contact_page", "contact_form", "quote_page", "enterprise_form"))
    )
    metric_html = "".join(
        "<div class='metric-card'><span>{label}</span><strong>{value}</strong><small>{note}</small></div>".format(
            label=html.escape(label),
            value=html.escape(str(value)),
            note=html.escape(note),
        )
        for label, value, note in [
            ("权威客户主池", total, "按公司去重后的 10001 高匹配客户，不把执行包重复计数。"),
            ("已批准草稿", approved, f"已找到 {email_count} 条邮件路径、{form_count} 条联系/报价页路径；真实发送仍需确认。"),
            ("待负责人复核", pending_review, "先核对公司、需求信号和官方联系方式，再进入触达草稿。"),
            ("研究对象", research, "工具、平台或合作对象单独研究，不冒充直接买家。"),
            ("真实已外联", sent, "只认发送证据；复制草稿、打开邮箱或生成文案都不算已联系。"),
        ]
    )
    asset_links = [
        ("第一单冲刺", b2b_output_href(first_order_sprint.name) if first_order_sprint else ""),
        ("手动触达控制台", b2b_output_href(manual_send_console.name) if manual_send_console else ""),
        ("触达控制表", b2b_output_href(manual_send_console_csv.name) if manual_send_console_csv else ""),
        ("发出证据表", b2b_output_href(sent_evidence_log_template.name) if sent_evidence_log_template else ""),
        ("买家回复队列", b2b_output_href(reply_intake_queue_template.name) if reply_intake_queue_template else ""),
        ("报价/PI台账", b2b_output_href(quote_pi_workbench.name) if quote_pi_workbench else ""),
        ("报价/PI表", b2b_output_href(quote_pi_workbench_csv.name) if quote_pi_workbench_csv else ""),
        ("销售指挥台", b2b_output_href(command_page.name) if command_page else ""),
        ("样品申请页", b2b_output_href(sample_page.name) if sample_page else ""),
        ("首批发送确认单", b2b_output_href(send_confirmation_sheet.name) if send_confirmation_sheet else ""),
        ("当前发送状态表", b2b_output_href(current_send_status.name) if current_send_status else ""),
        ("人工发送日志", b2b_output_href(manual_send_log.name) if manual_send_log else ""),
        ("报价草稿日志", b2b_output_href(quote_draft_log.name) if quote_draft_log else ""),
        ("报价跟进任务", b2b_output_href(quote_followup_tasks.name) if quote_followup_tasks else ""),
        ("报价确认队列", b2b_output_href(quote_confirmation_queue.name) if quote_confirmation_queue else ""),
        ("客户回复记录", b2b_output_href(reply_intake_log.name) if reply_intake_log else ""),
        ("回复后下一步", b2b_output_href(reply_next_actions.name) if reply_next_actions else ""),
        ("发送后跟单", b2b_output_href(sent_followup_tasks.name) if sent_followup_tasks else ""),
        ("Top3成交包", b2b_output_href(top3_deal_pack.name) if top3_deal_pack else ""),
        ("Top3发送前检查", b2b_output_href(top3_send_preflight.name) if top3_send_preflight else ""),
        ("Top3硬信息", b2b_output_href(top3_deal_readiness.name) if top3_deal_readiness else ""),
        ("Top3成交前检查", b2b_output_href(top3_deal_readiness_csv.name) if top3_deal_readiness_csv else ""),
        ("Top3成交流水线", b2b_output_href(top3_close_ready.name) if top3_close_ready else ""),
        ("Top3成交检查表", b2b_output_href(top3_close_ready_csv.name) if top3_close_ready_csv else ""),
        ("Top3负责人确认", b2b_output_href(top3_owner_confirmation_queue.name) if top3_owner_confirmation_queue else ""),
        ("Top3触达执行包", b2b_output_href(top3_first_touch_execution.name) if top3_first_touch_execution else ""),
        ("Top3触达清单", b2b_output_href(top3_first_touch_execution_csv.name) if top3_first_touch_execution_csv else ""),
        ("Top3跟单节奏", b2b_output_href(top3_followup_cadence.name) if top3_followup_cadence else ""),
        ("Top3跟单表", b2b_output_href(top3_followup_cadence_csv.name) if top3_followup_cadence_csv else ""),
        ("产品 One-Pager", b2b_output_href(str(onepager.relative_to(root / "outputs"))) if onepager.exists() else ""),
        ("颜色卡", b2b_output_href(str(color_card.relative_to(root / "outputs"))) if color_card.exists() else ""),
        ("尺码表", b2b_output_href(str(size_chart.relative_to(root / "outputs"))) if size_chart.exists() else ""),
    ]
    primary_asset_labels = {
        "第一单冲刺",
        "手动触达控制台",
        "报价/PI台账",
        "样品申请页",
        "产品 One-Pager",
        "颜色卡",
        "尺码表",
    }
    primary_asset_html = "".join(
        f"<a class='button secondary' href='{html.escape(url)}' target='_blank'>{html.escape(label)}</a>"
        for label, url in asset_links
        if url and label in primary_asset_labels
    )
    supporting_asset_html = "".join(
        f"<a class='button secondary' href='{html.escape(url)}' target='_blank'>{html.escape(label)}</a>"
        for label, url in asset_links
        if url and label not in primary_asset_labels
    )
    asset_html = primary_asset_html
    if supporting_asset_html:
        asset_html += (
            "<details class='asset-more'><summary>展开全部销售资料</summary>"
            f"<div class='actions'>{supporting_asset_html}</div></details>"
        )
    table_rows: list[str] = []
    for row in rows[:20]:
        draft_url = b2b_output_href_from_path(root, row.get("draft_file") or "")
        draft_cell = (
            f"<a href='{html.escape(draft_url)}' target='_blank'>打开草稿</a>"
            if draft_url
            else "<span>待补草稿</span>"
        )
        table_rows.append(
            "<tr>"
            f"<td><strong>{html.escape(row.get('company') or '')}</strong><br><span>{html.escape(row.get('market') or '')}</span></td>"
            f"<td>{html.escape(b2b_10001_contact_display(row.get('contact_path') or ''))}<br><small>{html.escape(b2b_10001_send_channel_label(row.get('send_channel') or ''))}</small></td>"
            f"<td>{html.escape(row.get('subject') or '')}</td>"
            f"<td>{html.escape(b2b_10001_reply_status_label(row.get('reply_status') or ''))}<br><small>{html.escape(b2b_10001_next_action_label(row.get('next_action') or ''))}</small></td>"
            f"<td>{draft_cell}</td>"
            "</tr>"
        )
    row_html = "".join(table_rows)
    if not row_html:
        row_html = "<tr><td colspan='5'>还没有销售对象；先从 B2B 线索池生成 CRM 队列。</td></tr>"
    send_action_html = render_b2b_10001_send_action_cards(root, action_rows, limit=8)
    quote_aftercare_html = render_b2b_10001_quote_aftercare_preview(root)
    quote_templates_json = json.dumps(load_b2b_10001_quote_template_rows(root), ensure_ascii=False)
    reply_rules_json = json.dumps(b2b_10001_reply_rules(), ensure_ascii=False)
    pipeline_rows_json = json.dumps(rows, ensure_ascii=False)
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>B2B 获客/跟单工作台</title>
  <style>{simple_page_css()}
    main {{ padding: 22px 28px 42px; max-width: 1320px; margin: 0 auto; }}
    .grid {{ display:grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap:12px; }}
    .metric-card small {{ display:block; color:var(--muted); margin-top:8px; line-height:1.45; }}
    .actions {{ display:flex; flex-wrap:wrap; gap:10px; }}
    .asset-more {{ flex-basis:100%; border-top:1px solid var(--line); margin-top:4px; padding-top:10px; }}
    .asset-more summary {{ cursor:pointer; color:#047481; font-weight:800; margin-bottom:10px; }}
    .button {{ display:inline-block; border:1px solid var(--line); border-radius:8px; padding:9px 13px; background:#111318; color:#fff; text-decoration:none; font-weight:800; }}
    .button.secondary {{ background:#fff; color:var(--ink); }}
    .brief-grid {{ display:grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap:12px; }}
    .brief-card {{ border:1px solid #a7f3d0; background:#f0fdfa; border-radius:8px; padding:14px; color:var(--ink); text-decoration:none; }}
    .brief-card strong {{ display:block; margin-bottom:8px; }}
    .brief-card span {{ display:block; color:var(--muted); line-height:1.55; }}
    table {{ width:100%; border-collapse:collapse; background:#fff; border:1px solid var(--line); }}
    .table-scroll {{ width:100%; max-width:100%; overflow-x:auto; -webkit-overflow-scrolling:touch; }}
    .table-scroll table {{ min-width:760px; }}
    .sales-queue-panel {{ overflow:hidden; min-width:0; }}
    th, td {{ padding:10px; border-bottom:1px solid var(--line); text-align:left; vertical-align:top; font-size:13px; }}
    th {{ background:var(--soft); }}
    td span, td small {{ color:var(--muted); }}
    .warning {{ border:1px solid #f4d19b; background:#fff7ed; border-radius:8px; padding:12px 14px; color:#7c4a03; line-height:1.55; }}
    .send-grid {{ display:grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap:12px; }}
    .send-card {{ border:1px solid var(--line); border-radius:8px; background:#fff; padding:14px; }}
    .send-card-head {{ display:flex; justify-content:space-between; gap:10px; align-items:flex-start; margin-bottom:10px; }}
    .send-card-head span, .send-chip {{ border:1px solid #a7f3d0; background:#f0fdfa; color:#047481; border-radius:999px; padding:4px 8px; font-size:12px; font-weight:800; }}
    .send-card dl {{ display:grid; grid-template-columns:72px minmax(0,1fr); gap:6px 8px; margin:0 0 10px; }}
    .send-card dt {{ color:var(--muted); font-size:12px; }}
    .send-card dd {{ margin:0; word-break:break-word; font-size:13px; }}
    .send-card textarea {{ width:100%; min-height:190px; resize:vertical; border:1px solid var(--line); border-radius:8px; padding:10px; font-family:Arial, Helvetica, sans-serif; line-height:1.5; }}
    .send-actions {{ display:flex; flex-wrap:wrap; gap:8px; margin-top:10px; }}
    .send-actions button {{ border:1px solid var(--line); border-radius:8px; padding:8px 10px; background:#111318; color:#fff; font-weight:800; cursor:pointer; }}
    .send-status {{ margin-top:9px; color:var(--muted); font-size:12px; }}
    .send-status.done {{ color:#0f7b45; font-weight:800; }}
    .quote-tool {{ display:grid; grid-template-columns:minmax(280px, 0.8fr) minmax(320px, 1.2fr); gap:14px; align-items:start; min-width:0; }}
    .quote-form {{ display:grid; grid-template-columns:minmax(0, 1fr) minmax(0, 1fr); gap:10px; min-width:0; }}
    .quote-form label {{ display:grid; gap:5px; font-size:12px; color:var(--muted); font-weight:800; }}
    .quote-form input, .quote-form select {{ width:100%; max-width:100%; min-width:0; border:1px solid var(--line); border-radius:8px; padding:9px; font-size:13px; color:var(--ink); }}
    .quote-form .wide {{ grid-column:1 / -1; }}
    .quote-output {{ display:grid; gap:10px; min-width:0; }}
    .quote-output textarea {{ width:100%; max-width:100%; min-width:0; min-height:180px; resize:vertical; border:1px solid var(--line); border-radius:8px; padding:10px; font-family:Arial, Helvetica, sans-serif; line-height:1.5; }}
    .quote-summary {{ border:1px solid #a7f3d0; background:#f0fdfa; border-radius:8px; padding:12px; color:#047481; font-weight:800; }}
    .reply-tool {{ display:grid; grid-template-columns:minmax(280px, 0.85fr) minmax(320px, 1.15fr); gap:14px; align-items:start; min-width:0; }}
    .reply-form {{ display:grid; grid-template-columns:minmax(0, 1fr) minmax(0, 1fr); gap:10px; min-width:0; }}
    .reply-form label {{ display:grid; gap:5px; font-size:12px; color:var(--muted); font-weight:800; }}
    .reply-form input, .reply-form select, .reply-form textarea {{ width:100%; max-width:100%; min-width:0; border:1px solid var(--line); border-radius:8px; padding:9px; font-size:13px; color:var(--ink); }}
    .reply-form textarea {{ min-height:150px; resize:vertical; font-family:Arial, Helvetica, sans-serif; line-height:1.5; }}
    .reply-form .wide {{ grid-column:1 / -1; }}
    .reply-output {{ display:grid; gap:10px; min-width:0; }}
    .reply-output textarea {{ width:100%; max-width:100%; min-width:0; min-height:210px; resize:vertical; border:1px solid var(--line); border-radius:8px; padding:10px; font-family:Arial, Helvetica, sans-serif; line-height:1.5; }}
    .reply-summary {{ border:1px solid #bfdbfe; background:#eff6ff; border-radius:8px; padding:12px; color:#1d4ed8; line-height:1.55; }}
    .aftercare-grid {{ display:grid; grid-template-columns:repeat(auto-fit, minmax(320px, 1fr)); gap:12px; }}
    .aftercare-card {{ border:1px solid var(--line); border-radius:8px; background:#fff; padding:12px; overflow:auto; }}
    .aftercare-head {{ display:flex; justify-content:space-between; gap:10px; align-items:center; margin-bottom:10px; }}
    .aftercare-head a {{ color:#047481; font-weight:800; text-decoration:none; }}
    @media (max-width: 860px) {{
      main {{ padding-left:14px; padding-right:14px; min-width:0; }}
      .panel, .quote-tool, .reply-tool, .quote-form, .reply-form, .quote-output, .reply-output {{ min-width:0; max-width:100%; }}
      .quote-tool, .reply-tool {{ grid-template-columns:minmax(0, 1fr); }}
      .quote-form, .reply-form {{ grid-template-columns:minmax(0, 1fr); }}
    }}
  </style>
</head>
<body>
  <header>
    <h1>B2B 获客/跟单工作台</h1>
    <div class="muted">10001 230g 水洗 T 恤 · 找客户、建 CRM、样品包、批发询盘、报价、跟单和复购；真实外联、收款、发货仍进入确认队列。</div>
    <div class="actions" style="margin-top:14px;">
      <a class="button" href="/dashboard">返回今日工作台</a>
      <a class="button secondary" href="/store-erp">店铺ERP</a>
      <a class="button secondary" href="/chat?intent=approval">待确认动作</a>
    </div>
  </header>
  <main>
    <section class="panel">
      <h2>今天先推进成交</h2>
      <div class="grid">{metric_html}</div>
      <div class="warning" style="margin-top:12px;">边界：这里负责把客户、资料、样品话术、报价字段和跟单节奏准备好；不会绕过平台规则，不会批量发邮件/私信/WhatsApp，不会自动提交表单或付款。</div>
    </section>
    <section class="panel">
      <h2>可直接使用的销售资产</h2>
      <div class="actions">{asset_html}</div>
      <div class="muted" style="margin-top:10px;">样品申请页可用于客户查看资料和本地记录询盘；销售指挥台用于内部打开草稿、网站、联系人和下一步动作。</div>
    </section>
    <section class="panel">
      <h2>今天优先触达 / 跟单</h2>
      <div class="warning" style="margin-bottom:12px;">这里的按钮只复制文案、打开草稿或打开邮件客户端；不会自动发送。负责人完成外部发送后，点“外部发送后回写证据”并填写真实发送证据，系统才会入库和生成后续跟单。</div>
      <div class="send-grid">{send_action_html}</div>
    </section>
    <section class="panel">
      <h2>客户回复路由器</h2>
      <div class="warning" style="margin-bottom:12px;">把客户回复粘进来，系统只生成 CRM 阶段、下一步字段和可复制回复草稿；不会对外发送，也不会承诺付款、发货或最终报价。</div>
      <div class="reply-tool">
        <div class="reply-form">
          <label class="wide">关联客户<select id="replyPipeline" onchange="fillReplyFromLead()"><option value="">手动填写</option></select></label>
          <label>客户公司<input id="replyCompany" placeholder="T-Shirt Shop Dallas"></label>
          <label>联系人/邮箱<input id="replyContact" placeholder="buyer@example.com"></label>
          <label class="wide">回复类型<select id="replyType" onchange="generateReplyRoute()">
            <option value="auto_detect">自动判断</option>
          </select></label>
          <label class="wide">客户原话<textarea id="replyRaw" oninput="generateReplyRoute()" placeholder="粘贴客户邮件/表单/WhatsApp 回复。比如：What is your MOQ and price for 24 pcs to Dallas?"></textarea></label>
          <div class="actions wide">
            <button type="button" onclick="generateReplyRoute()">生成下一步</button>
            <button type="button" onclick="saveReplyIntake()">保存回复记录</button>
          </div>
        </div>
        <div class="reply-output">
          <div class="reply-summary" id="replySummary">粘贴客户回复后，系统会判断阶段、下一步和需要补齐的字段。</div>
          <textarea id="replyDraft" readonly placeholder="下一封回复草稿会出现在这里"></textarea>
          <div class="actions">
            <button type="button" onclick="copyQuote('replyDraft')">复制回复草稿</button>
            <button type="button" onclick="copyReplyFields()">复制需补字段</button>
            <button type="button" onclick="sendReplyToQuote()">带入报价/PI</button>
          </div>
          <div class="send-status" id="replySaveStatus">未保存回复记录。</div>
        </div>
      </div>
    </section>
    <section class="panel">
      <h2>客户一回复，马上生成报价 / PI 草稿</h2>
      <div class="warning" style="margin-bottom:12px;">这里生成的是草稿：报价、PI、付款方式、发货承诺都必须负责人复核后才能对外发送。</div>
      <div class="quote-tool">
        <div class="quote-form">
          <label class="wide">关联客户<select id="quotePipeline" onchange="fillQuoteFromLead()"><option value="">手动填写</option></select></label>
          <label>客户公司<input id="quoteCompany" placeholder="T-Shirt Shop Dallas"></label>
          <label>邮箱<input id="quoteEmail" placeholder="orders@example.com"></label>
          <label>国家/市场<input id="quoteMarket" placeholder="US"></label>
          <label>城市/邮编<input id="quoteCity" placeholder="Dallas TX / 75201"></label>
          <label>样品/订单类型<select id="quoteRequestType" onchange="suggestQuote()">
            <option>3pc review pack</option>
            <option>6pc print test pack</option>
            <option>24pc pilot order</option>
            <option>100pc wholesale trial</option>
          </select></label>
          <label>数量<input id="quoteQuantity" type="number" min="1" value="3" oninput="suggestQuote(); updateQuoteProfit()"></label>
          <label>颜色<input id="quoteColors" placeholder="Black / Gray / Coffee"></label>
          <label>尺码<input id="quoteSizes" placeholder="M / L / XL"></label>
          <label>印花方式<input id="quotePrintMethod" placeholder="blank only / DTF / DTG / screen print"></label>
          <label>贸易/配送条款<input id="quoteTerms" placeholder="DAP / DDP / buyer handles import"></label>
          <label>建议报价USD<input id="quoteTotal" placeholder="39" oninput="updateQuoteProfit()"></label>
          <label>单件成本USD<input id="quoteUnitCost" type="number" step="0.01" min="0" value="4.80" oninput="updateQuoteProfit()"></label>
          <label>包装/处理USD<input id="quotePackagingCost" type="number" step="0.01" min="0" value="3.00" oninput="updateQuoteProfit()"></label>
          <label>预估运费USD<input id="quoteFreightCost" type="number" step="0.01" min="0" value="24.00" oninput="updateQuoteProfit()"></label>
          <label>支付费率%<input id="quotePaymentFeeRate" type="number" step="0.1" min="0" value="3.5" oninput="updateQuoteProfit()"></label>
          <label>目标毛利%<input id="quoteTargetMargin" type="number" step="1" min="0" value="30" oninput="updateQuoteProfit()"></label>
          <label>下次跟进日期<input id="quoteFollowUpDate" type="date"></label>
          <div class="actions wide">
            <button type="button" onclick="generateQuoteDraft()">生成报价和 PI 草稿</button>
            <button type="button" onclick="saveQuoteDraft()">保存报价草稿</button>
          </div>
        </div>
        <div class="quote-output">
          <div class="quote-summary" id="quoteSummary">选择客户和样品类型后生成报价草稿。</div>
          <div class="quote-summary" id="quoteProfitSummary">利润草稿：等待数量、报价、成本和运费。</div>
          <textarea id="quoteReply" readonly placeholder="客户回复报价话术会出现在这里"></textarea>
          <textarea id="quotePI" readonly placeholder="PI 草稿会出现在这里"></textarea>
          <div class="actions">
            <button type="button" onclick="copyQuote('quoteReply')">复制回复</button>
            <button type="button" onclick="copyQuote('quotePI')">复制 PI 草稿</button>
          </div>
          <div class="send-status" id="quoteSaveStatus">未保存报价草稿。</div>
        </div>
      </div>
    </section>
    <section class="panel">
      <h2>报价保存后自动承接</h2>
      <div class="warning" style="margin-bottom:12px;">保存报价草稿后，系统会生成内部跟进任务和负责人确认项；不会自动给客户发邮件、收款、下单或发货。</div>
      {quote_aftercare_html}
    </section>
    <section class="panel sales-queue-panel">
      <h2>首批销售队列</h2>
      <div class="table-scroll" role="region" aria-label="首批销售队列，可横向滚动">
        <table>
          <thead><tr><th>客户</th><th>联系路径</th><th>首触主题</th><th>状态 / 下一步</th><th>资料</th></tr></thead>
          <tbody>{row_html}</tbody>
        </table>
      </div>
    </section>
    <section class="panel">
      <h2>下一步</h2>
      <div class="brief-grid">
        <a class="brief-card" href="{html.escape(b2b_output_href(sample_page.name) if sample_page else '#')}" target="_blank"><strong>收样品询盘</strong><span>让客户先选 3 件/6 件/24 件样品包，记录尺码、颜色、目的地和交期。</span></a>
        <a class="brief-card" href="/chat?intent=approval"><strong>整理确认队列</strong><span>把允许发送的邮件、报价、样品费、付款链接、发货动作逐项进入负责人确认。</span></a>
        <a class="brief-card" href="/store-erp"><strong>回写订单和利润</strong><span>成交后把样品费、成本、运费、回款、复购节点写回 ERP，不和 Amazon 单件 $20 混用。</span></a>
      </div>
    </section>
  </main>
  {render_floating_ai_widget()}
  <script>
    const quoteTemplates = {quote_templates_json};
    const replyRules = {reply_rules_json};
    const pipelineRows = {pipeline_rows_json};
    const replyStageLabels = {{
      interested_sample: '有兴趣，推进样品',
      quote_request: '已提出报价需求',
      not_fit_now: '当前不匹配，停止强推',
      needs_owner_review: '待负责人判断'
    }};
    const replyNextActionLabels = {{
      send_color_size_sheet_and_sample_options: '发送颜色尺码表，并确认样品包方案',
      collect_quantity_city_blank_or_print_before_final_quote: '补齐数量、收货城市和空白衫/印花需求后报价',
      send_10001_product_sheet_and_ask_test_colors: '发送 10001 产品表，并确认首批测试颜色',
      move_to_3pc_6pc_sample_or_24pc_pilot: '推进 3 件/6 件样品包或 24 件试单',
      close_or_permission_based_future_followup: '结束当前跟进；获得允许后再联系',
      offer_comparison_sample_only_if_useful: '仅在客户需要时提供对比样品',
      collect_private_label_requirements_before_factory_check: '先收集私标要求，再向工厂核实',
      owner_reads_reply_and_selects_reply_type: '负责人阅读完整回复并选择类型'
    }};
    const replyRequiredFieldLabels = {{
      'delivery country/city; 3pc or 6pc sample preference; preferred colors/sizes; print method if any': '收货国家/城市；3 件或 6 件样品偏好；颜色/尺码；印花方式',
      'quantity; delivery city; colors/sizes; blank-only or print/private-label support': '数量；收货城市；颜色/尺码；空白衫、印花或私标需求',
      'colors they want to review first; size range; customer segment': '首批测试颜色；尺码范围；客户群体',
      'preferred test quantity; sample purpose; delivery country/city': '测试数量；样品用途；收货国家/城市',
      'no required fields; avoid pushing': '无需补字段；停止强推',
      'whether they review comparison blanks; priority fabric/price/print concern': '是否愿意对比空白衫；面料、价格或印花的优先问题',
      'label type; estimated quantity; target country; blank-only or printed': '标签类型；预计数量；目标国家；空白衫或印花需求',
      'paste complete reply; choose reply type before sending externally': '粘贴完整回复；对外发送前由负责人选择类型'
    }};
    function replyStageLabel(value) {{ return replyStageLabels[value] || '待负责人复核'; }}
    function replyNextActionLabel(value) {{ return replyNextActionLabels[value] || '负责人查看回复并确定下一步'; }}
    function replyRequiredFieldsLabel(value) {{ return replyRequiredFieldLabels[value] || '按客户回复补齐必要信息'; }}
    function normalizeText(value) {{ return String(value || '').trim().toLowerCase(); }}
    function initReplyPipeline() {{
      const select = document.getElementById('replyPipeline');
      if (!select) return;
      pipelineRows.forEach(row => {{
        const opt = document.createElement('option');
        opt.value = row.pipeline_id || '';
        opt.textContent = (row.pipeline_id || '') + ' · ' + (row.company || '');
        select.appendChild(opt);
      }});
    }}
    function initReplyTypes() {{
      const select = document.getElementById('replyType');
      if (!select) return;
      replyRules.forEach(rule => {{
        if (rule.reply_type === 'unclear') return;
        const opt = document.createElement('option');
        opt.value = rule.reply_type || '';
        opt.textContent = rule.label || rule.reply_type || '';
        select.appendChild(opt);
      }});
    }}
    function fillReplyFromLead() {{
      const id = document.getElementById('replyPipeline').value;
      const row = pipelineRows.find(item => item.pipeline_id === id);
      if (!row) return;
      document.getElementById('replyCompany').value = row.company || '';
      document.getElementById('replyContact').value = row.contact_path || '';
      generateReplyRoute();
    }}
    function findReplyRule() {{
      const selected = document.getElementById('replyType').value;
      if (selected && selected !== 'auto_detect') {{
        return replyRules.find(rule => rule.reply_type === selected) || replyRules.find(rule => rule.reply_type === 'unclear') || {{}};
      }}
      const raw = normalizeText(document.getElementById('replyRaw').value);
      for (const rule of replyRules) {{
        const words = rule.keywords || [];
        for (const word of words) {{
          if (raw.includes(normalizeText(word))) return rule;
        }}
      }}
      return replyRules.find(rule => rule.reply_type === 'unclear') || replyRules[0] || {{}};
    }}
    function replyPayload(rule) {{
      const selectedRule = rule || findReplyRule();
      const lead = pipelineRows.find(item => item.pipeline_id === document.getElementById('replyPipeline').value) || {{}};
      return {{
        pipeline_id: document.getElementById('replyPipeline').value,
        company: document.getElementById('replyCompany').value || lead.company || '',
        contact: document.getElementById('replyContact').value || lead.contact_path || '',
        market: lead.market || '',
        reply_type: selectedRule.reply_type || 'unclear',
        raw_reply: document.getElementById('replyRaw').value || '',
        crm_stage: selectedRule.crm_stage || 'needs_owner_review',
        next_action: selectedRule.next_action || 'owner_reads_reply_and_selects_reply_type',
        required_fields: selectedRule.required_fields || '',
        reply_draft: selectedRule.reply_draft || ''
      }};
    }}
    function generateReplyRoute() {{
      const rule = findReplyRule();
      const p = replyPayload(rule);
      const summary = document.getElementById('replySummary');
      if (summary) {{
        summary.innerHTML = [
          '<strong>识别：</strong>' + (rule.label || p.reply_type || '需要人工判断'),
          '<strong>CRM阶段：</strong>' + replyStageLabel(p.crm_stage),
          '<strong>下一步：</strong>' + replyNextActionLabel(p.next_action),
          '<strong>需补字段：</strong>' + replyRequiredFieldsLabel(p.required_fields)
        ].join('<br>');
      }}
      const draft = document.getElementById('replyDraft');
      if (draft) draft.value = p.reply_draft || '';
      const status = document.getElementById('replySaveStatus');
      if (status) {{
        status.className = 'send-status';
        status.textContent = '已生成待复核回复草稿，尚未保存。';
      }}
    }}
    function copyReplyFields() {{
      const rule = findReplyRule();
      const text = [
        'CRM阶段：' + replyStageLabel(rule.crm_stage),
        '下一步：' + replyNextActionLabel(rule.next_action),
        '需补字段：' + replyRequiredFieldsLabel(rule.required_fields)
      ].join('\\n');
      navigator.clipboard.writeText(text);
    }}
    async function saveReplyIntake() {{
      generateReplyRoute();
      const status = document.getElementById('replySaveStatus');
      try {{
        const res = await fetch('/api/b2b/10001/reply-intake', {{
          method: 'POST',
          headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify(replyPayload())
        }});
        const data = await res.json();
        if (!res.ok || !data.ok) throw new Error(data.error || '保存失败');
        if (status) {{
          status.className = 'send-status done';
          status.textContent = '已保存回复记录：' + (data.crm_stage || 'draft_owner_review') + '；对外回复前仍需负责人确认。';
        }}
      }} catch (e) {{
        if (status) {{
          status.className = 'send-status';
          status.textContent = '保存失败：' + (e && e.message ? e.message : e);
        }}
      }}
    }}
    function parseReplyQuantity(raw) {{
      const match = String(raw || '').match(/(\\d{{1,5}})\\s*(pcs|pieces|pc|shirts|tees|件|个)?/i);
      return match ? match[1] : '';
    }}
    function parseReplyCity(raw) {{
      const text = String(raw || '');
      const toMatch = text.match(/\\bto\\s+([A-Za-z][A-Za-z\\s.-]{{1,40}})(?:[?.!,;]|$)/i);
      if (toMatch) return toMatch[1].trim();
      const inMatch = text.match(/\\bin\\s+([A-Za-z][A-Za-z\\s.-]{{1,40}})(?:[?.!,;]|$)/i);
      return inMatch ? inMatch[1].trim() : '';
    }}
    function parseReplyColors(raw) {{
      const colorWords = ['black', 'gray', 'grey', 'coffee', 'beige', 'orange', 'rose red', 'purple', 'blue', 'green', 'olive', 'army green'];
      const text = normalizeText(raw);
      const found = colorWords.filter(color => text.includes(color));
      return found.join(' / ');
    }}
    function parseReplySizes(raw) {{
      const text = String(raw || '').toUpperCase();
      const found = [];
      for (const size of ['S', 'M', 'L', 'XL', '2XL', '3XL', '4XL', '5XL']) {{
        const pattern = new RegExp('(^|[^A-Z0-9])' + size.replace('XL', 'XL') + '([^A-Z0-9]|$)');
        if (pattern.test(text) && !found.includes(size)) found.push(size);
      }}
      return found.join(' / ');
    }}
    function requestTypeForQuantity(quantity) {{
      const qty = Number(quantity || 0);
      if (qty >= 100) return '100pc wholesale trial';
      if (qty >= 24) return '24pc pilot order';
      if (qty >= 6) return '6pc print test pack';
      return '3pc review pack';
    }}
    function sendReplyToQuote() {{
      generateReplyRoute();
      const raw = document.getElementById('replyRaw').value || '';
      const quantity = parseReplyQuantity(raw);
      const leadId = document.getElementById('replyPipeline').value || '';
      document.getElementById('quotePipeline').value = leadId;
      fillQuoteFromLead();
      document.getElementById('quoteCompany').value = document.getElementById('replyCompany').value || document.getElementById('quoteCompany').value;
      const contact = document.getElementById('replyContact').value || '';
      if (contact.includes('@')) document.getElementById('quoteEmail').value = contact;
      if (quantity) {{
        document.getElementById('quoteQuantity').value = quantity;
        document.getElementById('quoteRequestType').value = requestTypeForQuantity(quantity);
      }}
      const city = parseReplyCity(raw);
      if (city) document.getElementById('quoteCity').value = city;
      const colors = parseReplyColors(raw);
      if (colors) document.getElementById('quoteColors').value = colors;
      const sizes = parseReplySizes(raw);
      if (sizes) document.getElementById('quoteSizes').value = sizes;
      if (!document.getElementById('quotePrintMethod').value) {{
        document.getElementById('quotePrintMethod').value = raw.toLowerCase().includes('print') ? 'print support / TBD' : 'blank only / TBD';
      }}
      document.getElementById('quoteTotal').value = '';
      suggestQuote();
      generateQuoteDraft();
      const quotePanel = document.getElementById('quotePipeline');
      if (quotePanel) quotePanel.scrollIntoView({{ behavior: 'smooth', block: 'center' }});
    }}
    function initQuotePipeline() {{
      const select = document.getElementById('quotePipeline');
      if (!select) return;
      pipelineRows.forEach(row => {{
        const opt = document.createElement('option');
        opt.value = row.pipeline_id || '';
        opt.textContent = (row.pipeline_id || '') + ' · ' + (row.company || '');
        select.appendChild(opt);
      }});
    }}
    function fillQuoteFromLead() {{
      const id = document.getElementById('quotePipeline').value;
      const row = pipelineRows.find(item => item.pipeline_id === id);
      if (!row) return;
      document.getElementById('quoteCompany').value = row.company || '';
      document.getElementById('quoteEmail').value = (row.contact_path || '').includes('@') ? row.contact_path : '';
      document.getElementById('quoteMarket').value = row.market || 'US';
      suggestQuote();
    }}
    function findQuoteTemplate() {{
      const market = normalizeText(document.getElementById('quoteMarket').value || 'US');
      const requestType = normalizeText(document.getElementById('quoteRequestType').value);
      return quoteTemplates.find(row => normalizeText(row.market) === market && normalizeText(row.request_type) === requestType)
        || quoteTemplates.find(row => normalizeText(row.market) === market)
        || quoteTemplates[0] || {{}};
    }}
    function suggestQuote() {{
      const template = findQuoteTemplate();
      if (template.minimum_safe_quote_usd && !document.getElementById('quoteTotal').value) {{
        document.getElementById('quoteTotal').value = template.minimum_safe_quote_usd;
      }}
      const summary = document.getElementById('quoteSummary');
      if (summary) {{
        summary.textContent = '建议：' + (template.quote_id || 'quote draft') + '，最低安全草稿价 $' + (template.minimum_safe_quote_usd || document.getElementById('quoteTotal').value || 'TBD') + '；发送前必须复核运费、库存、税费和付款方式。';
      }}
      updateQuoteProfit();
    }}
    function numValue(id) {{
      const el = document.getElementById(id);
      const value = Number((el && el.value) || 0);
      return Number.isFinite(value) && value > 0 ? value : 0;
    }}
    function quoteProfitValues() {{
      const quantity = numValue('quoteQuantity');
      const total = numValue('quoteTotal');
      const unitCost = numValue('quoteUnitCost');
      const packaging = numValue('quotePackagingCost');
      const freight = numValue('quoteFreightCost');
      const feeRate = numValue('quotePaymentFeeRate');
      const targetMargin = numValue('quoteTargetMargin');
      const productionCost = unitCost * quantity;
      const paymentFee = total * feeRate / 100;
      const totalCost = productionCost + packaging + freight + paymentFee;
      const netProfit = total - totalCost;
      const margin = total ? (netProfit / total * 100) : 0;
      const status = (!quantity || !total || !unitCost)
        ? 'needs_cost_inputs'
        : (targetMargin && margin < targetMargin ? 'below_target_margin' : 'profit_draft_review');
      return {{ quantity, total, unitCost, packaging, freight, feeRate, targetMargin, productionCost, paymentFee, totalCost, netProfit, margin, status }};
    }}
    function updateQuoteProfit() {{
      const p = quoteProfitValues();
      const summary = document.getElementById('quoteProfitSummary');
      if (!summary) return p;
      const statusText = p.status === 'below_target_margin'
        ? '低于目标毛利，发送前必须调价/改运费/改数量'
        : (p.status === 'profit_draft_review' ? '利润草稿可复核' : '还缺成本或报价');
      summary.textContent = '利润草稿：收入 $' + p.total.toFixed(2)
        + '，产品成本 $' + p.productionCost.toFixed(2)
        + '，包装 $' + p.packaging.toFixed(2)
        + '，运费 $' + p.freight.toFixed(2)
        + '，支付费 $' + p.paymentFee.toFixed(2)
        + '，预估净利 $' + p.netProfit.toFixed(2)
        + '，毛利 ' + p.margin.toFixed(1) + '%；状态：' + statusText + '。';
      summary.style.borderColor = p.status === 'below_target_margin' ? '#f4d19b' : '#a7f3d0';
      summary.style.background = p.status === 'below_target_margin' ? '#fff7ed' : '#f0fdfa';
      summary.style.color = p.status === 'below_target_margin' ? '#7c4a03' : '#047481';
      return p;
    }}
    function quotePayload() {{
      const profit = quoteProfitValues();
      return {{
        pipeline_id: document.getElementById('quotePipeline').value,
        buyer_company: document.getElementById('quoteCompany').value,
        buyer_email: document.getElementById('quoteEmail').value,
        market: document.getElementById('quoteMarket').value,
        city_or_postcode: document.getElementById('quoteCity').value,
        request_type: document.getElementById('quoteRequestType').value,
        quantity: document.getElementById('quoteQuantity').value,
        preferred_colors: document.getElementById('quoteColors').value,
        preferred_sizes: document.getElementById('quoteSizes').value,
        print_method: document.getElementById('quotePrintMethod').value,
        delivery_terms: document.getElementById('quoteTerms').value,
        quote_total_usd: document.getElementById('quoteTotal').value,
        unit_cost_usd: document.getElementById('quoteUnitCost').value,
        packaging_cost_usd: document.getElementById('quotePackagingCost').value,
        freight_cost_usd: document.getElementById('quoteFreightCost').value,
        payment_fee_rate: document.getElementById('quotePaymentFeeRate').value,
        target_margin_rate: document.getElementById('quoteTargetMargin').value,
        estimated_net_profit_usd: profit.netProfit.toFixed(2),
        estimated_margin_rate: profit.margin.toFixed(2),
        profit_status: profit.status,
        follow_up_date: document.getElementById('quoteFollowUpDate').value,
        follow_up_note: 'follow up after buyer reviews sample quote; no external send by system'
      }};
    }}
    function generateQuoteDraft() {{
      suggestQuote();
      const p = quotePayload();
      const profit = quoteProfitValues();
      const total = p.quote_total_usd || 'TBD';
      const colorSize = [p.preferred_colors || 'TBD colors', p.preferred_sizes || 'TBD sizes'].join(' / ');
      const profitLine = 'Internal draft check: estimated net profit USD ' + profit.netProfit.toFixed(2) + ', margin ' + profit.margin.toFixed(1) + '%. Do not send externally until stock, freight, duties/taxes, payment route, and owner review are confirmed.';
      document.getElementById('quoteReply').value = [
        'Hi,',
        '',
        'Thanks. Based on ' + (p.request_type || 'your sample request') + ' for ' + (p.quantity || 'TBD') + ' pcs to ' + (p.city_or_postcode || p.market || 'your city') + ', the current draft sample quote is USD ' + total + '.',
        '',
        'This is still subject to final freight, stock, delivery terms, and payment confirmation. The suggested mix is ' + colorSize + '. If this works, I can prepare the final proforma for owner review.',
        '',
        'Best,',
        'TeeLab'
      ].join('\\n');
      document.getElementById('quotePI').value = [
        'TeeLab 10001 Sample Order Proforma Draft',
        '',
        'Status: draft only, not an issued invoice.',
        '',
        'Buyer: ' + (p.buyer_company || 'TBD'),
        'Email: ' + (p.buyer_email || 'TBD'),
        'Country / City: ' + (p.market || 'TBD') + ' / ' + (p.city_or_postcode || 'TBD'),
        '',
        'Item: 230g vintage-washed 100% cotton T-shirt sample pack',
        'Quantity: ' + (p.quantity || 'TBD'),
        'Color / Size Mix: ' + colorSize,
        'Print Method: ' + (p.print_method || 'blank review / TBD'),
        'Draft Total: USD ' + total,
        'Delivery Terms: ' + (p.delivery_terms || 'TBD'),
        '',
        profitLine,
        '',
        'Before sending final PI:',
        '1. confirm exact stock by color and size',
        '2. confirm freight and delivery time',
        '3. confirm duties/taxes responsibility',
        '4. confirm payment route',
        '5. owner approves external send'
      ].join('\\n');
      document.getElementById('quoteSaveStatus').textContent = '已生成草稿，尚未保存。';
    }}
    async function saveQuoteDraft() {{
      generateQuoteDraft();
      const status = document.getElementById('quoteSaveStatus');
      try {{
        const res = await fetch('/api/b2b/10001/quote-draft', {{
          method: 'POST',
          headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify(quotePayload())
        }});
        const data = await res.json();
        if (!res.ok || !data.ok) throw new Error(data.error || '保存失败');
        status.className = 'send-status done';
        status.textContent = '已保存报价草稿：' + (data.quote_status || 'draft_owner_review')
          + '；预估净利 $' + (data.estimated_net_profit_usd || 'TBD')
          + '，毛利 ' + (data.estimated_margin_rate || 'TBD') + '%'
          + '，状态 ' + (data.profit_status || 'profit_draft_review')
          + '；跟进日 ' + (data.follow_up_date || 'TBD')
          + '；已进入确认队列 ' + (data.confirmation_id || '')
          + '；对外发送前仍需负责人确认。';
      }} catch (e) {{
        status.className = 'send-status';
        status.textContent = '保存失败：' + (e && e.message ? e.message : e);
      }}
    }}
    function copyQuote(id) {{
      const el = document.getElementById(id);
      if (!el) return;
      navigator.clipboard.writeText(el.value || '');
    }}
    function copyDraft(id) {{
      const el = document.getElementById('draft-' + id);
      if (!el) return;
      navigator.clipboard.writeText(el.value || '').then(() => {{
        const status = document.getElementById('status-' + id);
        if (status) status.textContent = '已复制正文：请人工检查收件人和主题后再发送。';
      }});
    }}
    async function markSent(id, company, button) {{
      const proof = window.prompt('只在你已经人工发送后回写。请填写发送证据：发送邮箱/渠道 + 时间 + 简短证明。');
      if (!proof || proof.trim().length < 8) {{
        const status = document.getElementById('status-' + id);
        if (status) status.textContent = '已取消回写：需要先填写人工发送证据。';
        return;
      }}
      if (button) button.disabled = true;
      const now = new Date().toISOString();
      let saved = false;
      let responseText = '';
      try {{
        const res = await fetch('/api/b2b/10001/manual-send', {{
          method: 'POST',
          headers: {{ 'Content-Type': 'application/json' }},
          body: JSON.stringify({{ pipeline_id: id, company, manual_sent_at: now, source: 'b2b-sales-local', note: proof.trim() }})
        }});
        const data = await res.json();
        if (!res.ok || !data.ok) throw new Error(data.error || '服务器回写失败');
        saved = true;
        responseText = '已写入服务器日志：' + (data.reply_status || 'sent_pending_reply');
      }} catch (e) {{
        responseText = '服务器回写失败：' + (e && e.message ? e.message : e);
      }} finally {{
        if (button) button.disabled = false;
      }}
      const key = 'b2b_10001_manual_sent';
      const raw = localStorage.getItem(key) || '[]';
      let rows = [];
      try {{ rows = JSON.parse(raw); }} catch (e) {{ rows = []; }}
      rows = rows.filter(item => item && item.pipeline_id !== id);
      rows.push({{ pipeline_id: id, company, manual_sent_at: now, source: 'b2b-sales-local', server_saved: saved, proof: proof.trim() }});
      localStorage.setItem(key, JSON.stringify(rows));
      const status = document.getElementById('status-' + id);
      if (status && saved) {{
        status.className = 'send-status done';
        status.textContent = responseText + '；下一步等回复或回写 CRM。';
      }} else if (status) {{
        status.className = 'send-status';
        status.textContent = responseText + '；本机已暂存，请稍后重试服务器回写。';
      }}
    }}
    (function restoreSentMarks() {{
      let rows = [];
      try {{ rows = JSON.parse(localStorage.getItem('b2b_10001_manual_sent') || '[]'); }} catch (e) {{ rows = []; }}
      rows.forEach(item => {{
        const status = document.getElementById('status-' + item.pipeline_id);
        if (status) {{
          status.className = 'send-status done';
          status.textContent = '本机记录：已人工发送，时间 ' + (item.manual_sent_at || '');
        }}
      }});
    }})();
    initReplyPipeline();
    initReplyTypes();
    generateReplyRoute();
    initQuotePipeline();
    suggestQuote();
  </script>
</body>
</html>"""


def latest_learning_workbook(root: Path) -> Path | None:
    return newest_output_file(root, "learning_case_workbook_*.csv")


def render_learning_workbook_preview(path: Path | None, limit: int = 12) -> str:
    if not path or not path.exists():
        return (
            "<div class='empty-state'>还没有知识整理表。点击“立即学习一次”后，系统会把案例整理成问题、答案、步骤、风险和下一步。</div>"
        )
    rows: list[dict[str, str]] = []
    try:
        with path.open("r", encoding="utf-8-sig", newline="") as handle:
            reader = csv.DictReader(handle)
            for row in reader:
                rows.append({str(k): str(v or "") for k, v in row.items()})
                if len(rows) >= limit:
                    break
    except Exception as exc:  # noqa: BLE001 - admin preview should fail softly.
        return f"<div class='empty-state'>知识整理表读取失败：{html.escape(str(exc))}</div>"
    if not rows:
        return "<div class='empty-state'>知识整理表目前为空。先添加学习源或导入案例，再重新学习。</div>"
    columns = [
        ("知识分类", "分类"),
        ("问题/要点", "问题 / 要点"),
        ("来源", "来源"),
        ("可信度", "可信度"),
        ("答案/结论", "答案 / 结论"),
        ("可执行步骤", "可执行步骤"),
        ("风险提示", "风险"),
        ("下一步", "下一步"),
        ("是否需要人工确认", "确认"),
    ]
    body = []
    for row in rows:
        body.append(
            "<tr>"
            + "".join(
                f"<td>{html.escape(row.get(key, ''))}</td>"
                for key, _label in columns
            )
            + "</tr>"
        )
    header = "".join(f"<th>{html.escape(label)}</th>" for _key, label in columns)
    return (
        "<div class='table-wrap'>"
        f"<table class='workbook-table'><thead><tr>{header}</tr></thead><tbody>{''.join(body)}</tbody></table>"
        "</div>"
        f"<div class='muted'>只预览前 {len(rows)} 条；完整 CSV：{html.escape(str(path))}</div>"
    )


def load_dashboard_report_preview(root: Path) -> tuple[str, Path]:
    """Use the latest saved report for page load; explicit buttons regenerate."""
    today = date.today().isoformat()
    for pattern in (
        f"daily_report*{today}*.md",
        f"autonomous_run*{today}*.md",
        "daily_report*.md",
        "autonomous_run*.md",
    ):
        path = newest_output_file(root, pattern)
        if path and path.exists():
            return path.read_text(encoding="utf-8", errors="replace"), path
    output_dir = root / "outputs"
    output_dir.mkdir(parents=True, exist_ok=True)
    path = output_dir / f"dashboard_report_placeholder_{today}.md"
    if not path.exists():
        path.write_text(
            "# 今日AI报告\n\n后台 AI 还在生成今日报告：系统会自动整理监控对象、店铺数据和待确认草稿；客户先看工作台状态。",
            encoding="utf-8",
        )
    return path.read_text(encoding="utf-8", errors="replace"), path


def safe_output_report_path(root: Path, filename: str) -> Path:
    clean = Path(filename).name
    if not clean.endswith(".md"):
        raise ValueError("只能打开 outputs 里的 Markdown 报告。")
    output_dir = (root / "outputs").resolve()
    path = (output_dir / clean).resolve()
    if output_dir not in path.parents or not path.exists():
        raise ValueError("找不到这份报告。")
    return path


def public_report_reference(path: Path) -> str:
    digest = hashlib.sha1(path.name.encode("utf-8")).hexdigest()[:10].upper()
    return f"RPT-{digest}"


def public_report_url(path: Path) -> str:
    return "/report-file?" + urlencode({"id": public_report_reference(path)})


def render_dashboard_report_summary(
    *,
    report_content: str,
    report_path: Path,
    pending_count: int,
    target_count: int,
    content_count: int,
    ranking_count: int,
    store_count: int,
    top_products: list[str] | None = None,
    report_link: str | None = None,
) -> str:
    safe_content = sanitize_public_report_content(report_content)
    verdict = extract_report_verdict(safe_content)
    if is_count_only_verdict(verdict):
        if target_count <= 0:
            if top_products:
                verdict = "已有历史候选商品，后台 AI 正在自动建立重点监控对象并聚焦证据。"
            else:
                verdict = "还没有稳定商品结论；后台 AI 会持续从候选、榜单和店铺商品里挑重点出短报告。"
        elif content_count <= 0:
            verdict = "商品已设置，但 TK 视频和达人证据不足。后台 AI 等待视频素材证据。"
        else:
            verdict = "已有商品和内容线索，先看报告结论，再处理少量待确认动作。"
    verdict = customer_visible_report_gap_text(verdict)
    action_lines = [
        customer_visible_report_action_text(line)
        for line in extract_report_action_lines(safe_content)
        if is_public_report_action_line(line)
    ][:3]
    if not action_lines:
        action_lines = [
            "后台 AI 自动建立监控对象并生成商品报告；报告按证据强弱排序。",
            "后台 AI 优先等待 TK 视频脚本、达人证据、评论痛点和价格区间。",
            "上架、改价、投流、退款和发货只生成草稿并进入高风险确认。",
        ]
    action_html = "".join(f"<li>{html.escape(line)}</li>" for line in action_lines)
    if target_count <= 0:
        judgement = (
            "已有历史候选可由后台先复核；AI 会自动生成重点监控对象并按证据强弱排序。"
            if top_products
            else "暂时不能下判断；后台 AI 会先从候选、榜单、店铺商品和同行线索里建初筛并自动排序。"
        )
        missing_items = ["AI重点商品初筛", "TK 视频/达人证据", "商品卡/价格/评论", "店铺经营数据"]
    elif content_count <= 0:
        judgement = "不能下预算。商品已设置，但缺 TK 视频、达人和脚本打法。"
        missing_items = ["TK 视频钩子", "达人类型", "商品卡承接", "评论购买理由"]
    elif ranking_count <= 0:
        judgement = "只能初步判断。已有内容线索，但缺商品卡、榜单、价格和竞品证据。"
        missing_items = ["商品卡链接", "平台榜单", "价格带", "竞品评论"]
    elif store_count <= 0:
        judgement = "可以做选品判断，但不能算回本周期。还缺真实订单、广告、退款和财务数据。"
        missing_items = ["订单", "广告花费", "退款退货", "结算报表"]
    else:
        judgement = "可以进入测品准备。真实上架、改价、投流、退款和发货仍要人工确认。"
        missing_items = ["老板确认动作"] if pending_count else ["继续观察 ROI 和退款"]
    product_items = [clip_text(item, 58) for item in (top_products or []) if item][:3]
    product_note = ""
    if product_items:
        prefix = "后台优先复核：" if target_count <= 0 else "优先复核："
        product_note = f"<p>{prefix}" + "、".join(html.escape(item) for item in product_items) + "</p>"
    missing_html = "".join(f"<li>{html.escape(item)}</li>" for item in missing_items)
    report_link = public_report_url(report_path) if report_link is None else report_link
    report_link_html = (
        f"<p><a href='{html.escape(report_link)}'>查看运营简报</a></p>"
        if report_link
        else "<p class='muted'>当前为子账号授权范围摘要；全局运营简报由主账号查看。</p>"
    )
    return (
        "<div class='report-summary'>"
        "<div class='report-summary-card'>"
        "<strong>老板结论</strong>"
        f"<p>{html.escape(verdict)}</p>"
        "</div>"
        "<div class='report-summary-card'>"
        "<strong>现在能不能判断</strong>"
        f"<p>{html.escape(judgement)}</p>"
        f"{product_note}"
        f"{report_link_html}"
        "</div>"
        "<div class='report-summary-card'>"
        "<strong>后台读取队列 / 下一步</strong>"
        f"<ul>{missing_html}</ul>"
        f"<div class='summary-next-actions'><ul>{action_html}</ul></div>"
        "</div>"
        "</div>"
    )


def is_count_only_verdict(verdict: str) -> bool:
    text = verdict.strip()
    if not text:
        return True
    count_signals = ["信号", "记录", "数据", "证据", "线索"]
    return len(text) <= 40 and any(signal in text for signal in count_signals) and any(ch.isdigit() for ch in text)


