def render_store_dashboard_panel(
    *,
    store_records: list[IntakeRecord],
    store_profile_records: list[IntakeRecord],
) -> str:
    visible_profile_records = [
        record for record in store_profile_records if not is_fake_store_profile_record(record)
    ]
    metric_records = [
        record
        for record in store_records
        if record.record_type == "store_metric_snapshot" and is_real_store_metric_record(record)
    ]
    health_records = [
        record for record in store_records if record.record_type == "store_health_event"
    ]
    real_issue_records = [
        record for record in health_records if is_real_store_issue_record(record)
    ]
    profile_names: list[str] = []
    if metric_records or real_issue_records:
        for record in newest_dashboard_records(visible_profile_records, 4):
            fields = record.fields
            name = str(fields.get("store_id") or fields.get("store_name") or fields.get("browser_profile") or "").strip()
            if name and name not in profile_names:
                profile_names.append(name)
    for record in newest_dashboard_records(metric_records, 4):
        fields = record.fields
        name = str(
            fields.get("store_id")
            or fields.get("store_name")
            or fields.get("shop_name")
            or fields.get("browser_profile")
            or ""
        ).strip()
        if name and name not in profile_names:
            profile_names.append(name)
    if not store_records and not visible_profile_records:
        return (
            "<div class='empty'>后台 AI 暂未读到授权范围内的销售、订单、广告、退款或店铺健康数据。"
            "完成授权后系统会自动整理成经营大屏和今日建议。</div>"
        )
    if not metric_records and not real_issue_records:
        if visible_profile_records:
            message = (
                "已保存店铺档案，但还没有销售、订单、广告、退款或财务报表。"
                "卖家端不会把店铺档案当成经营结果。"
            )
        else:
            message = "还没有真实店铺经营数据。"
        return (
            "<div class='empty'>"
            f"{message} 授权范围内读到销售、订单、广告、退款或财务报表后，这里会自动生成经营判断。"
            " <a href='/store-erp'>让AI查接入状态</a></div>"
        )
    cards = [
        ("店铺档案", len(visible_profile_records), "只统计已接入的真实店铺档案"),
        ("经营数据", len(metric_records), "销售、订单、广告、退款、财务导入后才计入"),
        ("异常待处理", len(real_issue_records), "只显示掉线、风控、违规和异常"),
    ]
    card_html = "".join(
        "<div class='store-summary-card'>"
        f"<span>{html.escape(label)}</span>"
        f"<strong>{value}</strong>"
        f"<small>{html.escape(note)}</small>"
        "</div>"
        for label, value, note in cards
    )
    names_html = ""
    if profile_names:
        names_html = (
            "<p class='muted'>当前店铺："
            + "、".join(html.escape(name) for name in profile_names)
            + "</p>"
        )
    if real_issue_records:
        issue_rows = "\n".join(render_store_row(record) for record in newest_dashboard_records(real_issue_records, 8))
        issue_html = (
            "<div style='margin-top:12px;'>"
            "<strong>需要关注的店铺异常</strong>"
            f"{render_store_table(issue_rows)}"
            "</div>"
        )
    else:
        if metric_records:
            issue_html = "<div class='empty'>暂无需要你处理的店铺异常。</div>"
        else:
            issue_html = (
                "<div class='empty'>后台 AI 暂未读到授权范围内的真实销售、订单、广告、退款或财务数据。"
                "店铺档案不会当成经营结果展示；读取经营数据后再生成判断。</div>"
            )
    return (
        "<div class='store-summary'>"
        f"{card_html}"
        "</div>"
        f"{names_html}"
        f"{issue_html}"
    )


def is_real_store_issue_record(record: IntakeRecord) -> bool:
    fields = record.fields
    store_hint = " ".join(
        str(fields.get(key) or "")
        for key in ("store_id", "store_name", "browser_profile", "profile_name")
    ).lower()
    if any(
        marker in store_hint
        for marker in (
            "demo",
            "sample",
            "virtual",
            "mock",
            "test",
            "tk-us-test",
            "aelfric",
            "culture kings",
            "iherb",
        )
    ):
        return False
    status = str(fields.get("health_status") or "").lower()
    if status not in {"", "normal", "ok", "healthy"}:
        return True
    for key in ("appealable_violation_count", "rejected_product_count", "complaint_count", "risk_count"):
        try:
            if int(fields.get(key) or 0) > 0:
                return True
        except (TypeError, ValueError):
            continue
    return False


def is_fake_store_profile_record(record: IntakeRecord) -> bool:
    fields = record.fields
