def is_public_report_action_line(text: str) -> bool:
    internal_words = [
        "策略记忆",
        "资料整理任务",
        "页面助手",
        "后台",
        "训练",
        "蒸馏",
        "员工评分",
        "JSON",
        "source_chunk",
        "能力",
        "skill",
        "模型密钥",
        "接口配置",
    ]
    return not any(word in text for word in internal_words)


def safe_output_report_path_by_reference(root: Path, report_ref: str) -> Path:
    ref = report_ref.strip().upper()
    if not re.fullmatch(r"RPT-[A-F0-9]{10}", ref):
        raise ValueError("报告编号无效。")
    output_dir = (root / "outputs").resolve()
    for path in output_dir.glob("*.md"):
        if public_report_reference(path) == ref:
            return path.resolve()
    raise ValueError("找不到这份报告。")


def sanitize_public_report_content(content: str, locale: str = "zh-CN") -> str:
    replacements = {
        "Codex": "系统",
        "Claude Code": "协作工具",
        "Claude": "协作模型",
        "能力员工": "运营能力",
        "能力员工": "运营能力",
        "skill_agents": "operation_tools",
        "skill_id": "ability_id",
        "运营能力": "能力与页面助手",
        "插件": "页面助手",
        "能力": "能力",
        "skill": "ability",
        "plugin": "capture_tool",
        "Plugin": "Capture Tool",
        "TK-US-TEST-01": "店铺待接入",
        "TK-US-TEST": "店铺待接入",
        "AELFRIC EDEN": "店铺待接入",
        "Culture Kings": "店铺待接入",
        "iHerb": "店铺待接入",
        "Bit窗口": "登录环境窗口",
        "IP区域": "访问区域",
        "bit_window": "login_environment",
        "ip_region": "access_region",
        "raw evidence": "复核依据",
        "Raw evidence": "复核依据",
        "debug": "排查",
        "Debug": "排查",
    }
    sanitized = content
    for old, new in replacements.items():
        sanitized = sanitized.replace(old, new)
    hidden_markers = (
        "source_chunk",
        "strategy_memory",
        "员工考试",
        "训练日志",
        "原始JSON",
        "原始数据",
        "调试字段",
        "fake store",
        "demo store",
    )
    visible_lines = []
    for line in sanitized.splitlines():
        if any(marker.lower() in line.lower() for marker in hidden_markers):
            continue
        visible_lines.append(line)
    sanitized = "\n".join(visible_lines)
    return humanize_system_text(sanitized, locale)


def should_hide_raw_report_body(path: Path) -> bool:
    """Seller-facing commerce reports should expose decisions, not raw operating logs."""
    name = path.name.lower()
    hidden_prefixes = (
        "action_queue_",
        "autonomous_",
        "brand_report_",
        "daily_report_",
        "ecommerce_workflow_",
        "operation_closure_",
        "platform_autopilot_",
        "product_target_report_",
        "selection_intelligence_",
        "selection_meeting_",
        "supervised_ai_council_",
        "visual_creative_",
    )
    hidden_fragments = (
        "ai_employee",
        "agent_exam",
        "exam_answer",
        "browser_operator",
        "learning_sources",
    )
    return name.startswith(hidden_prefixes) or any(fragment in name for fragment in hidden_fragments)


def report_public_meta(path: Path, locale: str = "zh-CN") -> str:
    updated = date.fromtimestamp(path.stat().st_mtime).isoformat() if path.exists() else date.today().isoformat()
    if locale.startswith("en"):
        return f"Updated: {updated} · public summary"
    return f"更新日期：{updated} · 展示版"


def collect_exam_report_paths(root: Path, limit: int = 30) -> list[Path]:
    output_dir = root / "outputs"
    if not output_dir.exists():
        return []
    ignored_prefixes = (
        "daily_report_",
        "platform_autopilot_",
        "selection_intelligence_",
        "selection_meeting_",
        "action_queue_",
        "autonomous_run_",
        "visual_creative_",
        "ecommerce_workflow_gap_audit_",
    )
    reports = [
        path
        for path in output_dir.glob("*.md")
        if not path.name.startswith(ignored_prefixes)
    ]
    priority_prefixes = (
        "brand_report_",
        "brand_intelligence_",
        "aporro_ai_employee_exam_cn_",
        "aporro_ai_employee_exam_",
        "codex_aporro_exam_answer_",
        "supervised_ai_council_",
        "tiktok_knowledge_lake_pilot_",
        "global_commerce_os_compliant_pipeline_boss_summary_",
    )

    def sort_key(path: Path) -> tuple[int, float]:
        priority = 0 if path.name.startswith(priority_prefixes) else 1
        return priority, -path.stat().st_mtime

    return sorted(reports, key=sort_key)[:limit]


def report_display_label(path: Path) -> str:
    name = path.name
    labels = [
        ("brand_report_aporro_", "Aporro 品牌报告"),
        ("brand_intelligence_aporro_full_", "Aporro 运营情报补考版"),
        ("aporro_ai_employee_exam_cn_", "Aporro AI员工中文交卷"),
        ("aporro_ai_employee_exam_", "Aporro AI员工英文交卷"),
        ("codex_aporro_exam_answer_", "系统自评交卷"),
        ("supervised_ai_council_", "受监督AI员工会议报告"),
        ("tiktok_knowledge_lake_pilot_", "TikTok视频知识湖试点报告"),
        ("global_commerce_os_compliant_pipeline_boss_summary_", "Global Commerce OS 合规采集管道老板摘要"),
    ]
    for prefix, label in labels:
        if name.startswith(prefix):
            return label
    return path.stem.replace("_", " ")


