def report_group_label(path: Path) -> str:
    name = path.name.lower()
    if name.startswith(("brand_report_", "brand_intelligence_", "global_commerce_os_compliant_pipeline_boss_summary_")):
        return "老板先看"
    if any(key in name for key in ["tiktok", "selection", "product_target", "platform_autopilot"]):
        return "TK与选品训练"
    if any(key in name for key in ["exam", "aporro_ai_employee", "codex_aporro", "supervised_ai_council"]):
        return "员工考试"
    if any(key in name for key in ["autonomous", "loop", "learning", "closure", "budget", "launch", "lifecycle", "browser"]):
        return "系统训练复盘"
    return "其他报告"


def render_exam_report_card(path: Path) -> str:
    label = report_display_label(path)
    href = public_report_url(path)
    updated = date.fromtimestamp(path.stat().st_mtime).isoformat()
    ref = public_report_reference(path)
    preview = extract_report_card_preview(path)
    return (
        "<article class='report-card'>"
        f"<strong>{html.escape(label)}</strong>"
        f"<p>{html.escape(preview)}</p>"
        f"<div class='report-meta'><span>{html.escape(updated)}</span><span>{html.escape(ref)}</span></div>"
        f"<a class='open-report' href='{href}'>打开完整交卷</a>"
        "</article>"
    )


def extract_report_card_preview(path: Path) -> str:
    try:
        content = sanitize_public_report_content(path.read_text(encoding="utf-8", errors="ignore"))
    except OSError:
        return "报告文件暂时无法读取。"
    return extract_report_verdict(content)


def is_amazon_bs_new_record(record: IntakeRecord) -> bool:
    fields = record.fields
    marketplace = str(fields.get("marketplace") or fields.get("source_platform") or "").lower()
    ranking_type = str(fields.get("ranking_type") or "").lower()
    ranking_page = str(fields.get("ranking_page") or fields.get("url") or fields.get("page_url") or "").lower()
    text = f"{marketplace} {ranking_type} {ranking_page}"
    if "amazon" not in text and "亚马逊" not in text:
        return False
    return any(
        signal in text
        for signal in [
            "bsr",
            "bs.new",
            "bs/new",
            "best sellers",
            "best-sellers",
            "new releases",
            "new-releases",
            "amazon bs/new",
            "amazon bs.new",
        ]
    )


def update_record_from_payload(root: Path, payload: dict[str, Any]) -> IntakeRecord:
    record_id = str(payload.get("record_id") or "").strip()
    if not record_id:
        raise ValueError("缺少 record_id。")
    record = find_record(root, record_id)
    if not record:
        raise ValueError(f"找不到这条记录：{record_id}")

    fields_payload = payload.get("fields", record.fields)
    if isinstance(fields_payload, str):
        fields_payload = json.loads(fields_payload or "{}")
    if not isinstance(fields_payload, dict):
        raise ValueError("fields 必须是 JSON 对象。")

    record.fields = normalize_fields(fields_payload)
    if "raw_text" in payload:
        record.raw_text = str(payload.get("raw_text") or "")
    if "review_status" in payload:
        record.review_status = str(payload.get("review_status") or "approved")
    record.score, record.director_notes = score_record(record.record_type, record.fields)
    update_record(root, record)
    return record


