def render_director_run_row(record: IntakeRecord) -> str:
    fields = record.fields
    classification = fields.get("classification") if isinstance(fields.get("classification"), dict) else {}
    scores = fields.get("scores") if isinstance(fields.get("scores"), dict) else {}
    score_text = " / ".join(
        f"{key.replace('_score', '')} {value}"
        for key, value in scores.items()
        if key.endswith("_score")
    )
    return (
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}</td>"
        f"<td>{html.escape(str(fields.get('agent_run_id') or record.record_id))}</td>"
        f"<td>{html.escape(str(fields.get('status') or ''))}</td>"
        f"<td>{html.escape(str(classification.get('platform') or ''))} / {html.escape(str(classification.get('category') or ''))}</td>"
        f"<td>{html.escape(score_text or '-')}</td>"
        "</tr>"
    )


def render_employee_evaluation_row(record: IntakeRecord) -> str:
    fields = record.fields
    return (
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}</td>"
        f"<td>{html.escape(str(fields.get('employee') or ''))}</td>"
        f"<td>{html.escape(str(fields.get('score') or ''))}</td>"
        f"<td>{html.escape(str(fields.get('verdict') or fields.get('grade') or ''))}</td>"
        f"<td>{html.escape(short_text(fields.get('retraining_plan'), 180))}</td>"
        f"<td>{html.escape(short_text(fields.get('next_exam'), 160))}</td>"
        "</tr>"
    )


def render_retraining_task_row(record: IntakeRecord) -> str:
    fields = record.fields
    return (
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}</td>"
        f"<td>{html.escape(str(fields.get('target_agent_id') or fields.get('assigned_agent') or ''))}</td>"
        f"<td>{html.escape(str(fields.get('task_title') or ''))}</td>"
        f"<td>{html.escape(short_text(fields.get('expected_output'), 180))}</td>"
        f"<td>{html.escape(str(fields.get('status') or ''))}</td>"
        "</tr>"
    )


def short_text(value: Any, limit: int = 160) -> str:
    text = compact_text(str(value or ""))
    if len(text) <= limit:
        return text
    return text[: limit - 3].rstrip() + "..."


