def build_category_filter_options(categories: list[Any], recommendations: list[dict[str, Any]]) -> str:
    paths: dict[str, str] = {}
    for path in DEFAULT_CATEGORY_FILTER_PATHS:
        clean_path = str(path or "").strip()
        if clean_path:
            paths[clean_path] = category_display_label(clean_path)
    for category in categories:
        path = str(getattr(category, "category_path", "") or "").strip()
        if path:
            paths.setdefault(path, category_display_label(path))
    for item in recommendations:
        path = str(item.get("category_path") or "").strip()
        if path:
            paths.setdefault(path, category_display_label(path))

    def sort_key(option: tuple[str, str]) -> tuple[int, str]:
        path, _label = option
        platform = path.split(">")[0].strip()
        return (selection_platform_priority(platform), path.lower())

    return "".join(
        f"<option value='{html.escape(path)}'>{html.escape(label)}</option>"
        for path, label in sorted(paths.items(), key=sort_key)
    )


