def render_seller_workflow_nav(active: str = "", ai_widget_links: bool = True, root: Path | None = None) -> str:
    links: list[str] = []
    for key, url, label in SELLER_PRIMARY_NAV_ITEMS:
        classes = ["active" if key == active else "", "admin" if key == "admin" else ""]
        class_text = " ".join(item for item in classes if item)
        attr = f" class='{html.escape(class_text)}'" if class_text else ""
        links.append(f"<a{attr} href='{html.escape(url)}'>{html.escape(label)}</a>")
    # 二级「经营工具」簇：仍可达，但不占主导航位置。
    tools_html = ""
    if SELLER_TOOLS_NAV_ITEMS:
        tool_links = "".join(
            f"<a class='tool' href='{html.escape(url)}'>{html.escape(label)}</a>"
            for url, label in SELLER_TOOLS_NAV_ITEMS
        )
        tools_html = (
            "<span class='nav-tools'><span class='nav-tools-label'>经营工具</span>"
            + tool_links
            + "</span>"
        )
    return (
        "<nav class='seller-workflow-nav'>"
        + "".join(links)
        + tools_html
        + "</nav>"
        + render_floating_ai_widget(show_links=ai_widget_links, root=root)
    )


def render_seller_service_catalog() -> str:
    cards: list[str] = []
    for item in SELLER_SERVICE_CATEGORIES:
        tags = "".join(
            f"<span>{html.escape(str(tag))}</span>"
            for tag in item.get("tags", [])
        )
        cards.append(
            "<article class='service-card'>"
            f"<div class='service-eyebrow'>{html.escape(str(item.get('subtitle', '')))}</div>"
            f"<h3>{html.escape(str(item.get('title', '')))}</h3>"
            f"<p>{html.escape(str(item.get('description', '')))}</p>"
            f"<div class='service-tags'>{tags}</div>"
            f"<a class='service-link' href='{html.escape(str(item.get('url', '/chat')))}'>"
            f"{html.escape(str(item.get('cta', '去处理')))}</a>"
            "</article>"
        )
    return "<div class='service-grid'>" + "".join(cards) + "</div>"


def render_function_map_page(root: Path) -> str:
    group_html = "\n".join(
        "<section class='function-group'>"
        f"<h2>{html.escape(str(group['title']))}</h2>"
        f"<p>{html.escape(str(group['note']))}</p>"
        "<div class='function-grid'>"
        + "".join(
            "<a class='function-card' href='{url}'>"
            "<strong>{label}</strong>"
            "<span>{note}</span>"
            "</a>".format(
                url=html.escape(url),
                label=html.escape(label),
                note=html.escape(note),
            )
            for url, label, note in group["items"]
        )
        + "</div></section>"
        for group in FUNCTION_MAP_GROUPS
    )
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>功能入口 - AI Ecommerce Director</title>
  <style>{simple_page_css()}
    main {{ max-width: 1280px; }}
    .hero {{ display:flex; justify-content:space-between; gap:18px; align-items:flex-start; }}
    .hero p {{ max-width: 780px; line-height: 1.6; }}
    .function-group {{ background: var(--surface); border: 1px solid var(--line); border-radius: 10px; padding: 18px; margin-top: 16px; box-shadow: 0 12px 26px rgba(17, 19, 24, 0.035); }}
    .function-group p {{ margin: -4px 0 14px; color: var(--muted); font-size: 13px; }}
    .function-grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(220px, 1fr)); gap: 12px; }}
    .function-card {{ display:block; border:1px solid var(--line); border-radius:8px; background:var(--soft); padding:14px; text-decoration:none; color:var(--ink); min-height:96px; }}
    .function-card strong {{ display:block; font-size:15px; margin-bottom:8px; }}
    .function-card span {{ display:block; color:var(--muted); font-size:13px; line-height:1.45; }}
    .function-card:hover {{ border-color:#b9f0f5; background:#f0fdfa; text-decoration:none; }}
  </style>
</head>
<body>
  <header>
    <h1>功能入口</h1>
    <div class="muted">这里只放卖家每天真正要看的结果、报告和待确认动作。</div>
    <div class="actions">
      <a class="button secondary" href="/dashboard">返回首页</a>
      <a class="button secondary" href="/dashboard">今日工作台</a>
      <a class="button secondary" href="/realtime-big-screen">经营大屏</a>
    </div>
  </header>
  <main>
    <section class="panel hero">
      <div>
        <h2>使用原则</h2>
      <p>卖家端只看结论、报告、店铺数据和待确认事项；后台处理细节不出现在日常经营页面。</p>
      </div>
    </section>
    {group_html}
  </main>
</body>
</html>"""


def render_ai_provider_row(provider: dict[str, Any]) -> str:
    status = "可用" if provider.get("ready") else ("已启用但未完整配置" if provider.get("enabled") else "未启用")
    tasks = ", ".join(str(task) for task in provider.get("tasks", []))
    return (
        "<tr>"
        f"<td>{html.escape(str(provider.get('name') or ''))}</td>"
        f"<td>{html.escape(status)}</td>"
        f"<td>{html.escape(str(provider.get('model') or ''))}</td>"
        f"<td>{html.escape(str(provider.get('api_format') or 'openai'))}</td>"
        f"<td>{html.escape(tasks)}</td>"
        f"<td>{html.escape(str(provider.get('priority') or ''))}</td>"
        f"<td>{html.escape(str(provider.get('base_url') or ''))}</td>"
        "</tr>"
    )


def render_pod_admin_page(root: Path) -> str:
    config = load_pod_admin_config(root)
    try:
        snapshot, _ = build_pod_admin_snapshot(root, persist=False)
        fields = snapshot.fields
        status = snapshot.status
        error = ""
    except Exception as exc:  # noqa: BLE001 - diagnostic page should still load.
        fields = {"platform_name": config.platform_name, "project_path": str(config.project_path or "")}
        status = {"enabled": config.enabled, "safe_mode": config.safe_mode}
        error = str(exc)
    admin_url = str(fields.get("admin_url") or "")
    admin_finance_url = str(fields.get("admin_finance_url") or "")
    factory_url = str(fields.get("factory_url") or "")
    designer_url = str(fields.get("designer_url") or "")
    link_html = render_pod_link_list(
        [
            ("管理员端", admin_url),
            ("财务端", admin_finance_url),
            ("工厂端", factory_url),
            ("设计师端", designer_url),
        ]
    )
    error_html = f"<div class='warning'>{html.escape(error)}</div>" if error else ""
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>POD管理员端</title>
  <style>
    body {{ margin: 0; font-family: Arial, sans-serif; background: #f6f8fa; color: #111318; }}
    header {{ padding: 20px 28px; border-bottom: 1px solid #e8edf2; background: #fff; }}
    main {{ max-width: 1120px; margin: 0 auto; padding: 22px 28px 40px; }}
    h1 {{ margin: 0; font-size: 24px; }}
    h2 {{ margin: 0 0 12px; font-size: 18px; }}
    a {{ color: #087986; text-decoration: none; }}
    a:hover {{ text-decoration: underline; }}
    .muted {{ color: #7b8490; font-size: 13px; margin-top: 6px; }}
    .panel {{ background: #fff; border: 1px solid #e8edf2; border-radius: 8px; padding: 16px; margin-top: 16px; }}
    .actions {{ display: flex; flex-wrap: wrap; gap: 10px; margin-top: 14px; }}
    button, a.button {{ border: 1px solid #087986; border-radius: 6px; padding: 9px 12px; background: #087986; color: #fff; font-weight: 700; cursor: pointer; text-decoration: none; }}
    a.secondary {{ background: #fff; color: #087986; border-color: #e8edf2; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 12px; }}
    .metric-card {{ border: 1px solid #e8edf2; border-radius: 8px; padding: 14px; background: #f9fbfc; }}
    .metric-card span {{ display: block; color: #7b8490; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 24px; }}
    table {{ width: 100%; border-collapse: collapse; border: 1px solid #e8edf2; }}
    th, td {{ padding: 10px; border-bottom: 1px solid #e8edf2; text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: #111318; }}
    ul {{ margin: 0; padding-left: 20px; line-height: 1.6; }}
    pre {{ white-space: pre-wrap; word-break: break-word; background: #f9fbfc; border: 1px solid #e8edf2; border-radius: 8px; padding: 12px; }}
    .warning {{ background: #fff7ed; border: 1px solid #fed7aa; border-radius: 8px; padding: 12px; color: #9a3412; }}
    .empty {{ color: #7b8490; background: #f9fbfc; border: 1px dashed #e8edf2; border-radius: 8px; padding: 14px; }}
    #status {{ color: #087986; font-size: 13px; margin-top: 10px; }}
  </style>
</head>
<body>
  <header>
    <h1>POD管理员端</h1>
    <div class="muted">平台：{html.escape(str(fields.get("platform_name") or config.platform_name))} · 只读安全模式：{html.escape(str(status.get("safe_mode", True)))} · 项目：{html.escape(str(fields.get("project_path") or ""))}</div>
    <div class="actions">
      <a class="button secondary" href="/dashboard">返回控制台</a>
      <a class="button secondary" href="/autopilot">AI自动巡检</a>
      <a class="button secondary" href="/report">今日报告</a>
    </div>
  </header>
  <main>
    {error_html}
    <section class="panel">
      <h2>入口</h2>
      {link_html}
      <div class="actions">
        <button id="snapshot">生成并保存POD快照</button>
      </div>
      <div id="status"></div>
    </section>
    <section class="panel">
      <h2>运营数据</h2>
      {render_pod_metric_grid(fields)}
    </section>
    <section class="panel">
      <h2>端口状态</h2>
      {render_pod_portal_table(fields.get("portal_status") if isinstance(fields.get("portal_status"), dict) else {})}
    </section>
    <section class="panel">
      <h2>全平台渠道分析</h2>
      {render_pod_channel_panel(fields)}
    </section>
    <section class="panel">
      <h2>风险与动作</h2>
      {render_pod_list(fields.get("risk_summary"))}
      <div style="height: 12px"></div>
      {render_pod_list(fields.get("recommended_actions"))}
    </section>
    <section class="panel">
      <h2>原始快照</h2>
      <pre id="raw">{html.escape(json.dumps(fields, ensure_ascii=False, indent=2))}</pre>
    </section>
  </main>
  <script>
    document.getElementById("snapshot").addEventListener("click", async () => {{
      const status = document.getElementById("status");
      const raw = document.getElementById("raw");
      status.textContent = "正在生成POD只读快照...";
      const response = await fetch("/api/pod-admin/snapshot", {{
        method: "POST",
        headers: {{ "Content-Type": "application/json" }},
        body: JSON.stringify({{}})
      }});
      const payload = await response.json();
      if (!payload.ok) {{
        status.textContent = "生成失败：" + payload.error;
        return;
      }}
      status.textContent = "已保存为训练记录：" + (payload.record ? payload.record.record_id : "未保存");
      raw.textContent = JSON.stringify(payload.snapshot, null, 2);
    }});
  </script>
</body>
</html>"""


def render_pod_link_list(links: list[tuple[str, str]]) -> str:
    items = []
    for label, url in links:
        if url:
            items.append(f"<li>{html.escape(label)}：<a href='{html.escape(url)}' target='_blank'>{html.escape(url)}</a></li>")
        else:
            items.append(f"<li>{html.escape(label)}：暂未检测到</li>")
    return "<ul>" + "".join(items) + "</ul>"


def render_pod_platform_page(root: Path, locale: str | None = None) -> str:
    tr = translator(root, locale)
    config = load_pod_admin_config(root)
    try:
        snapshot, _ = build_pod_admin_snapshot(root, persist=False)
        fields = snapshot.fields
        status = snapshot.status
        error = ""
    except Exception as exc:  # noqa: BLE001 - keep the section visible even when POD is down.
        fields = {"platform_name": config.platform_name, "project_path": str(config.project_path or "")}
        status = {"enabled": config.enabled, "safe_mode": config.safe_mode}
        error = str(exc)
    portal_cards = render_pod_portal_cards(fields)
    action_cards = "".join(render_pod_center_action_card(item) for item in pod_center_actions(fields))
    error_html = f"<div class='warning'>{html.escape(error)}</div>" if error else ""
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>{html.escape(tr.t("pod_platform_center"))}</title>
  <style>{simple_page_css()}
    main {{ max-width: 1320px; }}
    .hero {{ background: #fff; border: 1px solid #e8edf2; border-radius: 8px; padding: 18px; margin-top: 16px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; }}
    .wide-grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px; }}
    .metric-card, .pod-card {{ border: 1px solid #e8edf2; border-radius: 8px; padding: 14px; background: #fff; }}
    .metric-card span, .pod-card span {{ display: block; color: #7b8490; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 22px; }}
    .pod-card strong {{ display: block; font-size: 16px; margin-bottom: 6px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e8edf2; }}
    th, td {{ padding: 10px; border-bottom: 1px solid #e8edf2; text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: #111318; }}
    .small {{ color: #7b8490; font-size: 12px; margin-top: 4px; }}
    .warning {{ background: #fff7ed; border: 1px solid #fed7aa; border-radius: 8px; padding: 12px; color: #9a3412; }}
  </style>
</head>
<body>
  <header>
    <h1>{html.escape(tr.t("pod_platform_center"))}</h1>
    <div class="muted">{html.escape(tr.t("pod_subtitle"))}</div>
    <div class="actions">
      <a class="button secondary" href="/dashboard">{html.escape(tr.t("dashboard"))}</a>
      <a class="button secondary" href="/store-erp">店铺ERP</a>
      <a class="button secondary" href="/selection">选品报告</a>
      <a class="button secondary" href="/chat">店铺AI顾问</a>
      <a class="button secondary" href="/chat?intent=approval">让AI整理确认草稿</a>
    </div>
  </header>
  <main>
    {error_html}
    <section class="hero">
      <h2>{html.escape(str(fields.get("platform_name") or config.platform_name))}</h2>
      <div class="muted">POD 独立通道：商品底板、设计、审核、生产、发货和结算单独管理；真实发布、改价和渠道同步仍进入待确认。</div>
      <div class="grid" style="margin-top: 16px;">{render_pod_center_metric_cards(fields)}</div>
    </section>

    <section class="panel">
      <h2>POD专属铺货工作流</h2>
      <div class="muted">POD 商家不是只看数据，核心是连续产出：商品图、视频、标题、Listing、侵权审核和多平台草稿。所有外部发布仍进入待确认队列。</div>
      {render_pod_listing_workflow()}
    </section>

    <section class="panel">
      <h2>{html.escape(tr.t("portals"))}</h2>
      <div class="wide-grid">{portal_cards}</div>
    </section>

    <section class="panel">
      <h2>{html.escape(tr.t("pod_modules"))}</h2>
      <div class="wide-grid">{action_cards}</div>
    </section>

    <section class="panel">
      <h2>{html.escape(tr.t("channel_fulfillment"))}</h2>
      {render_pod_channel_panel(fields)}
    </section>

    <section class="panel" id="pod-risk">
      <h2>{html.escape(tr.t("pod_ip_risk"))}</h2>
      {render_pod_ip_risk_summary(root, tr)}
    </section>

    <section class="panel">
      <h2>{html.escape(tr.t("risk_and_pending_actions"))}</h2>
      {render_pod_list(fields.get("risk_summary"))}
      <div style="height: 12px"></div>
      {render_pod_list(fields.get("recommended_actions"))}
      <div class="warning" style="margin-top: 12px;">POD 平台里的审核、派单、改价、发布/下架、财务结算、提现、供应商设置，都只生成建议和待确认动作，不自动执行。</div>
    </section>

  </main>
</body>
</html>"""


def render_pod_center_metric_cards(fields: dict[str, Any]) -> str:
    metrics = [
        ("底板", fields.get("blank_count", 0)),
        ("作品", fields.get("design_count", 0)),
        ("订单", fields.get("order_count", 0)),
        ("待生产", fields.get("pending_print_job_count", 0)),
        ("低库存SKU", fields.get("low_stock_sku_count", 0)),
        ("渠道销售", fields.get("channel_sales", 0)),
        ("渠道订单", fields.get("channel_orders", 0)),
        ("代运营待审", fields.get("platform_ops_pending_count", 0)),
    ]
    return "".join(
        f"<div class='metric-card'><span>{html.escape(label)}</span><strong>{html.escape(str(value))}</strong></div>"
        for label, value in metrics
    )


def render_pod_listing_workflow() -> str:
    steps = [
        (
            "1. 选底板 / 定SKU",
            "选择衣服、帽子、杯子等底板，确认颜色、尺码、成本、库存和可生产工厂。",
        ),
        (
            "2. 生图与主图方案",
            "生成白底图、细节图、模特图、场景图，并标记 Logo、材质、尺码和卖点位置。",
        ),
        (
            "3. 生视频与脚本",
            "输出 TK 商品脚本：0-2秒钩子、运镜、场景、口播、字幕、CTA、音乐版权提醒。",
        ),
        (
            "4. 标题 / Listing",
            "按 TikTok、Amazon、Etsy、SHEIN 等平台生成标题、五点、标签、FAQ 和价格建议。",
        ),
        (
            "5. 侵权与授权审核",
            "扫描商标、角色、明星、球队、TRO 高风险元素；有授权材料时进入复审。",
        ),
        (
            "6. 渠道草稿 / 待确认",
            "生成多平台上架草稿、达人素材包和投流建议；发布、改价、投流必须人工确认。",
        ),
    ]
    return (
        "<div class='wide-grid' style='margin-top:12px;'>"
        + "".join(
            "<div class='pod-card'>"
            f"<strong>{html.escape(title)}</strong>"
            f"<div>{html.escape(body)}</div>"
            "</div>"
            for title, body in steps
        )
        + "</div>"
    )


def render_pod_portal_cards(fields: dict[str, Any]) -> str:
    portal_status = fields.get("portal_status") if isinstance(fields.get("portal_status"), dict) else {}
    portal_defs = [
        ("客户/设计师端", fields.get("designer_url") or "", "选底板、做设计、买光板、提交作品。", "designer", True),
        ("平台运营", fields.get("admin_url") or "", "审核、商品、活动、渠道和代运营由平台团队处理。", "admin", False),
        ("结算", fields.get("admin_finance_url") or "", "收益、结算和提现由平台按规则处理。", "admin_finance", False),
        ("生产履约", fields.get("factory_url") or "", "工单、生产、质检、发货和异常由履约团队处理。", "factory", False),
    ]
    cards = []
    for title, url, body, key, show_link in portal_defs:
        status = portal_status.get(key) if isinstance(portal_status.get(key), dict) else {}
        ok = "可访问" if status.get("ok") else "未检测到"
        if show_link and url:
            link = f"<a href='{html.escape(str(url))}' target='_blank'>打开</a>"
        elif url:
            link = "<span class='small'>由平台团队处理</span>"
        else:
            link = "<span class='small'>暂无链接</span>"
        cards.append(
            "<div class='pod-card'>"
            f"<span>{html.escape(ok)}</span>"
            f"<strong>{html.escape(str(title))}</strong>"
            f"<div>{html.escape(str(body))}</div>"
            f"<div class='small'>{link}</div>"
            "</div>"
        )
    return "".join(cards)


