def render_pod_center_action_card(item: dict[str, str]) -> str:
    return (
        "<div class='pod-card'>"
        f"<span>{html.escape(item['status'])}</span>"
        f"<strong>{html.escape(item['title'])}</strong>"
        f"<div>{html.escape(item['body'])}</div>"
        "</div>"
    )


def render_pod_ip_risk_page(root: Path, locale: str | None = None) -> str:
    tr = translator(root, locale)
    records = sorted(read_records(root, "ip_image_risk"), key=lambda item: item.created_at, reverse=True)
    rows = "".join(render_pod_ip_risk_row(record) for record in records[:120])
    summary = pod_ip_risk_summary(records)
    return f"""<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8">
  <title>{html.escape(tr.t("pod_ip_risk"))}</title>
  <style>{simple_page_css()}
    main {{ max-width: 1320px; }}
    .grid {{ display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 12px; margin-top: 16px; }}
    .metric-card {{ border: 1px solid #e8edf2; border-radius: 8px; padding: 14px; background: #fff; }}
    .metric-card span {{ display: block; color: #7b8490; font-size: 12px; margin-bottom: 8px; }}
    .metric-card strong {{ font-size: 22px; }}
    table {{ width: 100%; border-collapse: collapse; background: #fff; border: 1px solid #e8edf2; }}
    th, td {{ padding: 10px; border-bottom: 1px solid #e8edf2; text-align: left; vertical-align: top; font-size: 13px; }}
    th {{ background: #f9fbfc; color: #111318; }}
    .small {{ color: #7b8490; font-size: 12px; margin-top: 4px; }}
    .warning {{ background: #fff7ed; border: 1px solid #fed7aa; border-radius: 8px; padding: 12px; color: #9a3412; }}
  </style>
</head>
<body>
  <header>
    <h1>{html.escape(tr.t("pod_ip_risk"))}</h1>
    <div class="muted">{html.escape(tr.t("ip_risk_subtitle"))}</div>
    <div class="actions">
      <a class="button secondary" href="/pod-channel">{html.escape(tr.t("pod_platform_center"))}</a>
      <a class="button secondary" href="/report">{html.escape(tr.t("today_report"))}</a>
      <a class="button secondary" href="/dashboard">{html.escape(tr.t("today_workbench"))}</a>
      <a class="button secondary" href="/chat?intent=approval">让AI整理确认草稿</a>
    </div>
  </header>
  <main>
    <section class="grid">
      <div class="metric-card"><span>{html.escape(tr.t("risk_elements"))}</span><strong>{summary['total']}</strong></div>
      <div class="metric-card"><span>{html.escape(tr.t("delist_review"))}</span><strong>{summary['delist']}</strong></div>
      <div class="metric-card"><span>{html.escape(tr.t("tro_cases"))}</span><strong>{summary['tro']}</strong></div>
      <div class="metric-card"><span>{html.escape(tr.t("high_priority"))}</span><strong>{summary['high']}</strong></div>
    </section>

    <section class="panel">
      <h2>{html.escape(tr.t("capture_format"))}</h2>
      <div class="warning">{html.escape(tr.t("capture_format_body"))}</div>
    </section>

    <section class="panel">
      <h2>{html.escape(tr.t("risk_library"))}</h2>
      {f"<table><thead><tr><th>{html.escape(tr.t('element_time'))}</th><th>{html.escape(tr.t('rights_owner_tro'))}</th><th>{html.escape(tr.t('evidence'))}</th><th>{html.escape(tr.t('suspected_link'))}</th><th>{html.escape(tr.t('action'))}</th></tr></thead><tbody>{rows}</tbody></table>" if rows else f"<div class='empty'>{html.escape(tr.t('no_ip_risks'))}</div>"}
    </section>
  </main>
</body>
</html>"""


def render_pod_ip_risk_summary(root: Path, tr: Translator | None = None) -> str:
    tr = tr or translator(root)
    records = sorted(read_records(root, "ip_image_risk"), key=lambda item: item.created_at, reverse=True)
    summary = pod_ip_risk_summary(records)
    header = (
        f"<div class='grid'><div class='metric-card'><span>{html.escape(tr.t('risk_elements'))}</span><strong>{summary['total']}</strong></div>"
        f"<div class='metric-card'><span>{html.escape(tr.t('delist_review'))}</span><strong>{summary['delist']}</strong></div>"
        f"<div class='metric-card'><span>{html.escape(tr.t('tro_cases'))}</span><strong>{summary['tro']}</strong></div>"
        f"<div class='metric-card'><span>{html.escape(tr.t('high_priority'))}</span><strong>{summary['high']}</strong></div></div>"
    )
    if not records:
        return (
            header
            + f"<div class='empty' style='margin-top:12px;'>{html.escape(tr.t('no_ip_risks'))}</div>"
            + "<div class='small'>详细复核材料只在 POD 管理端，前台只显示结论和是否需要确认。</div>"
        )
    return (
        header
        + "<div class='warning' style='margin-top:12px;'>前台只显示审核结论：clear 可以公开；borderline 观察；confirmed_ip 只允许私人定制或授权复审；prohibited 驳回。需要复核时再展开授权材料、截图、TRO 明细和复审记录。</div>"
    )


def pod_ip_risk_summary(records: list[IntakeRecord]) -> dict[str, int]:
    return {
        "total": len(records),
        "delist": len([record for record in records if record.score.get("requires_delist_review")]),
        "tro": len([record for record in records if record.fields.get("case_number") or "tro" in str(record.fields.get("tro_status") or "").lower()]),
        "high": len([record for record in records if float(record.score.get("priority", 0) or 0) >= 90]),
    }


def render_pod_ip_risk_row(record: IntakeRecord) -> str:
    fields = record.fields
    element = fields.get("risk_element") or fields.get("term") or fields.get("product_name") or fields.get("visual_signature") or record.record_id[:8]
    category = fields.get("element_category") or fields.get("risk_category") or ""
    owner = fields.get("rights_owner") or fields.get("plaintiff") or fields.get("trademark_owner") or ""
    tro = fields.get("case_number") or fields.get("tro_status") or ""
    evidence = fields.get("evidence_url") or fields.get("image_url") or fields.get("screenshot_path") or ""
    listing = fields.get("infringing_listing_url") or fields.get("url") or ""
    evidence_html = f"<a href='{html.escape(str(evidence))}' target='_blank'>Evidence</a>" if evidence else ""
    listing_html = f"<a href='{html.escape(str(listing))}' target='_blank'>Open listing</a>" if listing else ""
    if record.score.get("authorized_for_listing"):
        action = "Authorized listing allowed"
    elif record.score.get("requires_delist_review"):
        action = "Pending delist review"
    elif record.score.get("requires_authorization_review"):
        action = "Authorization review"
    else:
        action = "Scan and monitor"
    return (
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}<div class='small'>{html.escape(str(element))} / {html.escape(str(category))}</div></td>"
        f"<td>{html.escape(str(owner))}<div class='small'>{html.escape(str(tro))}</div></td>"
        f"<td>{evidence_html}</td>"
        f"<td>{listing_html}</td>"
        f"<td>{html.escape(action)}<div class='small'>Priority {html.escape(str(record.score.get('priority', '')))}</div></td>"
        "</tr>"
    )


def render_pod_metric_grid(fields: dict[str, Any]) -> str:
    metrics = [
        ("数据库", fields.get("db_status") or "unknown"),
        ("用户", fields.get("user_count", 0)),
        ("管理员", fields.get("admin_count", 0)),
        ("工厂", fields.get("factory_count", 0)),
        ("底板", fields.get("blank_count", 0)),
        ("作品", fields.get("design_count", 0)),
        ("订单", fields.get("order_count", 0)),
        ("生产工单", fields.get("print_job_count", 0)),
        ("待生产", fields.get("pending_print_job_count", 0)),
        ("异常工单", fields.get("exception_job_count", 0)),
        ("低库存SKU", fields.get("low_stock_sku_count", 0)),
        ("活动报名", fields.get("activity_enrollment_count", 0)),
        ("渠道接口", fields.get("channel_analytics_status", "unknown")),
        ("支持渠道", fields.get("supported_channel_count", 0)),
        ("渠道销售", fields.get("channel_sales", 0)),
        ("渠道订单", fields.get("channel_orders", 0)),
        ("待上架同步", fields.get("channel_pending_listing_count", 0)),
        ("待发货同步", fields.get("channel_pending_shipment_count", 0)),
        ("代运营待审", fields.get("platform_ops_pending_count", 0)),
        ("代运营未达标", fields.get("platform_ops_below_target_count", 0)),
    ]
    cards = "".join(
        f"<div class='metric-card'><span>{html.escape(label)}</span><strong>{html.escape(str(value))}</strong></div>"
        for label, value in metrics
    )
    return f"<div class='grid'>{cards}</div>"


def render_pod_channel_panel(fields: dict[str, Any]) -> str:
    status = str(fields.get("channel_analytics_status") or "unknown")
    channels = fields.get("channel_names") or fields.get("supported_channels") or []
    top_products = fields.get("channel_top_products") if isinstance(fields.get("channel_top_products"), list) else []
    channel_text = "、".join(str(item) for item in channels[:20]) if isinstance(channels, list) else str(channels)
    summary = fields.get("channel_summary") if isinstance(fields.get("channel_summary"), dict) else {}
    rows = "".join(
        "<tr>"
        f"<td>{html.escape(str(product.get('title') or product.get('id') or '未命名商品'))}</td>"
        f"<td>{html.escape(str(product.get('units', 0)))}</td>"
        f"<td>{html.escape(str(product.get('sales', 0)))}</td>"
        "</tr>"
        for product in top_products
        if isinstance(product, dict)
    )
    top_table = (
        "<table><thead><tr><th>商品</th><th>销量</th><th>销售额</th></tr></thead>"
        f"<tbody>{rows}</tbody></table>"
        if rows
        else "<div class='empty'>当前暂无渠道 Top Products。接入渠道销售、商品排行或平台榜单后，这里会显示。</div>"
    )
    return f"""
    <div class="muted">接口状态：{html.escape(status)} · 接口：{html.escape(str(fields.get("channel_analytics_url") or ""))}</div>
    <div class="muted">支持渠道：{html.escape(channel_text)}</div>
    <pre>{html.escape(json.dumps(summary, ensure_ascii=False, indent=2))}</pre>
    {top_table}
    """


def render_pod_portal_table(portal_status: dict[str, Any]) -> str:
    if not portal_status:
        return "<div class='empty'>暂未检测到可访问的 POD 端口。</div>"
    rows = []
    for name, payload in portal_status.items():
        payload = payload if isinstance(payload, dict) else {}
        ok = "可访问" if payload.get("ok") else "不可访问"
        url = str(payload.get("url") or "")
        title = str(payload.get("title") or payload.get("error") or "")
        url_html = f"<a href='{html.escape(url)}' target='_blank'>open</a>" if url else ""
        rows.append(
            "<tr>"
            f"<td>{html.escape(str(name))}</td>"
            f"<td>{html.escape(ok)}</td>"
            f"<td>{html.escape(title)}</td>"
            f"<td>{url_html}</td>"
            "</tr>"
        )
    return (
        "<table><thead><tr><th>入口</th><th>状态</th><th>标题/错误</th><th>链接</th></tr></thead>"
        f"<tbody>{''.join(rows)}</tbody></table>"
    )


def render_pod_list(items: Any) -> str:
    if not isinstance(items, list) or not items:
        return "<div class='empty'>暂无。</div>"
    return "<ul>" + "".join(f"<li>{html.escape(str(item))}</li>" for item in items) + "</ul>"


def public_model_label(model: dict[str, Any], locale: str | None = None) -> str:
    is_en = str(locale or "").lower().startswith("en")
    model_id = str(model.get("model") or "").strip()
    name = str(model.get("name") or "").lower()
    text = f"{name} {model_id}".lower()
    if "gemini" in text:
        vendor = "Gemini"
    elif "deepseek" in text:
        vendor = "DeepSeek"
    elif "zhipu" in text or "glm" in text:
        vendor = "Zhipu GLM" if is_en else "智谱 GLM"
    elif "claude" in text:
        vendor = "Claude"
    elif "gpt" in text or "openai" in text:
        vendor = "GPT"
    elif "qwen" in text or "siliconflow" in text:
        vendor = "Qwen"
    elif "longcat" in text:
        vendor = "LongCat"
    elif "agnes" in text:
        vendor = "Agnes"
    elif "kiro" in text:
        vendor = "Kiro"
    elif "local" in text or "ollama" in text:
        vendor = "Local Model" if is_en else "本地模型"
    else:
        vendor = "AI Model" if is_en else "AI模型"
    tier = str(model.get("tier") or "").replace("_", " ").strip()
    tier_label = f" · {tier}" if tier and tier.lower() not in {"recommended", "default"} else ""
    ready_label = (" · available" if model.get("ready") else " · not configured") if is_en else (" · 可用" if model.get("ready") else " · 未开通")
    return f"{vendor} · {model_id or 'custom model'}{tier_label}{ready_label}"


def render_chat_model_options(root: Path | None, locale: str | None = None) -> str:
    is_en = str(locale or "").lower().startswith("en")
    disconnected = "AI not connected (configure and test it in Settings)" if is_en else "AI 未连接（请到设置中配置并测试）"
    options: list[str] = []
    if root is None:
        return f'<option value="" selected disabled>{disconnected}</option>'
    try:
        models = account_center.list_models(root)
    except Exception:
        models = []
    visible_models = []
    for model in models:
        tasks = model.get("tasks") if isinstance(model.get("tasks"), list) else []
        if tasks and "chat" not in tasks and "default" not in tasks:
            continue
        if not model.get("enabled"):
            continue
        if not str(model.get("name") or "").strip():
            continue
        visible_models.append(model)
    visible_models.sort(key=lambda item: (not bool(item.get("ready")), int(item.get("priority") or 100), str(item.get("name") or "")))
    ready_models = [model for model in visible_models if model.get("ready")]
    if ready_models:
        options.append(
            f'<option value="">{"Auto select (recommended)" if is_en else "自动选择（推荐）"}</option>'
        )
    else:
        options.append(f'<option value="" selected disabled>{disconnected}</option>')
    seen: set[str] = {""}

    def append_group(label: str, group_models: list[dict], *, disabled: bool = False) -> None:
        if not group_models:
            return
        options.append(f'<optgroup label="{html.escape(label, quote=True)}">')
        for model in group_models:
            name = str(model.get("name") or "").strip()
            if not name or name in seen:
                continue
            seen.add(name)
            disabled_attr = " disabled" if disabled else ""
            label_text = public_model_label(model, locale)
            options.append(
                f'<option value="{html.escape(name, quote=True)}"{disabled_attr}>{html.escape(label_text)}</option>'
            )
        options.append("</optgroup>")

    pending_models = [model for model in visible_models if not model.get("ready")]
    append_group("Connected Models" if is_en else "已接通模型", ready_models)
    append_group("Not Configured (finish model setup first)" if is_en else "未接通模型（请先完成模型配置）", pending_models, disabled=True)
    return "".join(options)


