def render_chat_approval_queue_summary(
    root: Path | None,
    session_info: dict[str, Any] | None = None,
    limit: int = 5,
    store_scope: str = "",
    platform_scope: str = "",
    country_scope: str = "",
) -> tuple[str, list[str]]:
    if session_info and any([store_scope, platform_scope, country_scope]):
        session_info = session_with_query_scope(
            session_info,
            store=store_scope,
            platform=platform_scope,
            country=country_scope,
        )
    scope_values_for_queue = session_scope_context_values(session_info)
    restricted_scope = bool(scope_values_for_queue.get("restricted"))
    scope_label = (
        f'{scope_values_for_queue.get("platform_label") or "全部平台"} / '
        f'{scope_values_for_queue.get("store_label") or "全部店铺"}'
    )
    closure_text = approval_closure_standard_text()
    empty_text = (
        f"当前授权范围（{scope_label}）内没有待负责人确认的真实动作。后台 AI 发现发布、改价、退款、发货、授权或投广告风险时，会只按当前范围整理草稿、证据和风险，再进入确认队列。"
        if restricted_scope
        else "现在没有待负责人确认的真实动作。后台 AI 发现发布、改价、退款、发货、授权或投广告风险时，会自动整理草稿、证据和风险，再进入确认队列。"
    )
    empty_text = f"{empty_text} {closure_text}"
    approval_summary_prompt = (
        "请后台 AI 按当前待确认队列，总结负责人现在只需要看的证据、风险、回滚条件、后台任务包和执行后回写要求。"
    )
    approval_summary_button = (
        "<button type='button' class='secondary compact-link' "
        f"data-prompt='{html.escape(approval_summary_prompt, quote=True)}'>继续问AI确认摘要</button>"
    )
    if root is None:
        return (
            f"""
          <section class="approval-queue-summary">
            <h2>当前待确认队列</h2>
            <p>{html.escape(empty_text)}</p>
            <div class="compact-actions">{approval_summary_button}</div>
          </section>
""",
            ["当前待确认队列：0 条等待负责人确认，0 条已确认待负责人执行。"],
        )
    if not session_info:
        public_text = (
            "负责人登录后才显示具体店铺草稿、执行结果、草稿编号和回写证据；"
            "未登录只展示确认规则，不带出历史店铺、内部测试记录或执行包。 "
            f"{closure_text}"
        )
        return (
            f"""
          <section class="approval-queue-summary">
            <h2>当前待确认队列</h2>
            <p>{html.escape(public_text)}</p>
            <div class="compact-actions">{approval_summary_button}</div>
          </section>
""",
            ["当前待确认队列：未登录不展示具体店铺草稿、执行结果或草稿编号。"],
        )
    can_decide = bool(session_info and session_info.get("is_owner"))
    result_summary_html, result_context_cards = render_chat_approval_result_summary(root, session_info=session_info)
    actions = pending_actions_for_session_scope(root, session_info)
    pending_decision = [
        action
        for action in actions
        if str(action.get("status") or "pending_confirmation") == "pending_confirmation"
    ]
    approved_pending = [
        action
        for action in actions
        if str(action.get("status") or "") == "approved_pending_manual_execution"
    ]
    evidence_pending = [
        action
        for action in actions
        if str(action.get("status") or "") == "execution_needs_evidence"
    ]
    queue_actions = pending_decision + approved_pending + evidence_pending
    grouped: dict[tuple[str, str, str, str], list[dict[str, Any]]] = {}
    for action in queue_actions:
        status = str(action.get("status") or "pending_confirmation")
        if is_amazon_10001_owner_review_action(action):
            title = "Amazon 10001 负责人复核包"
            action_type = "amazon_10001_owner_review_package"
        else:
            title = customer_safe_action_title(approval_title_text(action))
            action_type = str(action.get("action_type") or "")
        scope_key = approval_action_group_scope_key(action)
        grouped.setdefault((status, action_type, title, scope_key), []).append(action)
    grouped_actions = sorted(
        grouped.values(),
        key=lambda group: (
            -approval_risk_score(group[0]),
            -safe_int(group[0].get("priority") or 0),
            customer_safe_action_title(approval_title_text(group[0])),
        ),
    )
    shown_groups = grouped_actions[:limit]
    context_cards = [
        (
            f"当前待确认队列：{len(pending_decision)} 条等待负责人确认，"
            f"{len(approved_pending)} 条已确认待负责人执行，"
            f"{len(evidence_pending)} 条待补执行证据，已按风险合并为 {len(grouped_actions)} 组。"
        )
    ]
    context_cards.append(f"负责人回写标准：{closure_text.removeprefix('负责人回写标准：')}")
    if restricted_scope:
        context_cards.append(f"当前账号授权范围：{scope_label}；待确认动作只显示这个范围内的草稿。")
    context_cards.extend(result_context_cards)
    if not shown_groups:
        return (
            f"""
          <section class="approval-queue-summary">
            <h2>当前待确认队列</h2>
            <p>{html.escape(empty_text)}</p>
            <div class="compact-actions">{approval_summary_button}</div>
          </section>
          {result_summary_html}
""",
            context_cards,
        )
    item_html: list[str] = []
    for group in shown_groups:
        if approval_group_is_amazon_10001_owner_review(group):
            summary = amazon_10001_owner_review_group_summary(group)
            action_refs = json.dumps([str(item.get("action_id") or "") for item in group], ensure_ascii=False)
            status_label, _stage_class = approval_status_label(str(group[0].get("status") or "pending_confirmation"))
            module_text = "、".join(dict.fromkeys(str(item) for item in summary["modules"] if str(item).strip()))
            missing_text = "、".join(summary["missing"][:6]) if summary["missing"] else "暂无关键缺口"
            blocked_text = "、".join(summary["blocked"][:6]) if summary["blocked"] else "不会自动执行外部动作"
            decision_html = ""
            if can_decide and str(group[0].get("status") or "pending_confirmation") == "pending_confirmation":
                decision_html = (
                    "<div class='approval-queue-decision'>"
                    "<textarea placeholder='负责人备注：确认、拒绝或暂缓原因'></textarea>"
                    "<div class='approval-queue-actions'>"
                    "<button type='button' class='approve' data-chat-approval-decision='approve'>确认这组草稿</button>"
                    "<button type='button' class='reject' data-chat-approval-decision='reject'>拒绝</button>"
                    "<button type='button' class='skip' data-chat-approval-decision='skip'>暂缓</button>"
                    "</div>"
                    f"<small>{html.escape(approval_confirmation_to_closure_text())}</small>"
                    "</div>"
                )
            item_html.append(
                f"<div class='approval-queue-item amazon-owner-review-card' data-action-refs='{html.escape(action_refs, quote=True)}' data-current-status='{html.escape(str(group[0].get('status') or 'pending_confirmation'), quote=True)}'>"
                "<strong>Amazon 10001 负责人复核包</strong>"
                f"<span>{html.escape(status_label)}</span>"
                f"<span>{html.escape(str(summary['module_count']))} 个模块</span>"
                f"<span>{html.escape(str(summary['profit_source']))}</span>"
                f"<small><b>店铺路线：</b>{html.escape(str(summary['route']))}</small>"
                f"<small><b>模块：</b>{html.escape(module_text)}</small>"
                f"<small><b>当前缺口：</b>{html.escape(missing_text)}</small>"
                f"<small><b>禁止动作：</b>{html.escape(blocked_text)}</small>"
                f"<small><b>负责人只需确认：</b>{html.escape('商品页、广告、优惠、回款四块草稿是否继续进入人工执行准备；系统不会上传、发布、开广告、发券、改价、改库存、发货或付款。')}</small>"
                f"{decision_html}"
                "</div>"
            )
            continue
        action = group[0]
        group_count = len(group)
        title = customer_safe_action_title(approval_title_text(action))
        status_label, _stage_class = approval_status_label(str(action.get("status") or "pending_confirmation"))
        action_type = approval_action_type_label_for_action(action)
        source_label = approval_source_category_label(action)
        risk_score = approval_risk_score(action)
        risk_label = approval_risk_label(risk_score)
        reason = approval_reason_text(action)
        if reason and len(reason) > 140:
            reason = reason[:137].rstrip() + "..."
        evidence = (
            f"{group_count} 条同类草稿来自同一类风险；{reason}"
            if group_count > 1
            else reason
        )
        evidence = evidence or "负责人确认前只看证据、影响范围和回滚条件。"
        if len(evidence) > 170:
            evidence = evidence[:167].rstrip() + "..."
        grouped_title = f"{title}（同类 {group_count} 条）" if group_count > 1 else title
        route_labels = approval_route_group_labels(group)
        route_text = "；".join(route_labels)
        route_html = (
            f"<small><b>{html.escape('覆盖路线' if len(route_labels) > 1 else '店铺路线')}：</b>{html.escape(route_text)}</small>"
            if route_text
            else ""
        )
        activity_boundary_html = f"<small><b>活动边界：</b>{html.escape(approval_activity_boundary_summary(action))}</small>"
        ads_boundary_html = f"<small><b>广告边界：</b>{html.escape(approval_ads_boundary_summary(action))}</small>"
        action_refs = ",".join(str(item.get("action_id") or "").strip() for item in group if str(item.get("action_id") or "").strip())
        status = str(action.get("status") or "pending_confirmation")
        checklist_summary = approval_activity_checklist_summary(action)
        detail_rows = []
        if checklist_summary:
            detail_rows.append(("后台核对", checklist_summary))
        detail_rows.append(("执行证据", approval_evidence_gap_summary(action)))
        detail_rows.append(("回滚条件", approval_rollback_text(action)))
        detail_html = (
            "<details class='approval-queue-details'><summary>查看证据、回写和回滚细节</summary>"
            + "".join(
                f"<small><b>{html.escape(label)}：</b>{html.escape(value)}</small>"
                for label, value in detail_rows
                if str(value or "").strip()
            )
            + "</details>"
        )
        if status == "pending_confirmation" and action_refs and can_decide:
            decision_target = f"这组 {group_count} 条" if group_count > 1 else "这项"
            if approval_action_is_ads_preflight(action):
                approve_label = (
                    "确认已读缺口，生成补资料清单"
                    if group_count == 1
                    else f"确认{decision_target}缺口，生成补资料清单"
                )
                reject_label = "拒绝这项缺口" if group_count == 1 else f"拒绝{decision_target}缺口"
                skip_label = "暂缓这项缺口" if group_count == 1 else f"暂缓{decision_target}缺口"
            else:
                approve_label = "同意，生成待执行包" if group_count == 1 else f"同意{decision_target}，生成待执行包"
                reject_label = "拒绝这项" if group_count == 1 else f"拒绝{decision_target}"
                skip_label = "暂缓" if group_count == 1 else f"暂缓{decision_target}"
            decision_html = (
                "<div class='approval-queue-decision'>"
                "<textarea placeholder='负责人备注：为什么同意、拒绝或暂缓'></textarea>"
                "<div class='approval-queue-actions'>"
                f"<button type='button' class='approve' data-chat-approval-decision='approve'>{html.escape(approve_label)}</button>"
                f"<button type='button' class='reject' data-chat-approval-decision='reject'>{html.escape(reject_label)}</button>"
                f"<button type='button' class='skip' data-chat-approval-decision='skip'>{html.escape(skip_label)}</button>"
                "</div>"
                f"<small>{html.escape(approval_confirmation_to_closure_text())}</small>"
                "</div>"
            )
        elif status == "pending_confirmation" and action_refs:
            decision_html = (
                "<small><b>当前状态：</b>等待负责人确认；当前账号只能查看授权范围内草稿，不能同意、拒绝或暂缓真实店铺动作。</small>"
            )
        elif status == "execution_needs_evidence":
            decision_html = f"<small><b>当前状态：</b>{html.escape(approval_evidence_gap_summary(action))}</small>"
        else:
            decision_html = f"<small><b>当前状态：</b>{html.escape(approval_confirmed_waiting_closure_text())}</small>"
        item_html.append(
            f"<div class='approval-queue-item' data-action-refs='{html.escape(action_refs, quote=True)}' data-current-status='{html.escape(status or 'pending_confirmation', quote=True)}'>"
            f"<strong>{html.escape(grouped_title)}</strong>"
            f"<span>{html.escape(status_label)}</span>"
            f"<span>{html.escape(source_label)}</span>"
            f"<span>{html.escape(action_type)}</span>"
            f"<span>{html.escape(risk_label)}</span>"
            f"{route_html}"
            f"{activity_boundary_html}"
            f"{ads_boundary_html}"
            f"<small><b>证据：</b>{html.escape(evidence)}</small>"
            f"<small><b>确认重点：</b>{html.escape(approval_impact_text(action))}</small>"
            f"{detail_html}"
            f"{decision_html}"
            "</div>"
        )
    hidden_groups = max(0, len(grouped_actions) - len(shown_groups))
    hidden_actions = max(0, len(queue_actions) - sum(len(group) for group in shown_groups))
    more_text = (
        f" 还有 {hidden_groups} 组 / {hidden_actions} 条未展开；后台 AI 已按风险合并，继续问可看每组证据和回滚条件。"
        if hidden_groups
        else " 已显示当前主要待确认动作，并按风险合并重复草稿。"
    )
    return (
        f"""
          <section class="approval-queue-summary">
            <h2>当前待确认队列</h2>
            <p>{html.escape(str(len(pending_decision)))} 条等待负责人确认，{html.escape(str(len(approved_pending)))} 条已确认待负责人执行，{html.escape(str(len(evidence_pending)))} 条待补执行证据；已按风险合并为 {html.escape(str(len(grouped_actions)))} 组。{html.escape(more_text)}</p>
            <div class="approval-summary-note">聊天里默认只放摘要和快速决定；证据、回写和回滚细节已折叠，负责人需要时再展开。</div>
            <div class="compact-actions">{approval_summary_button}</div>
            <div class="approval-queue-list">{''.join(item_html)}</div>
          </section>
          {result_summary_html}
""",
        context_cards,
    )


def render_chat_approval_result_summary(
    root: Path,
    session_info: dict[str, Any] | None = None,
    limit: int = 4,
    title: str = "最近负责人执行结果",
    description: str | None = None,
) -> tuple[str, list[str]]:
    section_title = title
    actions = approval_actions_for_session(load_action_queue(root, pending_only=False), session_info)
    allowed_action_ids = {str(action.get("action_id") or "").strip() for action in actions if str(action.get("action_id") or "").strip()}
    results = approval_records_for_session(
        sorted(read_records(root, "execution_result"), key=lambda record: record.created_at, reverse=True),
        session_info,
        allowed_action_ids=allowed_action_ids,
    )
    results = filter_current_real_value_records(root, results)
    if not results:
        return "", [f"{section_title}：暂无已记录执行结果。"]

    cards: list[str] = []
    context_cards = [f"{section_title}：{len(results)} 条已记录执行结果；助手会带上草稿编号、ERP回写、负责人确认、回滚状态和证据完整度。"]
    for record in results[:limit]:
        fields = record.fields
        action_title = customer_safe_execution_result_title(fields)
        route_key = str(fields.get("route_key") or fields.get("cloud_route_key") or "").strip()
        route_label = customer_route_key_label(route_key) if route_key else ""
        store_name = approval_customer_visible_execution_store_name(fields.get("store_name") or fields.get("store_id") or "")
        if store_name and store_name not in route_label:
            route_label = f"{route_label} - {store_name}" if route_label else store_name
        outcome = str(fields.get("outcome") or "unknown")
        outcome_label = {"unknown": "等待 24-72 小时数据", "success": "表现可复盘", "failed": "执行未达预期"}.get(outcome, outcome)
        draft_id = customer_safe_execution_draft_reference(fields.get("execution_draft_id"))
        evidence_complete = "证据回写完整" if fields.get("execution_evidence_complete") else "执行证据待补"
        erp_status = customer_safe_erp_writeback_status(fields.get("erp_writeback_status"))
        owner_status = customer_safe_owner_confirmation_status(fields.get("owner_confirmation_status"))
        rollback_status = customer_safe_rollback_status(fields.get("rollback_status"))
        rows = [
            ("执行范围", route_label or "路径待确认"),
            ("草稿/编号", draft_id),
            ("ERP", erp_status),
            ("负责人", owner_status),
            ("回滚", rollback_status),
            ("证据", evidence_complete),
            ("执行边界", "系统未自动提交平台"),
        ]
        rows_html = "".join(
            f"<small><b>{html.escape(label)}：</b>{html.escape(value)}</small>"
            for label, value in rows
            if str(value or "").strip()
        )
        cards.append(
            "<div class='approval-result-item'>"
            f"<strong>{html.escape(action_title)}</strong>"
            "<span>已记录执行结果</span>"
            f"<span>{html.escape(outcome_label)}</span>"
            f"{rows_html}"
            f"{render_execution_customer_result_summary(record, outcome_label)}"
            "</div>"
        )
        context_cards.append(
            "负责人手动执行结果回写："
            f"{action_title}；{route_label or '路径待确认'}；{erp_status}；{owner_status}；回滚 {rollback_status}；{evidence_complete}；系统未自动提交平台。"
        )

    hidden_count = max(0, len(results) - len(cards))
    hidden_text = f" 还有 {hidden_count} 条已收进后台记录，继续问 AI 可按店铺路线复盘。" if hidden_count else ""
    description_text = description or "负责人手动执行后的截图/编号、ERP回写、负责人最终确认和回滚状态会在这里带给 AI；系统不会自动提交外部平台。"
    return (
        "<section class='approval-result-summary'>"
        f"<h2>{html.escape(section_title)}</h2>"
        f"<p>{html.escape(description_text)}{html.escape(hidden_text)}</p>"
        f"<div class='approval-result-list'>{''.join(cards)}</div>"
        "</section>",
        context_cards,
    )


def execution_result_context_lines_for_chat(
    root: Path | None,
    session_info: dict[str, Any] | None,
    limit: int = 5,
) -> list[str]:
    if root is None or not session_info:
        return []
    actions = approval_actions_for_session(load_action_queue(root, pending_only=False), session_info)
    allowed_action_ids = {
        str(action.get("action_id") or "").strip()
        for action in actions
        if str(action.get("action_id") or "").strip()
    }
    results = approval_records_for_session(
        sorted(read_records(root, "execution_result"), key=lambda record: record.created_at, reverse=True),
        session_info,
        allowed_action_ids=allowed_action_ids,
    )
    results = filter_current_real_value_records(root, results)
    lines: list[str] = []
    for record in results[:limit]:
        fields = record.fields if isinstance(record.fields, dict) else {}
        title = customer_safe_execution_result_title(fields)
        route_key = str(fields.get("route_key") or fields.get("cloud_route_key") or "").strip()
        route_label = customer_route_key_label(route_key) if route_key else "路径待确认"
        store_name = approval_customer_visible_execution_store_name(fields.get("store_name") or fields.get("store_id") or "")
        if store_name and store_name not in route_label:
            route_label = f"{route_label} - {store_name}" if route_label else store_name
        outcome = str(fields.get("outcome") or "unknown")
        outcome_label = {"unknown": "等待 24-72 小时数据", "success": "表现可复盘", "failed": "执行未达预期"}.get(outcome, outcome)
        draft_id = customer_safe_execution_draft_reference(fields.get("execution_draft_id"))
        evidence_complete = "证据回写完整" if fields.get("execution_evidence_complete") else "执行证据待补"
        erp_status = customer_safe_erp_writeback_status(fields.get("erp_writeback_status"))
        owner_status = customer_safe_owner_confirmation_status(fields.get("owner_confirmation_status"))
        rollback_status = customer_safe_rollback_status(fields.get("rollback_status"))
        owner_review_evidence = amazon_10001_owner_review_evidence_summary(fields)
        repair_followup_evidence = amazon_10001_repair_followup_evidence_summary(fields)
        evidence_parts = [item for item in [owner_review_evidence, repair_followup_evidence] if item]
        owner_review_part = ("；" + "；".join(evidence_parts)) if evidence_parts else ""
        lines.append(
            customer_safe_activity_context_line(
                f"负责人手动执行结果回写 {title}；范围 {route_label}；草稿/编号 {draft_id}；"
                f"{erp_status}；{owner_status}；回滚 {rollback_status}；"
                f"证据 {evidence_complete}{owner_review_part}；结果 {outcome_label}；系统未自动提交平台"
            )
        )
    return lines


def approval_closure_standard_text() -> str:
    return "负责人回写标准：确认前只看证据、影响范围和回滚条件；确认后只生成后台待执行包；负责人手动执行后必须回写截图或草稿编号、ERP回写状态、负责人最终确认和回滚状态，系统不自动提交外部平台。"


def approval_pending_closure_requirement_text() -> str:
    return "负责人手动执行后必须回写截图/编号、ERP状态、负责人最终确认和回滚状态；缺一项不会闭环。"


def approval_confirmation_to_closure_text() -> str:
    return "同意后只生成后台待执行包，不会自动提交平台、改价、发券、投广告、退款或发货；执行后必须补截图/编号、ERP回写、负责人最终确认和回滚状态。"


def approval_confirmed_waiting_closure_text() -> str:
    return "已确认，等待负责人按官方后台执行；执行后必须回写截图/编号、ERP状态、负责人最终确认和回滚状态，缺一项不会闭环。"


def chat_context_line_matches_session_scope(
    line: str,
    session_info: dict[str, Any] | None,
    *,
    require_store_match: bool = True,
) -> bool:
    if not session_scope_is_restricted(session_info):
        return True
    values = session_scope_context_values(session_info)
    text = str(line or "")
    if not text.strip():
        return False
    platform_values = [str(item) for item in values["platform_values"] if str(item).lower() != "all"]
    store_values = [str(item) for item in values["store_values"] if str(item).lower() != "all"]
    country_aliases = {
        "US": ["US", "美国站", "美国"],
        "GB": ["GB", "英国站", "英国"],
        "SG": ["SG", "新加坡站", "新加坡"],
        "MY": ["MY", "马来西亚站", "马来西亚"],
        "TH": ["TH", "泰国站", "泰国"],
        "VN": ["VN", "越南站", "越南"],
        "PH": ["PH", "菲律宾站", "菲律宾"],
        "ID": ["ID", "印尼站", "印尼", "印度尼西亚"],
        "MX": ["MX", "墨西哥站", "墨西哥"],
        "BR": ["BR", "巴西站", "巴西"],
    }
    country_values: list[str] = []
    country_keys: set[str] = set()
    for item in values.get("country_values", []):
        clean = str(item).strip()
        if not clean or clean.lower() == "all":
            continue
        country_key = clean.upper()
        country_keys.add(country_key)
        country_values.extend(country_aliases.get(country_key, [clean]))
    platform_ok = not platform_values or scope_value_matches(text, platform_values)
    store_ok = not require_store_match or not store_values or scope_value_matches(text, store_values)
    country_ok = not country_values or scope_value_matches(text, country_values)
    if country_ok and country_keys:
        for country_key, aliases in country_aliases.items():
            if country_key in country_keys:
                continue
            for alias in aliases:
                alias_text = str(alias or "").strip()
                if not alias_text:
                    continue
                if re.fullmatch(r"[A-Z]{2}", alias_text):
                    if re.search(rf"(?<![A-Z0-9]){re.escape(alias_text)}(?![A-Z0-9])", text):
                        return False
                elif alias_text in text:
                    return False
    return platform_ok and store_ok and country_ok


def store_erp_snapshot_for_chat(root: Path | None, session_info: dict[str, Any] | None = None) -> dict[str, Any]:
    if root is None or not session_info:
        manifest = build_store_data_manifest(root, session_info, {})
        return {
            "gaps": ["店铺授权", "订单/销售", "广告", "退款/售后", "财务结算", "库存", "商品状态"],
            "summary": {},
            "store_count": 0,
            "pending_count": 0,
            "has_data": False,
            "latest_day": "",
            "connection_lines": [],
            "route_lines": [],
            "activity_lines": [],
            "activity_boundary_lines": [],
            "developer_capability_lines": [],
            "execution_result_lines": [],
            "data_manifest": manifest,
            "manifest_lines": manifest.get("lines") or [],
        }
    scope_store = first_scope_value(session_info.get("store_scope") if session_info else "")
    scope_platform = first_scope_value(session_info.get("platform_scope") if session_info else "")
    metric_scope_filters = session_metric_scope_filters(session_info)
    metrics = summarize_store_metrics(
        root,
        platform=scope_platform or None,
        store=scope_store or None,
        grain="day",
        **metric_scope_filters,
    )
    latest_metric_day = ""
    if not metric_bucket_has_business_value(metrics.get("summary", {})):
        latest_metric_day = latest_real_store_metric_day(root, session_info)
        if latest_metric_day:
            latest_metrics = summarize_store_metrics(
                root,
                start=latest_metric_day,
                end=latest_metric_day,
                platform=scope_platform or None,
                store=scope_store or None,
                grain="day",
                **metric_scope_filters,
            )
            if metric_bucket_has_business_value(latest_metrics.get("summary", {})):
                metrics = latest_metrics
    summary = metrics.get("summary", {})
    profile = account_center.load_profile(root)
    profile_stores = [store for store in (profile.get("stores") or []) if isinstance(store, dict)]
    store_profiles = real_store_profile_records(root)
    imported_metric_stores = imported_store_metric_identity_rows(root)
    if session_scope_is_restricted(session_info):
        profile_stores = [store for store in profile_stores if profile_store_matches_session_scope(store, session_info)]
        store_profiles = [record for record in store_profiles if store_record_matches_session_scope(record, session_info)]
        imported_metric_stores = [item for item in imported_metric_stores if metric_store_row_matches_session_scope(item, session_info)]
    explicit_store_count = count_connected_store_identities(profile_stores, store_profiles)
    store_count = count_connected_store_identities(profile_stores, store_profiles, imported_metric_stores)
    has_imported_metric_store_only = bool(imported_metric_stores) and not explicit_store_count
    listing_count = count_records_for_session_scope(root, ["listing_snapshot"], session_info)
    order_count = count_records_for_session_scope(root, ["order_item"], session_info) or int(summary.get("orders") or 0)
    inventory_count = count_records_for_session_scope(root, ["inventory_ledger"], session_info)
    refund_count = count_records_for_session_scope(root, ["refund_record"], session_info) or int(summary.get("return_count") or 0)
    finance_count = count_records_for_session_scope(root, ["finance_transaction"], session_info) or (1 if (summary.get("revenue") or summary.get("settlement_amount")) else 0)
    ad_count = count_records_for_session_scope(root, ["ad_performance_signal"], session_info) or (1 if summary.get("ad_spend") else 0)
    gaps: list[str] = []
    if not store_count:
        gaps.append("店铺授权")
    elif has_imported_metric_store_only:
        gaps.append("店铺连接档案")
    if not order_count:
        gaps.append("订单/销售")
    if not listing_count:
        gaps.append("商品状态")
    if not inventory_count:
        gaps.append("库存")
    if not refund_count:
        gaps.append("退款/售后")
    if not finance_count:
        gaps.append("财务结算")
    if not ad_count:
        gaps.append("广告")
    pending_count = len(pending_actions_for_session_scope(root, session_info))
    connection_lines = store_connection_context_lines_for_chat(profile_stores, store_profiles, imported_metric_stores)
    visible_store_count = customer_visible_store_connection_count(connection_lines, store_count)
    route_rows = build_channel_route_readiness(root, profile_stores)
    activity_rows = build_platform_activity_readiness(root, profile_stores)
    route_lines = store_route_context_lines_for_chat(route_rows)
    activity_lines = store_activity_context_lines_for_chat(activity_rows)
    activity_boundary_lines = platform_activity_boundary_summary_lines(root, limit=8)
    developer_capability_lines = store_developer_capability_context_lines_for_chat(root, profile_stores)
    execution_result_lines = execution_result_context_lines_for_chat(root, session_info)
    if session_scope_is_restricted(session_info):
        connection_lines = [
            line for line in connection_lines if chat_context_line_matches_session_scope(line, session_info)
        ]
        route_lines = [line for line in route_lines if chat_context_line_matches_session_scope(line, session_info)]
        activity_lines = [
            line
            for line in activity_lines
            if chat_context_line_matches_session_scope(line, session_info, require_store_match=False)
        ]
        developer_capability_lines = [
            line
            for line in developer_capability_lines
            if chat_context_line_matches_session_scope(line, session_info, require_store_match=False)
        ]
    data_manifest = build_store_data_manifest(root, session_info, summary)
    return {
        "gaps": gaps,
        "summary": summary,
        "store_count": visible_store_count,
        "pending_count": pending_count,
        "has_data": metric_bucket_has_business_value(summary),
        "latest_day": latest_metric_day,
        "connection_lines": connection_lines,
        "route_lines": route_lines,
        "activity_lines": activity_lines,
        "activity_boundary_lines": activity_boundary_lines,
        "developer_capability_lines": developer_capability_lines,
        "execution_result_lines": execution_result_lines,
        "data_manifest": data_manifest,
        "manifest_lines": data_manifest.get("lines") or [],
    }


def store_route_context_lines_for_chat(route_rows: list[dict[str, Any]]) -> list[str]:
    lines: list[str] = []
    seen: set[tuple[str, str, str, str]] = set()
    for row in route_rows[:8]:
        route_key = str(row.get("route_key") or "").strip()
        if not route_key:
            continue
        route_label = customer_route_key_label(route_key)
        raw_source = str(row.get("source_label") or row.get("source_type") or "").strip()
        status = customer_safe_machine_text(row.get("status") or "status_pending")
        matched_store = str(row.get("matched_store") or "").strip() or "未匹配后台平台店铺"
        visibility_note = str(row.get("store_visibility_note") or "").strip()
        if "历史/测试痕迹" in visibility_note or "历史/测试" in matched_store:
            matched_store = "历史/测试店铺（不作为真实店铺拉单、投放或外部执行）"
        else:
            matched_store = customer_visible_store_reference_name(
                matched_store,
                route_label=route_label,
                fallback="未匹配后台平台店铺",
            )
        source = customer_visible_store_reference_name(
            raw_source,
            route_label=route_label,
            fallback=customer_safe_machine_text(raw_source, empty=""),
        )
        dedupe_store = matched_store
        dedupe_key = (route_key, status, dedupe_store, visibility_note)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        next_step = str(row.get("next_step") or "").strip() or "等待后台确认上架路径后再进入映射。"
        source_text = f"；来源 {source}" if source else ""
        visibility_text = f"；连接性质 {visibility_note}" if visibility_note else ""
        lines.append(
            customer_safe_activity_context_line(
                f"上架路径 {route_label}；状态 {status}；匹配店铺 {matched_store}{source_text}{visibility_text}；下一步 {next_step}"
            )
        )
    return lines


def store_activity_context_lines_for_chat(activity_rows: list[dict[str, Any]]) -> list[str]:
    lines: list[str] = []
    seen: set[tuple[str, str, str]] = set()
    for row in activity_rows[:8]:
        route_key = str(row.get("route_key") or "").strip()
        if not route_key:
            continue
        route_label = customer_route_key_label(route_key)
        activity_types = customer_safe_machine_list(row.get("activity_types") or [], empty="活动类型待维护")
        stacking_rules = customer_safe_machine_list(row.get("stacking_rules") or [], empty="叠加规则待复核")
        platform_boundary = customer_safe_machine_text(row.get("api_boundary") or "rules_need_review")
        ads_boundary = customer_safe_machine_text(row.get("ads_boundary") or "rules_need_review")
        readiness_label = str(row.get("execution_readiness_label") or "只能草稿").strip()
        dedupe_key = (route_key, customer_safe_machine_text(row.get("status") or "rules_need_review"), readiness_label)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        guardrails = " / ".join(
            item
            for item in [
                customer_safe_machine_text(row.get("margin_guardrail") or ""),
                customer_safe_machine_text(row.get("inventory_guardrail") or ""),
            ]
            if item and item != "待后台 AI 复核"
        ) or "利润和库存待复核"
        confirm_text = "必须负责人确认" if row.get("confirmation_required", True) else "可进入自动草稿"
        next_step = str(row.get("next_step") or "").strip() or "先生成活动草稿、叠加校验和确认包。"
        auth_requirements = row.get("authorization_requirements") if isinstance(row.get("authorization_requirements"), list) else []
        execution_surfaces = row.get("execution_surfaces") if isinstance(row.get("execution_surfaces"), list) else []
        real_submission_requires = (
            row.get("real_submission_requires") if isinstance(row.get("real_submission_requires"), list) else []
        )
        auth_text = customer_safe_machine_list(auth_requirements, limit=5, empty="")
        surface_text = customer_safe_machine_list(execution_surfaces, limit=5, empty="")
        submission_text = customer_safe_machine_list(real_submission_requires, limit=5, empty="")
        customer_boundary = str(row.get("customer_execution_boundary") or "").strip()
        cloud_reason = str(row.get("cloud_plugin_reason") or "").strip()
        extra_parts = []
        if auth_text:
            extra_parts.append(f"授权要求 {auth_text}")
        if surface_text:
            extra_parts.append(f"执行后台 {surface_text}")
        if submission_text:
            extra_parts.append(f"提交门槛 {submission_text}")
        if customer_boundary:
            extra_parts.append(f"客户边界 {customer_boundary}")
        if cloud_reason:
            extra_parts.append(f"后台执行身份原因 {cloud_reason}")
        extra_parts.append(f"规则到任务 {activity_rule_to_task_summary(row)}")
        site_difference = activity_site_display_text(row)
        if site_difference and "按平台通用规则" not in site_difference:
            extra_parts.append(f"站点差异 {site_difference}")
        extra_text = "；" + "；".join(extra_parts) if extra_parts else ""
        line = (
            f"活动路径 {route_label}；状态 {customer_safe_machine_text(row.get('status') or 'rules_need_review')}；"
            f"执行状态 {readiness_label}；"
            f"活动类型 {activity_types}；叠加规则 {stacking_rules}；"
            f"执行边界 {customer_safe_machine_text(row.get('execution_mode') or 'draft_then_confirmation')}；"
            f"连接/广告 {platform_boundary} / {ads_boundary}；"
            f"利润/库存 {guardrails}；确认 {confirm_text}{extra_text}；下一步 {next_step}"
        )
        lines.append(customer_safe_activity_context_line(line))
    return lines


def platform_activity_boundary_summary_lines(root: Path | None, limit: int = 8) -> list[str]:
    if root is None:
        return []
    priority_channels = [
        "amazon",
        "walmart",
        "etsy",
        "ebay",
        "shopify",
        "woocommerce",
        "tiktok_shop",
        "shein",
        "shopee",
        "lazada",
    ]
    channel_labels = {
        "amazon": "Amazon",
        "walmart": "Walmart",
        "etsy": "Etsy",
        "ebay": "eBay",
        "shopify": "Shopify",
        "woocommerce": "WooCommerce",
        "tiktok_shop": "TikTok Shop",
        "shein": "SHEIN",
        "shopee": "Shopee",
        "lazada": "Lazada",
    }

    def add_labels(target: list[str], values: Any, *, max_items: int = 3) -> None:
        for value in rule_list(values):
            label = humanize_activity_token_for_display(str(value))
            if "_" in label:
                continue
            if not label or label in target:
                continue
            target.append(label)
            if len(target) >= max_items:
                break

    overrides_by_channel: dict[str, list[dict[str, Any]]] = {}
    for item in load_platform_activity_site_overrides(root):
        if not isinstance(item, dict):
            continue
        channel = str(item.get("channel_id") or "").strip()
        if channel:
            overrides_by_channel.setdefault(channel, []).append(item)

    lines: list[str] = []
    for channel in priority_channels:
        overrides = overrides_by_channel.get(channel) or []
        if not overrides:
            continue
        countries: list[str] = []
        ads_notes: list[str] = []
        rule_notes: list[str] = []
        submission_notes: list[str] = []
        for item in overrides:
            for country in rule_list(item.get("countries") or item.get("sites")):
                country_text = str(country).strip().upper()
                if country_text and country_text not in countries:
                    countries.append(country_text)
            add_labels(ads_notes, item.get("site_ads_notes") or item.get("ads_notes"), max_items=2)
            add_labels(rule_notes, item.get("site_rule_notes") or item.get("rule_notes"), max_items=2)
            add_labels(submission_notes, item.get("real_submission_requires_add"), max_items=1)
        if not (ads_notes or rule_notes or submission_notes):
            continue
        country_text = " / ".join(countries[:4]) if countries else "GLOBAL"
        if len(countries) > 4:
            country_text += " 等"
        parts = []
        if ads_notes:
            parts.append("广告：" + " / ".join(ads_notes[:2]))
        if rule_notes:
            parts.append("活动：" + " / ".join(rule_notes[:2]))
        if submission_notes:
            parts.append("确认：" + " / ".join(submission_notes[:1]))
        line = f"{channel_labels.get(channel, channel)} / {country_text}；" + "；".join(parts)
        if len(line) > 180:
            line = line[:177].rstrip("；/，, ") + "..."
        lines.append(customer_safe_activity_context_line(line))
        if len(lines) >= limit:
            break
    return lines


def render_platform_activity_boundary_summary_panel(lines: list[str]) -> str:
    if not lines:
        return ""
    item_html = "".join(f"<li>{html.escape(line)}</li>" for line in lines[:8])
    return f"""
    <section class="panel activity-boundary-summary">
      <h2>跨平台活动 / 广告边界</h2>
      <p class="muted">后台 AI 已把活动、优惠叠加、广告账号、平台连接和后台任务包按平台 + 国家站点 + 店铺模式 + 归属拆开，并用于后续自动分析和待确认队列。</p>
      <ul class="plain-list">{item_html}</ul>
    </section>
"""


def render_compact_platform_activity_boundary_summary(
    root: Path | None,
    *,
    title: str = "活动 / 广告执行边界",
    limit: int = 4,
) -> str:
    lines = platform_activity_boundary_summary_lines(root, limit=limit)
    if not lines:
        return ""
    item_html = "".join(f"<li>{html.escape(line)}</li>" for line in lines[:limit])
    return f"""
      <section class="panel activity-boundary-summary">
        <h2>{html.escape(title)}</h2>
        <p class="muted">后台 AI 已按平台、国家站点、店铺模式和归属拆开活动、优惠叠加、广告账号、平台连接和后台任务包；真实提交仍进负责人确认。</p>
        <ul class="plain-list">{item_html}</ul>
      </section>
"""


def store_developer_capability_context_lines_for_chat(
    root: Path | None,
    profile_stores: list[dict[str, Any]],
) -> list[str]:
    if root is None:
        return []
    capabilities = load_platform_capabilities(root)
    if not capabilities:
        return []
    wanted_channels = {
        str(store.get("platform_id") or store.get("platform") or "").strip()
        for store in profile_stores
        if str(store.get("platform_id") or store.get("platform") or "").strip()
    }
    wanted_countries = {
        str(store.get("country_code") or "").strip().upper()
        for store in profile_stores
        if str(store.get("country_code") or "").strip()
    }
    wanted_models = {
        normalize_channel_store_model_for_route(store.get("shop_type") or store.get("store_model"))
        for store in profile_stores
        if str(store.get("shop_type") or store.get("store_model") or "").strip()
    }
    matrix_model_by_channel: dict[str, set[str]] = {}
    for item in load_platform_execution_capability_matrix(root):
        channel = str(item.get("channel_id") or "").strip()
        if not channel:
            continue
        models = {
            normalize_channel_store_model_for_route(value)
            for value in rule_list(item.get("store_models"))
            if str(value or "").strip()
        }
        if models:
            matrix_model_by_channel.setdefault(channel, set()).update(models)
    matched: list[dict[str, Any]] = []
    for item in capabilities:
        channel = str(item.get("channel_id") or "").strip()
        sites = [str(site).strip().upper() for site in (item.get("sites") or []) if str(site).strip()]
        item_models = matrix_model_by_channel.get(channel, set())
        if wanted_channels and channel not in wanted_channels:
            continue
        if wanted_countries and sites and not any(country in sites for country in wanted_countries):
            continue
        if wanted_models and item_models and not (wanted_models & item_models):
            continue
        matched.append(item)
    if not matched and wanted_channels:
        matched = [
            item
            for item in capabilities
            if str(item.get("channel_id") or "").strip() in wanted_channels
        ]
    if not matched:
        matched = capabilities[:4]

    lines: list[str] = []
    for item in matched[:6]:
        channel = str(item.get("channel_id") or "").strip()
        label = str(item.get("label") or channel or "平台待确认").strip()
        sites = [str(site).strip().upper() for site in (item.get("sites") or []) if str(site).strip()]
        site_text = " / ".join(sites[:8]) if sites else "GLOBAL"
        model_candidates = sorted(matrix_model_by_channel.get(channel, set()) & wanted_models) if wanted_models else []
        if not model_candidates:
            model_candidates = sorted(matrix_model_by_channel.get(channel, set()))[:6]
        model_text = customer_safe_machine_list(model_candidates, empty="店铺模式待确认")
        listing = customer_safe_machine_text(item.get("listing"), empty="上架能力待确认")
        order = customer_safe_machine_text(item.get("order"), empty="拉单能力待确认")
        shipment = customer_safe_machine_text(item.get("shipment"), empty="物流回传待确认")
        settlement = customer_safe_machine_text(item.get("settlement"), empty="结算映射待确认")
        promo = " / ".join(
            value
            for value in [
                customer_safe_machine_text(item.get("discount"), empty=""),
                customer_safe_machine_text(item.get("promotion"), empty=""),
            ]
            if value
        ) or "优惠/活动待确认"
        ads = customer_safe_machine_text(item.get("ads"), empty="广告能力待确认")
        binding_policy = " / ".join(
            value
            for value in [
                str(item.get("authorization_surface") or "").strip(),
                str(item.get("store_binding_policy") or "").strip(),
                str(item.get("cloud_plugin_policy") or "").strip(),
            ]
            if value
        )
        if not usable_display_text(binding_policy):
            binding_policy = default_capability_binding_policy(channel)
        customer_boundary = str(item.get("customer_boundary") or "").strip()
        if not usable_display_text(customer_boundary):
            customer_boundary = default_capability_customer_boundary(channel)
        detail_text = platform_capability_detail_text(item)
        lines.append(
            f"平台连接能力 {label}；站点 {site_text}；"
            f"店铺模式 {model_text}；"
            f"上架 {listing}；拉单 {order}；物流 {shipment}；结算 {settlement}；"
            f"优惠/活动 {promo}；广告 {ads}；细分 {detail_text}；"
            f"绑定/后台 {binding_policy}；客户边界 {customer_boundary}"
        )
    return lines


def store_connection_context_lines_for_chat(
    profile_stores: list[dict[str, Any]],
    store_profiles: list[IntakeRecord],
    imported_metric_stores: list[dict[str, str]],
) -> list[str]:
    lines: list[str] = []
    seen: set[tuple[str, str, str, str]] = set()
    for store in profile_stores[:4]:
        platform = str(store.get("platform_label") or store.get("platform_id") or "").strip() or "未确认平台"
        name = customer_visible_store_name_for_store(store, fallback="当前授权店铺")
        country = str(store.get("country_code") or "").strip().upper() or "国家待确认"
        method = str(store.get("connection_method") or "manual_report_or_authorized_connection").strip()
        scopes = normalize_store_authorization_scopes(store.get("authorization_scopes"))
        data_scope = "、".join(scopes[:8]) if scopes else "权限范围待确认"
        store_external_id = str(store.get("store_external_id") or "").strip()
        sub_store_name = str(store.get("sub_store_name") or "").strip()
        store_identity = store_identity_scope_label(store, empty="店铺范围待确认")
        route_missing = store_route_missing_prerequisites(store)
        sync_status = store_connection_sync_status(method, key_present=bool(store.get("key_present")))
        failure_reason = store_connection_failure_reason(method, key_present=bool(store.get("key_present")))
        next_step = store_connection_next_step(method, key_present=bool(store.get("key_present")))
        connection_note = store_connection_visibility_note(store, route_missing=route_missing)
        dedupe_name = "历史/测试店铺" if "历史/测试痕迹" in connection_note else name
        dedupe_key = (platform, country, dedupe_name, store_identity)
        if dedupe_key in seen:
            continue
        seen.add(dedupe_key)
        if "platform_store_identity" in route_missing and method == "official_authorization":
            sync_status = "平台店铺身份待确认，暂不进入系统连接或外部执行"
            failure_reason = "缺平台店铺编号、卖家ID或真实平台店铺身份；内部备注不能替代平台身份"
            next_step = store_route_pending_next_step(store)
        line = (
            f"{platform} / {name} / {country}；"
            f"连接性质 {connection_note}；"
            f"店铺范围 {store_identity}；"
            f"接入方式 {connection_method_label(method)}；"
            f"权限范围 {data_scope}；"
            f"{store_connection_ads_status(store)}；"
            f"{store_connection_business_center_status(store)}；"
            f"{store_connection_site_limit_status(store)}；"
            f"同步状态 {sync_status}；"
            f"失败/限制 {failure_reason}；"
            f"后台下一步 {next_step}"
        )
        lines.append(customer_safe_activity_context_line(line))
    if not lines:
        for record in store_profiles[:3]:
            fields = record.fields
            platform = str(fields.get("marketplace") or fields.get("platform") or fields.get("source_platform") or "").strip()
            name = customer_visible_store_reference_name(
                fields.get("store_name") or fields.get("store_id") or "",
                fallback="当前授权店铺",
            )
            country = str(fields.get("country_code") or fields.get("shop_region") or "").strip().upper()
            if platform or name:
                lines.append(
                    customer_safe_activity_context_line(
                        f"{platform or '未确认平台'} / {name or '当前授权店铺'} / {country or '国家待确认'}；"
                        "已接入店铺档案；后台 AI 等待读取订单、广告、退款、财务、库存和商品状态。"
                    )
                )
    if not lines:
        for item in imported_metric_stores[:3]:
            platform = str(item.get("platform") or "").strip()
            name = customer_visible_store_reference_name(item.get("name") or "", fallback="当前授权店铺")
            country = str(item.get("country") or "").strip().upper()
            if platform or name:
                lines.append(
                    customer_safe_activity_context_line(
                        f"{platform or '未确认平台'} / {name or '当前授权店铺'} / {country or '国家待确认'}；"
                        "已从经营报表识别，等待负责人确认连接档案。"
                    )
                )
    return lines


def chat_status_customer_visible_line(label: str, line: str) -> str:
    """Keep chat status panels readable; detailed rule surfaces stay in backend context."""
    text = str(line or "").strip()
    if not text:
        return ""

    def part_after(prefix: str) -> str:
        marker = f"{prefix} "
        for part in text.split("；"):
            part = part.strip()
            if part.startswith(marker):
                return part[len(marker) :].strip()
        return ""

    def compact_slash_list(value: str, limit: int = 3) -> str:
        items = [item.strip() for item in str(value or "").split(" / ") if item.strip()]
        if len(items) > limit:
            return " / ".join(items[:limit]) + " / 等"
        return " / ".join(items)

    if label == "真实数据清单":
        name = text.split("：", 1)[0].strip()
        status = text.split("：", 1)[1].split("；", 1)[0].strip() if "：" in text else "待读取"
        next_step = part_after("下一步")
        if not next_step:
            next_step = "后台 AI 继续读取证据，客户只看结果和待确认动作。"
        return f"{name}：{status}；{next_step}"
    if label == "店铺连接档案":
        head = text.split("；", 1)[0].strip()
        connection_note = part_after("连接性质")
        if "历史/测试痕迹" in connection_note:
            head = "历史/测试店铺"
        elif re.search(r"\bround\s*\d+\b", head, flags=re.IGNORECASE):
            head_parts = [item.strip() for item in head.split(" / ") if item.strip()]
            platform = head_parts[0] if head_parts else "当前平台"
            country = head_parts[-1] if len(head_parts) >= 3 else ""
            head = f"{platform} / {country} 店铺".strip()
        store_scope = part_after("店铺范围")
        method = part_after("接入方式")
        sync_status = part_after("同步状态")
        ads_status = ""
        for part in text.split("；"):
            if "广告" in part and ("已登记" in part or "未登记" in part or "等待" in part):
                ads_status = part.strip()
                break
        bits = [head]
        if connection_note:
            bits.append(f"连接性质 {connection_note}")
        if store_scope:
            bits.append(f"店铺范围 {store_scope}")
        if method:
            bits.append(f"接入方式 {method}")
        if ads_status:
            bits.append(ads_status)
        if sync_status:
            bits.append(f"后台 AI {sync_status}")
        else:
            bits.append("后台 AI 继续核对订单、广告、退款、库存和结算。")
        return "；".join(bits)
    if label == "平台/国家/店铺模式":
        route = text.split("；", 1)[0].strip()
        status = part_after("状态")
        connection_note = part_after("连接性质")
        next_step = part_after("下一步")
        status_text = f"状态 {status}" if status else "状态待确认"
        if "系统连接" in text or "API" in text or "映射" in text:
            next_step = "后台 AI 已识别店铺路径，继续等待读取真实经营数据。"
        elif not next_step:
            next_step = "没有匹配后台平台店铺时，后台 AI 继续核对店铺路径，不上架、不拉单、不投广告。"
        connection_text = f"；连接性质 {connection_note}" if connection_note else ""
        return f"{route}；{status_text}{connection_text}；{next_step}"
    if label == "平台连接能力":
        text = re.split(r"；细分\s*", text, maxsplit=1)[0].strip()
        text = re.sub(r"^平台连接能力\s+", "", text)
        text = text.replace("Product Discount 连接", "活动草稿").replace("Flash Deal 连接", "活动草稿")
        text = text.replace("Promotion 连接", "活动草稿").replace("Coupon 连接", "优惠券草稿")
        text = text.replace("Voucher 连接", "优惠券草稿").replace("Seller Center Coupon", "卖家后台优惠券")
    elif label in {"活动规则", "活动规则 / 广告边界", "活动/广告规则"}:
        route = text.split("；", 1)[0].strip()
        status = part_after("执行状态") or part_after("状态") or "规则待复核"
        activity_types = compact_slash_list(part_after("活动类型") or "活动类型待确认")
        stacking = compact_slash_list(part_after("叠加规则") or "叠加规则待复核")
        guardrails = compact_slash_list(part_after("利润/库存") or "毛利、库存和履约待复核", limit=2)
        next_step = part_after("下一步") or "后台 AI 先生成活动草稿、叠加校验和负责人确认包。"
        if "缺后台真实平台店铺" in text or "缺店铺" in status:
            next_step = "缺真实平台店铺；只做候选规划和开店准备，不报名活动、不改价、不投广告。"
        elif "缺广告" in status or "广告账号" in text and "未登记" in text:
            next_step = "可生成活动草稿；广告预算和投放先等广告账号与归属主体确认。"
        compact_parts = [
            route,
            f"执行状态 {status}",
            f"活动 {activity_types}",
            f"叠加 {stacking}",
            f"护栏 {guardrails}",
            "确认 真实报名、改价、发券、改预算和外部提交必须负责人确认",
            f"下一步 {next_step}",
        ]
        text = "；".join(compact_parts)
        text = re.split(r"；(?:连接/广告|授权要求|执行后台|提交门槛|客户边界|后台执行身份原因|规则到任务|站点差异)\s*", text, maxsplit=1)[0].strip()
        text = text.replace("Product Discount API", "活动后台").replace("Flash Deal API", "活动后台")
        text = text.replace("Seller Center campaign backend", "卖家后台活动")
    elif label == "活动边界 / 广告边界":
        route = text.split("；", 1)[0].strip()
        ads = compact_slash_list(part_after("广告/授权") or "广告账号和归属主体单独确认", limit=3)
        activity = compact_slash_list(part_after("活动/叠加") or "活动规则按站点复核", limit=3)
        gates = compact_slash_list(part_after("提交门槛") or "负责人确认后才提交", limit=2)
        text = (
            f"{route}；广告 {ads}；活动 {activity}；"
            f"确认 {gates}；真实活动报名、广告预算和外部提交必须负责人确认"
        )
    return text


def render_chat_erp_status_summary(
    root: Path | None,
    session_info: dict[str, Any] | None = None,
    intent: str = "",
    source_page: str = "",
) -> tuple[str, list[str]]:
    snapshot = store_erp_snapshot_for_chat(root, session_info)
    gaps = [str(item) for item in snapshot.get("gaps") or []]
    summary = snapshot.get("summary") if isinstance(snapshot.get("summary"), dict) else {}
    pending_count = int(snapshot.get("pending_count") or 0)
    store_count = int(snapshot.get("store_count") or 0)
    latest_day = str(snapshot.get("latest_day") or "")
    has_data = bool(snapshot.get("has_data"))
    has_business_metrics = metric_bucket_has_business_value(summary)
    connection_lines = [str(item) for item in (snapshot.get("connection_lines") or []) if str(item).strip()]
    route_lines = [str(item) for item in (snapshot.get("route_lines") or []) if str(item).strip()]
    activity_lines = [str(item) for item in (snapshot.get("activity_lines") or []) if str(item).strip()]
    activity_boundary_lines = [
        str(item) for item in (snapshot.get("activity_boundary_lines") or []) if str(item).strip()
    ]
    developer_capability_lines = [
        str(item) for item in (snapshot.get("developer_capability_lines") or []) if str(item).strip()
    ]
    manifest_lines = [str(item) for item in (snapshot.get("manifest_lines") or []) if str(item).strip()]
    manifest = snapshot.get("data_manifest") if isinstance(snapshot.get("data_manifest"), dict) else {}
    if source_page == "amazon-seller-central":
        amazon_line = lambda line: bool(re.search(r"\bAmazon\b|亚马逊|Seller Central|FBA|FBM|SP-API", str(line), re.I))
        connection_lines = [line for line in connection_lines if amazon_line(line)]
        route_lines = [line for line in route_lines if amazon_line(line)]
        activity_lines = [line for line in activity_lines if amazon_line(line)]
        activity_boundary_lines = [line for line in activity_boundary_lines if amazon_line(line)]
        developer_capability_lines = [line for line in developer_capability_lines if amazon_line(line)]
    route_display_lines = route_lines or [
        (
            "Amazon / US 新店路径：后台 AI 先按 Amazon + US + 自运营店铺判断；账户非在售、FBA/FBM 无库存或授权未完成时，只保留诊断和草稿，不上架、不拉单、不投广告。"
            if source_page == "amazon-seller-central"
            else "路由口径：后台 AI 先按平台 + 国家站点 + 店铺模式判断；没有匹配后台平台店铺时，只保留候选和开店准备，不上架、不拉单、不投广告。"
        )
    ]
    title = (
        "当前 Amazon 新店缺口"
        if source_page == "amazon-seller-central"
        else ("当前店铺连接状态" if intent == "store_connection" else "当前 ERP 缺口")
    )
    gap_text = "、".join(gaps[:6]) + (" 等" if len(gaps) > 6 else "") if gaps else "基础经营数据已接入"
    manifest_ready = int(manifest.get("ready_count") or 0)
    manifest_missing = int(manifest.get("missing_count") or 0)
    data_note = (
        f"页面正在回看最近一次真实指标：{latest_day}。"
        if latest_day
        else ("当前已有真实经营指标。" if has_data else "当前没有可用于经营判断的真实指标。")
    )
    metrics = [
        ("店铺连接", str(store_count)),
        ("销售额", money(summary.get("revenue")) if has_business_metrics else "待读取"),
        ("订单", str(int(summary.get("orders") or 0)) if has_business_metrics else "待读取"),
        ("广告花费", money(summary.get("ad_spend")) if has_business_metrics else "待读取"),
        ("待确认", str(pending_count)),
    ]
    metrics_html = "".join(
        f"<div><span>{html.escape(label)}</span><strong>{html.escape(value)}</strong></div>"
        for label, value in metrics
    )
    next_step = (
        (
            "后台 AI 已读取负责人确认的店铺连接档案；接下来按授权范围等待订单、广告、退款、财务、库存和商品状态，不扩大读取范围。"
            if connection_lines
            else "后台 AI 等待负责人确认平台、国家、店铺名和授权方式；确认后自动读取订单、广告、退款、财务、库存和商品状态。"
        )
        if intent == "store_connection"
        else "后台 AI 先核对最小经营证据：订单/销售、广告、退款/售后、财务结算、库存和商品状态；真实授权和外部动作仍进确认。"
    )
    connection_groups: list[tuple[str, list[str]]] = [
        ("真实数据清单", manifest_lines[:3]),
        ("店铺连接档案", connection_lines[:3]),
        ("平台/国家/店铺模式", route_display_lines[:3]),
        ("平台连接能力", developer_capability_lines[:2]),
        ("活动规则", activity_lines[:3]),
        ("活动边界 / 广告边界", activity_boundary_lines[:3]),
    ]
    connection_html = ""
    visible_connection_groups = [(label, lines) for label, lines in connection_groups if lines]
    if visible_connection_groups:
        connection_html = (
            "<div class=\"chat-connection-list\">"
            + "".join(
                f"<div><b>{html.escape(label)}：</b>{html.escape(chat_status_customer_visible_line(label, line))}</div>"
                for label, lines in visible_connection_groups
                for line in lines
                if chat_status_customer_visible_line(label, line)
            )
            + "</div>"
        )
    context_cards = [
        f"{title}：后台 AI 当前等待 {gap_text}；真实数据清单 {manifest_ready} 项可分析 / {manifest_missing} 项待读取；{data_note} 待确认动作 {pending_count} 条。"
    ]

    def append_visible_context(label: str, lines: list[str], limit: int) -> None:
        for line in lines[:limit]:
            visible = chat_status_customer_visible_line(label, line)
            if visible:
                context_cards.append(f"{label}：{visible}")

    append_visible_context("真实数据清单", manifest_lines, 7)
    append_visible_context("店铺连接档案", connection_lines, 4)
    append_visible_context("平台/国家/店铺模式", route_display_lines, 4)
    append_visible_context("平台连接能力", developer_capability_lines, 4)
    append_visible_context("活动规则", activity_lines, 4)
    append_visible_context("活动边界 / 广告边界", activity_boundary_lines, 6)
    return (
        f"""
          <section class="chat-status-summary">
            <h2>{html.escape(title)}</h2>
            <p>后台 AI 当前等待：<strong>{html.escape(gap_text)}</strong>。真实数据清单 {html.escape(str(manifest_ready))} 项可分析 / {html.escape(str(manifest_missing))} 项待读取。{html.escape(data_note)}</p>
            <div class="chat-status-metrics">{metrics_html}</div>
            {connection_html}
            <p class="chat-status-next">{html.escape(next_step)}</p>
          </section>
""",
        context_cards,
    )


def render_workspace_project_navigation(
    root: Path | None,
    *,
    current_url: str,
    session_info: dict[str, Any] | None = None,
) -> tuple[str, str, str]:
    config: dict[str, Any] = {}
    if root:
        path = root / "config" / "workspace_projects.json"
        if path.exists():
            try:
                payload = json.loads(path.read_text(encoding="utf-8"))
                if isinstance(payload, dict):
                    config = payload
            except (OSError, ValueError):
                config = {}
    if not config:
        config = {
            "workspace_name": "TeeLab 全球商业",
            "description": "多项目、多店铺、多智能体运营空间",
            "project_groups": [
                {
                    "name": "当前任务",
                    "projects": [
                        {"name": "Amazon 出单", "status": "运营中", "href": "/desktop", "active_when": "amazon"},
                        {"name": "B2B 获客", "status": "进行中", "href": "/desktop?task=b2b-10001-apparel", "active_when": "b2b"},
                    ],
                }
            ],
        }
    workspace_name = str(config.get("workspace_name") or "TeeLab 全球商业")
    workspace_desc = str(config.get("description") or "多项目、多店铺、多智能体运营空间")
    groups = config.get("project_groups") if isinstance(config.get("project_groups"), list) else []
    group_html: list[str] = []
    for group in groups:
        if not isinstance(group, dict):
            continue
        projects = group.get("projects") if isinstance(group.get("projects"), list) else []
        links: list[str] = []
        for project in projects:
            if not isinstance(project, dict):
                continue
            href = str(project.get("href") or "/dashboard")
            name = str(project.get("name") or "未命名项目")
            status = str(project.get("status") or "")
            marker = str(project.get("active_when") or "")
            active = " active" if marker and marker in current_url else ""
            links.append(
                f'<a class="side-link{active}" href="{html.escape(href, quote=True)}">'
                f"<span>{html.escape(name)}</span><small>{html.escape(status)}</small></a>"
            )
        if not links:
            continue
        group_html.append(
            f'<div class="side-title project-group-title">{html.escape(str(group.get("name") or "项目组"))}</div>'
            + "".join(links)
        )

    profile: dict[str, Any] = {}
    if root:
        try:
            profile = account_center.load_profile(root)
        except Exception:
            profile = {}
    subaccounts = profile.get("subaccounts") if isinstance(profile.get("subaccounts"), list) else []
    active_subaccounts = [item for item in subaccounts if isinstance(item, dict) and item.get("active", True)]
    display_name = str((session_info or {}).get("display_name") or profile.get("name") or "Owner")
    team_html = (
        '<div class="team-summary">'
        f'<span class="team-avatar">{html.escape(display_name[:1].upper() or "O")}</span>'
        '<span class="team-copy">'
        f"<strong>{html.escape(display_name)}</strong>"
        f"<small>{len(active_subaccounts)} 个启用子账号</small>"
        "</span>"
        '<a href="/account#team-permissions" title="管理子账号与分组权限">管理</a>'
        "</div>"
    )
    return "".join(group_html), team_html, f"{workspace_name} · {workspace_desc}"


def render_chat_page(
    root: Path | None = None,
    query: dict[str, list[str]] | None = None,
    session_info: dict[str, Any] | None = None,
) -> str:
    model_options = render_chat_model_options(root)
