def render_data_row(record: IntakeRecord) -> str:
    fields = record.fields
    name = (
        fields.get("product_name")
        or format_platform_ranking_name(fields)
        or format_store_profile_name(fields)
        or format_pod_admin_name(fields)
        or format_concept_weight_name(fields)
        or format_contract_record_name(fields)
        or fields.get("playbook_name")
        or fields.get("video_url")
        or fields.get("creator_handle")
        or fields.get("product_theme")
        or fields.get("influencer_handle")
        or fields.get("english_label")
        or fields.get("store_id")
        or fields.get("url")
        or record.record_id[:8]
    )
    return (
        "<tr>"
        f"<td>{html.escape(record.created_at[:19])}</td>"
        f"<td>{html.escape(display_record_type(record.record_type))}</td>"
        f"<td>{html.escape(str(name))}</td>"
        f"<td>{html.escape(str(record.source))}</td>"
        f"<td>{html.escape(str(record.score.get('priority', '')))}</td>"
        f"<td>{html.escape(record.review_status)}</td>"
        f"<td><a href='/record?id={html.escape(record.record_id)}'>编辑</a></td>"
        "</tr>"
    )


def format_concept_weight_name(fields: dict[str, Any]) -> str:
    entity = fields.get("entity")
    if not entity:
        return ""
    weight = fields.get("concept_weight")
    status = fields.get("concept_status")
    suffix = f" · weight {weight}" if weight not in (None, "") else ""
    status_suffix = f" · {status}" if status else ""
    return f"{entity}{suffix}{status_suffix}"


