        "company_name",
        "quote_status",
        "contract_type",
        "inquiry_text",
        "chunk_type",
        "connector_name",
        "dataset_name",
        "claim_text",
        "document_type",
        "rule_title",
        "diff_type",
        "alias_text",
        "change_type",
        "eval_suite",
        "judge_type",
        "slice_key",
        "action_type",
        "model_name",
        "prompt_name",
        "event_source",
        "dedup_key",
        "task_type",
        "failure_reason",
        "data_class",
        "delete_mode",
        "purpose",
        "company_type",
        "catalog_name",
