def _compat_workspace_signature(root: _RecoveryPath) -> str:
    normalized = str(root.resolve()).casefold().encode("utf-8")
    return _recovery_sha256(normalized).hexdigest()[:16]


def _compat_project_count(root: _RecoveryPath) -> int:
    try:
        payload = _compat_json.loads(
            (root / "config" / "workspace_projects.json").read_text(
                encoding="utf-8"
            )
        )
    except (OSError, ValueError, TypeError):
        return 0
    projects = payload.get("projects") if isinstance(payload, dict) else None
    return len(projects) if isinstance(projects, list) else 0


def build_handler(root: _RecoveryPath):
    recovered_handler = _recovered_build_handler(root)
    # Freeze the source identity when this process starts. Recomputing it for
    # every health check lets an old process impersonate newer files on disk.
    started_backend_source_signature = _compat_backend_source_signature(root)

    class CompatibilityHandler(recovered_handler):
        def _compat_owner_session(self):
            session_token = self.get_cookie("acct_session")
            if not account_center.is_owner_session(root, session_token):
                self.write_json(
                    {
                        "ok": False,
                        "error": "owner_session_required",
                        "message": "Owner session is required.",
                    },
                    status=403,
                )
                return None
            return account_center.current_session(root, session_token) or {
                "display_name": "Owner"
            }

        def _compat_external_client(self):
            from .external_access_gateway import authenticate_external_client

            try:
                return authenticate_external_client(
                    root,
                    str(self.headers.get("Authorization") or ""),
                )
            except PermissionError as exc:
                self.write_json(
                    {"ok": False, "error": str(exc)},
                    status=401,
                )
                return None

        def do_GET(self):
            parsed = _compat_urlsplit(self.path)
            path = parsed.path
            retired_admin_location = _COMPAT_RETIRED_ADMIN_REDIRECTS.get(path)
            if retired_admin_location:
                if not account_center.is_admin(
                    root,
                    self.get_cookie("acct_session"),
                    self.get_cookie("acct_admin"),
                ):
                    self.send_response(302)
                    self.send_header(
                        "Location",
                        "/account?" + urlencode({"next": path}),
                    )
                    self.end_headers()
                    return
                self.send_response(302)
                self.send_header("Location", retired_admin_location)
                self.end_headers()
                return
            legacy_location = _COMPAT_LEGACY_DESKTOP_REDIRECTS.get(path)
            if path == "/chat":
                intent = parse_qs(parsed.query).get("intent", [""])[0]
                legacy_location = (
                    "/desktop?view=new&intent=product_data"
                    if intent == "product_data"
                    else "/desktop?view=new"
                )
            if legacy_location:
                self.send_response(302)
                self.send_header("Location", legacy_location)
                self.end_headers()
                return
            if path == "/auto-mode":
                # The old one-page autonomous dashboard has been retired.  Its
                # data and background jobs remain available, but every visible
                # entry must return to the current T One workspace.
                self.send_response(302)
                self.send_header("Location", "/desktop?view=dashboard")
                self.end_headers()
                return
            if path == "/realtime-big-screen":
                # The standalone screen is a retired seller portal.  Route all
                # roles through the current workspace, where subaccount scope
                # is applied before dashboard data is rendered.
                self.send_response(302)
                self.send_header("Location", "/desktop?view=module_dashboard")
                self.end_headers()
                return
            if path == "/health":
                self.write_json(
                    {
                        "ok": True,
                        "desktop_runtime_version": (
                            _COMPAT_DESKTOP_RUNTIME_VERSION
                        ),
                        "workspace_signature": _compat_workspace_signature(
                            root
                        ),
                        "backend_source_signature": (
                            started_backend_source_signature
                        ),
                        "workspace_ready": root.exists(),
                        "project_count": _compat_project_count(root),
                    }
                )
                return

            if path == "/api/v1/new-media-operations":
                from .new_media_operations import new_media_operations_snapshot

                self.write_json(
                    {"ok": True, **new_media_operations_snapshot(root)}
                )
                return

            if path == "/api/v1/browser-environments":
                if self._compat_owner_session() is None:
                    return
                from .browser_environments import browser_environment_snapshot

                try:
                    payload = browser_environment_snapshot(root)
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/tools":
                if self._compat_owner_session() is None:
                    return
                from .open_tool_registry import open_tool_registry_snapshot

                try:
                    payload = open_tool_registry_snapshot(root)
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            if path == "/api/data-acquisition-connectors":
                if self._compat_owner_session() is None:
                    return
                from .data_acquisition_connectors import data_acquisition_snapshot

                self.write_json(
                    {"ok": True, **data_acquisition_snapshot(root)}
                )
                return

            if path == "/api/v1/external-access-control":
                if self._compat_owner_session() is None:
                    return
                from .external_access_gateway import (
                    external_access_control_snapshot,
                )

                self.write_json(external_access_control_snapshot(root))
                return

            if path == "/api/v1/external/context":
                client = self._compat_external_client()
                if client is None:
                    return
                from .external_access_gateway import read_external_project_context

                project_id = parse_qs(parsed.query).get("project_id", [""])[0]
                try:
                    payload = read_external_project_context(
                        root,
                        client,
                        project_id,
                    )
                except PermissionError as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=403,
                    )
                    return
                except ValueError as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            external_draft_route = _COMPAT_EXTERNAL_DRAFT_ROUTE.fullmatch(path)
            if external_draft_route is not None:
                client = self._compat_external_client()
                if client is None:
                    return
                from .external_access_gateway import read_external_draft

                try:
                    payload = read_external_draft(
                        root,
                        client,
                        _compat_unquote(external_draft_route.group(1)),
                    )
                except PermissionError as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=403,
                    )
                    return
                except ValueError as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=404,
                    )
                    return
                self.write_json(payload)
                return

            store_requirements_route = (
                _COMPAT_STORE_PRODUCT_REQUIREMENTS_ROUTE.fullmatch(path)
            )
            channel_requirements_route = (
                _COMPAT_CHANNEL_PRODUCT_REQUIREMENTS_ROUTE.fullmatch(path)
            )
            if (
                store_requirements_route is not None
                or channel_requirements_route is not None
            ):
                from .platform_product_requirements import (
                    build_channel_product_requirements_snapshot,
                    build_platform_product_requirements_snapshot,
                )

                try:
                    if store_requirements_route is not None:
                        payload = build_platform_product_requirements_snapshot(
                            root,
                            _compat_unquote(store_requirements_route.group(1)),
                            _compat_unquote(store_requirements_route.group(2)),
                        )
                    else:
                        payload = build_channel_product_requirements_snapshot(
                            root,
                            _compat_unquote(channel_requirements_route.group(1)),
                            _compat_unquote(channel_requirements_route.group(2)),
                        )
                except ValueError as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=404,
                    )
                    return
                self.write_json(payload)
                return

            route = _COMPAT_STORE_ROUTE.fullmatch(path)
            if route is None:
                return super().do_GET()
            if self._compat_owner_session() is None:
                return

            project_id = _compat_unquote(route.group(1))
            store_binding_id = _compat_unquote(route.group(2))
            if route.group(3) == "connection-test":
                payload = run_store_connection_test(
                    root,
                    project_id,
                    store_binding_id,
                )
            else:
                payload = build_store_connection_options(
                    root,
                    project_id,
                    store_binding_id,
                )
            self.write_json(payload)

        def do_POST(self):
            path = _compat_urlsplit(self.path).path
            if path == "/api/v1/workspace/items":
                owner_session = self._compat_owner_session()
                if owner_session is None:
                    return
                try:
                    payload = update_workspace_item(
                        root,
                        self.read_json(),
                        actor=str(owner_session.get("display_name") or "owner"),
                    )
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json({"ok": False, "error": str(exc)}, status=400)
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/task-skills/prepare":
                if self._compat_owner_session() is None:
                    return
                from .project_capability_profiles import prepare_task_skill_packages

                try:
                    payload = prepare_task_skill_packages(root, self.read_json())
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json({"ok": False, "error": str(exc)}, status=400)
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/browser-environments/prepare":
                if self._compat_owner_session() is None:
                    return
                from .browser_environments import prepare_browser_environment

                try:
                    payload = prepare_browser_environment(root, self.read_json())
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            amazon_authorization_route = (
                _COMPAT_AMAZON_AUTHORIZATION_VERIFY_ROUTE.fullmatch(path)
            )
            if amazon_authorization_route is not None:
                if self._compat_owner_session() is None:
                    return
                self.write_json(
                    {
                        "ok": False,
                        "status": "paused_by_owner",
                        "error": "amazon_operations_paused",
                        "message": (
                            "Amazon 工作当前已按负责人要求暂停；"
                            "未读取授权资料，也未调用任何外部接口。"
                        ),
                        "external_action_count": 0,
                    },
                    status=409,
                )
                return

            if path == "/api/v1/finance/settlement/snapshot":
                if self._compat_owner_session() is None:
                    return
                from .platform_settlement_finance import (
                    finance_settlement_snapshot,
                )

                try:
                    request_payload = self.read_json()
                    limit = max(
                        1,
                        min(50, int(request_payload.get("limit") or 5)),
                    )
                    payload = finance_settlement_snapshot(
                        root,
                        project_id=str(
                            request_payload.get("project_id") or ""
                        ),
                        task_id=str(request_payload.get("task_id") or ""),
                        limit=limit,
                    )
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/finance/settlement/import-file":
                if self._compat_owner_session() is None:
                    return
                from .platform_settlement_finance import import_settlement_statement_file

                try:
                    payload = import_settlement_statement_file(
                        root,
                        self.read_json(max_bytes=14 * 1024 * 1024),
                        actor="desktop-owner",
                    )
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json({"ok": False, "error": str(exc)}, status=400)
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/communications/import-file":
                if self._compat_owner_session() is None:
                    return
                from .communications_connector_control import import_communications_message_file

                try:
                    payload = import_communications_message_file(
                        root,
                        self.read_json(max_bytes=8 * 1024 * 1024),
                        actor="desktop-owner",
                    )
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json({"ok": False, "error": str(exc)}, status=400)
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/tools":
                if self._compat_owner_session() is None:
                    return
                from .open_tool_registry import register_open_tool

                try:
                    payload = register_open_tool(root, self.read_json())
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/external-access/clients":
                owner_session = self._compat_owner_session()
                if owner_session is None:
                    return
                from .external_access_gateway import register_external_client

                try:
                    payload = register_external_client(
                        root,
                        self.read_json(),
                        actor=str(
                            owner_session.get("display_name")
                            or owner_session.get("login_id")
                            or "Owner"
                        ),
                    )
                except (TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return

            if path == "/api/v1/external/drafts":
                client = self._compat_external_client()
                if client is None:
                    return
                from .external_access_gateway import submit_external_draft

                try:
                    payload = submit_external_draft(
                        root,
                        client,
                        self.read_json(),
                        idempotency_key=str(
                            self.headers.get("Idempotency-Key") or ""
                        ),
                    )
                except PermissionError as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=403,
                    )
                    return
                except (TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json(payload)
                return
            if path == "/api/chat":
                # The recovered chat handler predates the local operating-
                # expense route. Read once, let the deterministic ledger claim
                # only explicit finance intents, then replay untouched payloads
                # to the recovered advisor handler.
                try:
                    content_length = int(self.headers.get("Content-Length") or 0)
                except (TypeError, ValueError):
                    content_length = 0
                raw_body = self.rfile.read(content_length) if content_length else b""
                payload = None
                try:
                    decoded = _compat_json.loads(raw_body.decode("utf-8"))
                    if isinstance(decoded, dict):
                        payload = decoded
                except (UnicodeDecodeError, ValueError):
                    payload = None
                if payload is not None:
                    try:
                        from .operating_expense_ledger import (
                            maybe_handle_operating_expense_chat,
                        )

                        expense_reply = maybe_handle_operating_expense_chat(
                            root,
                            payload,
                            actor="desktop-owner",
                        )
                    except (OSError, TypeError, ValueError) as exc:
                        self.write_json(
                            {"ok": False, "error": str(exc)},
                            status=400,
                        )
                        return
                    if expense_reply is not None:
                        self.write_json({"ok": True, **expense_reply})
                        return
                self.rfile = _compat_io.BytesIO(raw_body)
                return super().do_POST()

            if path == "/api/desktop/session":
                expected_token = str(
                    _compat_os.environ.get("TEELAB_DESKTOP_AUTH_TOKEN") or ""
                )
                provided_token = str(
                    self.headers.get("X-TeeLab-Desktop-Token") or ""
                )
                if (
                    not expected_token
                    or not provided_token
                    or not _compat_secrets.compare_digest(
                        provided_token,
                        expected_token,
                    )
                ):
                    self.write_json(
                        {
                            "ok": False,
                            "code": "desktop_auth_rejected",
                            "message": "Desktop process authentication failed.",
                        },
                        status=403,
                    )
                    return
                if not account_center.profile_exists(root):
                    account_center.create_profile(
                        root,
                        "Owner",
                        _compat_secrets.token_urlsafe(32),
                    )
                self.write_json(
                    {
                        "ok": True,
                        "role": "owner",
                        "session_token": account_center.session_token(root),
                    }
                )
                return

            if path == "/api/v1/workspace/commerce-profile":
                session = self._compat_owner_session()
                if session is None:
                    return
                try:
                    from .workspace_runtime import save_workspace_commerce_profile

                    result = save_workspace_commerce_profile(
                        root,
                        self.read_json(),
                        actor=str(session.get("display_name") or "Owner"),
                    )
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)}, status=400
                    )
                    return
                self.write_json(result)
                return

            if path == "/api/v1/new-media-operations/work-packet":
                if self._compat_owner_session() is None:
                    return
                try:
                    from .new_media_operations import build_new_media_work_packet

                    packet = build_new_media_work_packet(root, self.read_json())
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json({"ok": True, "packet": packet})
                return

            if path == "/api/v1/organization/management-actions":
                owner_session = self._compat_owner_session()
                if owner_session is None:
                    return
                try:
                    from .organization_operating import record_management_action

                    event = record_management_action(
                        root,
                        self.read_json(),
                        actor_session={
                            "is_owner": True,
                            "login_id": str(
                                owner_session.get("login_id")
                                or owner_session.get("display_name")
                                or "owner"
                            ),
                        },
                    )
                except (OSError, PermissionError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json({"ok": True, "event": event})
                return

            if path == "/api/data-acquisition-connectors/import":
                if self._compat_owner_session() is None:
                    return
                try:
                    from .data_acquisition_connectors import (
                        import_data_acquisition_file,
                    )

                    result = import_data_acquisition_file(
                        root,
                        self.read_json(max_bytes=14 * 1024 * 1024),
                    )
                except (OSError, TypeError, ValueError) as exc:
                    self.write_json(
                        {"ok": False, "error": str(exc)},
                        status=400,
                    )
                    return
                self.write_json({"ok": True, "receipt": result})
                return

            erp_route = _COMPAT_ERP_VERIFY_ROUTE.fullmatch(path)
            config_route = _COMPAT_CONNECTION_CONFIG_ROUTE.fullmatch(path)
            if erp_route is None and config_route is None:
                return super().do_POST()
            session = self._compat_owner_session()
            if session is None:
                return

            payload = self.read_json()
            try:
                if config_route is not None:
                    result = save_store_connection_configuration(
                        root,
                        _compat_unquote(config_route.group(1)),
                        _compat_unquote(config_route.group(2)),
                        payload,
                        actor=str(session.get("display_name") or "Owner"),
                    )
                else:
                    result = configure_erp_http_json_adapter(
                        root,
                        _compat_unquote(erp_route.group(1)),
                        _compat_unquote(erp_route.group(2)),
                        payload,
                        actor=str(session.get("display_name") or "Owner"),
                    )
            except (TypeError, ValueError) as exc:
                self.write_json(
                    {
                        "ok": False,
                        "error": "invalid_connection_configuration",
                        "message": str(exc),
                    },
                    status=400,
                )
                return
            self.write_json(result)

    return CompatibilityHandler


# The verified recovery payload predates task-scoped expert learning memory.
# Keep its context sanitization and scope handling intact, then add only the
# persisted memory for the exact project/task named by the chat request.
from .external_ai_distillation import (
    resolve_approved_expert_learning_memory as _compat_resolve_learning_memory,
)
from .task_execution_runtime import (
    task_run_context_lines_for_chat as _compat_task_run_context_lines,
)
from .chat_execution_identity import (
    safe_chat_execution_identity as _compat_safe_chat_execution_identity,
)


_recovered_seller_chat_context_from_payload = seller_chat_context_from_payload


def _compat_chat_scope_id(payload, key):
    page_context = payload.get("page_context")
    if not isinstance(page_context, dict):
        page_context = {}
    value = payload.get(key) or page_context.get(key) or ""
    return str(value).strip()


def _compat_frontend_page_context(root, payload, session_info):
    supplied = payload.get("page_context")
    supplied = dict(supplied) if isinstance(supplied, dict) else {}
    task_id = _compat_chat_scope_id(payload, "task_id") or str(
        payload.get("id") or ""
    ).strip()
    page_url = str(payload.get("page_url") or "")
    if task_id and _compat_urlsplit(page_url).path == "/desktop":
        try:
            trusted = desktop_task_page_context_snapshot(
                _RecoveryPath(root),
                task_id,
            )
        except (OSError, TypeError, ValueError):
            trusted = {}
        if isinstance(trusted, dict) and trusted:
            return dict(trusted), True

    scoped_session = session_with_query_scope(
        session_info,
        store=str(payload.get("store_id") or payload.get("store") or payload.get("shop_id") or ""),
        platform=str(payload.get("platform") or ""),
        country=str(payload.get("country") or ""),
    )
    if not scoped_session or session_scope_is_restricted(scoped_session):
        supplied = sanitize_frontend_page_context_for_session_scope(supplied)
    return supplied, False


def seller_chat_context_from_payload(root, payload, session_info):
    if root is None or not isinstance(payload, dict):
        return _recovered_seller_chat_context_from_payload(
            root,
            payload,
            session_info,
        )
    frontend_page_context, trusted_task_context = _compat_frontend_page_context(
        root,
        payload,
        session_info,
    )
    effective_payload = payload
    if trusted_task_context:
        effective_payload = dict(payload)
        effective_payload["page_context"] = dict(frontend_page_context)
    context = _recovered_seller_chat_context_from_payload(
        root,
        effective_payload,
        session_info,
    )

    project_id = _compat_chat_scope_id(payload, "project_id")
    task_id = _compat_chat_scope_id(payload, "task_id")
    result = dict(context)
    result["project_id"] = project_id
    result["task_id"] = task_id
    result["frontend_page_context"] = frontend_page_context
    execution_identity = _compat_safe_chat_execution_identity(
        _RecoveryPath(root),
        payload,
        context,
    )
    result.update(execution_identity)
    if trusted_task_context:
        result["page_context"] = dict(frontend_page_context)
    page_context = result.get("page_context")
    page_context = dict(page_context) if isinstance(page_context, dict) else {}

    if execution_identity and not page_context.get("route_rows"):
        platform = str(result.get("platform") or "").strip()
        country = str(result.get("country") or "").strip()
        store_id = str(result.get("store_id") or "").strip()
        store_model = str(execution_identity.get("store_model") or "").strip()
        ownership = str(execution_identity.get("ownership") or "").strip()
        if platform and country and store_id and store_model:
            page_context["route_rows"] = [
                "当前已登记执行身份："
                f"平台 {platform}；站点 {country}；店铺 {store_id}；"
                f"店铺模式 {store_model}；归属 {ownership or '未标注'}。"
            ]

    if project_id and task_id:
        try:
            learning_memory = _compat_resolve_learning_memory(
                _RecoveryPath(root),
                project_id=project_id,
                task_id=task_id,
            )
        except (OSError, TypeError, ValueError):
            learning_memory = {}
        if int(learning_memory.get("memory_count") or 0) > 0:
            page_context["learning_memory"] = learning_memory

    if task_id == "b2b-dtg-machines":
        try:
            from .b2b_sales_runtime import sales_snapshot as _compat_b2b_sales_snapshot

            b2b_snapshot = _compat_b2b_sales_snapshot(
                _RecoveryPath(root),
                product_id="",
                task_context={
                    "id": task_id,
                    "project_id": project_id,
                    "sales_scope": "equipment_cross_sell",
                },
            )
        except (OSError, TypeError, ValueError):
            b2b_snapshot = {}
        b2b_context_lines = []
        for lead in (b2b_snapshot.get("top_leads") or [])[:5]:
            if not isinstance(lead, dict):
                continue
            company = str(lead.get("company") or "未命名公司").strip()
            market = str(lead.get("market") or "市场待确认").strip()
            stage = str(lead.get("stage") or "阶段待确认").strip()
            signals = "、".join(
                str(item).strip()
                for item in (lead.get("equipment_review_signals") or [])
                if str(item).strip()
            ) or "设备信号待确认"
            next_action = str(lead.get("next_action") or "补客户原话与技术需求证据").strip()
            b2b_context_lines.append(
                f"设备候选：{company}；市场={market}；阶段={stage}；"
                f"信号={signals}；历史记录（不得视为当前授权）={next_action[:120]}"
            )
        if b2b_context_lines:
            page_context["tables"] = b2b_context_lines
        page_context["metrics"] = [
            "共享客户池公司数="
            f"{int(b2b_snapshot.get('authoritative_company_count') or 0)}",
            "设备文字信号候选数="
            f"{int(b2b_snapshot.get('scope_candidate_count') or 0)}",
            "设备报价资料完整数="
            f"{int(b2b_snapshot.get('quote_ready_count') or 0)}",
        ]

    task_run_id = _compat_chat_scope_id(payload, "task_run_id")
    if task_run_id:
        try:
            task_run_lines = _compat_task_run_context_lines(
                _RecoveryPath(root),
                task_run_id,
                task_id=task_id,
            )
        except (OSError, TypeError, ValueError):
            task_run_lines = []
        if task_run_lines:
            page_context["task_run_context"] = task_run_lines

    result["page_context"] = page_context
    return result


def public_model_label(model: dict[str, Any], locale: str | None = None) -> str:
    """Post-recovery U23 overlay with receipt-backed availability language."""

    is_en = str(locale or "").lower().startswith("en")
    model_id = str(model.get("model") or "").strip()
    name = str(model.get("name") or "").lower()
    text = f"{name} {model_id}".lower()
    if "gemini" in text:
        vendor = "Gemini"
    elif "deepseek" in text:
        vendor = "DeepSeek"
    elif "zhipu" in text or "glm" in text:
        vendor = "Zhipu GLM" if is_en else "智谱 GLM"
    elif "claude" in text:
        vendor = "Claude"
    elif "gpt" in text or "openai" in text:
        vendor = "GPT"
    elif "qwen" in text or "siliconflow" in text:
        vendor = "Qwen"
    elif "longcat" in text:
        vendor = "LongCat"
    elif "agnes" in text:
        vendor = "Agnes"
    elif "kiro" in text:
        vendor = "Kiro"
    elif "local" in text or "ollama" in text:
        vendor = "Local Model" if is_en else "本地模型"
    else:
        vendor = "AI Model" if is_en else "AI模型"
    tier = str(model.get("tier") or "").replace("_", " ").strip()
    tier_label = (
        f" · {tier}" if tier and tier.lower() not in {"recommended", "default"} else ""
    )
    state = str(model.get("verification_state") or "")
    if model.get("runtime_eligible") or (model.get("ready") and not state):
        availability = " · current probe verified" if is_en else " · 当前实测可用"
    elif state == "stale":
        availability = " · receipt expired" if is_en else " · 回执已过期"
    elif state == "blocked":
        availability = " · current probe blocked" if is_en else " · 当前实测受阻"
    elif model.get("credential_ready"):
        availability = " · awaiting verification" if is_en else " · 待实测"
    else:
        availability = " · not configured" if is_en else " · 未开通"
    return f"{vendor} · {model_id or 'custom model'}{tier_label}{availability}"


def render_chat_model_options(root: Path | None, locale: str | None = None) -> str:
    """Post-recovery U23 selector: only current exact receipts are selectable."""

    is_en = str(locale or "").lower().startswith("en")
    disconnected = "AI not connected (configure and test it in Settings)" if is_en else "AI 未连接（请到设置中配置并测试）"
    options: list[str] = []
    if root is None:
        return f'<option value="" selected disabled>{disconnected}</option>'
    try:
        from .ai_provider_catalog import provider_catalog_snapshot

        models = provider_catalog_snapshot(root).get("configured", [])
    except Exception:
        models = []
    visible_models = []
    for model in models:
        tasks = model.get("tasks") if isinstance(model.get("tasks"), list) else []
        if tasks and "chat" not in tasks and "default" not in tasks:
            continue
        if not model.get("enabled") or not str(model.get("name") or "").strip():
            continue
        visible_models.append(model)
    visible_models.sort(
        key=lambda item: (
            not bool(item.get("runtime_eligible")),
            int(item.get("priority") or 100),
            str(item.get("name") or ""),
        )
    )
    ready_models = [model for model in visible_models if model.get("runtime_eligible")]
    if ready_models:
        options.append(
            f'<option value="">{"Auto select (recommended)" if is_en else "自动选择（推荐）"}</option>'
        )
    else:
        options.append(f'<option value="" selected disabled>{disconnected}</option>')
    seen: set[str] = {""}

    def append_group(label: str, group_models: list[dict], *, disabled: bool = False) -> None:
        if not group_models:
            return
        options.append(f'<optgroup label="{html.escape(label, quote=True)}">')
        for model in group_models:
            name = str(model.get("name") or "").strip()
            if not name or name in seen:
                continue
            seen.add(name)
            disabled_attr = " disabled" if disabled else ""
            label_text = public_model_label(model, locale)
            options.append(
                f'<option value="{html.escape(name, quote=True)}"{disabled_attr}>{html.escape(label_text)}</option>'
            )
        options.append("</optgroup>")

    stale_models = [
        model for model in visible_models if model.get("verification_state") == "stale"
    ]
    pending_models = [
        model
        for model in visible_models
        if not model.get("runtime_eligible")
        and model.get("verification_state") != "stale"
    ]
    append_group(
        "Current probe verified" if is_en else "当前实测可用模型", ready_models
    )
    append_group(
        "Receipt expired (re-test required)" if is_en else "待重新验收模型",
        stale_models,
        disabled=True,
    )
    append_group(
        "Unavailable (finish setup or probe first)"
        if is_en
        else "不可用模型（请先完成配置与实测）",
        pending_models,
        disabled=True,
    )
    return "".join(options)
